-- Name: _assert_configuration_key_scope(text, text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public._assert_configuration_key_scope(p_config_key text, p_scope_kind text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.configuration_definitions
         WHERE config_key = p_config_key
           AND active
           AND contract_json->'allowed_scopes' ? p_scope_kind
    ) THEN
        RAISE EXCEPTION 'CONFIG_KEY_UNKNOWN_OR_SCOPE_FORBIDDEN'
            USING ERRCODE = '22023';
    END IF;
END;
$$;


