--
-- Name: _assert_mcp_application_actor(uuid, boolean); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public._assert_mcp_application_actor(p_org_id uuid, p_admin_required boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public.mcp_application_actor_user_id();
    v_org UUID := public.mcp_application_org_id();
    v_role TEXT;
BEGIN
    IF session_user <> 'everydayai'
       OR current_setting('app.access_kind', TRUE) IS DISTINCT FROM 'runtime'
       OR v_actor IS NULL
       OR p_org_id IS NULL
       OR v_org IS DISTINCT FROM p_org_id
       OR NOT EXISTS (
           SELECT 1 FROM public.users
            WHERE id = v_actor AND status::TEXT = 'active'
       )
       OR NOT EXISTS (
           SELECT 1 FROM public.organizations
            WHERE id = p_org_id AND status = 'active'
       ) THEN
        RAISE EXCEPTION 'MCP_CONNECTOR_SCOPE_DENIED'
            USING ERRCODE = '42501';
    END IF;

    SELECT role INTO v_role
      FROM public.org_members
     WHERE org_id = p_org_id
       AND user_id = v_actor
       AND status = 'active';
    IF NOT FOUND OR (p_admin_required AND v_role NOT IN ('owner', 'admin')) THEN
        RAISE EXCEPTION 'MCP_CONNECTOR_AUTHORITY_DENIED'
            USING ERRCODE = '42501';
    END IF;
    RETURN v_role;
END;
$$;


