--
-- Name: _bind_user_asset_ref(uuid, text, uuid, uuid, text, text, text, uuid, uuid, uuid, uuid, uuid, integer, text, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public._bind_user_asset_ref(p_asset_id uuid, p_ref_key text, p_actor_user_id uuid, p_org_id uuid, p_source_type text, p_source_kind text, p_ref_kind text, p_conversation_id uuid, p_source_message_id uuid, p_source_task_id uuid, p_source_generation_id uuid, p_source_attachment_id uuid, p_content_index integer, p_model_id text, p_prompt text, p_ref_metadata jsonb, p_created_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_ref user_asset_refs%ROWTYPE;
    v_created BOOLEAN := FALSE;
BEGIN
    SELECT * INTO v_ref
      FROM user_asset_refs
     WHERE ref_key = p_ref_key
     FOR UPDATE;

    IF v_ref.id IS NULL THEN
        BEGIN
            INSERT INTO user_asset_refs (
                ref_key, asset_id, actor_user_id, org_id, source_type,
                source_kind, ref_kind, conversation_id, source_message_id,
                source_task_id, source_generation_id, source_attachment_id,
                content_index, model_id, prompt, metadata, created_at,
                updated_at
            ) VALUES (
                p_ref_key, p_asset_id, p_actor_user_id, p_org_id,
                p_source_type, p_source_kind, p_ref_kind, p_conversation_id,
                p_source_message_id, p_source_task_id,
                p_source_generation_id, p_source_attachment_id,
                p_content_index, p_model_id, p_prompt,
                COALESCE(p_ref_metadata, '{}'::JSONB),
                COALESCE(p_created_at, NOW()), NOW()
            ) RETURNING * INTO v_ref;
            v_created := TRUE;
        EXCEPTION WHEN unique_violation THEN
            SELECT * INTO v_ref
              FROM user_asset_refs
             WHERE ref_key = p_ref_key
             FOR UPDATE;
        END;
    END IF;

    IF v_ref.id IS NULL
       OR v_ref.asset_id <> p_asset_id
       OR v_ref.actor_user_id <> p_actor_user_id
       OR v_ref.org_id IS DISTINCT FROM p_org_id
       OR v_ref.source_type <> p_source_type
       OR v_ref.source_kind <> p_source_kind
       OR v_ref.ref_kind <> p_ref_kind
       OR (
           v_ref.conversation_id IS NOT NULL
           AND p_conversation_id IS NOT NULL
           AND v_ref.conversation_id <> p_conversation_id
       )
       OR (
           v_ref.source_message_id IS NOT NULL
           AND p_source_message_id IS NOT NULL
           AND v_ref.source_message_id <> p_source_message_id
       )
       OR (
           v_ref.source_task_id IS NOT NULL
           AND p_source_task_id IS NOT NULL
           AND v_ref.source_task_id <> p_source_task_id
       )
       OR (
           v_ref.source_generation_id IS NOT NULL
           AND p_source_generation_id IS NOT NULL
           AND v_ref.source_generation_id <> p_source_generation_id
       )
       OR (
           v_ref.source_attachment_id IS NOT NULL
           AND p_source_attachment_id IS NOT NULL
           AND v_ref.source_attachment_id <> p_source_attachment_id
       )
       OR (
           v_ref.content_index IS NOT NULL
           AND p_content_index IS NOT NULL
           AND v_ref.content_index <> p_content_index
       )
    THEN
        RAISE EXCEPTION 'USER_ASSET_REF_CONFLICT';
    END IF;

    UPDATE user_asset_refs SET
        conversation_id = COALESCE(
            user_asset_refs.conversation_id, p_conversation_id
        ),
        source_message_id = COALESCE(
            user_asset_refs.source_message_id, p_source_message_id
        ),
        source_task_id = COALESCE(
            user_asset_refs.source_task_id, p_source_task_id
        ),
        source_generation_id = COALESCE(
            user_asset_refs.source_generation_id, p_source_generation_id
        ),
        source_attachment_id = COALESCE(
            user_asset_refs.source_attachment_id, p_source_attachment_id
        ),
        model_id = COALESCE(user_asset_refs.model_id, p_model_id),
        prompt = COALESCE(user_asset_refs.prompt, p_prompt),
        metadata = user_asset_refs.metadata || COALESCE(
            p_ref_metadata, '{}'::JSONB
        ),
        updated_at = NOW()
    WHERE id = v_ref.id
    RETURNING * INTO v_ref;

    RETURN jsonb_build_object(
        'ref', to_jsonb(v_ref), 'created', v_created
    );
END
$$;


ALTER FUNCTION public._bind_user_asset_ref(p_asset_id uuid, p_ref_key text, p_actor_user_id uuid, p_org_id uuid, p_source_type text, p_source_kind text, p_ref_kind text, p_conversation_id uuid, p_source_message_id uuid, p_source_task_id uuid, p_source_generation_id uuid, p_source_attachment_id uuid, p_content_index integer, p_model_id text, p_prompt text, p_ref_metadata jsonb, p_created_at timestamp with time zone) OWNER TO everydayai;

--
-- Name: _configuration_scope_id(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public._configuration_scope_id(p_scope_kind text, p_org_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT CASE p_scope_kind
        WHEN 'organization' THEN p_org_id::TEXT
        WHEN 'user' THEN p_user_id::TEXT
        ELSE NULL
    END
$$;


ALTER FUNCTION public._configuration_scope_id(p_scope_kind text, p_org_id uuid, p_user_id uuid) OWNER TO everydayai;

--
-- Name: _disable_configuration_entry(text, uuid, uuid, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public._disable_configuration_entry(p_scope_kind text, p_org_id uuid, p_user_id uuid, p_config_key text, p_expected_version bigint, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_entry public.configuration_entries%ROWTYPE;
    v_new_version BIGINT;
BEGIN
    PERFORM public._assert_configuration_key_scope(
        p_config_key, p_scope_kind
    );
    SELECT * INTO v_entry
      FROM public.configuration_entries
     WHERE scope_kind = p_scope_kind
       AND org_id IS NOT DISTINCT FROM p_org_id
       AND user_id IS NOT DISTINCT FROM p_user_id
       AND config_key = p_config_key
     FOR UPDATE;
    IF NOT FOUND THEN
        IF p_expected_version <> 0 THEN
            RAISE EXCEPTION 'CONFIG_VERSION_CONFLICT'
                USING ERRCODE = '40001';
        END IF;
        RETURN jsonb_build_object(
            'key', p_config_key, 'configured', FALSE,
            'deleted', FALSE, 'version', 0
        );
    END IF;
    IF v_entry.version <> p_expected_version THEN
        RAISE EXCEPTION 'CONFIG_VERSION_CONFLICT'
            USING ERRCODE = '40001';
    END IF;
    IF v_entry.status = 'disabled' THEN
        RETURN jsonb_build_object(
            'key', p_config_key, 'configured', FALSE,
            'deleted', FALSE, 'version', v_entry.version
        );
    END IF;
    v_new_version := v_entry.version + 1;
    UPDATE public.configuration_entries
       SET status = 'disabled', version = v_new_version,
           updated_by = p_actor, updated_at = NOW()
     WHERE id = v_entry.id;
    IF v_entry.secret_id IS NOT NULL THEN
        UPDATE public.secret_records
           SET status = 'revoked', updated_by = p_actor, updated_at = NOW()
         WHERE id = v_entry.secret_id;
    END IF;
    RETURN jsonb_build_object(
        'key', p_config_key, 'configured', FALSE,
        'deleted', TRUE, 'version', v_new_version
    );
END;
$$;


ALTER FUNCTION public._disable_configuration_entry(p_scope_kind text, p_org_id uuid, p_user_id uuid, p_config_key text, p_expected_version bigint, p_actor uuid) OWNER TO everydayai_owner;

--
-- Name: _list_configuration_status(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public._list_configuration_status(p_scope_kind text, p_org_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'key', definition.config_key,
        'configured', entry.status = 'active',
        'source', CASE WHEN entry.status = 'active' THEN p_scope_kind END,
        'version', COALESCE(entry.version, 0),
        'updated_at', entry.updated_at
    ) ORDER BY definition.config_key), '[]'::JSONB)
    FROM public.configuration_definitions definition
    LEFT JOIN public.configuration_entries entry
      ON entry.definition_version = definition.definition_version
     AND entry.config_key = definition.config_key
     AND entry.scope_kind = p_scope_kind
     AND entry.org_id IS NOT DISTINCT FROM p_org_id
     AND entry.user_id IS NOT DISTINCT FROM p_user_id
    WHERE definition.active
      AND definition.contract_json->'allowed_scopes' ? p_scope_kind
$$;


ALTER FUNCTION public._list_configuration_status(p_scope_kind text, p_org_id uuid, p_user_id uuid) OWNER TO everydayai_owner;

--
-- Name: _project_configuration_entry(uuid, boolean); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public._project_configuration_entry(p_entry_id uuid, p_required boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_entry public.configuration_entries%ROWTYPE;
    v_definition public.configuration_definitions%ROWTYPE;
    v_secret public.secret_records%ROWTYPE;
BEGIN
    SELECT * INTO STRICT v_entry
      FROM public.configuration_entries
     WHERE id = p_entry_id;
    SELECT * INTO STRICT v_definition
      FROM public.configuration_definitions
     WHERE definition_version = v_entry.definition_version
       AND config_key = v_entry.config_key
       AND active;
    IF v_definition.contract_json->>'value_kind' <> 'secret' THEN
        RETURN jsonb_build_object(
            'key', v_entry.config_key, 'required', p_required,
            'configured', TRUE, 'source', v_entry.scope_kind,
            'scope_id', public._configuration_scope_id(
                v_entry.scope_kind, v_entry.org_id, v_entry.user_id
            ),
            'version', v_entry.version, 'value_kind',
            v_definition.contract_json->>'value_kind',
            'value_json', v_entry.value_json
        );
    END IF;
    SELECT * INTO v_secret
      FROM public.secret_records
     WHERE id = v_entry.secret_id;
    IF NOT FOUND
       OR v_secret.status <> 'active'
       OR (v_secret.expires_at IS NOT NULL AND v_secret.expires_at <= NOW())
       OR v_secret.scope_kind <> v_entry.scope_kind
       OR v_secret.org_id IS DISTINCT FROM v_entry.org_id
       OR v_secret.user_id IS DISTINCT FROM v_entry.user_id
       OR v_secret.payload_version <> v_entry.version
       OR v_secret.secret_name IS DISTINCT FROM
          v_definition.contract_json->>'secret_name' THEN
        RAISE EXCEPTION 'CONFIG_SECRET_UNAVAILABLE'
            USING ERRCODE = '55000';
    END IF;
    RETURN jsonb_build_object(
        'key', v_entry.config_key, 'required', p_required,
        'configured', TRUE, 'source', v_entry.scope_kind,
        'scope_id', public._configuration_scope_id(
            v_entry.scope_kind, v_entry.org_id, v_entry.user_id
        ),
        'version', v_entry.version, 'value_kind', 'secret',
        'secret_ref', jsonb_build_object(
            'secret_name', v_secret.secret_name,
            'payload_ciphertext', v_secret.payload_ciphertext,
            'wrapped_dek', v_secret.wrapped_dek,
            'kek_version', v_secret.kek_version,
            'payload_version', v_secret.payload_version
        )
    );
EXCEPTION
    WHEN no_data_found THEN
        RAISE EXCEPTION 'CONFIG_REGISTRY_DRIFT'
            USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION public._project_configuration_entry(p_entry_id uuid, p_required boolean) OWNER TO everydayai;

--
-- Name: _record_governance_audit(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public._record_governance_audit(p_org_id uuid, p_authority text, p_action text, p_target_kind text, p_target_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_audit_id UUID;
BEGIN
    IF p_authority NOT IN ('super_admin', 'owner', 'admin', 'self')
       OR COALESCE(BTRIM(p_action), '') = ''
       OR COALESCE(BTRIM(p_target_kind), '') = ''
       OR p_metadata IS NULL
       OR jsonb_typeof(p_metadata) <> 'object' THEN
        RAISE EXCEPTION 'GOVERNANCE_AUDIT_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.governance_audit_log(
        org_id, actor_id, authority, action, target_kind,
        target_key, request_id, metadata
    ) VALUES (
        p_org_id, public.tenant_actor_user_id(), p_authority,
        BTRIM(p_action), BTRIM(p_target_kind), p_target_key,
        NULLIF(current_setting('app.request_id', TRUE), ''), p_metadata
    ) RETURNING id INTO v_audit_id;
    RETURN v_audit_id;
END;
$$;


ALTER FUNCTION public._record_governance_audit(p_org_id uuid, p_authority text, p_action text, p_target_kind text, p_target_key text, p_metadata jsonb) OWNER TO everydayai_owner;

--
-- Name: _resolve_configuration_bundle(text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public._resolve_configuration_bundle(p_definition_version text, p_bundle_name text, p_actor_user_id uuid, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_contract JSONB;
    v_key TEXT;
    v_items JSONB := '[]'::JSONB;
BEGIN
    SELECT contract_json INTO STRICT v_contract
      FROM public.configuration_bundle_definitions
     WHERE definition_version = p_definition_version
       AND bundle_name = p_bundle_name
       AND active;
    FOR v_key IN
        SELECT jsonb_array_elements_text(v_contract->'required_keys')
    LOOP
        v_items := v_items || jsonb_build_array(
            public._resolve_effective_configuration_item(
                p_definition_version, v_key, TRUE,
                p_actor_user_id, p_org_id
            )
        );
    END LOOP;
    FOR v_key IN
        SELECT jsonb_array_elements_text(v_contract->'optional_keys')
    LOOP
        v_items := v_items || jsonb_build_array(
            public._resolve_effective_configuration_item(
                p_definition_version, v_key, FALSE,
                p_actor_user_id, p_org_id
            )
        );
    END LOOP;
    RETURN jsonb_build_object(
        'bundle', p_bundle_name,
        'definition_version', p_definition_version,
        'items', v_items
    );
EXCEPTION
    WHEN no_data_found THEN
        RAISE EXCEPTION 'CONFIG_BUNDLE_UNKNOWN'
            USING ERRCODE = '22023';
END;
$$;


ALTER FUNCTION public._resolve_configuration_bundle(p_definition_version text, p_bundle_name text, p_actor_user_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: _resolve_effective_configuration_item(text, text, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public._resolve_effective_configuration_item(p_definition_version text, p_config_key text, p_required boolean, p_actor_user_id uuid, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_definition public.configuration_definitions%ROWTYPE;
    v_policy public.configuration_policies%ROWTYPE;
    v_user_allowed BOOLEAN := FALSE;
    v_entry_id UUID;
BEGIN
    SELECT * INTO STRICT v_definition
      FROM public.configuration_definitions
     WHERE definition_version = p_definition_version
       AND config_key = p_config_key
       AND active;
    IF p_org_id IS NOT NULL THEN
        SELECT * INTO v_policy
          FROM public.configuration_policies
         WHERE org_id = p_org_id
           AND config_key = p_config_key;
    END IF;
    v_user_allowed := p_actor_user_id IS NOT NULL
        AND v_definition.contract_json->'allowed_scopes' ? 'user'
        AND (
            (p_org_id IS NULL
             AND v_definition.contract_json->>'user_override'
                 IN ('allow', 'org_policy'))
            OR
            (p_org_id IS NOT NULL
             AND COALESCE(v_policy.locked, FALSE) = FALSE
             AND (
                 v_definition.contract_json->>'user_override' = 'allow'
                 OR (
                     v_definition.contract_json->>'user_override' = 'org_policy'
                     AND COALESCE(v_policy.allow_user_override, FALSE)
                 )
             ))
        );

    SELECT candidate.id INTO v_entry_id
      FROM (
        SELECT entry.id, 1 AS priority
          FROM public.configuration_entries entry
         WHERE v_user_allowed
           AND entry.scope_kind = 'user'
           AND entry.user_id = p_actor_user_id
           AND entry.org_id IS NULL
           AND entry.config_key = p_config_key
           AND entry.definition_version = p_definition_version
           AND entry.status = 'active'
        UNION ALL
        SELECT entry.id, 2 AS priority
          FROM public.configuration_entries entry
         WHERE p_org_id IS NOT NULL
           AND v_definition.contract_json->'allowed_scopes' ? 'organization'
           AND entry.scope_kind = 'organization'
           AND entry.org_id = p_org_id
           AND entry.user_id IS NULL
           AND entry.config_key = p_config_key
           AND entry.definition_version = p_definition_version
           AND entry.status = 'active'
        UNION ALL
        SELECT entry.id, 3 AS priority
          FROM public.configuration_entries entry
         WHERE v_definition.contract_json->'allowed_scopes' ? 'platform'
           AND v_definition.contract_json->>'fallback_policy'
               IN ('platform', 'org_then_platform')
           AND entry.scope_kind = 'platform'
           AND entry.org_id IS NULL
           AND entry.user_id IS NULL
           AND entry.config_key = p_config_key
           AND entry.definition_version = p_definition_version
           AND entry.status = 'active'
      ) candidate
     ORDER BY candidate.priority
     LIMIT 1;

    IF NOT FOUND THEN
        IF p_required THEN
            RAISE EXCEPTION 'CONFIG_BUNDLE_INCOMPLETE'
                USING ERRCODE = 'P0002';
        END IF;
        RETURN jsonb_build_object(
            'key', p_config_key, 'required', FALSE, 'configured', FALSE
        );
    END IF;
    RETURN public._project_configuration_entry(
        v_entry_id,
        p_required
    );
EXCEPTION
    WHEN no_data_found THEN
        RAISE EXCEPTION 'CONFIG_REGISTRY_DRIFT'
            USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION public._resolve_effective_configuration_item(p_definition_version text, p_config_key text, p_required boolean, p_actor_user_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: _resolve_user_asset(uuid, text, text, text, text, text, text, text, text, text, text, text, bigint, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public._resolve_user_asset(p_org_id uuid, p_storage_scope text, p_storage_owner_key text, p_storage_provider text, p_storage_key text, p_media_type text, p_original_url text, p_thumbnail_url text, p_download_url text, p_workspace_path text, p_name text, p_mime_type text, p_size bigint, p_content_sha256 text, p_asset_metadata jsonb, p_created_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_asset user_assets%ROWTYPE;
    v_created BOOLEAN := FALSE;
BEGIN
    SELECT * INTO v_asset
      FROM user_assets
     WHERE org_id IS NOT DISTINCT FROM p_org_id
       AND storage_scope = p_storage_scope
       AND storage_owner_key = p_storage_owner_key
       AND storage_provider = p_storage_provider
       AND storage_key = p_storage_key
     FOR UPDATE;

    IF v_asset.id IS NULL THEN
        BEGIN
            INSERT INTO user_assets (
                org_id, storage_scope, storage_owner_key, storage_provider,
                storage_key, media_type, original_url, thumbnail_url,
                download_url, workspace_path, name, mime_type, size,
                content_sha256, metadata, created_at, updated_at
            ) VALUES (
                p_org_id, p_storage_scope, p_storage_owner_key,
                p_storage_provider, p_storage_key, p_media_type,
                p_original_url, p_thumbnail_url, p_download_url,
                p_workspace_path, p_name, p_mime_type, p_size,
                p_content_sha256, COALESCE(p_asset_metadata, '{}'::JSONB),
                COALESCE(p_created_at, NOW()), NOW()
            ) RETURNING * INTO v_asset;
            v_created := TRUE;
        EXCEPTION WHEN unique_violation THEN
            SELECT * INTO v_asset
              FROM user_assets
             WHERE org_id IS NOT DISTINCT FROM p_org_id
               AND storage_scope = p_storage_scope
               AND storage_owner_key = p_storage_owner_key
               AND storage_provider = p_storage_provider
               AND storage_key = p_storage_key
             FOR UPDATE;
        END;
    END IF;

    IF v_asset.id IS NULL OR v_asset.media_type <> p_media_type THEN
        RAISE EXCEPTION 'USER_ASSET_IDENTITY_CONFLICT';
    END IF;

    UPDATE user_assets SET
        thumbnail_url = COALESCE(user_assets.thumbnail_url, p_thumbnail_url),
        workspace_path = COALESCE(user_assets.workspace_path, p_workspace_path),
        mime_type = COALESCE(user_assets.mime_type, p_mime_type),
        size = COALESCE(user_assets.size, p_size),
        content_sha256 = COALESCE(
            user_assets.content_sha256, p_content_sha256
        ),
        metadata = user_assets.metadata || COALESCE(
            p_asset_metadata, '{}'::JSONB
        ),
        updated_at = NOW()
    WHERE id = v_asset.id
    RETURNING * INTO v_asset;

    RETURN jsonb_build_object(
        'asset', to_jsonb(v_asset), 'created', v_created
    );
END
$$;


ALTER FUNCTION public._resolve_user_asset(p_org_id uuid, p_storage_scope text, p_storage_owner_key text, p_storage_provider text, p_storage_key text, p_media_type text, p_original_url text, p_thumbnail_url text, p_download_url text, p_workspace_path text, p_name text, p_mime_type text, p_size bigint, p_content_sha256 text, p_asset_metadata jsonb, p_created_at timestamp with time zone) OWNER TO everydayai;

--
-- Name: _validate_configuration_material(text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public._validate_configuration_material(p_definition_version text, p_config_key text, p_scope_kind text, p_value_json jsonb, p_secret_envelope jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_contract JSONB;
    v_value_kind TEXT;
BEGIN
    SELECT contract_json INTO v_contract
      FROM public.configuration_definitions
     WHERE definition_version = p_definition_version
       AND config_key = p_config_key
       AND active;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'CONFIG_KEY_UNKNOWN'
            USING ERRCODE = '22023';
    END IF;
    IF NOT (v_contract->'allowed_scopes' ? p_scope_kind) THEN
        RAISE EXCEPTION 'CONFIG_SCOPE_FORBIDDEN'
            USING ERRCODE = '42501';
    END IF;

    v_value_kind := v_contract->>'value_kind';
    IF v_value_kind = 'secret' THEN
        IF p_value_json IS NOT NULL
           OR jsonb_typeof(p_secret_envelope) <> 'object'
           OR NOT (p_secret_envelope ?& ARRAY[
               'payload_ciphertext', 'wrapped_dek', 'kek_version'
           ])
           OR (SELECT COUNT(*) FROM jsonb_object_keys(p_secret_envelope)) <> 3
           OR COALESCE(p_secret_envelope->>'payload_ciphertext', '') = ''
           OR LENGTH(p_secret_envelope->>'payload_ciphertext') > 1048576
           OR COALESCE(p_secret_envelope->>'wrapped_dek', '') = ''
           OR LENGTH(p_secret_envelope->>'wrapped_dek') > 16384
           OR COALESCE(p_secret_envelope->>'kek_version', '') = ''
           OR LENGTH(p_secret_envelope->>'kek_version') > 64 THEN
            RAISE EXCEPTION 'CONFIG_VALUE_INVALID'
                USING ERRCODE = '22023';
        END IF;
    ELSIF p_secret_envelope IS NOT NULL OR p_value_json IS NULL
       OR (v_value_kind = 'string' AND jsonb_typeof(p_value_json) <> 'string')
       OR (v_value_kind = 'integer' AND jsonb_typeof(p_value_json) <> 'number')
       OR (v_value_kind = 'boolean' AND jsonb_typeof(p_value_json) <> 'boolean')
       OR (v_value_kind = 'json'
           AND jsonb_typeof(p_value_json) NOT IN ('array', 'object')) THEN
        RAISE EXCEPTION 'CONFIG_VALUE_INVALID'
            USING ERRCODE = '22023';
    END IF;
    RETURN v_contract;
END;
$$;


ALTER FUNCTION public._validate_configuration_material(p_definition_version text, p_config_key text, p_scope_kind text, p_value_json jsonb, p_secret_envelope jsonb) OWNER TO everydayai;

--
-- Name: _write_configuration_entry(text, uuid, uuid, text, text, jsonb, jsonb, bigint, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public._write_configuration_entry(p_scope_kind text, p_org_id uuid, p_user_id uuid, p_definition_version text, p_config_key text, p_value_json jsonb, p_secret_envelope jsonb, p_expected_version bigint, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_contract JSONB;
    v_entry public.configuration_entries%ROWTYPE;
    v_new_version BIGINT;
    v_secret_id UUID;
    v_secret_name TEXT;
BEGIN
    IF p_expected_version < 0 OR (
        (p_scope_kind = 'platform' AND (p_org_id IS NOT NULL OR p_user_id IS NOT NULL))
        OR (p_scope_kind = 'organization' AND (p_org_id IS NULL OR p_user_id IS NOT NULL))
        OR (p_scope_kind = 'user' AND (p_org_id IS NOT NULL OR p_user_id IS NULL))
        OR p_scope_kind NOT IN ('platform', 'organization', 'user')
    ) THEN
        RAISE EXCEPTION 'CONFIG_SCOPE_FORBIDDEN'
            USING ERRCODE = '42501';
    END IF;
    v_contract := public._validate_configuration_material(
        p_definition_version, p_config_key, p_scope_kind,
        p_value_json, p_secret_envelope
    );
    SELECT * INTO v_entry
      FROM public.configuration_entries
     WHERE scope_kind = p_scope_kind
       AND org_id IS NOT DISTINCT FROM p_org_id
       AND user_id IS NOT DISTINCT FROM p_user_id
       AND config_key = p_config_key
     FOR UPDATE;
    IF NOT FOUND THEN
        IF p_expected_version <> 0 THEN
            RAISE EXCEPTION 'CONFIG_VERSION_CONFLICT'
                USING ERRCODE = '40001';
        END IF;
        v_new_version := 1;
    ELSE
        IF v_entry.version <> p_expected_version THEN
            RAISE EXCEPTION 'CONFIG_VERSION_CONFLICT'
                USING ERRCODE = '40001';
        END IF;
        v_new_version := v_entry.version + 1;
    END IF;

    IF v_contract->>'value_kind' = 'secret' THEN
        v_secret_name := v_contract->>'secret_name';
        UPDATE public.secret_records
           SET status = 'retired', updated_by = p_actor, updated_at = NOW()
         WHERE scope_kind = p_scope_kind
           AND org_id IS NOT DISTINCT FROM p_org_id
           AND user_id IS NOT DISTINCT FROM p_user_id
           AND secret_name = v_secret_name
           AND status = 'active';
        INSERT INTO public.secret_records(
            scope_kind, org_id, user_id, secret_name,
            payload_ciphertext, wrapped_dek, kek_version,
            payload_version, created_by, updated_by
        ) VALUES (
            p_scope_kind, p_org_id, p_user_id, v_secret_name,
            p_secret_envelope->>'payload_ciphertext',
            p_secret_envelope->>'wrapped_dek',
            p_secret_envelope->>'kek_version',
            v_new_version, p_actor, p_actor
        ) RETURNING id INTO v_secret_id;
    ELSIF v_entry.secret_id IS NOT NULL THEN
        UPDATE public.secret_records
           SET status = 'revoked', updated_by = p_actor, updated_at = NOW()
         WHERE id = v_entry.secret_id;
    END IF;

    INSERT INTO public.configuration_entries(
        scope_kind, org_id, user_id, definition_version, config_key,
        value_json, secret_id, status, version, updated_by, updated_at
    ) VALUES (
        p_scope_kind, p_org_id, p_user_id, p_definition_version, p_config_key,
        p_value_json, v_secret_id, 'active', v_new_version, p_actor, NOW()
    )
    ON CONFLICT (scope_kind, org_id, user_id, config_key) DO UPDATE SET
        definition_version = EXCLUDED.definition_version,
        value_json = EXCLUDED.value_json,
        secret_id = EXCLUDED.secret_id,
        status = 'active',
        version = EXCLUDED.version,
        updated_by = EXCLUDED.updated_by,
        updated_at = EXCLUDED.updated_at;
    RETURN jsonb_build_object(
        'key', p_config_key, 'configured', TRUE,
        'source', p_scope_kind, 'version', v_new_version
    );
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'CONFIG_VERSION_CONFLICT'
            USING ERRCODE = '40001';
END;
$$;


ALTER FUNCTION public._write_configuration_entry(p_scope_kind text, p_org_id uuid, p_user_id uuid, p_definition_version text, p_config_key text, p_value_json jsonb, p_secret_envelope jsonb, p_expected_version bigint, p_actor uuid) OWNER TO everydayai;

--
-- Name: accept_chat_ecom_plan_image(uuid, uuid, jsonb, uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.accept_chat_ecom_plan_image(p_parent_task_id uuid, p_execution_token uuid, p_snapshot jsonb, p_org_id uuid, p_plan_id uuid, p_plan_revision integer, p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE prior public.ecom_image_plan_acceptances%ROWTYPE; result JSONB;
        plan public.ecom_image_plans%ROWTYPE; parent public.tasks%ROWTYPE; item JSONB;
        generation_id UUID; expected_refs JSONB; submitted_refs JSONB; expected_generation_refs JSONB; submitted_generation_refs JSONB;
BEGIN
    IF SESSION_USER <> 'everydayai' OR current_setting('app.access_kind',TRUE) <> 'runtime'
       OR current_setting('app.actor_user_id',TRUE) IS NULL THEN
        RAISE EXCEPTION 'ECOM_PLAN_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
    SELECT * INTO plan FROM public.ecom_image_plans WHERE id=p_plan_id FOR SHARE;
    SELECT * INTO parent FROM public.tasks WHERE id=p_parent_task_id;
    IF parent.status <> 'running' OR parent.execution_token IS DISTINCT FROM p_execution_token
       OR p_execution_token IS NULL OR parent.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',true),'')::uuid
       OR parent.org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'ECOM_PLAN_PARENT_DENIED' USING ERRCODE='42501';
    END IF;
    generation_id=(parent.request_params->'_ecom_workflow'->>'generation_run_id')::uuid;
    IF parent.request_params->'_ecom_workflow'->>'kind'='main_images'
       AND parent.request_params->'_ecom_workflow'->>'plan_id' IS DISTINCT FROM p_plan_id::text THEN
        RAISE EXCEPTION 'ECOM_PLAN_WORKFLOW_MISMATCH' USING ERRCODE='42501';
    END IF;
    SELECT entry.value INTO item FROM jsonb_array_elements(COALESCE(plan.items,'[]'::jsonb)) AS entry(value)
        WHERE entry.value->>'item_id'=p_item_id::text LIMIT 1;
    SELECT COALESCE(jsonb_agg(entry.value - 'source_id' ORDER BY entry.ordinality),'[]'::jsonb)
        INTO expected_refs FROM jsonb_array_elements(COALESCE(item->'references','[]'::jsonb))
            WITH ORDINALITY AS entry(value,ordinality);
    SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
            'resource_ref',entry.value->'resource_ref','file_id',entry.value->'file_id',
            'asset_id',entry.value->'asset_id','message_id',entry.value->'message_id',
            'content_index',entry.value->'content_index','role',entry.value->'role'))
            ORDER BY entry.ordinality),'[]'::jsonb)
        INTO submitted_refs FROM jsonb_array_elements(COALESCE(p_snapshot->'references','[]'::jsonb))
            WITH ORDINALITY AS entry(value,ordinality);
    SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
            'resource_ref',selected.value->'resource_ref','file_id',selected.value->'file_id',
            'asset_id',selected.value->'asset_id','message_id',selected.value->'message_id',
            'content_index',selected.value->'content_index','role',selected.value->'role',
            'source_id',selected.value->'source_id','content_sha256',facts.value->'content_sha256',
            'file_version',facts.value->'file_version','workspace_path',facts.value->'workspace_path'))
            ORDER BY selected.ordinality),'[]'::jsonb)
        INTO expected_generation_refs
        FROM jsonb_array_elements(COALESCE(item->'references','[]'::jsonb))
            WITH ORDINALITY AS selected(value,ordinality)
        LEFT JOIN LATERAL (
            SELECT resolved.value FROM jsonb_array_elements(
                COALESCE(plan.input_snapshot->'resolved_references','[]'::jsonb)) AS resolved(value)
            WHERE resolved.value->>'source_id'=selected.value->>'source_id' LIMIT 1
        ) AS facts ON TRUE;
    SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
            'resource_ref',entry.value->'resource_ref','file_id',entry.value->'file_id',
            'asset_id',entry.value->'asset_id','message_id',entry.value->'message_id',
            'content_index',entry.value->'content_index','role',entry.value->'role',
            'source_id',entry.value->'source_id','content_sha256',entry.value->'content_sha256',
            'file_version',entry.value->'file_version','workspace_path',entry.value->'workspace_path'))
            ORDER BY entry.ordinality),'[]'::jsonb)
        INTO submitted_generation_refs FROM jsonb_array_elements(COALESCE(p_snapshot->'references','[]'::jsonb))
            WITH ORDINALITY AS entry(value,ordinality);
    IF plan.id IS NULL OR parent.id IS NULL OR plan.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',true),'')::uuid
       OR plan.org_id IS DISTINCT FROM p_org_id OR plan.conversation_id IS DISTINCT FROM parent.conversation_id
       OR plan.status <> 'ready' OR plan.plan_revision IS DISTINCT FROM p_plan_revision OR item IS NULL
       OR item->>'request_text' IS DISTINCT FROM p_snapshot->>'prompt'
       OR item->>'request_text_sha256' IS DISTINCT FROM p_snapshot->>'prompt_sha256'
       OR item->>'aspect_ratio' IS DISTINCT FROM plan.target_size->>'aspect_ratio'
       OR p_snapshot->>'aspect_ratio' IS DISTINCT FROM item->>'aspect_ratio'
       OR p_snapshot->>'resolution' IS DISTINCT FROM plan.target_size->>'resolution'
       OR expected_refs IS DISTINCT FROM submitted_refs
       OR expected_generation_refs IS DISTINCT FROM submitted_generation_refs THEN
        RAISE EXCEPTION 'ECOM_PLAN_SOURCE_DENIED' USING ERRCODE='42501';
    END IF;
    IF p_snapshot->'origin'->'plan_source'->>'plan_id' IS DISTINCT FROM p_plan_id::text
       OR (p_snapshot->'origin'->'plan_source'->>'revision')::integer IS DISTINCT FROM p_plan_revision
       OR p_snapshot->'origin'->'plan_source'->>'item_id' IS DISTINCT FROM p_item_id::text
       OR p_snapshot->'origin'->'plan_source'->>'request_text_sha256' IS DISTINCT FROM item->>'request_text_sha256' THEN
        RAISE EXCEPTION 'ECOM_PLAN_SOURCE_DENIED' USING ERRCODE='42501';
    END IF;
    INSERT INTO public.ecom_image_plan_acceptances(parent_task_id,plan_id,plan_revision,item_id,request_hash,receipt,generation_run_id)
        VALUES(p_parent_task_id,p_plan_id,p_plan_revision,p_item_id,p_snapshot->>'prompt_sha256','{}'::jsonb,generation_id)
        ON CONFLICT DO NOTHING;
    SELECT * INTO prior FROM public.ecom_image_plan_acceptances WHERE ((generation_id IS NOT NULL AND generation_run_id=generation_id)
            OR (generation_id IS NULL AND parent_task_id=p_parent_task_id))
        AND plan_id=p_plan_id AND plan_revision=p_plan_revision AND item_id=p_item_id FOR UPDATE;
    IF prior.parent_task_id IS NULL THEN RAISE EXCEPTION 'ECOM_PLAN_ACCEPTANCE_CONFLICT' USING ERRCODE='22023'; END IF;
    IF prior.receipt <> '{}'::jsonb THEN
        IF prior.request_hash IS DISTINCT FROM p_snapshot->>'prompt_sha256' THEN
            RAISE EXCEPTION 'ECOM_PLAN_ACCEPTANCE_CONFLICT' USING ERRCODE='22023';
        END IF;
        RETURN prior.receipt || jsonb_build_object('outcome','replay');
    END IF;
    result := public.accept_chat_image_request(p_parent_task_id,p_execution_token,p_snapshot,p_org_id);
    UPDATE public.ecom_image_plan_acceptances SET receipt=result WHERE parent_task_id=prior.parent_task_id
        AND plan_id=p_plan_id AND plan_revision=p_plan_revision AND item_id=p_item_id;
    RETURN result;
END $$;


ALTER FUNCTION public.accept_chat_ecom_plan_image(p_parent_task_id uuid, p_execution_token uuid, p_snapshot jsonb, p_org_id uuid, p_plan_id uuid, p_plan_revision integer, p_item_id uuid) OWNER TO everydayai_owner;

--
-- Name: accept_chat_image_request(uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.accept_chat_image_request(p_parent_task_id uuid, p_execution_token uuid, p_snapshot jsonb, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    v_parent public.tasks%ROWTYPE;
    v_child public.tasks%ROWTYPE;
    v_conversation public.conversations%ROWTYPE;
    v_actor UUID := NULLIF(current_setting('app.actor_user_id', TRUE), '')::UUID;
    v_org UUID := NULLIF(current_setting('app.org_id', TRUE), '')::UUID;
    v_origin JSONB := p_snapshot->'origin';
    v_budget JSONB;
    v_call TEXT := v_origin->>'tool_call_id';
    v_count INTEGER;
    v_cost INTEGER;
    v_max_count INTEGER;
    v_max_cost INTEGER;
    v_task UUID := gen_random_uuid();
    v_message UUID := gen_random_uuid();
BEGIN
    IF SESSION_USER <> 'everydayai'
       OR current_setting('app.access_kind', TRUE) IS DISTINCT FROM 'runtime'
       OR v_actor IS NULL OR v_org IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'CHAT_IMAGE_SCOPE_DENIED' USING ERRCODE = '42501';
    END IF;
    IF p_snapshot IS NULL OR jsonb_typeof(p_snapshot) <> 'object'
       OR p_snapshot->>'schema_version' IS DISTINCT FROM '1'
       OR COALESCE(p_snapshot->>'mode', '') NOT IN ('text_to_image', 'image_to_image')
       OR p_snapshot->>'num_images' IS DISTINCT FROM '1'
       OR NULLIF(BTRIM(p_snapshot->>'prompt'), '') IS NULL
       OR COALESCE(p_snapshot->>'request_hash', '') !~ '^[0-9a-f]{64}$'
       OR COALESCE(v_call, '') !~ '^.{1,200}$'
       OR jsonb_typeof(p_snapshot->'references') IS DISTINCT FROM 'array'
       OR octet_length(p_snapshot::TEXT) > 131072 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_INPUT_INVALID' USING ERRCODE = '22023';
    END IF;
    v_cost := (p_snapshot->>'estimated_credits')::INTEGER;
    v_max_count := (p_snapshot->'budget'->>'max_requests')::INTEGER;
    v_max_cost := (p_snapshot->'budget'->>'max_credits')::INTEGER;
    IF v_cost IS NULL OR v_cost < 1 OR v_max_count IS NULL OR v_max_count NOT BETWEEN 1 AND 15
       OR v_max_cost IS NULL OR v_max_cost NOT BETWEEN 1 AND 300 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_BUDGET_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_parent FROM public.tasks WHERE id = p_parent_task_id FOR UPDATE;
    IF NOT FOUND OR v_parent.type <> 'chat' OR v_parent.user_id IS DISTINCT FROM v_actor
       OR v_parent.org_id IS DISTINCT FROM p_org_id
       OR v_origin->>'parent_task_id' IS DISTINCT FROM p_parent_task_id::TEXT
       OR v_origin->>'actor_user_id' IS DISTINCT FROM v_actor::TEXT
       OR v_origin->>'org_id' IS DISTINCT FROM p_org_id::TEXT
       OR v_origin->>'conversation_id' IS DISTINCT FROM v_parent.conversation_id::TEXT
       OR v_origin->>'workspace_owner_id' IS DISTINCT FROM v_actor::TEXT
       OR v_origin->>'context_scope' IS DISTINCT FROM 'user'
       OR v_origin->>'turn_id' IS DISTINCT FROM v_parent.turn_id::TEXT
       OR v_origin->>'input_message_id' IS DISTINCT FROM v_parent.input_message_id::TEXT
       OR v_origin->>'base_context_revision' IS DISTINCT FROM v_parent.base_context_revision::TEXT
       OR v_parent.turn_id IS NULL OR v_parent.input_message_id IS NULL
       OR v_parent.base_context_revision IS NULL
       OR (v_parent.delivery_context @> '{"actor":true}') IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'CHAT_IMAGE_PARENT_DENIED' USING ERRCODE = '42501';
    END IF;
    IF p_execution_token IS NULL OR v_parent.execution_token IS DISTINCT FROM p_execution_token THEN
        RAISE EXCEPTION 'CHAT_IMAGE_FENCING_LOST' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_conversation FROM public.conversations WHERE id = v_parent.conversation_id;
    IF NOT FOUND OR v_conversation.user_id IS DISTINCT FROM v_actor
       OR v_conversation.org_id IS DISTINCT FROM p_org_id
       OR COALESCE(v_conversation.scope_type, 'user') <> 'user'
       OR NOT EXISTS (SELECT 1 FROM public.users WHERE id = v_actor AND status::TEXT = 'active')
       OR (p_org_id IS NOT NULL AND (NOT EXISTS (
           SELECT 1 FROM public.org_members WHERE org_id = p_org_id AND user_id = v_actor AND status = 'active'
       ) OR NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id AND status = 'active'))) THEN
        RAISE EXCEPTION 'CHAT_IMAGE_IDENTITY_DENIED' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_child FROM public.tasks
     WHERE type = 'image' AND request_params->'_media_request_v1'->'origin'->>'parent_task_id' = p_parent_task_id::TEXT
       AND request_params->'_media_request_v1'->'origin'->>'tool_call_id' = v_call;
    IF FOUND THEN
        IF v_child.request_params->'_media_request_v1' IS DISTINCT FROM p_snapshot THEN
            RAISE EXCEPTION 'CHAT_IMAGE_CALL_CONFLICT' USING ERRCODE = '22023';
        END IF;
        RETURN jsonb_build_object('outcome','replay','task_id',v_child.id,
            'message_id',v_child.assistant_message_id,
            'submission_state',v_child.request_params->'_media_lifecycle_v1'->>'phase');
    END IF;
    IF v_parent.status <> 'running' THEN
        RAISE EXCEPTION 'CHAT_IMAGE_PARENT_STOPPED' USING ERRCODE = '55000';
    END IF;
    v_budget := COALESCE(v_parent.request_params->'_media_budget_v1', '{}'::JSONB);
    -- Keep the first accepted bounds; random variants and later requests cannot raise them.
    v_max_count := LEAST(v_max_count, COALESCE((v_budget->>'max_requests')::INTEGER, v_max_count));
    v_max_cost := LEAST(v_max_cost, COALESCE((v_budget->>'max_credits')::INTEGER, v_max_cost));
    v_count := COALESCE((v_budget->>'requests')::INTEGER, 0);
    IF COALESCE((v_budget->>'reserved_credits')::INTEGER, 0)
       + COALESCE((v_parent.request_params->'_media_retry_budget_v1'->>'reserved_credits')::INTEGER, 0) + v_cost > v_max_cost THEN
        RAISE EXCEPTION 'CHAT_IMAGE_BUDGET_EXCEEDED' USING ERRCODE = '54000';
    END IF;
    INSERT INTO public.messages(id, conversation_id, org_id, role, content, status, generation_params)
    VALUES (v_message, v_parent.conversation_id, p_org_id, 'assistant', '[{"type":"image","url":null}]', 'pending',
        jsonb_build_object('origin','chat_image','task_id',v_task,'mode',p_snapshot->>'mode',
            'type','image','num_images',1,'submission_state','queued','model',p_snapshot->>'model',
            'aspect_ratio',p_snapshot->>'aspect_ratio','resolution',p_snapshot->>'resolution',
            'size_requirement',p_snapshot->'size_requirement'));
    INSERT INTO public.tasks(id, user_id, org_id, conversation_id, type, status, model_id,
        assistant_message_id, placeholder_message_id, batch_id, image_index, request_params)
    VALUES (v_task, v_actor, p_org_id, v_parent.conversation_id, 'image', 'pending', p_snapshot->>'model',
        v_message, v_message::TEXT, v_task::TEXT, 0,
        jsonb_build_object('_media_request_v1',p_snapshot,
            '_media_lifecycle_v1',jsonb_build_object('phase','queued','attempt',0),
            'prompt',p_snapshot->>'prompt','model',p_snapshot->>'model', 'num_images',1));
    UPDATE public.tasks SET request_params = jsonb_set(COALESCE(request_params,'{}'::JSONB),
        '{_media_budget_v1}', jsonb_build_object('requests',v_count+1,
            'reserved_credits',COALESCE((v_budget->>'reserved_credits')::INTEGER,0)+v_cost,
            'max_requests',v_max_count,'max_credits',v_max_cost)) WHERE id = p_parent_task_id;
    RETURN jsonb_build_object('outcome','accepted','task_id',v_task,'message_id',v_message,'submission_state','queued');
END;
$_$;


ALTER FUNCTION public.accept_chat_image_request(p_parent_task_id uuid, p_execution_token uuid, p_snapshot jsonb, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: accept_chat_image_trial(uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.accept_chat_image_trial(p_trial_id uuid, p_snapshot jsonb, p_result jsonb, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID:=NULLIF(current_setting('app.actor_user_id',TRUE),'')::UUID;
    v_trial public.skill_draft_trial_runs%ROWTYPE; v_change public.change_sets%ROWTYPE;
    v_task public.tasks%ROWTYPE; v_conv public.conversations%ROWTYPE; v_id UUID:=gen_random_uuid();
    v_origin JSONB:=p_snapshot->'origin'; v_cost INTEGER:=(p_snapshot->>'estimated_credits')::INTEGER;
BEGIN
    IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',TRUE) IS DISTINCT FROM 'runtime_admin'
       OR NULLIF(current_setting('app.org_id',TRUE),'')::UUID IS DISTINCT FROM p_org_id
       OR p_org_id IS NULL OR v_actor IS NULL THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TRIAL_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
    SELECT * INTO v_trial FROM public.skill_draft_trial_runs WHERE id=p_trial_id AND org_id=p_org_id
        AND actor_user_id=v_actor FOR UPDATE;
    IF NOT FOUND OR v_trial.mode<>'image'
       OR v_origin->>'trial_id' IS DISTINCT FROM p_trial_id::TEXT
       OR v_origin->>'destination' IS DISTINCT FROM 'skill_trial'
       OR v_origin->>'actor_user_id' IS DISTINCT FROM v_actor::TEXT
       OR v_origin->>'workspace_owner_id' IS DISTINCT FROM v_actor::TEXT
       OR v_origin->>'org_id' IS DISTINCT FROM p_org_id::TEXT
       OR v_origin->>'context_scope' IS DISTINCT FROM 'user'
       OR v_origin->>'candidate_revision' IS DISTINCT FROM v_trial.candidate_revision::TEXT
       OR v_origin->>'content_sha256' IS DISTINCT FROM v_trial.content_sha256
       OR v_origin->>'change_set_id' IS DISTINCT FROM v_trial.change_set_id::TEXT
       OR p_snapshot->>'model' IS DISTINCT FROM v_trial.model_id THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TRIAL_DENIED' USING ERRCODE='42501';
    END IF;
    SELECT * INTO v_task FROM public.tasks WHERE type='image'
        AND request_params->'_media_request_v1'->'origin'->>'trial_id'=p_trial_id::TEXT;
    IF FOUND THEN
        IF v_task.request_params->'_media_request_v1' IS DISTINCT FROM p_snapshot THEN
            RAISE EXCEPTION 'CHAT_IMAGE_TRIAL_CONFLICT' USING ERRCODE='22023';
        END IF;
        RETURN jsonb_build_object('outcome','replay','task_id',v_task.id,'submission_state',v_task.request_params->'_media_lifecycle_v1'->>'phase');
    END IF;
    IF v_trial.status<>'running' OR p_snapshot->>'schema_version' IS DISTINCT FROM '1'
       OR p_snapshot->>'num_images' IS DISTINCT FROM '1' OR v_cost IS NULL OR v_cost NOT BETWEEN 1 AND 200
       OR COALESCE(p_snapshot->>'mode','') NOT IN ('text_to_image','image_to_image')
       OR NULLIF(BTRIM(p_snapshot->>'prompt'),'') IS NULL
       OR COALESCE(jsonb_typeof(p_snapshot->'references'),'')<>'array'
       OR pg_column_size(p_snapshot)>128000 OR p_result IS NULL OR jsonb_typeof(p_result)<>'object' THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TRIAL_REQUEST_INVALID' USING ERRCODE='22023';
    END IF;
    SELECT * INTO v_change FROM public.change_sets WHERE id=v_trial.change_set_id AND org_id=p_org_id FOR SHARE;
    IF NOT FOUND OR v_change.status<>'awaiting_approval' OR v_change.expires_at<=NOW()
       OR v_change.created_by IS DISTINCT FROM v_actor::TEXT OR v_change.resource_type<>'skill_draft'
       OR v_change.revision IS DISTINCT FROM v_trial.candidate_revision
       OR v_change.proposed_snapshot->>'content_sha256' IS DISTINCT FROM v_trial.content_sha256
       OR NOT EXISTS(SELECT 1 FROM public.org_members m JOIN public.users u ON u.id=m.user_id
           JOIN public.organizations o ON o.id=m.org_id WHERE m.org_id=p_org_id AND m.user_id=v_actor
           AND m.status='active' AND m.role IN ('owner','admin') AND u.status='active' AND o.status='active') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TRIAL_CANDIDATE_UNAVAILABLE' USING ERRCODE='42501';
    END IF;
    SELECT * INTO v_conv FROM public.conversations WHERE id=(v_origin->>'conversation_id')::UUID;
    IF NOT FOUND OR v_conv.user_id IS DISTINCT FROM v_actor OR v_conv.org_id IS DISTINCT FROM p_org_id
       OR COALESCE(v_conv.scope_type,'user')<>'user' THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TRIAL_CONVERSATION_DENIED' USING ERRCODE='42501';
    END IF;
    INSERT INTO public.tasks(id,user_id,org_id,conversation_id,type,status,model_id,batch_id,image_index,request_params)
        VALUES(v_id,v_actor,p_org_id,v_conv.id,'image','pending',p_snapshot->>'model',v_id::TEXT,0,
            jsonb_build_object('_media_request_v1',p_snapshot,'_media_lifecycle_v1',jsonb_build_object('phase','queued','accepted_at',NOW())));
    UPDATE public.skill_draft_trial_runs SET result=p_result || jsonb_build_object('image_task_id',v_id,'status','running','submission_state','queued') WHERE id=p_trial_id;
    RETURN jsonb_build_object('outcome','accepted','task_id',v_id,'submission_state','queued');
END;
$$;


ALTER FUNCTION public.accept_chat_image_trial(p_trial_id uuid, p_snapshot jsonb, p_result jsonb, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: accept_detail_page_group(uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.accept_detail_page_group(p_project_id uuid, p_plan_id uuid, p_snapshots jsonb, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE entry JSONB; receipts JSONB:='[]';
BEGIN
 IF jsonb_typeof(p_snapshots)<>'array' OR jsonb_array_length(p_snapshots) NOT BETWEEN 1 AND 15 THEN RAISE EXCEPTION 'DETAIL_GROUP_INVALID'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_snapshots) LOOP
  receipts=receipts||jsonb_build_array(public.accept_detail_page_image(p_project_id,p_plan_id,(entry->>'item_id')::uuid,entry->'snapshot',p_org_id));
 END LOOP;
 RETURN receipts;
END $$;


ALTER FUNCTION public.accept_detail_page_group(p_project_id uuid, p_plan_id uuid, p_snapshots jsonb, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: accept_detail_page_image(uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.accept_detail_page_image(p_project_id uuid, p_plan_id uuid, p_item_id uuid, p_snapshot jsonb, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE d public.detail_projects%ROWTYPE; plan public.ecom_image_plans%ROWTYPE; item JSONB; origin JSONB:=p_snapshot->'origin';
 actor UUID:=NULLIF(current_setting('app.actor_user_id',true),'')::uuid; prior public.tasks%ROWTYPE;
 source public.tasks%ROWTYPE; task_id UUID:=gen_random_uuid(); cost INTEGER:=(p_snapshot->>'estimated_credits')::int;
 n INTEGER; reserved INTEGER;
BEGIN
 IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',true)<>'runtime' OR actor IS NULL
 OR NULLIF(current_setting('app.org_id',true),'')::uuid IS DISTINCT FROM p_org_id THEN
  RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO d FROM public.detail_projects WHERE id=p_project_id AND user_id=actor AND org_id IS NOT DISTINCT FROM p_org_id FOR UPDATE;
 SELECT * INTO plan FROM public.ecom_image_plans WHERE id=p_plan_id AND project_id=p_project_id AND user_id=actor AND org_id IS NOT DISTINCT FROM p_org_id;
 SELECT value INTO item FROM jsonb_array_elements(plan.items) WHERE value->>'item_id'=p_item_id::text;
 IF d.id IS NULL OR plan.id IS NULL OR plan.status<>'ready' OR item IS NULL
 OR d.run_state->>'run_id' IS DISTINCT FROM plan.generation_run_id::text
 OR origin->>'generation_run_id' IS DISTINCT FROM plan.generation_run_id::text
 OR origin->>'project_id' IS DISTINCT FROM d.id::text OR origin->>'destination' IS DISTINCT FROM 'detail_project'
 OR origin->>'actor_user_id' IS DISTINCT FROM actor::text OR origin->>'workspace_owner_id' IS DISTINCT FROM actor::text
 OR origin->>'org_id' IS DISTINCT FROM p_org_id::text OR origin->>'context_scope' IS DISTINCT FROM 'user'
 OR origin ?| ARRAY['conversation_id','parent_task_id','input_message_id','base_context_revision','trial_id']
 OR origin->'plan_source'->>'plan_id' IS DISTINCT FROM plan.id::text
 OR origin->'plan_source'->>'item_id' IS DISTINCT FROM p_item_id::text
 OR origin->'plan_source'->>'revision' IS DISTINCT FROM plan.plan_revision::text
 OR origin->'plan_source'->>'request_text_sha256' IS DISTINCT FROM item->>'request_text_sha256'
 OR p_snapshot->>'schema_version' IS DISTINCT FROM '1' OR p_snapshot->>'num_images' IS DISTINCT FROM '1'
 OR p_snapshot->>'prompt' IS DISTINCT FROM item->>'request_text'
 OR p_snapshot->>'prompt_sha256' IS DISTINCT FROM item->>'request_text_sha256'
 OR p_snapshot->'references' IS DISTINCT FROM plan.input_snapshot->'resolved_references'
 OR p_snapshot->>'aspect_ratio' IS DISTINCT FROM item->>'aspect_ratio'
 OR p_snapshot->>'resolution' IS DISTINCT FROM plan.target_size->>'resolution'
 OR p_snapshot->>'request_hash' !~ '^[0-9a-f]{64}$' OR cost IS NULL OR cost NOT BETWEEN 1 AND 300
 OR pg_column_size(p_snapshot)>131072 THEN
  RAISE EXCEPTION 'DETAIL_IMAGE_SOURCE_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=actor AND status='active')
 OR (p_org_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_members m JOIN public.organizations o ON o.id=m.org_id
 WHERE m.user_id=actor AND m.org_id=p_org_id AND m.status='active' AND o.status='active')) THEN
  RAISE EXCEPTION 'DETAIL_IDENTITY_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO prior FROM public.tasks WHERE type='image' AND user_id=actor AND org_id IS NOT DISTINCT FROM p_org_id
 AND request_params->'_media_request_v1'->'origin'->>'project_id'=d.id::text
 AND request_params->'_media_request_v1'->'origin'->'plan_source'->>'item_id'=p_item_id::text
 AND COALESCE(request_params->'_media_request_v1'->'origin'->>'retry_request_id','initial')=COALESCE(origin->>'retry_request_id','initial');
 IF FOUND THEN RETURN jsonb_build_object('outcome','replay','task_id',prior.id,'message_id',NULL,'submission_state',prior.request_params->'_media_lifecycle_v1'->>'phase'); END IF;
 IF origin ? 'retry_request_id' THEN
  SELECT * INTO source FROM public.tasks WHERE id=(origin->>'retry_of_task_id')::uuid AND user_id=actor AND org_id IS NOT DISTINCT FROM p_org_id;
  IF source.id IS NULL OR source.request_params->'_media_lifecycle_v1'->>'phase'<>'published'
  OR source.request_params->'_media_request_v1'->'origin'->>'project_id' IS DISTINCT FROM d.id::text
  OR source.request_params->'_media_request_v1'->>'prompt' IS DISTINCT FROM p_snapshot->>'prompt'
  OR source.request_params->'_media_request_v1'->'references' IS DISTINCT FROM p_snapshot->'references'
  OR source.request_params->'_media_request_v1'->>'model' IS DISTINCT FROM p_snapshot->>'model'
  OR source.request_params->'_media_request_v1'->>'estimated_credits' IS DISTINCT FROM p_snapshot->>'estimated_credits' THEN
   RAISE EXCEPTION 'DETAIL_REPLAY_DENIED' USING ERRCODE='42501'; END IF;
 ELSE
  SELECT COUNT(*),COALESCE(SUM((request_params->'_media_request_v1'->>'estimated_credits')::int),0) INTO n,reserved
   FROM public.tasks WHERE type='image' AND user_id=actor AND org_id IS NOT DISTINCT FROM p_org_id
   AND request_params->'_media_request_v1'->'origin'->>'project_id'=d.id::text
   AND request_params->'_media_request_v1'->'origin'->>'generation_run_id'=plan.generation_run_id::text
   AND NOT(request_params->'_media_request_v1'->'origin' ? 'retry_request_id');
  IF n>=COALESCE((plan.model_settings->'image_budget'->>'max_requests')::int,15) OR reserved+cost>COALESCE((plan.model_settings->'image_budget'->>'max_credits')::int,300) THEN RAISE EXCEPTION 'DETAIL_IMAGE_BUDGET_EXCEEDED' USING ERRCODE='54000'; END IF;
 END IF;
 INSERT INTO public.tasks(id,user_id,org_id,type,status,model_id,batch_id,image_index,request_params)
 VALUES(task_id,actor,p_org_id,'image','pending',p_snapshot->>'model',plan.generation_run_id::text,(item->>'position')::int-1,
 jsonb_build_object('_media_request_v1',p_snapshot,'_media_lifecycle_v1',jsonb_build_object('phase','queued','attempt',0),
 'prompt',p_snapshot->>'prompt','model',p_snapshot->>'model','num_images',1));
 UPDATE public.detail_projects SET status='generating',updated_at=NOW() WHERE id=d.id;
 RETURN jsonb_build_object('outcome','accepted','task_id',task_id,'message_id',NULL,'submission_state','queued');
END $_$;


ALTER FUNCTION public.accept_detail_page_image(p_project_id uuid, p_plan_id uuid, p_item_id uuid, p_snapshot jsonb, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: accept_governed_invitation(text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.accept_governed_invitation(p_invite_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public._assert_governance_self_scope();
    v_phone TEXT;
    v_invitation public.org_invitations%ROWTYPE;
    v_org public.organizations%ROWTYPE;
BEGIN
    IF COALESCE(BTRIM(p_invite_token), '') = '' THEN
        RAISE EXCEPTION 'GOVERNANCE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_invitation FROM public.org_invitations
     WHERE invite_token = p_invite_token FOR UPDATE;
    IF NOT FOUND OR v_invitation.status <> 'pending' THEN
        RAISE EXCEPTION 'GOVERNANCE_INVITATION_MISSING'
            USING ERRCODE = 'P0002';
    END IF;
    IF v_invitation.expires_at <= NOW() THEN
        RAISE EXCEPTION 'GOVERNANCE_INVITATION_EXPIRED'
            USING ERRCODE = '22023';
    END IF;
    SELECT phone INTO v_phone FROM public.users WHERE id = v_actor;
    IF v_phone IS DISTINCT FROM v_invitation.phone THEN
        RAISE EXCEPTION 'GOVERNANCE_INVITATION_RECIPIENT_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_org FROM public.organizations
     WHERE id = v_invitation.org_id AND status = 'active'
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'GOVERNANCE_ORG_INACTIVE'
            USING ERRCODE = '42501';
    END IF;
    IF EXISTS (
        SELECT 1 FROM public.org_members
         WHERE org_id = v_org.id AND user_id = v_actor
    ) THEN
        RAISE EXCEPTION 'GOVERNANCE_MEMBER_EXISTS'
            USING ERRCODE = '23505';
    END IF;
    IF (SELECT COUNT(*) FROM public.org_members
         WHERE org_id = v_org.id AND status = 'active') >= v_org.max_members THEN
        RAISE EXCEPTION 'GOVERNANCE_MEMBER_LIMIT_REACHED'
            USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.org_members(
        org_id, user_id, role, status, invited_by
    ) VALUES (
        v_org.id, v_actor, v_invitation.role,
        'active', v_invitation.invited_by
    );
    UPDATE public.org_invitations SET status = 'accepted'
     WHERE id = v_invitation.id;
    PERFORM public._record_governance_audit(
        v_org.id, 'self', 'invitation.accept', 'invitation',
        v_invitation.id::TEXT,
        jsonb_build_object('role', v_invitation.role)
    );
    RETURN jsonb_build_object(
        'org_id', v_org.id,
        'role', v_invitation.role,
        'org_name', v_org.name
    );
END;
$$;


ALTER FUNCTION public.accept_governed_invitation(p_invite_token text) OWNER TO everydayai_owner;

--
-- Name: ack_chat_image_delivery(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.ack_chat_image_delivery(p_task_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    PERFORM public.assert_chat_image_worker(p_org_id);
    UPDATE public.tasks SET request_params=jsonb_set(request_params,'{_media_lifecycle_v1,delivery_pending}','false')
        WHERE id=p_task_id AND type='image' AND org_id IS NOT DISTINCT FROM p_org_id
        AND request_params ? '_media_request_v1'
        AND request_params->'_media_lifecycle_v1'->>'phase'='published';
    RETURN jsonb_build_object('outcome',CASE WHEN FOUND THEN 'delivered' ELSE 'not_published' END);
END;
$$;


