--
-- Name: acknowledge_conversation_control_command(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.acknowledge_conversation_control_command(p_event_id uuid, p_task_id uuid, p_execution_token uuid, p_outcome text DEFAULT 'applied'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_updated_count BIGINT;
BEGIN
    IF p_event_id IS NULL
       OR p_task_id IS NULL
       OR p_execution_token IS NULL
       OR p_outcome NOT IN ('applied', 'ignored') THEN
        RAISE EXCEPTION 'ACTOR_CONTROL_ACK_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat' THEN
        RAISE EXCEPTION 'ACTOR_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    UPDATE conversation_control_events
       SET status = p_outcome,
           applied_execution_token = p_execution_token,
           applied_at = NOW()
     WHERE id = p_event_id
       AND task_id = p_task_id
       AND status = 'pending';
    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        RETURN jsonb_build_object('outcome', 'already_acknowledged');
    END IF;
    RETURN jsonb_build_object('outcome', p_outcome, 'event_id', p_event_id);
END;
$$;


ALTER FUNCTION public.acknowledge_conversation_control_command(p_event_id uuid, p_task_id uuid, p_execution_token uuid, p_outcome text) OWNER TO everydayai;

--
-- Name: FUNCTION acknowledge_conversation_control_command(p_event_id uuid, p_task_id uuid, p_execution_token uuid, p_outcome text); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.acknowledge_conversation_control_command(p_event_id uuid, p_task_id uuid, p_execution_token uuid, p_outcome text) IS '仅当前 fencing owner 可确认控制事件，重复确认幂等';


--
-- Name: actor_message_text_to_blocks(text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.actor_message_text_to_blocks(p_content text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_value JSONB;
    v_text TEXT := COALESCE(p_content, '');
BEGIN
    IF BTRIM(v_text) = '' THEN
        RETURN '[]'::JSONB;
    END IF;

    BEGIN
        v_value := v_text::JSONB;
    EXCEPTION WHEN invalid_text_representation THEN
        RETURN jsonb_build_array(
            jsonb_build_object('type', 'text', 'text', v_text)
        );
    END;

    IF jsonb_typeof(v_value) = 'array' THEN
        RETURN v_value;
    END IF;
    IF jsonb_typeof(v_value) = 'string' THEN
        RETURN jsonb_build_array(
            jsonb_build_object('type', 'text', 'text', v_value #>> '{}')
        );
    END IF;
    RETURN jsonb_build_array(
        jsonb_build_object('type', 'text', 'text', v_text)
    );
END;
$$;


ALTER FUNCTION public.actor_message_text_to_blocks(p_content text) OWNER TO everydayai;

--
-- Name: add_governed_member(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.add_governed_member(p_org_id uuid, p_target_user_id uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_authority TEXT;
    v_org public.organizations%ROWTYPE;
    v_member public.org_members%ROWTYPE;
BEGIN
    v_authority := public._assert_governance_authority(
        p_org_id, ARRAY['owner', 'admin'], FALSE
    );
    IF p_role NOT IN ('admin', 'member') OR NOT EXISTS (
        SELECT 1 FROM public.users
         WHERE id = p_target_user_id AND status::TEXT = 'active'
    ) THEN
        RAISE EXCEPTION 'GOVERNANCE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_org FROM public.organizations
     WHERE id = p_org_id FOR UPDATE;
    IF (SELECT COUNT(*) FROM public.org_members
         WHERE org_id = p_org_id AND status = 'active') >= v_org.max_members THEN
        RAISE EXCEPTION 'GOVERNANCE_MEMBER_LIMIT_REACHED'
            USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.org_members(
        org_id, user_id, role, status, invited_by
    ) VALUES (
        p_org_id, p_target_user_id, p_role, 'active',
        public.tenant_actor_user_id()
    ) RETURNING * INTO v_member;
    PERFORM public._record_governance_audit(
        p_org_id, v_authority, 'member.add', 'member',
        p_target_user_id::TEXT, jsonb_build_object('role', p_role)
    );
    RETURN to_jsonb(v_member);
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'GOVERNANCE_MEMBER_EXISTS'
            USING ERRCODE = '23505';
END;
$$;


ALTER FUNCTION public.add_governed_member(p_org_id uuid, p_target_user_id uuid, p_role text) OWNER TO everydayai_owner;

--
-- Name: admin_adjust_credits(uuid, integer, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.admin_adjust_credits(p_user_id uuid, p_delta integer, p_reason text, p_operator_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_balance INTEGER;
BEGIN
    IF p_delta = 0 THEN
        RETURN jsonb_build_object('success', false, 'reason', 'zero_delta');
    END IF;

    UPDATE public.users
       SET credits = credits + p_delta,
           updated_at = NOW()
     WHERE id = p_user_id
       AND credits + p_delta >= 0
    RETURNING credits INTO v_new_balance;

    IF NOT FOUND THEN
        IF EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
            RETURN jsonb_build_object('success', false, 'reason', 'insufficient_balance');
        END IF;
        RETURN jsonb_build_object('success', false, 'reason', 'user_not_found');
    END IF;

    INSERT INTO public.credits_history (
        user_id, change_amount, balance_after, change_type,
        description, operator_id, org_id
    ) VALUES (
        p_user_id, p_delta, v_new_balance, 'admin_adjust'::public.credits_change_type,
        p_reason, p_operator_id, p_org_id
    );

    RETURN jsonb_build_object(
        'success', true,
        'new_balance', v_new_balance,
        'delta', p_delta
    );
END;
$$;


ALTER FUNCTION public.admin_adjust_credits(p_user_id uuid, p_delta integer, p_reason text, p_operator_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION admin_adjust_credits(p_user_id uuid, p_delta integer, p_reason text, p_operator_id uuid, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
