COMMENT ON FUNCTION public.admin_adjust_credits(p_user_id uuid, p_delta integer, p_reason text, p_operator_id uuid, p_org_id uuid) IS '旧 Web 管理后台原子调整积分（正=充值/负=扣减），写 operator_id 审计流水';


--
-- Name: api_delete_org_mcp_connector_credential(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.api_delete_org_mcp_connector_credential(p_org_id uuid, p_config_key text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_authority TEXT;
    v_result JSONB;
BEGIN
    v_authority := public._assert_mcp_application_actor(p_org_id, TRUE);
    IF p_config_key IS DISTINCT FROM 'mcp.test_readonly.bearer_token'
       OR p_expected_version < 0 THEN
        RAISE EXCEPTION 'MCP_CREDENTIAL_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    v_result := public._disable_configuration_entry(
        'organization', p_org_id, NULL, p_config_key,
        p_expected_version, public.mcp_application_actor_user_id()
    );
    IF (v_result->>'deleted')::BOOLEAN THEN
        PERFORM public.mcp_record_connector_audit(
            p_org_id, v_authority, 'mcp_connector.delete_credential',
            'mcp_connector', 'test-readonly',
            jsonb_build_object('configured', FALSE, 'version', v_result->'version')
        );
    END IF;
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.api_delete_org_mcp_connector_credential(p_org_id uuid, p_config_key text, p_expected_version bigint) OWNER TO everydayai_owner;

