--
-- Name: api_get_org_mcp_connector_credential_status(uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.api_get_org_mcp_connector_credential_status(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_entry public.configuration_entries%ROWTYPE;
    v_secret public.secret_records%ROWTYPE;
    v_configured BOOLEAN := FALSE;
BEGIN
    PERFORM public._assert_mcp_application_actor(p_org_id, TRUE);
    SELECT * INTO v_entry
      FROM public.configuration_entries
     WHERE scope_kind = 'organization'
       AND org_id = p_org_id
       AND config_key = 'mcp.test_readonly.bearer_token';
    IF FOUND AND v_entry.secret_id IS NOT NULL THEN
        SELECT * INTO v_secret FROM public.secret_records
         WHERE id = v_entry.secret_id AND status = 'active';
        v_configured := FOUND AND v_entry.status = 'active';
    END IF;
    RETURN jsonb_build_object(
        'key', 'mcp.test_readonly.bearer_token',
        'configured', v_configured,
        'version', COALESCE(v_entry.version, 0),
        'source', CASE WHEN v_entry.status = 'active' THEN 'organization' END,
        'updated_at', v_entry.updated_at
    );
END;
$$;


ALTER FUNCTION public.api_get_org_mcp_connector_credential_status(p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: api_get_org_mcp_connector_state(uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.api_get_org_mcp_connector_state(p_org_id uuid, p_connector_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_state public.organization_mcp_connectors%ROWTYPE;
BEGIN
    PERFORM public._assert_mcp_application_actor(p_org_id, FALSE);
    IF p_connector_id IS DISTINCT FROM 'test-readonly' THEN
        RAISE EXCEPTION 'MCP_CONNECTOR_NOT_ALLOWLISTED'
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_state
      FROM public.organization_mcp_connectors
     WHERE org_id = p_org_id AND connector_id = p_connector_id;
    RETURN jsonb_build_object(
        'org_id', p_org_id,
        'connector_id', p_connector_id,
        'enabled', COALESCE(v_state.enabled, FALSE),
        'state', CASE
            WHEN NOT COALESCE(v_state.enabled, FALSE) THEN 'disabled'
            WHEN v_state.health_status = 'ready' THEN 'ready'
            WHEN v_state.health_status = 'error' THEN 'error'
            ELSE 'configured'
        END,
        'health_status', COALESCE(v_state.health_status, 'unknown'),
        'last_checked_at', v_state.last_checked_at,
        'last_error_code', v_state.last_error_code,
        'updated_at', v_state.updated_at
    );
END;
$$;


ALTER FUNCTION public.api_get_org_mcp_connector_state(p_org_id uuid, p_connector_id text) OWNER TO everydayai_owner;

--
-- Name: api_record_org_mcp_connector_health(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.api_record_org_mcp_connector_health(p_org_id uuid, p_connector_id text, p_health_status text, p_error_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public.mcp_application_actor_user_id();
    v_state public.organization_mcp_connectors%ROWTYPE;
BEGIN
    PERFORM public._assert_mcp_application_actor(p_org_id, FALSE);
    IF p_connector_id IS DISTINCT FROM 'test-readonly'
       OR p_health_status IS NULL
       OR p_health_status NOT IN ('ready', 'error')
       OR (p_error_code IS NOT NULL AND p_error_code NOT IN (
           'MCP_AUTH_FAILED', 'MCP_CREDENTIAL_UNAVAILABLE', 'MCP_HEALTH_FAILED',
           'MCP_REMOTE_ERROR', 'MCP_PROTOCOL_ERROR', 'MCP_RESULT_INVALID',
           'MCP_SCHEMA_NOT_REVIEWED', 'MCP_TIMEOUT', 'MCP_TOOL_ERROR',
           'MCP_UNAVAILABLE', 'MCP_CANCELLED'
       )) THEN
        RAISE EXCEPTION 'MCP_HEALTH_FACT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.organization_mcp_connectors(
        org_id, connector_id, enabled, health_status,
        last_checked_at, last_error_code, updated_by, updated_at
    ) VALUES (
        p_org_id, p_connector_id, FALSE, p_health_status,
        NOW(), p_error_code, v_actor, NOW()
    )
    ON CONFLICT (org_id, connector_id) DO UPDATE SET
        health_status = EXCLUDED.health_status,
        last_checked_at = NOW(),
        last_error_code = EXCLUDED.last_error_code,
        updated_by = EXCLUDED.updated_by,
        updated_at = NOW()
    RETURNING * INTO v_state;
    RETURN jsonb_build_object(
        'org_id', p_org_id, 'connector_id', p_connector_id,
        'enabled', v_state.enabled,
        'state', CASE
            WHEN NOT v_state.enabled THEN 'disabled'
            WHEN v_state.health_status = 'ready' THEN 'ready'
            ELSE 'error'
        END,
        'health_status', v_state.health_status,
        'last_checked_at', v_state.last_checked_at,
        'last_error_code', v_state.last_error_code,
        'updated_at', v_state.updated_at
    );
END;
$$;


ALTER FUNCTION public.api_record_org_mcp_connector_health(p_org_id uuid, p_connector_id text, p_health_status text, p_error_code text) OWNER TO everydayai_owner;

--
-- Name: api_set_org_mcp_connector_credential(uuid, text, text, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.api_set_org_mcp_connector_credential(p_org_id uuid, p_definition_version text, p_config_key text, p_value_json jsonb, p_secret_envelope jsonb, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_authority TEXT;
    v_result JSONB;
BEGIN
    v_authority := public._assert_mcp_application_actor(p_org_id, TRUE);
    IF p_config_key IS DISTINCT FROM 'mcp.test_readonly.bearer_token'
       OR p_value_json IS NOT NULL
       OR p_secret_envelope IS NULL THEN
        RAISE EXCEPTION 'MCP_CREDENTIAL_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    v_result := public._write_configuration_entry(
        'organization', p_org_id, NULL, p_definition_version, p_config_key,
        p_value_json, p_secret_envelope, p_expected_version,
        public.mcp_application_actor_user_id()
    );
    PERFORM public.mcp_record_connector_audit(
        p_org_id, v_authority, 'mcp_connector.set_credential',
        'mcp_connector', 'test-readonly',
        jsonb_build_object('configured', TRUE, 'version', v_result->'version')
    );
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.api_set_org_mcp_connector_credential(p_org_id uuid, p_definition_version text, p_config_key text, p_value_json jsonb, p_secret_envelope jsonb, p_expected_version bigint) OWNER TO everydayai_owner;

--
-- Name: api_set_org_mcp_connector_enabled(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.api_set_org_mcp_connector_enabled(p_org_id uuid, p_connector_id text, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public.mcp_application_actor_user_id();
    v_authority TEXT;
    v_state public.organization_mcp_connectors%ROWTYPE;
BEGIN
    v_authority := public._assert_mcp_application_actor(p_org_id, TRUE);
    IF p_connector_id IS DISTINCT FROM 'test-readonly' OR p_enabled IS NULL THEN
        RAISE EXCEPTION 'MCP_CONNECTOR_NOT_ALLOWLISTED'
            USING ERRCODE = '22023';
    END IF;
    IF p_enabled AND NOT EXISTS (
        SELECT 1
          FROM public.configuration_entries entry
          JOIN public.secret_records secret ON secret.id = entry.secret_id
         WHERE entry.scope_kind = 'organization'
           AND entry.org_id = p_org_id
           AND entry.config_key = 'mcp.test_readonly.bearer_token'
           AND entry.status = 'active'
           AND secret.scope_kind = 'organization'
           AND secret.org_id = p_org_id
           AND secret.secret_name = 'mcp.test_readonly_bearer_token'
           AND secret.status = 'active'
    ) THEN
        RAISE EXCEPTION 'MCP_CREDENTIAL_REQUIRED'
            USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.organization_mcp_connectors(
        org_id, connector_id, enabled, health_status,
        last_error_code, updated_by, updated_at
    ) VALUES (
        p_org_id, p_connector_id, p_enabled,
        CASE WHEN p_enabled THEN 'configured' ELSE 'unknown' END,
        NULL, v_actor, NOW()
    )
    ON CONFLICT (org_id, connector_id) DO UPDATE SET
        enabled = EXCLUDED.enabled,
        health_status = CASE WHEN EXCLUDED.enabled
            THEN 'configured' ELSE organization_mcp_connectors.health_status END,
        last_error_code = CASE WHEN EXCLUDED.enabled
            THEN NULL ELSE organization_mcp_connectors.last_error_code END,
        updated_by = EXCLUDED.updated_by,
        updated_at = NOW()
    RETURNING * INTO v_state;
    PERFORM public.mcp_record_connector_audit(
        p_org_id, v_authority, 'mcp_connector.set_enabled',
        'mcp_connector', p_connector_id,
        jsonb_build_object('enabled', v_state.enabled)
    );
    RETURN jsonb_build_object(
        'org_id', p_org_id, 'connector_id', p_connector_id,
        'enabled', v_state.enabled,
        'state', CASE WHEN v_state.enabled THEN 'configured' ELSE 'disabled' END,
        'health_status', v_state.health_status,
        'last_checked_at', v_state.last_checked_at,
        'last_error_code', v_state.last_error_code,
        'updated_at', v_state.updated_at
    );
END;
$$;


ALTER FUNCTION public.api_set_org_mcp_connector_enabled(p_org_id uuid, p_connector_id text, p_enabled boolean) OWNER TO everydayai_owner;

--
-- Name: append_conversation_control_command(uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.append_conversation_control_command(p_conversation_id uuid, p_task_id uuid, p_turn_id uuid, p_event_type text, p_dedupe_key text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_event conversation_control_events%ROWTYPE;
    v_inserted_count BIGINT;
BEGIN
    IF p_conversation_id IS NULL OR p_task_id IS NULL
       OR p_event_type NOT IN (
           'cancel', 'pause', 'resume', 'approval_result',
           'subtask_completed', 'tool_completed'
       )
       OR NULLIF(BTRIM(p_dedupe_key), '') IS NULL
       OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
        RAISE EXCEPTION 'ACTOR_CONTROL_EVENT_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.conversation_id IS DISTINCT FROM p_conversation_id
       OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_CONTROL_EVENT_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF p_event_type IN ('approval_result', 'pause', 'cancel')
       AND v_task.status <> 'running' THEN
        RAISE EXCEPTION 'ACTOR_CONTROL_EVENT_TASK_NOT_RUNNING' USING ERRCODE = '55000';
    END IF;

    INSERT INTO conversation_control_events(
        conversation_id, task_id, turn_id, event_type, dedupe_key, payload
    ) VALUES (
        p_conversation_id, p_task_id, p_turn_id, p_event_type,
        BTRIM(p_dedupe_key), p_payload
    ) ON CONFLICT (task_id, dedupe_key) DO NOTHING;
    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

    SELECT * INTO v_event FROM conversation_control_events
     WHERE task_id = p_task_id AND dedupe_key = BTRIM(p_dedupe_key);
    RETURN jsonb_build_object(
        'outcome', 'enqueued', 'event_id', v_event.id,
        'event_sequence', v_event.event_sequence,
        'already_enqueued', v_inserted_count = 0,
        'payload', v_event.payload
    );
END;
$$;


ALTER FUNCTION public.append_conversation_control_command(p_conversation_id uuid, p_task_id uuid, p_turn_id uuid, p_event_type text, p_dedupe_key text, p_payload jsonb) OWNER TO everydayai;

--
-- Name: append_conversation_control_command(uuid, uuid, uuid, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.append_conversation_control_command(p_conversation_id uuid, p_task_id uuid, p_turn_id uuid, p_event_type text, p_dedupe_key text, p_payload jsonb, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_conversation conversations%ROWTYPE;
BEGIN
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id;
    SELECT * INTO v_conversation FROM conversations WHERE id = p_conversation_id;
    IF NOT FOUND
       OR v_task.conversation_id IS DISTINCT FROM p_conversation_id
       OR v_task.org_id IS DISTINCT FROM p_org_id
       OR v_conversation.org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'ACTOR_CONTROL_EVENT_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    RETURN public.append_conversation_control_command(
        p_conversation_id, p_task_id, p_turn_id, p_event_type,
        p_dedupe_key, p_payload
    );
END;
$$;


ALTER FUNCTION public.append_conversation_control_command(p_conversation_id uuid, p_task_id uuid, p_turn_id uuid, p_event_type text, p_dedupe_key text, p_payload jsonb, p_org_id uuid) OWNER TO everydayai;

--
-- Name: append_conversation_delivery_event(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.append_conversation_delivery_event(p_task_id uuid, p_execution_token uuid, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_session conversation_delivery_sessions%ROWTYPE;
    v_seq BIGINT;
BEGIN
    IF p_task_id IS NULL OR p_execution_token IS NULL
       OR p_event_type NOT IN (
           'message_start', 'message_chunk', 'thinking_chunk',
           'content_block_add', 'stream_end'
       )
       OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
        RAISE EXCEPTION 'DELIVERY_EVENT_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'DELIVERY_EVENT_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    SELECT * INTO v_session
      FROM conversation_delivery_sessions
     WHERE task_id = p_task_id
     FOR UPDATE;
    IF NOT FOUND OR v_session.execution_token IS DISTINCT FROM p_execution_token
       OR v_session.status <> 'streaming' THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    v_seq := v_session.next_seq + 1;
    INSERT INTO conversation_delivery_events(
        session_id, task_id, stream_id, execution_attempt,
        delivery_seq, event_type, payload
    ) VALUES (
        v_session.id, p_task_id, v_session.stream_id,
        v_session.execution_attempt, v_seq, p_event_type, p_payload
    );
    UPDATE conversation_delivery_sessions
       SET next_seq = v_seq, updated_at = NOW()
     WHERE id = v_session.id;

    RETURN jsonb_build_object(
        'outcome', 'appended',
        'session_id', v_session.id,
        'stream_id', v_session.stream_id,
        'execution_attempt', v_session.execution_attempt,
        'delivery_seq', v_seq
    );
END;
$$;


ALTER FUNCTION public.append_conversation_delivery_event(p_task_id uuid, p_execution_token uuid, p_event_type text, p_payload jsonb) OWNER TO everydayai;

--
-- Name: append_conversation_delivery_event(uuid, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.append_conversation_delivery_event(p_task_id uuid, p_execution_token uuid, p_event_type text, p_payload jsonb, p_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_session conversation_delivery_sessions%ROWTYPE;
    v_event conversation_delivery_events%ROWTYPE;
    v_seq BIGINT;
    v_row_count BIGINT;
    v_inserted BOOLEAN;
BEGIN
    IF p_task_id IS NULL OR p_execution_token IS NULL OR p_event_id IS NULL
       OR p_event_type NOT IN (
           'message_start', 'message_chunk', 'thinking_chunk',
           'content_block_add', 'stream_end'
       )
       OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
        RAISE EXCEPTION 'DELIVERY_EVENT_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'DELIVERY_EVENT_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    SELECT * INTO v_session
      FROM conversation_delivery_sessions
     WHERE task_id = p_task_id
     FOR UPDATE;
    IF NOT FOUND OR v_session.execution_token IS DISTINCT FROM p_execution_token
       OR v_session.status <> 'streaming' THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    v_seq := v_session.next_seq + 1;
    INSERT INTO conversation_delivery_events(
        session_id, task_id, stream_id, execution_attempt,
        event_id, delivery_seq, event_type, payload
    ) VALUES (
        v_session.id, p_task_id, v_session.stream_id, v_session.execution_attempt,
        p_event_id, v_seq, p_event_type, p_payload
    ) ON CONFLICT (stream_id, event_id) DO NOTHING;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    v_inserted := v_row_count = 1;
    IF v_inserted THEN
        UPDATE conversation_delivery_sessions
           SET next_seq = v_seq, updated_at = NOW()
         WHERE id = v_session.id;
    ELSE
        SELECT * INTO v_event
          FROM conversation_delivery_events
         WHERE stream_id = v_session.stream_id AND event_id = p_event_id;
        IF v_event.event_type IS DISTINCT FROM p_event_type
           OR v_event.payload IS DISTINCT FROM p_payload THEN
            RAISE EXCEPTION 'DELIVERY_EVENT_ID_REUSE'
                USING ERRCODE = '23505';
        END IF;
        v_seq := v_event.delivery_seq;
    END IF;

    RETURN jsonb_build_object(
        'outcome', 'appended',
        'session_id', v_session.id,
        'stream_id', v_session.stream_id,
        'execution_attempt', v_session.execution_attempt,
        'delivery_seq', v_seq
    );
END;
$$;


ALTER FUNCTION public.append_conversation_delivery_event(p_task_id uuid, p_execution_token uuid, p_event_type text, p_payload jsonb, p_event_id uuid) OWNER TO everydayai;

--
-- Name: append_conversation_steer(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.append_conversation_steer(p_conversation_id uuid, p_task_id uuid, p_turn_id uuid, p_dedupe_key text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_event conversation_control_events%ROWTYPE;
    v_inserted_count BIGINT;
    v_message TEXT;
BEGIN
    v_message := NULLIF(BTRIM(p_payload->>'message'), '');
    IF p_conversation_id IS NULL
       OR p_task_id IS NULL
       OR NULLIF(BTRIM(p_dedupe_key), '') IS NULL
       OR p_payload IS NULL
       OR jsonb_typeof(p_payload) <> 'object'
       OR v_message IS NULL
       OR length(v_message) > 20000 THEN
        RAISE EXCEPTION 'ACTOR_STEER_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task
      FROM tasks
     WHERE id = p_task_id
     FOR UPDATE;
    IF NOT FOUND
       OR v_task.conversation_id IS DISTINCT FROM p_conversation_id
       OR v_task.type <> 'chat'
       OR v_task.status <> 'running'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_STEER_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    INSERT INTO conversation_control_events(
        conversation_id, task_id, turn_id, event_type, dedupe_key, payload
    ) VALUES (
        p_conversation_id, p_task_id, p_turn_id, 'steer',
        BTRIM(p_dedupe_key), jsonb_build_object('message', v_message)
    )
    ON CONFLICT (task_id, dedupe_key) DO NOTHING;
    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

    SELECT * INTO v_event
      FROM conversation_control_events
     WHERE task_id = p_task_id
       AND dedupe_key = BTRIM(p_dedupe_key);

    RETURN jsonb_build_object(
        'outcome', 'enqueued',
        'event_id', v_event.id,
        'event_sequence', v_event.event_sequence,
        'already_enqueued', v_inserted_count = 0,
        'payload', v_event.payload
    );
END;
$$;


ALTER FUNCTION public.append_conversation_steer(p_conversation_id uuid, p_task_id uuid, p_turn_id uuid, p_dedupe_key text, p_payload jsonb) OWNER TO everydayai;

