--
-- Name: atomic_refund_credits(uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.atomic_refund_credits(p_transaction_id uuid, p_final_status text DEFAULT 'refunded'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_id UUID;
    v_amount INTEGER;
    v_org_id UUID;
    v_status TEXT;
BEGIN
    -- CAS: 只有 pending 状态才能退款，同时锁行防并发
    UPDATE credit_transactions
    SET status = p_final_status, confirmed_at = NOW()
    WHERE id = p_transaction_id AND status = 'pending'
    RETURNING user_id, amount, org_id INTO v_user_id, v_amount, v_org_id;

    -- 未匹配到 pending 行：已退款或不存在
    IF v_user_id IS NULL THEN
        SELECT status INTO v_status
        FROM credit_transactions WHERE id = p_transaction_id;

        IF v_status IS NULL THEN
            RETURN jsonb_build_object('refunded', false, 'reason', 'not_found');
        ELSE
            RETURN jsonb_build_object('refunded', false, 'reason', 'status_' || v_status);
        END IF;
    END IF;

    -- 退回积分
    UPDATE users SET credits = credits + v_amount, updated_at = NOW()
    WHERE id = v_user_id;

    -- 记录积分变动历史（含 org_id 保持企业数据隔离一致性）
    INSERT INTO credits_history (user_id, change_amount, balance_after, change_type, description, org_id)
    SELECT v_user_id, v_amount,
           (SELECT credits FROM users WHERE id = v_user_id),
           'refund'::credits_change_type,
           'Refund for transaction ' || p_transaction_id,
           v_org_id;

    RETURN jsonb_build_object(
        'refunded', true,
        'user_id', v_user_id,
        'amount', v_amount
    );
END;
$$;


ALTER FUNCTION public.atomic_refund_credits(p_transaction_id uuid, p_final_status text) OWNER TO everydayai;

--
-- Name: FUNCTION atomic_refund_credits(p_transaction_id uuid, p_final_status text); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.atomic_refund_credits(p_transaction_id uuid, p_final_status text) IS '原子退款：CAS检查pending + 退回余额 + 更新状态，单事务内完成，防双倍退款';


--
-- Name: attach_chat_form_changeset(uuid, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.attach_chat_form_changeset(p_message_id uuid, p_conversation_id uuid, p_org_id uuid, p_form_id text, p_change_set_id uuid, p_result_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_content JSONB;
    v_block JSONB;
    v_path TEXT[];
    v_current_status TEXT;
    v_current_change_set_id TEXT;
BEGIN
    IF p_form_id IS NULL OR p_form_id = '' OR p_change_set_id IS NULL
       OR NOT EXISTS (
           SELECT 1 FROM public.change_sets
            WHERE id = p_change_set_id AND org_id = p_org_id
       ) THEN
        RETURN jsonb_build_object('outcome', 'changeset_missing');
    END IF;

    SELECT content::JSONB INTO v_content
      FROM public.messages
     WHERE id = p_message_id
       AND conversation_id = p_conversation_id
       AND role = 'assistant'
     FOR UPDATE;
    IF NOT FOUND OR jsonb_typeof(v_content) <> 'array' THEN
        RETURN jsonb_build_object('outcome', 'message_missing');
    END IF;

    WITH RECURSIVE form_nodes(path, block) AS (
        SELECT ARRAY[(item.ordinality - 1)::TEXT], item.value
          FROM jsonb_array_elements(v_content) WITH ORDINALITY AS item(value, ordinality)
        UNION ALL
        SELECT array_append(node.path, 'next_form'), node.block->'next_form'
          FROM form_nodes AS node
         WHERE jsonb_typeof(node.block->'next_form') = 'object'
    )
    SELECT path, block INTO v_path, v_block
      FROM form_nodes
     WHERE block->>'type' = 'form' AND block->>'form_id' = p_form_id
     LIMIT 1;

    IF v_path IS NULL THEN
        RETURN jsonb_build_object('outcome', 'form_missing');
    END IF;

    v_current_status := COALESCE(v_block->>'status', 'open');
    v_current_change_set_id := v_block->>'change_set_id';
    IF v_current_status = 'submitted' AND v_current_change_set_id = p_change_set_id::TEXT THEN
        RETURN jsonb_build_object('outcome', 'existing', 'change_set_id', p_change_set_id);
    END IF;
    IF v_current_status NOT IN ('open', 'submitting') THEN
        RETURN jsonb_build_object('outcome', 'state_conflict', 'status', v_current_status);
    END IF;

    v_block := v_block || jsonb_build_object(
        'status', 'submitted', 'change_set_id', p_change_set_id
    );
    IF p_result_message IS NOT NULL THEN
        v_block := v_block || jsonb_build_object('result_message', p_result_message);
    END IF;
    v_block := v_block - 'error_message';
    v_content := jsonb_set(v_content, v_path, v_block, FALSE);
    UPDATE public.messages SET content = v_content::TEXT WHERE id = p_message_id;
    RETURN jsonb_build_object('outcome', 'transitioned', 'change_set_id', p_change_set_id);
END;
$$;


ALTER FUNCTION public.attach_chat_form_changeset(p_message_id uuid, p_conversation_id uuid, p_org_id uuid, p_form_id text, p_change_set_id uuid, p_result_message text) OWNER TO everydayai;

--
-- Name: attach_detail_project_image(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.attach_detail_project_image(p_user_id uuid, p_org_id uuid, p_workspace_path text, p_category text) RETURNS TABLE(project_id uuid, project_version integer, image_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_project_id UUID;
    v_version INTEGER;
    v_image_id UUID;
    v_count INTEGER;
    v_sort_order SMALLINT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_user_id) THEN
        RAISE EXCEPTION 'DETAIL_PROJECT_USER_NOT_FOUND' USING ERRCODE = '23503';
    END IF;
    IF p_org_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM org_members member
         WHERE member.org_id = p_org_id
           AND member.user_id = p_user_id
           AND member.status = 'active'
    ) THEN
        RAISE EXCEPTION 'DETAIL_PROJECT_ORG_ACCESS_DENIED' USING ERRCODE = '42501';
    END IF;
    IF p_workspace_path IS NULL OR length(p_workspace_path) NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION 'DETAIL_IMAGE_INVALID_PATH' USING ERRCODE = '22023';
    END IF;
    IF p_category NOT IN ('product', 'reference') THEN
        RAISE EXCEPTION 'DETAIL_IMAGE_INVALID_CATEGORY' USING ERRCODE = '22023';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text||COALESCE(p_org_id::text,''),118));
    IF (SELECT COUNT(*) FROM detail_projects WHERE user_id=p_user_id AND org_id IS NOT DISTINCT FROM p_org_id AND status='draft')>1 THEN
        RAISE EXCEPTION 'DETAIL_PROJECT_AMBIGUOUS' USING ERRCODE='55000';
    END IF;
    SELECT id, version
      INTO v_project_id, v_version
      FROM detail_projects
     WHERE user_id = p_user_id
       AND org_id IS NOT DISTINCT FROM p_org_id
       AND status = 'draft'
     FOR UPDATE;

    IF v_project_id IS NULL THEN
        BEGIN
            INSERT INTO detail_projects(user_id, org_id)
            VALUES (p_user_id, p_org_id)
            RETURNING id, version INTO v_project_id, v_version;
        EXCEPTION WHEN unique_violation THEN
            SELECT id, version
              INTO v_project_id, v_version
              FROM detail_projects
             WHERE user_id = p_user_id
               AND org_id IS NOT DISTINCT FROM p_org_id
               AND status = 'draft'
             FOR UPDATE;
        END;
    END IF;

    IF v_project_id IS NULL THEN
        RAISE EXCEPTION 'DETAIL_PROJECT_CREATE_FAILED' USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1 FROM detail_project_images image
         WHERE image.project_id = v_project_id
           AND image.workspace_path = p_workspace_path
    ) THEN
        RAISE EXCEPTION 'DETAIL_IMAGE_DUPLICATE' USING ERRCODE = '23505';
    END IF;

    SELECT COUNT(*), COALESCE(MAX(sort_order) + 1, 0)::SMALLINT
      INTO v_count, v_sort_order
      FROM detail_project_images image
     WHERE image.project_id = v_project_id;

    IF v_count >= 9 THEN
        RAISE EXCEPTION 'DETAIL_IMAGE_LIMIT_EXCEEDED' USING ERRCODE = '22023';
    END IF;

    INSERT INTO detail_project_images(
        project_id, user_id, org_id, workspace_path, category, sort_order
    ) VALUES (
        v_project_id, p_user_id, p_org_id, p_workspace_path, p_category, v_sort_order
    ) RETURNING id INTO v_image_id;

    UPDATE detail_projects
       SET version = version + 1, updated_at = NOW()
     WHERE id = v_project_id
     RETURNING version INTO v_version;

    RETURN QUERY SELECT v_project_id, v_version, v_image_id;
END;
$$;


