--
-- Name: begin_conversation_delivery_session(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.begin_conversation_delivery_session(p_task_id uuid, p_execution_token uuid, p_execution_attempt integer, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_session conversation_delivery_sessions%ROWTYPE;
    v_stream_id UUID;
BEGIN
    IF p_task_id IS NULL OR p_execution_token IS NULL
       OR p_execution_attempt < 1 OR p_message_id IS NULL THEN
        RAISE EXCEPTION 'DELIVERY_SESSION_BEGIN_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB)
       OR v_task.assistant_message_id IS DISTINCT FROM p_message_id THEN
        RAISE EXCEPTION 'DELIVERY_SESSION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token
       OR v_task.execution_attempt IS DISTINCT FROM p_execution_attempt THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    SELECT * INTO v_session
      FROM conversation_delivery_sessions
     WHERE task_id = p_task_id
     FOR UPDATE;

    IF FOUND
       AND v_session.execution_token IS NOT DISTINCT FROM p_execution_token
       AND v_session.execution_attempt = p_execution_attempt
       AND v_session.status = 'streaming' THEN
        RETURN jsonb_build_object(
            'outcome', 'existing',
            'session_id', v_session.id,
            'stream_id', v_session.stream_id,
            'execution_attempt', v_session.execution_attempt,
            'next_seq', v_session.next_seq,
            'snapshot_seq', v_session.snapshot_seq,
            'snapshot_content', v_session.snapshot_content,
            'snapshot_blocks', v_session.snapshot_blocks
        );
    END IF;

    IF v_session.id IS NOT NULL THEN
        -- 一个 task 只保留当前 delivery stream；旧 attempt 由 ReplayCheckpoint
        -- 恢复模型，旧交付事件不能再次被页面消费。
        DELETE FROM conversation_delivery_events
         WHERE session_id = v_session.id;
    END IF;

    v_stream_id := uuid_generate_v4();
    INSERT INTO conversation_delivery_sessions(
        task_id, conversation_id, message_id, stream_id,
        execution_token, execution_attempt, status, next_seq,
        snapshot_seq, snapshot_content, snapshot_blocks
    ) VALUES (
        p_task_id, v_task.conversation_id, p_message_id, v_stream_id,
        p_execution_token, p_execution_attempt, 'streaming', 0,
        0, COALESCE(v_task.accumulated_content, ''),
        COALESCE(v_task.accumulated_blocks, '[]'::JSONB)
    )
    ON CONFLICT (task_id) DO UPDATE SET
        conversation_id = EXCLUDED.conversation_id,
        message_id = EXCLUDED.message_id,
        stream_id = EXCLUDED.stream_id,
        execution_token = EXCLUDED.execution_token,
        execution_attempt = EXCLUDED.execution_attempt,
        status = EXCLUDED.status,
        next_seq = EXCLUDED.next_seq,
        snapshot_seq = EXCLUDED.snapshot_seq,
        snapshot_content = EXCLUDED.snapshot_content,
        snapshot_blocks = EXCLUDED.snapshot_blocks,
        updated_at = NOW()
    RETURNING * INTO v_session;

    RETURN jsonb_build_object(
        'outcome', 'started',
        'session_id', v_session.id,
        'stream_id', v_session.stream_id,
        'execution_attempt', v_session.execution_attempt,
        'next_seq', v_session.next_seq,
        'snapshot_seq', v_session.snapshot_seq,
        'snapshot_content', v_session.snapshot_content,
        'snapshot_blocks', v_session.snapshot_blocks
    );
END;
$$;


ALTER FUNCTION public.begin_conversation_delivery_session(p_task_id uuid, p_execution_token uuid, p_execution_attempt integer, p_message_id uuid) OWNER TO everydayai;

--
-- Name: begin_tool_invocation(uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.begin_tool_invocation(p_task_id uuid, p_conversation_id uuid, p_turn_id uuid, p_execution_token uuid, p_tool_call_id text, p_tool_name text, p_args_hash text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_task tasks%ROWTYPE;
    v_invocation tool_invocations%ROWTYPE;
BEGIN
    IF p_task_id IS NULL OR p_conversation_id IS NULL OR p_turn_id IS NULL
       OR p_execution_token IS NULL
       OR NULLIF(BTRIM(p_tool_call_id), '') IS NULL
       OR NULLIF(BTRIM(p_tool_name), '') IS NULL
       OR p_args_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'ACTOR_TOOL_INVOCATION_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR v_task.conversation_id IS DISTINCT FROM p_conversation_id
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_TOOL_INVOCATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    SELECT * INTO v_invocation
      FROM tool_invocations
     WHERE task_id = p_task_id
       AND turn_id = p_turn_id
       AND tool_call_id = BTRIM(p_tool_call_id)
     FOR UPDATE;

    IF FOUND THEN
        IF v_invocation.tool_name IS DISTINCT FROM BTRIM(p_tool_name)
           OR v_invocation.args_hash IS DISTINCT FROM p_args_hash
           OR v_invocation.conversation_id IS DISTINCT FROM p_conversation_id THEN
            RAISE EXCEPTION 'ACTOR_TOOL_INVOCATION_REUSE_MISMATCH'
                USING ERRCODE = '42501';
        END IF;
        IF v_invocation.status = 'succeeded' THEN
            RETURN jsonb_build_object(
                'outcome', 'replay', 'result', v_invocation.result
            );
        END IF;
        IF v_invocation.status = 'uncertain' THEN
            RETURN jsonb_build_object(
                'outcome', 'uncertain', 'error_message', v_invocation.error_message
            );
        END IF;
        RETURN jsonb_build_object('outcome', 'in_progress');
    END IF;

    INSERT INTO tool_invocations(
        task_id, conversation_id, turn_id, tool_call_id,
        tool_name, args_hash, status, execution_token
    ) VALUES (
        p_task_id, p_conversation_id, p_turn_id, BTRIM(p_tool_call_id),
        BTRIM(p_tool_name), p_args_hash, 'running', p_execution_token
    );
    RETURN jsonb_build_object('outcome', 'execute');
END;
$_$;


ALTER FUNCTION public.begin_tool_invocation(p_task_id uuid, p_conversation_id uuid, p_turn_id uuid, p_execution_token uuid, p_tool_call_id text, p_tool_name text, p_args_hash text) OWNER TO everydayai;

--
-- Name: bind_chat_image_submission(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.bind_chat_image_submission(p_task_id uuid, p_claim_token uuid, p_external_task_id text, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_task public.tasks%ROWTYPE; v_lifecycle JSONB;
BEGIN
    PERFORM public.assert_chat_image_worker(p_org_id);
    IF NULLIF(BTRIM(p_external_task_id),'') IS NULL OR length(p_external_task_id)>100 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_EXTERNAL_ID_INVALID' USING ERRCODE='22023';
    END IF;
    SELECT * INTO v_task FROM public.tasks WHERE id=p_task_id AND type='image'
        AND org_id IS NOT DISTINCT FROM p_org_id FOR UPDATE;
    IF NOT FOUND OR NOT (v_task.request_params ? '_media_request_v1') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE='42501';
    END IF;
    v_lifecycle:=v_task.request_params->'_media_lifecycle_v1';
    IF v_task.external_task_id=p_external_task_id THEN RETURN jsonb_build_object('outcome','accepted'); END IF;
    IF v_lifecycle->>'claim_token' IS DISTINCT FROM p_claim_token::TEXT
       OR COALESCE(v_lifecycle->>'phase','') NOT IN ('submitting','uncertain')
       OR v_task.external_task_id IS NOT NULL THEN RETURN jsonb_build_object('outcome','not_owned'); END IF;
    UPDATE public.tasks SET external_task_id=p_external_task_id,
        request_params=jsonb_set(request_params,'{_media_lifecycle_v1}',
            v_lifecycle || jsonb_build_object('phase','accepted','accepted_at',NOW())),
        version=COALESCE(version,0)+1 WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','accepted');
END;
$$;


ALTER FUNCTION public.bind_chat_image_submission(p_task_id uuid, p_claim_token uuid, p_external_task_id text, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: bind_ecom_workflow(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.bind_ecom_workflow(p_task_id uuid, p_execution_token uuid, p_binding jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE t public.tasks%ROWTYPE; p public.ecom_image_plans%ROWTYPE; old JSONB;
BEGIN
    SELECT * INTO t FROM public.tasks WHERE id=p_task_id FOR UPDATE;
    IF SESSION_USER <> 'everydayai' OR current_setting('app.access_kind',TRUE) <> 'runtime'
       OR t.id IS NULL OR t.status <> 'running' OR t.execution_token IS DISTINCT FROM p_execution_token
       OR p_execution_token IS NULL OR t.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',TRUE),'')::uuid
       OR t.org_id IS DISTINCT FROM NULLIF(current_setting('app.org_id',TRUE),'')::uuid
       OR jsonb_typeof(p_binding) IS DISTINCT FROM 'object'
       OR p_binding->>'kind' IS DISTINCT FROM 'main_images' OR p_binding->>'version' IS DISTINCT FROM '1'
       OR p_binding->>'generation_run_id' IS NULL THEN
        RAISE EXCEPTION 'ECOM_WORKFLOW_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
    IF p_binding->>'plan_id' IS NOT NULL THEN
        SELECT * INTO p FROM public.ecom_image_plans WHERE id=(p_binding->>'plan_id')::uuid;
        IF p.id IS NULL OR p.user_id IS DISTINCT FROM t.user_id OR p.org_id IS DISTINCT FROM t.org_id
           OR p.conversation_id IS DISTINCT FROM t.conversation_id THEN
            RAISE EXCEPTION 'ECOM_WORKFLOW_PLAN_DENIED' USING ERRCODE='42501';
        END IF;
    END IF;
    old=t.request_params->'_ecom_workflow';
    IF old->>'generation_run_id' IS NOT NULL AND old->>'generation_run_id' IS DISTINCT FROM p_binding->>'generation_run_id' THEN
        RAISE EXCEPTION 'ECOM_WORKFLOW_BINDING_CONFLICT' USING ERRCODE='22023';
    END IF;
    UPDATE public.tasks SET request_params=jsonb_set(COALESCE(request_params,'{}'::jsonb),'{_ecom_workflow}',p_binding)
        WHERE id=t.id;
    RETURN p_binding;
END $$;


ALTER FUNCTION public.bind_ecom_workflow(p_task_id uuid, p_execution_token uuid, p_binding jsonb) OWNER TO everydayai_owner;

--
-- Name: bind_generation_turn(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.bind_generation_turn(p_conversation_id uuid, p_task_id uuid, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text DEFAULT 'serial'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_task tasks%ROWTYPE;
    v_input messages%ROWTYPE;
    v_output messages%ROWTYPE;
BEGIN
    IF p_turn_id IS NULL
       OR p_execution_mode IS NULL
       OR p_execution_mode NOT IN ('serial', 'branch') THEN
        RAISE EXCEPTION 'TURN_BIND_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_conversation
      FROM conversations
     WHERE id = p_conversation_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'TURN_CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND
       OR v_task.conversation_id IS DISTINCT FROM p_conversation_id
       OR v_task.org_id IS DISTINCT FROM v_conversation.org_id THEN
        RAISE EXCEPTION 'TURN_TASK_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_input FROM messages WHERE id = p_input_message_id;
    IF NOT FOUND
       OR v_input.conversation_id IS DISTINCT FROM p_conversation_id
       OR v_input.org_id IS DISTINCT FROM v_conversation.org_id
       OR v_input.role::TEXT <> 'user' THEN
        RAISE EXCEPTION 'TURN_INPUT_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_output FROM messages WHERE id = v_task.assistant_message_id;
    IF NOT FOUND
       OR v_output.conversation_id IS DISTINCT FROM p_conversation_id
       OR v_output.org_id IS DISTINCT FROM v_conversation.org_id
       OR v_output.role::TEXT <> 'assistant'
       OR (v_output.turn_id IS NOT NULL AND v_output.turn_id IS DISTINCT FROM p_turn_id)
       OR (v_output.reply_to_message_id IS NOT NULL
           AND v_output.reply_to_message_id IS DISTINCT FROM p_input_message_id)
       OR (v_input.turn_id IS NOT NULL AND v_input.turn_id IS DISTINCT FROM p_turn_id) THEN
        RAISE EXCEPTION 'TURN_MESSAGE_RELATION_MISMATCH' USING ERRCODE = '23505';
    END IF;

    IF v_task.input_message_id IS NOT NULL
       OR v_task.turn_id IS NOT NULL
       OR v_task.base_context_revision IS NOT NULL THEN
        IF v_task.input_message_id IS DISTINCT FROM p_input_message_id
           OR v_task.turn_id IS DISTINCT FROM p_turn_id
           OR v_task.execution_mode IS DISTINCT FROM p_execution_mode THEN
            RAISE EXCEPTION 'TURN_ALREADY_BOUND' USING ERRCODE = '23505';
        END IF;
    ELSE
        UPDATE messages SET turn_id = p_turn_id WHERE id = p_input_message_id;
        UPDATE messages
           SET turn_id = p_turn_id,
               reply_to_message_id = p_input_message_id
         WHERE id = v_task.assistant_message_id;
        UPDATE tasks
           SET input_message_id = p_input_message_id,
               turn_id = p_turn_id,
               base_context_revision = v_conversation.context_revision,
               context_through_message_id = v_conversation.last_closed_message_id,
               execution_mode = p_execution_mode
         WHERE id = p_task_id
         RETURNING * INTO v_task;
    END IF;

    RETURN jsonb_build_object(
        'turn_id', p_turn_id,
        'input_message_id', p_input_message_id,
        'base_context_revision', v_task.base_context_revision,
        'context_through_message_id', v_task.context_through_message_id,
        'execution_mode', p_execution_mode
    );
END;
$$;


ALTER FUNCTION public.bind_generation_turn(p_conversation_id uuid, p_task_id uuid, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text) OWNER TO everydayai;

--
-- Name: FUNCTION bind_generation_turn(p_conversation_id uuid, p_task_id uuid, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.bind_generation_turn(p_conversation_id uuid, p_task_id uuid, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text) IS '原子绑定生成任务的输入、Turn 和上下文基线；完全相同的重复调用幂等';


--
-- Name: bind_generation_turn(uuid, uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.bind_generation_turn(p_conversation_id uuid, p_task_id uuid, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org_id UUID;
BEGIN
    SELECT org_id INTO v_org_id
      FROM conversations
     WHERE id = p_conversation_id;
    IF NOT FOUND OR v_org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'TURN_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    RETURN bind_generation_turn(
        p_conversation_id,
        p_task_id,
        p_input_message_id,
        p_turn_id,
        p_execution_mode
    );
END;
$$;


ALTER FUNCTION public.bind_generation_turn(p_conversation_id uuid, p_task_id uuid, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text, p_org_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION bind_generation_turn(p_conversation_id uuid, p_task_id uuid, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.bind_generation_turn(p_conversation_id uuid, p_task_id uuid, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text, p_org_id uuid) IS '租户范围校验后调用 Turn 绑定原子核心';


--
-- Name: bind_task_attachments(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.bind_task_attachments(p_task_id uuid, p_turn_id uuid, p_input_message_id uuid, p_conversation_id uuid, p_org_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    INSERT INTO task_attachment_refs(
        org_id, task_id, turn_id, input_message_id, attachment_id,
        attachment_set_id
    )
    SELECT p_org_id, p_task_id, p_turn_id, p_input_message_id, a.id,
           a.attachment_set_id
      FROM conversation_attachment_refs a
     WHERE a.conversation_id = p_conversation_id
       AND a.org_id = p_org_id
       AND a.status = 'ready'
       AND a.reference_state = 'active'
       AND a.attachment_set_id = (
           SELECT attachment_set_id
             FROM conversation_attachment_refs
            WHERE conversation_id = p_conversation_id
              AND org_id = p_org_id
              AND status = 'ready'
              AND reference_state = 'active'
            ORDER BY created_at DESC
            LIMIT 1
       )
    ON CONFLICT (task_id, attachment_id) DO NOTHING;
    GET DIAGNOSTICS v_count = ROW_COUNT;

    UPDATE conversation_attachment_refs a
       SET reference_state = 'referenced',
           last_referenced_at = NOW()
     WHERE a.reference_state = 'active'
       AND EXISTS (
           SELECT 1
             FROM task_attachment_refs r
            WHERE r.task_id = p_task_id
              AND r.input_message_id = p_input_message_id
              AND r.attachment_id = a.id
       );
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.bind_task_attachments(p_task_id uuid, p_turn_id uuid, p_input_message_id uuid, p_conversation_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: bump_scheduled_task_revision(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.bump_scheduled_task_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        NEW.schedule_enabled := NEW.status='active';
        RETURN NEW;
    END IF;
    IF OLD.status <> 'running' AND NEW.status='running' THEN
        NEW.run_token := gen_random_uuid();
        NEW.claimed_at := NOW();
        NEW.run_claim_revision := OLD.revision;
        NEW.run_previous_status := OLD.status;
    ELSIF NEW.status <> 'running' THEN
        IF OLD.status='running' AND NOT OLD.schedule_enabled THEN
            NEW.status := CASE WHEN OLD.run_previous_status='error' THEN 'error' ELSE 'paused' END;
            NEW.next_run_at := NULL;
        END IF;
        NEW.schedule_enabled := NEW.status='active';
        NEW.run_token := NULL;
        NEW.claimed_at := NULL;
        NEW.run_claim_revision := NULL;
        NEW.run_manual := FALSE;
        NEW.run_previous_status := NULL;
    END IF;
    -- Definition revision does not change on claim/result/progress bookkeeping.
    IF NEW.revision=OLD.revision AND
       (to_jsonb(NEW) - ARRAY['revision','status','next_run_at','run_token','claimed_at','run_manual',
        'config_revision','run_config_revision','retry_config_revision','run_previous_status','run_claim_revision','notification_state','last_run_at','last_summary','last_result','run_count','consecutive_failures','updated_at'])
       IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['revision','status','next_run_at','run_token','claimed_at','run_manual',
        'config_revision','run_config_revision','retry_config_revision','run_previous_status','run_claim_revision','notification_state','last_run_at','last_summary','last_result','run_count','consecutive_failures','updated_at']) THEN
        NEW.revision := OLD.revision+1;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.bump_scheduled_task_revision() OWNER TO everydayai;

--
-- Name: cancel_generation_turn(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.cancel_generation_turn(p_task_id uuid, p_user_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_task tasks%ROWTYPE;
    v_output messages%ROWTYPE;
    v_conversation_id UUID;
    v_snapshot JSONB := '[]'::JSONB;
    v_blocks_text TEXT := '';
    v_remaining_text TEXT := '';
    v_now_iso TEXT := to_char(clock_timestamp() AT TIME ZONE 'UTC',
                              'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
    v_message_updated INTEGER := 0;
BEGIN
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_CANCEL_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    -- 与 122 保持一致：conversation -> task，避免和其他 Actor RPC 形成反向锁。
    SELECT conversation_id INTO v_conversation_id FROM tasks WHERE id = p_task_id;
    IF v_conversation_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_conversation FROM conversations
     WHERE id = v_conversation_id FOR UPDATE;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;

    IF v_task.id IS NULL OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB)
       OR v_task.conversation_id IS DISTINCT FROM v_conversation.id
       OR v_task.user_id IS DISTINCT FROM p_user_id
       OR v_task.org_id IS DISTINCT FROM p_org_id
       OR v_conversation.user_id IS DISTINCT FROM p_user_id
       OR v_conversation.org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'ACTOR_CANCEL_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.status = 'cancelled' THEN
        RETURN jsonb_build_object(
            'outcome', 'already_cancelled',
            'task_id', p_task_id,
            'snapshot_saved', FALSE
        );
    END IF;
    IF v_task.status NOT IN ('pending', 'running') THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;

    -- 消息锁位于 task 锁之后。缺少消息时仍允许取消，但会明确返回
    -- snapshot_saved=false，避免取消入口被一个已损坏的占位消息阻塞。
    IF v_task.assistant_message_id IS NOT NULL THEN
        SELECT * INTO v_output FROM messages
         WHERE id = v_task.assistant_message_id FOR UPDATE;
    END IF;

    -- 优先使用 fencing 进度；没有进度时保留已有助手消息内容，避免把非空内容
    -- 覆盖成空数组。兼容旧任务只有 accumulated_content 的情况。
    IF jsonb_typeof(v_task.accumulated_blocks) = 'array'
       AND jsonb_array_length(v_task.accumulated_blocks) > 0 THEN
        v_snapshot := v_task.accumulated_blocks;
    ELSIF v_task.accumulated_content IS NOT NULL
          AND BTRIM(v_task.accumulated_content) <> '' THEN
        v_snapshot := jsonb_build_array(
            jsonb_build_object('type', 'text', 'text', v_task.accumulated_content)
        );
    ELSIF v_output.id IS NOT NULL
          AND jsonb_typeof(v_output.content) = 'array'
          AND jsonb_array_length(v_output.content) > 0 THEN
        v_snapshot := v_output.content;
    END IF;

    -- 与 services.task_utils.merge_blocks_with_text 保持同一规则：
    -- blocks 中已提交的 text 是前缀，task 累积全文中的剩余部分追加为新 text block。
    IF jsonb_typeof(v_task.accumulated_blocks) = 'array'
       AND jsonb_array_length(v_task.accumulated_blocks) > 0
       AND v_task.accumulated_content IS NOT NULL THEN
        SELECT COALESCE(string_agg(item.value->>'text', '' ORDER BY item.ordinality), '')
          INTO v_blocks_text
          FROM jsonb_array_elements(v_snapshot) WITH ORDINALITY AS item(value, ordinality)
         WHERE item.value->>'type' = 'text';
        IF LEFT(v_task.accumulated_content, LENGTH(v_blocks_text)) = v_blocks_text
           AND LENGTH(v_task.accumulated_content) > LENGTH(v_blocks_text) THEN
            v_remaining_text := SUBSTRING(v_task.accumulated_content
                                          FROM LENGTH(v_blocks_text) + 1);
            IF BTRIM(v_remaining_text) <> '' THEN
                v_snapshot := v_snapshot || jsonb_build_array(
                    jsonb_build_object('type', 'text', 'text', v_remaining_text)
                );
            END IF;
        END IF;
    END IF;

    -- 取消时将仍处于 running 的工具步骤显式标记为 cancelled，避免恢复历史
    -- 把一个已经被用户终止的工具误判为仍在执行。
    SELECT COALESCE(jsonb_agg(
        CASE
            WHEN item.value->>'type' = 'tool_step'
             AND item.value->>'status' = 'running'
            THEN item.value || jsonb_build_object(
                'status', 'cancelled', 'cancelled_at', v_now_iso
            )
            ELSE item.value
        END
        ORDER BY item.ordinality
    ), '[]'::JSONB)
      INTO v_snapshot
      FROM jsonb_array_elements(v_snapshot) WITH ORDINALITY AS item(value, ordinality);

    IF NOT EXISTS (
        SELECT 1
          FROM jsonb_array_elements(v_snapshot) AS item(value)
         WHERE item.value->>'type' = 'interrupt_marker'
    ) THEN
        v_snapshot := v_snapshot || jsonb_build_array(
            jsonb_build_object(
                'type', 'interrupt_marker',
                'interrupted_at', v_now_iso,
                'reason', 'user_cancel'
            )
        );
    END IF;

    -- 主事实（messages）与任务终态在同一 RPC 事务中更新。
    IF v_output.id IS NOT NULL THEN
        UPDATE messages
           SET content = v_snapshot,
               status = 'interrupted'
         WHERE id = v_output.id
           AND status IS DISTINCT FROM 'completed';
        GET DIAGNOSTICS v_message_updated = ROW_COUNT;
    END IF;

    UPDATE tasks
       SET status = 'cancelled',
           error_message = '用户取消了任务',
           completed_at = NOW(),
           execution_token = NULL,
           lease_expires_at = NULL,
           terminal_reason = 'user_cancelled'
     WHERE id = p_task_id;
    UPDATE conversations
       SET active_serial_task_id = NULL,
           actor_updated_at = NOW()
     WHERE id = v_conversation.id
       AND active_serial_task_id = p_task_id;

    RETURN jsonb_build_object(
        'outcome', 'cancelled',
        'task_id', p_task_id,
        'snapshot_saved', v_message_updated = 1,
        'snapshot_blocks', jsonb_array_length(v_snapshot)
    );
END;
$$;


ALTER FUNCTION public.cancel_generation_turn(p_task_id uuid, p_user_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION cancel_generation_turn(p_task_id uuid, p_user_id uuid, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.cancel_generation_turn(p_task_id uuid, p_user_id uuid, p_org_id uuid) IS '用户范围校验后，在同一事务中保存 Actor 部分生成快照、追加中断标记并取消 Chat task';


--
-- Name: cancel_generation_turn_owned(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.cancel_generation_turn_owned(p_task_id uuid, p_execution_token uuid, p_reason text DEFAULT 'user_cancelled'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_conversation conversations%ROWTYPE;
    v_snapshot JSONB;
BEGIN
    IF p_task_id IS NULL OR p_execution_token IS NULL THEN
        RAISE EXCEPTION 'ACTOR_CANCEL_OWNER_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF v_task.id IS NULL OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_CANCEL_OWNER_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.status = 'cancelled' THEN
        RETURN jsonb_build_object('outcome', 'already_cancelled', 'task_id', p_task_id);
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    SELECT * INTO v_conversation FROM conversations
     WHERE id = v_task.conversation_id FOR UPDATE;
    IF v_conversation.id IS NULL OR v_conversation.org_id IS DISTINCT FROM v_task.org_id THEN
        RAISE EXCEPTION 'ACTOR_CANCEL_OWNER_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    v_snapshot := public.materialize_actor_cancel_snapshot(p_task_id);
    UPDATE tasks SET status = 'cancelled',
        error_message = COALESCE(NULLIF(BTRIM(p_reason), ''), '用户取消了任务'),
        completed_at = NOW(), execution_token = NULL, lease_expires_at = NULL,
        terminal_reason = 'user_cancelled'
     WHERE id = p_task_id;
    UPDATE conversations SET active_serial_task_id = NULL, actor_updated_at = NOW()
     WHERE id = v_conversation.id AND active_serial_task_id = p_task_id;
    RETURN jsonb_build_object(
        'outcome', 'cancelled', 'task_id', p_task_id,
        'snapshot_saved', COALESCE((v_snapshot->>'saved')::BOOLEAN, FALSE)
    );
END;
$$;


ALTER FUNCTION public.cancel_generation_turn_owned(p_task_id uuid, p_execution_token uuid, p_reason text) OWNER TO everydayai;

--
-- Name: cancel_paused_generation_turn(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.cancel_paused_generation_turn(p_task_id uuid, p_user_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_conversation conversations%ROWTYPE;
    v_snapshot JSONB;
BEGIN
    IF p_task_id IS NULL OR p_user_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_CANCEL_PAUSED_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    SELECT * INTO v_conversation FROM conversations
     WHERE id = v_task.conversation_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB)
       OR v_task.user_id IS DISTINCT FROM p_user_id
       OR v_task.org_id IS DISTINCT FROM p_org_id
       OR v_conversation.user_id IS DISTINCT FROM p_user_id
       OR v_conversation.org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'ACTOR_CANCEL_PAUSED_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.status = 'cancelled' THEN
        RETURN jsonb_build_object('outcome', 'already_cancelled', 'task_id', p_task_id);
    END IF;
    IF v_task.status <> 'paused' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;

    v_snapshot := public.materialize_actor_cancel_snapshot(p_task_id);
    UPDATE tasks SET status = 'cancelled', error_message = '用户取消了任务',
        completed_at = NOW(), execution_token = NULL, lease_expires_at = NULL,
        terminal_reason = 'user_cancelled'
     WHERE id = p_task_id;
    UPDATE conversations SET active_serial_task_id = NULL, actor_updated_at = NOW()
     WHERE id = v_conversation.id AND active_serial_task_id = p_task_id;
    RETURN jsonb_build_object(
        'outcome', 'cancelled', 'task_id', p_task_id,
        'snapshot_saved', COALESCE((v_snapshot->>'saved')::BOOLEAN, FALSE)
    );
END;
$$;


ALTER FUNCTION public.cancel_paused_generation_turn(p_task_id uuid, p_user_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: capture_scheduled_task_config(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.capture_scheduled_task_config() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE definition JSONB;
BEGIN
    definition := public.scheduled_task_definition(NEW);
    IF TG_OP='INSERT' OR definition IS DISTINCT FROM public.scheduled_task_definition(OLD) THEN
        IF jsonb_typeof(NEW.skill_revision_snapshot) IS DISTINCT FROM 'object'
           OR NEW.skill_revision_snapshot->'version' IS DISTINCT FROM '1'::jsonb
           OR jsonb_typeof(NEW.skill_revision_snapshot->'skills') IS DISTINCT FROM 'array'
           OR jsonb_array_length(NEW.skill_revision_snapshot->'skills') > 4 THEN
            RAISE EXCEPTION 'SKILL_SCHEDULED_SNAPSHOT_INVALID' USING ERRCODE='23514';
        END IF;
        INSERT INTO public.scheduled_task_config_revisions(task_id,org_id,definition_snapshot)
        VALUES(NEW.id,NEW.org_id,definition) RETURNING id INTO NEW.config_revision;
    ELSE
        NEW.config_revision := OLD.config_revision;
    END IF;
    IF TG_OP='UPDATE' AND OLD.status <> 'running' AND NEW.status='running' THEN
        NEW.run_config_revision := COALESCE(OLD.retry_config_revision,OLD.config_revision);
    ELSIF NEW.status <> 'running' THEN
        NEW.run_config_revision := NULL;
    ELSE
        NEW.run_config_revision := OLD.run_config_revision;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.capture_scheduled_task_config() OWNER TO everydayai;

--
-- Name: change_governed_member_role(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.change_governed_member_role(p_org_id uuid, p_target_user_id uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_authority TEXT;
    v_previous_role TEXT;
    v_member public.org_members%ROWTYPE;
BEGIN
    v_authority := public._assert_governance_authority(
        p_org_id, ARRAY['owner'], FALSE
    );
    IF p_role NOT IN ('admin', 'member')
       OR p_target_user_id = public.tenant_actor_user_id() THEN
        RAISE EXCEPTION 'GOVERNANCE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT role INTO v_previous_role FROM public.org_members
     WHERE org_id = p_org_id AND user_id = p_target_user_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'GOVERNANCE_MEMBER_MISSING'
            USING ERRCODE = 'P0002';
    END IF;
    IF v_previous_role = 'owner' THEN
        RAISE EXCEPTION 'GOVERNANCE_AUTHORITY_DENIED'
            USING ERRCODE = '42501';
    END IF;
    UPDATE public.org_members SET role = p_role
     WHERE org_id = p_org_id AND user_id = p_target_user_id
     RETURNING * INTO v_member;
    PERFORM public._record_governance_audit(
        p_org_id, v_authority, 'member.role_change', 'member',
        p_target_user_id::TEXT,
        jsonb_build_object(
            'previous_role', v_previous_role, 'role', p_role
        )
    );
    RETURN to_jsonb(v_member);
END;
$$;


ALTER FUNCTION public.change_governed_member_role(p_org_id uuid, p_target_user_id uuid, p_role text) OWNER TO everydayai_owner;

--
-- Name: chat_image_platform_cost_report(timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.chat_image_platform_cost_report(p_since timestamp with time zone, p_until timestamp with time zone, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_summary JSONB; v_items JSONB;
BEGIN
    IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',TRUE) IS DISTINCT FROM 'runtime_admin'
       OR NOT EXISTS(SELECT 1 FROM public.users WHERE id=NULLIF(current_setting('app.actor_user_id',TRUE),'')::UUID
            AND status='active' AND role='super_admin') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_COST_ADMIN_DENIED' USING ERRCODE='42501';
    END IF;
    IF p_since IS NULL OR p_until IS NULL OR p_since>=p_until
       OR p_until-p_since>INTERVAL '366 days' OR p_page IS NULL OR p_page NOT BETWEEN 1 AND 100000
       OR p_page_size IS NULL OR p_page_size NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_COST_RANGE_INVALID' USING ERRCODE='22023';
    END IF;
    SELECT jsonb_build_object('count',COUNT(*),
        'refunded_user_credits',COALESCE(SUM((request_params->'_media_platform_cost_v1'->>'refunded_user_credits')::BIGINT),0),
        'estimated_provider_credits',COALESCE(SUM((request_params->'_media_platform_cost_v1'->>'estimated_provider_credits')::BIGINT),0),
        'evidence','unconfirmed','since',p_since,'until',p_until) INTO v_summary
    FROM public.tasks WHERE request_params ? '_media_platform_cost_v1' AND completed_at>=p_since AND completed_at<p_until;
    SELECT COALESCE(jsonb_agg(item ORDER BY completed_at DESC,id DESC),'[]'::JSONB) INTO v_items FROM (
        SELECT id,completed_at,jsonb_build_object('task_id',id,'org_id',org_id,'user_id',user_id,
            'completed_at',completed_at,'cost',request_params->'_media_platform_cost_v1') AS item
        FROM public.tasks WHERE request_params ? '_media_platform_cost_v1' AND completed_at>=p_since AND completed_at<p_until
        ORDER BY completed_at DESC,id DESC LIMIT p_page_size OFFSET (p_page-1)*p_page_size
    ) page;
    RETURN jsonb_build_object('summary',v_summary,'items',v_items,'page',p_page,'page_size',p_page_size);
END;
$$;


ALTER FUNCTION public.chat_image_platform_cost_report(p_since timestamp with time zone, p_until timestamp with time zone, p_page integer, p_page_size integer) OWNER TO everydayai_owner;

--
-- Name: claim_branch_generation_turn(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.claim_branch_generation_turn(p_task_id uuid, p_lease_seconds integer DEFAULT 90, p_max_attempts integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_task tasks%ROWTYPE;
    v_token UUID;
    v_sources JSONB;
    v_conversation_id UUID;
BEGIN
    IF p_lease_seconds NOT BETWEEN 15 AND 300 OR p_max_attempts < 1 THEN
        RAISE EXCEPTION 'ACTOR_CLAIM_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT conversation_id INTO v_conversation_id FROM tasks WHERE id = p_task_id;
    IF v_conversation_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_conversation
      FROM conversations
     WHERE id = v_conversation_id
     FOR UPDATE;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF v_task.id IS NULL
       OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB)
       OR v_task.execution_mode <> 'branch'
       OR v_task.input_message_id IS NULL
       OR v_task.turn_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_BRANCH_NOT_CLAIMABLE' USING ERRCODE = '55000';
    END IF;
    IF v_task.status = 'running' AND v_task.lease_expires_at > NOW() THEN
        RETURN jsonb_build_object('outcome', 'busy');
    END IF;
    IF v_task.status = 'running' AND v_task.execution_attempt >= p_max_attempts THEN
        UPDATE tasks
           SET status = 'failed',
               terminal_reason = 'lease_attempts_exhausted',
               completed_at = NOW(),
               execution_token = NULL,
               lease_expires_at = NULL
         WHERE id = p_task_id;
        RETURN jsonb_build_object('outcome', 'attempts_exhausted');
    END IF;
    IF v_task.status NOT IN ('pending', 'running') THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;

    v_sources := public.freeze_chat_image_sources(v_task, v_conversation);
    v_token := uuid_generate_v4();
    UPDATE tasks
       SET status = 'running',
           execution_token = v_token,
           lease_expires_at = NOW() + make_interval(secs => p_lease_seconds),
           execution_attempt = execution_attempt + 1,
           started_at = COALESCE(started_at, NOW()),
           request_params = jsonb_set(COALESCE(request_params,'{}'::JSONB), '{_image_sources_v1}', v_sources),
           base_context_revision = (v_sources->>'base_revision')::BIGINT,
           context_through_message_id = (v_sources->>'through_message_id')::UUID,
           terminal_reason = NULL
     WHERE id = p_task_id
     RETURNING * INTO v_task;

    RETURN jsonb_build_object(
        'outcome', 'claimed',
        'task_id', v_task.id,
        'execution_token', v_token,
        'turn_id', v_task.turn_id,
        'input_message_id', v_task.input_message_id,
        'base_context_revision', v_task.base_context_revision,
        'context_through_message_id', v_task.context_through_message_id,
        'execution_attempt', v_task.execution_attempt
    );
END;
$$;


ALTER FUNCTION public.claim_branch_generation_turn(p_task_id uuid, p_lease_seconds integer, p_max_attempts integer) OWNER TO everydayai;

