--
-- Name: claim_chat_image_submission(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.claim_chat_image_submission(p_task_id uuid, p_claim_token uuid, p_lease_seconds integer, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_task public.tasks%ROWTYPE;
    v_snapshot JSONB;
    v_parent UUID;
    v_tx UUID := gen_random_uuid();
    v_cost INTEGER;
    v_balance INTEGER;
BEGIN
    IF SESSION_USER NOT IN ('everydayai', 'everydayai_worker')
       OR current_setting('app.access_kind', TRUE) IS DISTINCT FROM 'worker'
       OR NULLIF(current_setting('app.org_id', TRUE), '')::UUID IS DISTINCT FROM p_org_id
       OR p_claim_token IS NULL OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 10 AND 300 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_WORKER_DENIED' USING ERRCODE = '42501';
    END IF;
    SELECT (request_params->'_media_request_v1'->'origin'->>'parent_task_id')::UUID INTO v_parent
      FROM public.tasks WHERE id = p_task_id AND type = 'image' AND org_id IS NOT DISTINCT FROM p_org_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE = '42501';
    END IF;
    IF v_parent IS NULL THEN
        IF EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=p_task_id AND t.request_params->'_media_request_v1'->'origin'->>'destination'='detail_project') THEN
            PERFORM 1 FROM public.detail_projects d JOIN public.tasks t ON t.id=p_task_id
             WHERE d.id=(t.request_params->'_media_request_v1'->'origin'->>'project_id')::uuid
             AND d.user_id=t.user_id AND d.org_id IS NOT DISTINCT FROM p_org_id
             AND d.run_state->>'run_id'=t.request_params->'_media_request_v1'->'origin'->>'generation_run_id' FOR UPDATE OF d;
        ELSE
        PERFORM 1 FROM public.skill_draft_trial_runs r JOIN public.tasks t ON t.id=p_task_id
          WHERE t.request_params->'_media_request_v1'->'origin'->>'destination'='skill_trial'
            AND r.id=(t.request_params->'_media_request_v1'->'origin'->>'trial_id')::UUID
            AND r.actor_user_id=t.user_id AND r.org_id=p_org_id AND r.status='running'
            AND r.result->>'image_task_id'=p_task_id::TEXT FOR UPDATE OF r;
        IF NOT FOUND THEN RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE = '42501'; END IF;
        END IF;
        IF NOT FOUND THEN RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE='42501'; END IF;
    ELSE
        PERFORM 1 FROM public.tasks WHERE id = v_parent FOR UPDATE;
    END IF;
    SELECT * INTO v_task FROM public.tasks WHERE id = p_task_id FOR UPDATE;
    IF v_task.status <> 'pending' OR v_task.request_params->'_media_lifecycle_v1'->>'phase' <> 'queued' THEN
        RETURN jsonb_build_object('outcome','not_queued');
    END IF;
    v_snapshot := v_task.request_params->'_media_request_v1';
    v_cost := (v_snapshot->>'estimated_credits')::INTEGER;
    IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = v_task.user_id AND status::TEXT = 'active')
       OR (p_org_id IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM public.org_members
            WHERE org_id=p_org_id AND user_id=v_task.user_id AND status='active')
            OR NOT EXISTS (SELECT 1 FROM public.organizations WHERE id=p_org_id AND status='active'))) THEN
        RETURN jsonb_build_object('outcome','identity_denied');
    END IF;
    UPDATE public.users SET credits = credits-v_cost, updated_at=NOW()
     WHERE id=v_task.user_id AND credits >= v_cost RETURNING credits INTO v_balance;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome','insufficient_credits');
    END IF;
    INSERT INTO public.credit_transactions(id, task_id, user_id, org_id, amount, type, status, reason, expires_at)
    VALUES (v_tx,p_task_id,v_task.user_id,p_org_id,v_cost,'lock','pending','Chat image',NULL);
    -- No generic credit expiry can refund an accepted/uncertain provider request.
    UPDATE public.tasks SET credit_transaction_id=v_tx, credits_locked=v_cost,
        request_params=jsonb_set(request_params,'{_media_lifecycle_v1}',
            jsonb_build_object('phase','submitting','claim_token',p_claim_token,
                'lease_expires_at',NOW()+make_interval(secs=>p_lease_seconds), 'attempt',1)),
        started_at=NOW(), status='running', version=COALESCE(version,0)+1
    WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','claimed','transaction_id',v_tx,'task_id',p_task_id);
END;
$$;


ALTER FUNCTION public.claim_chat_image_submission(p_task_id uuid, p_claim_token uuid, p_lease_seconds integer, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: claim_conversation_delivery(integer, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.claim_conversation_delivery(p_lease_seconds integer DEFAULT 60, p_max_attempts integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_delivery conversation_deliveries%ROWTYPE;
    v_token UUID;
BEGIN
    IF p_lease_seconds NOT BETWEEN 15 AND 300 OR p_max_attempts < 1 THEN
        RAISE EXCEPTION 'DELIVERY_CLAIM_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    UPDATE conversation_deliveries
       SET status = 'dead', lease_token = NULL, lease_expires_at = NULL,
           last_error = COALESCE(
               last_error, 'delivery lease expired after max attempts'
           ),
           updated_at = NOW()
     WHERE status = 'delivering'
       AND lease_expires_at IS NOT NULL
       AND lease_expires_at <= NOW()
       AND attempt_count >= p_max_attempts;

    SELECT * INTO v_delivery
      FROM conversation_deliveries
     WHERE (
            status = 'pending'
            OR (
                status = 'delivering'
                AND lease_expires_at IS NOT NULL
                AND lease_expires_at <= NOW()
            )
       )
       AND next_attempt_at <= NOW()
       AND attempt_count < p_max_attempts
     ORDER BY next_attempt_at, created_at, id
     FOR UPDATE SKIP LOCKED
     LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'empty');
    END IF;

    v_token := uuid_generate_v4();
    UPDATE conversation_deliveries
       SET status = 'delivering',
           attempt_count = attempt_count + 1,
           lease_token = v_token,
           lease_expires_at = NOW() + make_interval(secs => p_lease_seconds),
           updated_at = NOW()
     WHERE id = v_delivery.id
     RETURNING * INTO v_delivery;

    RETURN jsonb_build_object(
        'outcome', 'claimed',
        'delivery_id', v_delivery.id,
        'task_id', v_delivery.task_id,
        'channel', v_delivery.channel,
        'delivery_kind', v_delivery.delivery_kind,
        'target_context', v_delivery.target_context,
        'attempt_count', v_delivery.attempt_count,
        'delivered_items', v_delivery.delivered_items,
        'lease_token', v_token
    );
END;
$$;


ALTER FUNCTION public.claim_conversation_delivery(p_lease_seconds integer, p_max_attempts integer) OWNER TO everydayai;

--
-- Name: claim_detail_delivery_retry(uuid, text, text, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.claim_detail_delivery_retry(p_plan_id uuid, p_key text, p_source text, p_token uuid, p_reason text, p_blocked boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE p public.ecom_image_plans%ROWTYPE; j JSONB; source public.tasks%ROWTYPE; latest UUID; delay INTEGER;
BEGIN
 p=public.lock_detail_delivery_plan(p_plan_id);
 IF p_token IS NULL OR p_blocked IS NULL OR p_reason IS NULL OR length(p_reason)>128
  OR p_source IS NULL OR length(p_source)>200 OR p_key IS NULL THEN
  RAISE EXCEPTION 'DETAIL_RETRY_INVALID' USING ERRCODE='22023'; END IF;
 IF p_key='plan' THEN
  IF p.status<>'failed' OR p.lease_expires_at>NOW()
   OR p_source IS DISTINCT FROM (COALESCE(p.recovery_state->>'window_task_id','initial')||':'||jsonb_array_length(p.stage_attempts)::text||':'||p.current_stage::text) THEN
   RETURN jsonb_build_object('outcome','stale'); END IF;
 ELSIF p_key='acceptance' THEN
  IF p.status<>'ready' OR p.recovery_state->'acceptance_error' IS NULL
   OR p_source IS DISTINCT FROM p.recovery_state->'acceptance_error'->>'attempt_id' THEN
   RETURN jsonb_build_object('outcome','stale'); END IF;
 ELSIF p_key ~ '^image:[0-9a-f-]{36}$' THEN
  SELECT * INTO source FROM public.tasks WHERE id=p_source::uuid;
  IF source.id IS NULL OR source.user_id IS DISTINCT FROM p.user_id OR source.org_id IS DISTINCT FROM p.org_id
   OR source.status<>'failed' OR source.request_params->'_media_lifecycle_v1'->>'phase' IS DISTINCT FROM 'published'
   OR source.request_params->'_media_request_v1'->'origin'->'plan_source'->>'plan_id' IS DISTINCT FROM p.id::text
   OR source.request_params->'_media_request_v1'->'origin'->>'generation_run_id' IS DISTINCT FROM p.generation_run_id::text
   OR p_key IS DISTINCT FROM 'image:'||(source.request_params->'_media_request_v1'->'origin'->'plan_source'->>'item_id') THEN
   RETURN jsonb_build_object('outcome','stale'); END IF;
  SELECT t.id INTO latest FROM public.tasks t
   WHERE t.user_id=p.user_id AND t.org_id IS NOT DISTINCT FROM p.org_id
   AND t.request_params->'_media_request_v1'->'origin'->'plan_source'->>'plan_id'=p.id::text
   AND t.request_params->'_media_request_v1'->'origin'->'plan_source'->>'item_id'=substring(p_key from 7)
   ORDER BY t.created_at DESC,t.id DESC LIMIT 1;
  IF latest IS DISTINCT FROM source.id THEN RETURN jsonb_build_object('outcome','stale'); END IF;
 ELSE RAISE EXCEPTION 'DETAIL_RETRY_INVALID' USING ERRCODE='22023'; END IF;
 j=COALESCE(p.delivery_recovery->p_key,'{}'::jsonb);
 IF p_blocked THEN
  j=j||jsonb_build_object('status','blocked','source',p_source,'reason',
   CASE WHEN j->>'source'=p_source AND j->>'status'='blocked' THEN COALESCE(j->>'reason',p_reason) ELSE p_reason END);
 ELSIF j->>'source' IS DISTINCT FROM p_source OR j->>'status'='blocked' THEN
  delay=LEAST(300,5*(2^LEAST(COALESCE((j->>'attempts')::int,0),6))::int);
  j=jsonb_build_object('status','waiting','source',p_source,'reason',p_reason,'request_id',gen_random_uuid(),
   'attempts',COALESCE((j->>'attempts')::int,0),'next_retry_at',NOW()+make_interval(secs=>delay));
 ELSIF j->>'status'='waiting' AND (j->>'next_retry_at')::timestamptz<=NOW()
  OR j->>'status'='running' AND (j->>'lease_expires_at')::timestamptz<=NOW() THEN
  j=j||jsonb_build_object('status','running','claim_token',p_token,'lease_expires_at',NOW()+interval '60 seconds',
   'attempts',COALESCE((j->>'attempts')::int,0)+1);
  UPDATE public.ecom_image_plans SET delivery_recovery=jsonb_set(delivery_recovery,ARRAY[p_key],j) WHERE id=p.id;
  RETURN j||jsonb_build_object('outcome','execute');
 END IF;
 UPDATE public.ecom_image_plans SET delivery_recovery=jsonb_set(delivery_recovery,ARRAY[p_key],j) WHERE id=p.id;
 RETURN j||jsonb_build_object('outcome','waiting');
END $_$;


ALTER FUNCTION public.claim_detail_delivery_retry(p_plan_id uuid, p_key text, p_source text, p_token uuid, p_reason text, p_blocked boolean) OWNER TO everydayai_owner;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: scheduled_tasks; Type: TABLE; Schema: public; Owner: everydayai
--

CREATE TABLE public.scheduled_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    user_id uuid NOT NULL,
    name character varying(100) NOT NULL,
    prompt text NOT NULL,
    cron_expr character varying(50),
    timezone character varying(50) DEFAULT 'Asia/Shanghai'::character varying NOT NULL,
    push_target jsonb NOT NULL,
    template_file jsonb,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    max_credits integer DEFAULT 10 NOT NULL,
    retry_count smallint DEFAULT 1 NOT NULL,
    timeout_sec integer DEFAULT 180 NOT NULL,
    last_summary text,
    last_result jsonb,
    next_run_at timestamp with time zone,
    last_run_at timestamp with time zone,
    run_count integer DEFAULT 0 NOT NULL,
    consecutive_failures smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    schedule_type character varying(20) DEFAULT 'cron'::character varying NOT NULL,
    run_at timestamp with time zone,
    weekdays smallint[],
    day_of_month smallint,
    execution_policy jsonb,
    plan_snapshot jsonb,
    revision bigint DEFAULT 0 NOT NULL,
    data_scope jsonb DEFAULT '{"kind": "task_prompt"}'::jsonb NOT NULL,
    schedule_enabled boolean DEFAULT true NOT NULL,
    run_token uuid,
    claimed_at timestamp with time zone,
    run_claim_revision bigint,
    run_manual boolean DEFAULT false NOT NULL,
    run_previous_status text,
    skill_revision_snapshot jsonb DEFAULT '{"skills": [], "version": 1}'::jsonb NOT NULL,
    config_revision uuid NOT NULL,
    run_config_revision uuid,
    retry_config_revision uuid,
    origin_conversation_id uuid,
    notification_policy jsonb DEFAULT '{"mode": "always"}'::jsonb NOT NULL,
    notification_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    interval_minutes integer,
    CONSTRAINT scheduled_tasks_day_of_month_check CHECK (((day_of_month IS NULL) OR ((day_of_month >= 1) AND (day_of_month <= 31)))),
    CONSTRAINT scheduled_tasks_schedule_type_check CHECK (((schedule_type)::text = ANY ((ARRAY['once'::character varying, 'daily'::character varying, 'weekly'::character varying, 'monthly'::character varying, 'cron'::character varying])::text[]))),
    CONSTRAINT scheduled_tasks_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'paused'::character varying, 'running'::character varying, 'error'::character varying])::text[])))
);

