--
-- Name: claim_due_tasks(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.claim_due_tasks(p_now timestamp with time zone, p_limit integer) RETURNS SETOF public.scheduled_tasks
    LANGUAGE sql
    AS $$
    UPDATE scheduled_tasks
    SET status = 'running',
        next_run_at = NULL  -- 清空，执行完再算下次
    WHERE id IN (
        SELECT id FROM scheduled_tasks
        WHERE status = 'active' AND schedule_enabled
          AND next_run_at IS NOT NULL
          AND next_run_at <= p_now
        ORDER BY next_run_at
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    )
    RETURNING *;
$$;


