--
-- Name: claim_ecom_image_plan(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.claim_ecom_image_plan(p_plan_id uuid, p_parent_task_id uuid, p_lease_token uuid, p_lease_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; t public.tasks%ROWTYPE;
BEGIN
    IF SESSION_USER <> 'everydayai' OR current_setting('app.access_kind', TRUE) NOT IN ('runtime','runtime_admin')
       OR p_lease_token IS NULL OR p_lease_seconds NOT BETWEEN 10 AND 600 THEN
        RAISE EXCEPTION 'ECOM_PLAN_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
    SELECT * INTO p FROM public.ecom_image_plans WHERE id=p_plan_id FOR UPDATE;
    SELECT * INTO t FROM public.tasks WHERE id=p_parent_task_id FOR UPDATE;
    IF p.id IS NULL OR p.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',TRUE),'')::uuid
       OR p.org_id IS DISTINCT FROM NULLIF(current_setting('app.org_id',TRUE),'')::uuid
       OR (p.source_kind='chat' AND (t.id IS NULL OR p.parent_task_id IS DISTINCT FROM p_parent_task_id
          OR t.user_id IS DISTINCT FROM p.user_id OR t.org_id IS DISTINCT FROM p.org_id
          OR t.conversation_id IS DISTINCT FROM p.conversation_id OR t.status<>'running'))
       OR (p.source_kind='detail_project' AND (p_parent_task_id IS NOT NULL OR NOT EXISTS(
          SELECT 1 FROM public.detail_projects d WHERE d.id=p.project_id AND d.user_id=p.user_id
          AND d.org_id IS NOT DISTINCT FROM p.org_id AND d.run_state->>'run_id'=p.generation_run_id::text
          AND d.status IN ('analyzing','plan_ready','generating')))) THEN
        RAISE EXCEPTION 'ECOM_PLAN_PARENT_DENIED' USING ERRCODE='42501';
    END IF;
    IF p.status IN ('ready','needs_input','insufficient','cancelled') THEN
        RETURN jsonb_build_object('claimed',false,'status',p.status,'row_version',p.row_version);
    END IF;
    IF p.lease_expires_at > NOW() AND p.lease_token IS DISTINCT FROM p_lease_token THEN
        RETURN jsonb_build_object('claimed',false,'status',p.status,'row_version',p.row_version);
    END IF;
    UPDATE public.ecom_image_plans SET status=CASE WHEN p.status='failed' THEN 'planning' ELSE p.status END,
        lease_token=p_lease_token,
        lease_expires_at=NOW()+make_interval(secs=>p_lease_seconds),updated_at=NOW(),row_version=row_version+1
        WHERE id=p_plan_id;
    RETURN jsonb_build_object('claimed',true,'status',CASE WHEN p.status='failed' THEN 'planning' ELSE p.status END,
        'current_stage',p.current_stage,
        'row_version',p.row_version+1,'stage_outputs',p.stage_outputs,'stage_attempts',p.stage_attempts);
END $$;


ALTER FUNCTION public.claim_ecom_image_plan(p_plan_id uuid, p_parent_task_id uuid, p_lease_token uuid, p_lease_seconds integer) OWNER TO everydayai_owner;

--
-- Name: claim_legacy_wecom_conversation(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.claim_legacy_wecom_conversation(p_user_id uuid, p_corp_id text, p_external_chat_id text, p_org_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation_id UUID;
BEGIN
    SELECT c.id INTO v_conversation_id
      FROM conversations c
     WHERE c.org_id = p_org_id
       AND c.user_id = p_user_id
       AND c.source = 'wecom'
       AND c.scope_type = 'user'
       AND NOT EXISTS (
           SELECT 1 FROM conversation_channel_bindings b
            WHERE b.conversation_id = c.id
       )
     ORDER BY c.updated_at DESC
     LIMIT 1
     FOR UPDATE SKIP LOCKED;
    IF v_conversation_id IS NULL THEN
        RETURN NULL;
    END IF;
    UPDATE conversations
       SET scope_id = BTRIM(p_external_chat_id)
     WHERE id = v_conversation_id;
    BEGIN
        INSERT INTO conversation_channel_bindings(
            org_id, conversation_id, channel, corp_id,
            external_chat_id, chat_type, owner_user_id
        ) VALUES (
            p_org_id, v_conversation_id, 'wecom', BTRIM(p_corp_id),
            BTRIM(p_external_chat_id), 'single', p_user_id
        );
        RETURN v_conversation_id;
    EXCEPTION WHEN unique_violation THEN
        RETURN NULL;
    END;
END;
$$;


ALTER FUNCTION public.claim_legacy_wecom_conversation(p_user_id uuid, p_corp_id text, p_external_chat_id text, p_org_id uuid) OWNER TO everydayai;

--
-- Name: claim_message_generation_request(uuid, uuid, uuid, character varying, character, character varying, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.claim_message_generation_request(p_org_id uuid, p_user_id uuid, p_conversation_id uuid, p_idempotency_key character varying, p_request_fingerprint character, p_client_task_id character varying, p_assistant_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_request message_generation_requests%ROWTYPE;
    v_outcome TEXT;
BEGIN
    IF p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION 'IDEMPOTENCY_KEY_INVALID' USING ERRCODE = '22023';
    END IF;
    IF p_request_fingerprint IS NULL OR p_request_fingerprint !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'IDEMPOTENCY_FINGERPRINT_INVALID' USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
        SELECT 1
          FROM conversations conversation
         WHERE conversation.id = p_conversation_id
           AND conversation.user_id = p_user_id
           AND conversation.org_id IS NOT DISTINCT FROM p_org_id
    ) THEN
        RAISE EXCEPTION 'IDEMPOTENCY_CONVERSATION_ACCESS_DENIED' USING ERRCODE = '42501';
    END IF;

    BEGIN
        INSERT INTO message_generation_requests(
            org_id,
            user_id,
            conversation_id,
            idempotency_key,
            request_fingerprint,
            client_task_id,
            assistant_message_id
        ) VALUES (
            p_org_id,
            p_user_id,
            p_conversation_id,
            p_idempotency_key,
            p_request_fingerprint,
            p_client_task_id,
            p_assistant_message_id
        ) RETURNING * INTO v_request;

        v_outcome := 'claimed';
    EXCEPTION WHEN unique_violation THEN
        SELECT *
          INTO v_request
          FROM message_generation_requests request
         WHERE request.user_id = p_user_id
           AND request.org_id IS NOT DISTINCT FROM p_org_id
           AND request.idempotency_key = p_idempotency_key;

        IF v_request.id IS NULL THEN
            RAISE;
        END IF;
        IF v_request.request_fingerprint <> p_request_fingerprint THEN
            v_outcome := 'fingerprint_mismatch';
        ELSE
            v_outcome := v_request.status;
        END IF;
    END;

    RETURN jsonb_build_object(
        'outcome', v_outcome,
        'request_id', v_request.id,
        'stored_fingerprint', v_request.request_fingerprint,
        'request_status', v_request.status,
        'stored_client_task_id', v_request.client_task_id,
        'stored_user_message_id', v_request.user_message_id,
        'stored_assistant_message_id', v_request.assistant_message_id,
        'stored_response_status', v_request.response_status,
        'stored_response_body', v_request.response_body,
        'stored_error_code', v_request.error_code
    );
END;
$_$;


