--
-- Name: claim_next_serial_generation_turn(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.claim_next_serial_generation_turn(p_conversation_id uuid, p_lease_seconds integer DEFAULT 90, p_max_attempts integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_owner tasks%ROWTYPE;
    v_task tasks%ROWTYPE;
    v_token UUID;
    v_sources JSONB;
BEGIN
    IF p_lease_seconds NOT BETWEEN 15 AND 300 OR p_max_attempts < 1 THEN
        RAISE EXCEPTION 'ACTOR_CLAIM_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_conversation
      FROM conversations
     WHERE id = p_conversation_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ACTOR_CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    IF v_conversation.active_serial_task_id IS NOT NULL THEN
        SELECT * INTO v_owner
          FROM tasks
         WHERE id = v_conversation.active_serial_task_id
         FOR UPDATE;
        IF v_owner.id IS NOT NULL
           AND v_owner.status = 'running'
           AND v_owner.lease_expires_at > NOW() THEN
            RETURN jsonb_build_object('outcome', 'busy');
        END IF;
        IF v_owner.id IS NOT NULL AND v_owner.status = 'running' THEN
            IF v_owner.execution_attempt >= p_max_attempts THEN
                UPDATE tasks
                   SET status = 'failed',
                       terminal_reason = 'lease_attempts_exhausted',
                       completed_at = NOW(),
                       execution_token = NULL,
                       lease_expires_at = NULL
                 WHERE id = v_owner.id;
            ELSE
                UPDATE tasks
                   SET status = 'pending',
                       terminal_reason = 'lease_expired',
                       execution_token = NULL,
                       lease_expires_at = NULL
                 WHERE id = v_owner.id;
            END IF;
        END IF;
        UPDATE conversations
           SET active_serial_task_id = NULL,
               actor_updated_at = NOW()
         WHERE id = p_conversation_id;
    END IF;

    SELECT * INTO v_task
      FROM tasks
     WHERE conversation_id = p_conversation_id
       AND type = 'chat'
       AND delivery_context @> '{"actor": true}'::JSONB
       AND execution_mode = 'serial'
       AND status = 'pending'
       AND input_message_id IS NOT NULL
       AND turn_id IS NOT NULL
     ORDER BY queue_sequence, id
     FOR UPDATE SKIP LOCKED
     LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'empty');
    END IF;

    v_sources := public.freeze_chat_image_sources(v_task, v_conversation);
    v_token := uuid_generate_v4();
    UPDATE tasks
       SET status = 'running',
           execution_token = v_token,
           lease_expires_at = NOW() + make_interval(secs => p_lease_seconds),
           execution_attempt = execution_attempt + 1,
           started_at = COALESCE(started_at, NOW()),
           request_params = jsonb_set(COALESCE(request_params,'{}'::JSONB), '{_image_sources_v1}', v_sources),
           base_context_revision = (v_sources->>'base_revision')::BIGINT,
           context_through_message_id = (v_sources->>'through_message_id')::UUID,
           terminal_reason = NULL
     WHERE id = v_task.id
     RETURNING * INTO v_task;

    UPDATE conversations
       SET active_serial_task_id = v_task.id,
           actor_updated_at = NOW()
     WHERE id = p_conversation_id;

    RETURN jsonb_build_object(
        'outcome', 'claimed',
        'task_id', v_task.id,
        'execution_token', v_token,
        'turn_id', v_task.turn_id,
        'input_message_id', v_task.input_message_id,
        'base_context_revision', v_task.base_context_revision,
        'context_through_message_id', v_task.context_through_message_id,
        'execution_attempt', v_task.execution_attempt
    );
END;
$$;


ALTER FUNCTION public.claim_next_serial_generation_turn(p_conversation_id uuid, p_lease_seconds integer, p_max_attempts integer) OWNER TO everydayai;

--
-- Name: FUNCTION claim_next_serial_generation_turn(p_conversation_id uuid, p_lease_seconds integer, p_max_attempts integer); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.claim_next_serial_generation_turn(p_conversation_id uuid, p_lease_seconds integer, p_max_attempts integer) IS '按 queue_sequence 认领 conversation 最早 serial Chat Turn，并绑定最新 context revision';


--
-- Name: claim_scheduled_task_delivery(integer, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.claim_scheduled_task_delivery(p_lease_seconds integer DEFAULT 120, p_max_attempts integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_delivery scheduled_task_deliveries%ROWTYPE;
    v_token UUID;
BEGIN
    IF p_lease_seconds NOT BETWEEN 15 AND 300 OR p_max_attempts < 1 THEN
        RAISE EXCEPTION 'SCHEDULED_TASK_DELIVERY_CLAIM_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    UPDATE scheduled_task_deliveries
       SET status = 'dead', lease_token = NULL, lease_expires_at = NULL,
           last_error = COALESCE(last_error, 'delivery lease expired after max attempts'),
           updated_at = NOW()
     WHERE status = 'delivering'
       AND lease_expires_at <= NOW()
       AND attempt_count >= p_max_attempts;

    SELECT * INTO v_delivery
      FROM scheduled_task_deliveries
     WHERE (
            status = 'pending'
            OR (status = 'delivering' AND lease_expires_at <= NOW())
       )
       AND next_attempt_at <= NOW()
       AND attempt_count < p_max_attempts
     ORDER BY next_attempt_at, created_at, id
     FOR UPDATE SKIP LOCKED
     LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'empty');
    END IF;

    v_token := gen_random_uuid();
    UPDATE scheduled_task_deliveries
       SET status = 'delivering',
           attempt_count = attempt_count + 1,
           lease_token = v_token,
           lease_expires_at = NOW() + make_interval(secs => p_lease_seconds),
           updated_at = NOW()
     WHERE id = v_delivery.id
     RETURNING * INTO v_delivery;

    RETURN jsonb_build_object(
        'outcome', 'claimed',
        'delivery_id', v_delivery.id,
        'run_id', v_delivery.run_id,
        'delivery_kind', v_delivery.delivery_kind,
        'lease_token', v_token,
        'org_id', v_delivery.org_id,
        'target_context', v_delivery.target_context,
        'payload', v_delivery.payload
    );
END;
$$;


ALTER FUNCTION public.claim_scheduled_task_delivery(p_lease_seconds integer, p_max_attempts integer) OWNER TO everydayai;

--
-- Name: claim_scheduled_task_now(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.claim_scheduled_task_now(p_task_id uuid, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task scheduled_tasks%ROWTYPE;
    v_previous_status TEXT;
BEGIN
    SELECT * INTO v_task FROM scheduled_tasks
     WHERE id = p_task_id AND org_id = p_org_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'not_found');
    END IF;
    IF v_task.status = 'running' THEN
        RETURN jsonb_build_object('outcome', 'already_running');
    END IF;

    v_previous_status := v_task.status;
    UPDATE scheduled_tasks
       SET status = 'running', run_manual = TRUE, next_run_at = NULL, updated_at = NOW()
     WHERE id = v_task.id
     RETURNING * INTO v_task;
    RETURN jsonb_build_object(
        'outcome', 'claimed',
        'previous_status', v_previous_status,
        'task', to_jsonb(v_task)
    );
END;
$$;


ALTER FUNCTION public.claim_scheduled_task_now(p_task_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: cleanup_expired_credit_locks(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.cleanup_expired_credit_locks() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER := 0;
    v_tx RECORD;
    v_result JSONB;
BEGIN
    FOR v_tx IN
        SELECT id FROM credit_transactions
        WHERE status = 'pending' AND expires_at < NOW()
    LOOP
        v_result := atomic_refund_credits(v_tx.id, 'expired');
        IF (v_result->>'refunded')::boolean THEN
            v_count := v_count + 1;
        END IF;
    END LOOP;
    RETURN v_count;
END;
$$;


