-- Name: cleanup_expired_message_generation_requests(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.cleanup_expired_message_generation_requests() RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_deleted BIGINT;
BEGIN
    DELETE FROM message_generation_requests
     WHERE expires_at < NOW();
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
END;
$$;


