--
-- Name: cleanup_old_error_logs(integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.cleanup_old_error_logs(retention_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM error_logs
    WHERE last_seen_at < now() - (retention_days || ' days')::INTERVAL;
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


