--
-- Name: close_generation_turn(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.close_generation_turn(p_conversation_id uuid, p_task_id uuid, p_output_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_task tasks%ROWTYPE;
    v_output messages%ROWTYPE;
    v_closed_revision BIGINT;
BEGIN
    SELECT * INTO v_conversation
      FROM conversations
     WHERE id = p_conversation_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'TURN_CONVERSATION_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND
       OR v_task.conversation_id IS DISTINCT FROM p_conversation_id
       OR v_task.org_id IS DISTINCT FROM v_conversation.org_id
       OR v_task.input_message_id IS NULL
       OR v_task.turn_id IS NULL THEN
        RAISE EXCEPTION 'TURN_TASK_NOT_BOUND' USING ERRCODE = '55000';
    END IF;

    SELECT * INTO v_output FROM messages WHERE id = p_output_message_id FOR UPDATE;
    IF NOT FOUND
       OR v_output.conversation_id IS DISTINCT FROM p_conversation_id
       OR v_output.org_id IS DISTINCT FROM v_conversation.org_id
       OR v_output.role::TEXT <> 'assistant'
       OR (v_task.assistant_message_id IS NOT NULL
           AND v_task.assistant_message_id IS DISTINCT FROM p_output_message_id)
       OR v_output.reply_to_message_id IS DISTINCT FROM v_task.input_message_id
       OR v_output.turn_id IS DISTINCT FROM v_task.turn_id THEN
        RAISE EXCEPTION 'TURN_OUTPUT_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;

    IF v_output.context_revision IS NOT NULL THEN
        UPDATE tasks
           SET status = 'completed',
               completed_at = COALESCE(completed_at, NOW())
         WHERE id = p_task_id;
        RETURN jsonb_build_object(
            'turn_id', v_task.turn_id,
            'closed_revision', v_output.context_revision,
            'output_message_id', p_output_message_id,
            'already_closed', TRUE
        );
    END IF;

    v_closed_revision := v_conversation.context_revision + 1;
    UPDATE messages
       SET turn_id = v_task.turn_id,
           context_revision = v_closed_revision,
           message_kind = 'conversation'
     WHERE id = v_task.input_message_id
       AND conversation_id = p_conversation_id
       AND context_revision IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'TURN_INPUT_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    UPDATE messages
       SET context_revision = v_closed_revision,
           message_kind = 'conversation'
     WHERE id = p_output_message_id;

    UPDATE tasks
       SET assistant_message_id = p_output_message_id,
           status = 'completed',
           completed_at = COALESCE(completed_at, NOW())
     WHERE id = p_task_id
       AND (assistant_message_id IS NULL OR assistant_message_id = p_output_message_id);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'TURN_OUTPUT_ALREADY_BOUND' USING ERRCODE = '23505';
    END IF;

    UPDATE conversations
       SET context_revision = v_closed_revision,
           last_closed_message_id = p_output_message_id
     WHERE id = p_conversation_id;

    RETURN jsonb_build_object(
        'turn_id', v_task.turn_id,
        'closed_revision', v_closed_revision,
        'output_message_id', p_output_message_id,
        'already_closed', FALSE
    );
END;
$$;


ALTER FUNCTION public.close_generation_turn(p_conversation_id uuid, p_task_id uuid, p_output_message_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION close_generation_turn(p_conversation_id uuid, p_task_id uuid, p_output_message_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.close_generation_turn(p_conversation_id uuid, p_task_id uuid, p_output_message_id uuid) IS '原子关闭 Turn 并推进会话 revision；重复关闭返回首次 revision';


--
-- Name: close_generation_turn(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.close_generation_turn(p_conversation_id uuid, p_task_id uuid, p_output_message_id uuid, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org_id UUID;
BEGIN
    SELECT org_id INTO v_org_id
      FROM conversations
     WHERE id = p_conversation_id;
    IF NOT FOUND OR v_org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'TURN_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    RETURN close_generation_turn(
        p_conversation_id,
        p_task_id,
        p_output_message_id
    );
END;
$$;


ALTER FUNCTION public.close_generation_turn(p_conversation_id uuid, p_task_id uuid, p_output_message_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION close_generation_turn(p_conversation_id uuid, p_task_id uuid, p_output_message_id uuid, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.close_generation_turn(p_conversation_id uuid, p_task_id uuid, p_output_message_id uuid, p_org_id uuid) IS '租户范围校验后调用 Turn 关闭原子核心';


--
-- Name: commit_generation_turn(uuid, uuid, uuid, jsonb, jsonb, integer, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.commit_generation_turn(p_task_id uuid, p_execution_token uuid, p_output_message_id uuid, p_result_content jsonb, p_usage jsonb DEFAULT '{}'::jsonb, p_credits_cost integer DEFAULT 0, p_tool_digest jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_task tasks%ROWTYPE;
    v_output messages%ROWTYPE;
    v_credit_result JSONB;
    v_close_result JSONB;
    v_conversation_id UUID;
BEGIN
    IF p_execution_token IS NULL
       OR p_output_message_id IS NULL
       OR p_result_content IS NULL
       OR jsonb_typeof(p_result_content) <> 'array'
       OR p_usage IS NULL
       OR jsonb_typeof(p_usage) <> 'object'
       OR p_credits_cost < 0
       OR (p_tool_digest IS NOT NULL AND jsonb_typeof(p_tool_digest) <> 'object') THEN
        RAISE EXCEPTION 'ACTOR_COMMIT_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT conversation_id INTO v_conversation_id FROM tasks WHERE id = p_task_id;
    IF v_conversation_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_conversation FROM conversations
     WHERE id = v_conversation_id FOR UPDATE;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;

    IF v_task.id IS NULL OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB)
       OR v_task.conversation_id IS DISTINCT FROM v_conversation.id
       OR v_task.org_id IS DISTINCT FROM v_conversation.org_id
       OR v_task.assistant_message_id IS DISTINCT FROM p_output_message_id
       OR v_task.input_message_id IS NULL
       OR v_task.turn_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_COMMIT_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.status = 'completed' THEN
        IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
            RETURN jsonb_build_object('outcome', 'ownership_lost');
        END IF;
        SELECT * INTO v_output FROM messages WHERE id = p_output_message_id;
        RETURN jsonb_build_object(
            'outcome', 'already_committed', 'task_id', v_task.id,
            'closed_revision', v_output.context_revision, 'credits_cost', v_task.credits_used
        );
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    IF v_task.lease_expires_at IS NULL OR v_task.lease_expires_at <= NOW() THEN
        RETURN jsonb_build_object('outcome', 'lease_expired');
    END IF;

    SELECT * INTO v_output FROM messages WHERE id = p_output_message_id FOR UPDATE;
    IF NOT FOUND
       OR v_output.conversation_id IS DISTINCT FROM v_conversation.id
       OR v_output.org_id IS DISTINCT FROM v_task.org_id
       OR v_output.role::TEXT <> 'assistant'
       OR v_output.reply_to_message_id IS DISTINCT FROM v_task.input_message_id
       OR v_output.turn_id IS DISTINCT FROM v_task.turn_id THEN
        RAISE EXCEPTION 'ACTOR_COMMIT_OUTPUT_MISMATCH' USING ERRCODE = '42501';
    END IF;

    IF p_credits_cost > 0 THEN
        SELECT deduct_credits_atomic(
            v_task.user_id, p_credits_cost,
            'Chat: ' || COALESCE(v_task.model_id, 'unknown'), 'conversation_cost', v_task.org_id
        ) INTO v_credit_result;
        IF COALESCE((v_credit_result->>'success')::BOOLEAN, FALSE) IS NOT TRUE THEN
            RAISE EXCEPTION 'ACTOR_COMMIT_INSUFFICIENT_CREDITS' USING ERRCODE = 'P0001';
        END IF;
    END IF;

    UPDATE messages
       SET content = p_result_content,
           status = 'completed',
           credits_cost = p_credits_cost,
           is_error = FALSE,
           generation_params = COALESCE(generation_params, '{}'::JSONB)
               || jsonb_build_object(
                    'type', 'chat', 'model', COALESCE(v_task.model_id, 'unknown'),
                    'usage', p_usage, 'tool_digest', p_tool_digest
               )
     WHERE id = p_output_message_id;

    SELECT close_generation_turn(v_conversation.id, v_task.id, p_output_message_id)
      INTO v_close_result;

    UPDATE tasks
       SET credits_used = p_credits_cost,
           total_credits = p_credits_cost,
           result = jsonb_build_object('usage', p_usage, 'tool_digest', p_tool_digest),
           lease_expires_at = NULL,
           terminal_reason = NULL
     WHERE id = p_task_id;
    UPDATE conversations
       SET active_serial_task_id = NULL,
           actor_updated_at = NOW()
     WHERE id = v_conversation.id
       AND active_serial_task_id = p_task_id;

    RETURN jsonb_build_object(
        'outcome', 'committed', 'task_id', p_task_id,
        'closed_revision', v_close_result->'closed_revision',
        'credits_cost', p_credits_cost
    );
END;
$$;


ALTER FUNCTION public.commit_generation_turn(p_task_id uuid, p_execution_token uuid, p_output_message_id uuid, p_result_content jsonb, p_usage jsonb, p_credits_cost integer, p_tool_digest jsonb) OWNER TO everydayai;

--
-- Name: FUNCTION commit_generation_turn(p_task_id uuid, p_execution_token uuid, p_output_message_id uuid, p_result_content jsonb, p_usage jsonb, p_credits_cost integer, p_tool_digest jsonb); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.commit_generation_turn(p_task_id uuid, p_execution_token uuid, p_output_message_id uuid, p_result_content jsonb, p_usage jsonb, p_credits_cost integer, p_tool_digest jsonb) IS '当前 fencing token 在有效租约内原子提交 Chat 消息、积分、Turn revision 和 task 终态';


--
-- Name: commit_scheduled_task_changeset(uuid, uuid, uuid, uuid, text, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.commit_scheduled_task_changeset(p_change_set_id uuid, p_org_id uuid, p_user_id uuid, p_task_id uuid, p_operation text, p_base_revision bigint, p_definition jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task public.scheduled_tasks%ROWTYPE;
    v_receipt public.scheduled_task_change_receipts%ROWTYPE;
    v_new_revision BIGINT;
    v_result JSONB;
    v_next_run_at TIMESTAMPTZ;
    v_weekdays SMALLINT[];
BEGIN
    IF p_operation NOT IN ('create','update','pause','resume','delete')
       OR p_definition IS NULL OR jsonb_typeof(p_definition) <> 'object'
       OR COALESCE(p_idempotency_key, '') = '' THEN
        RAISE EXCEPTION 'SCHEDULED_TASK_CHANGE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_receipt
      FROM public.scheduled_task_change_receipts
     WHERE org_id = p_org_id AND idempotency_key = p_idempotency_key
     FOR UPDATE;
    IF FOUND THEN
        RETURN jsonb_build_object(
            'outcome', 'duplicate', 'task_id', v_receipt.task_id,
            'new_revision', v_receipt.new_revision, 'result', v_receipt.result
        );
    END IF;

    IF p_operation = 'create' THEN
        IF p_base_revision <> 0 THEN
            RETURN jsonb_build_object('outcome', 'conflict', 'reason', 'create_base_revision_must_be_zero');
        END IF;
        INSERT INTO public.scheduled_tasks(
            id, org_id, user_id, name, prompt, cron_expr, schedule_type,
            weekdays, day_of_month, run_at, timezone, push_target, template_file,
            status, max_credits, retry_count, timeout_sec, next_run_at,
            run_count, consecutive_failures, execution_policy, plan_snapshot, data_scope, revision, skill_revision_snapshot, origin_conversation_id, notification_policy, interval_minutes
        ) VALUES (
            p_task_id, p_org_id, p_user_id, p_definition->>'name', p_definition->>'prompt',
            NULLIF(p_definition->>'cron_expr',''), p_definition->>'schedule_type',
            CASE WHEN jsonb_typeof(p_definition->'weekdays') = 'array'
                 THEN ARRAY(SELECT jsonb_array_elements_text(p_definition->'weekdays')::smallint)
                 ELSE NULL END,
            NULLIF(p_definition->>'day_of_month','')::smallint,
            NULLIF(p_definition->>'run_at','')::timestamptz,
            COALESCE(p_definition->>'timezone', 'Asia/Shanghai'),
            p_definition->'push_target', p_definition->'template_file', 'active',
            COALESCE((p_definition->>'max_credits')::integer, 10),
            COALESCE((p_definition->>'retry_count')::smallint, 1),
            COALESCE((p_definition->>'timeout_sec')::integer, 180),
            NULLIF(p_definition->>'next_run_at','')::timestamptz,
            0, 0, p_definition->'execution_policy', p_definition->'plan_snapshot',
            COALESCE(p_definition->'data_scope', '{"kind":"task_prompt"}'::JSONB), 1,
            COALESCE(p_definition->'skill_revision_snapshot','{"version":1,"skills":[]}'::jsonb),
            NULLIF(p_definition->>'origin_conversation_id','')::uuid,
            COALESCE(p_definition->'notification_policy','{"mode":"always"}'::jsonb),
            NULLIF(p_definition->>'interval_minutes','')::integer
        ) RETURNING * INTO v_task;
        v_new_revision := v_task.revision;
        v_result := jsonb_build_object('outcome','created','task_id',v_task.id,'new_revision',v_new_revision);
    ELSE
        SELECT * INTO v_task
          FROM public.scheduled_tasks
         WHERE id = p_task_id AND org_id = p_org_id
         FOR UPDATE;
        IF NOT FOUND THEN
            RETURN jsonb_build_object('outcome', 'conflict', 'reason', 'task_not_found');
        END IF;
        IF v_task.revision <> p_base_revision THEN
            RETURN jsonb_build_object(
                'outcome', 'conflict', 'reason', 'base_revision_mismatch',
                'current_revision', v_task.revision, 'base_revision', p_base_revision
            );
        END IF;
        IF v_task.status = 'running' AND p_operation NOT IN ('pause','resume') THEN
            RETURN jsonb_build_object('outcome', 'conflict', 'reason', 'task_running');
        END IF;

        IF p_operation = 'delete' THEN
            v_new_revision := v_task.revision + 1;
            DELETE FROM public.scheduled_tasks WHERE id = v_task.id;
            v_result := jsonb_build_object('outcome','deleted','task_id',v_task.id,'new_revision',v_new_revision);
        ELSE
            IF p_operation = 'pause' THEN
                UPDATE public.scheduled_tasks
                   SET schedule_enabled = FALSE, run_previous_status = 'paused',
                       status = CASE WHEN status='running' THEN 'running' ELSE 'paused' END,
                       next_run_at = NULL, revision = revision + 1,
                       updated_at = NOW()
                 WHERE id = v_task.id
                 RETURNING * INTO v_task;
                v_result := jsonb_build_object('outcome','paused','task_id',v_task.id,'new_revision',v_task.revision);
            ELSIF p_operation = 'resume' THEN
                v_next_run_at := NULLIF(p_definition->>'next_run_at','')::timestamptz;
                IF v_next_run_at IS NULL THEN
                    RAISE EXCEPTION 'SCHEDULED_TASK_RESUME_TIME_REQUIRED' USING ERRCODE = '22023';
                END IF;
                UPDATE public.scheduled_tasks
                   SET schedule_enabled = TRUE,
                       status = CASE WHEN status='running' THEN 'running' ELSE 'active' END,
                       next_run_at = CASE WHEN status='running' THEN NULL ELSE v_next_run_at END,
                       consecutive_failures = 0, revision = revision + 1,
                       updated_at = NOW()
                 WHERE id = v_task.id
                 RETURNING * INTO v_task;
                v_result := jsonb_build_object('outcome','resumed','task_id',v_task.id,'new_revision',v_task.revision);
            ELSE
                UPDATE public.scheduled_tasks
                   SET origin_conversation_id = NULLIF(p_definition->>'origin_conversation_id','')::uuid,
                       notification_policy = COALESCE(p_definition->'notification_policy','{"mode":"always"}'::jsonb),
                       interval_minutes = NULLIF(p_definition->>'interval_minutes','')::integer,
                       name = p_definition->>'name',
                       prompt = p_definition->>'prompt',
                       cron_expr = NULLIF(p_definition->>'cron_expr',''),
                       schedule_type = p_definition->>'schedule_type',
                       weekdays = CASE WHEN jsonb_typeof(p_definition->'weekdays') = 'array'
                                      THEN ARRAY(SELECT jsonb_array_elements_text(p_definition->'weekdays')::smallint)
                                      ELSE NULL END,
                       day_of_month = NULLIF(p_definition->>'day_of_month','')::smallint,
                       run_at = NULLIF(p_definition->>'run_at','')::timestamptz,
                       timezone = COALESCE(p_definition->>'timezone','Asia/Shanghai'),
                       push_target = p_definition->'push_target',
                       template_file = p_definition->'template_file',
                       max_credits = COALESCE((p_definition->>'max_credits')::integer, 10),
                       retry_count = COALESCE((p_definition->>'retry_count')::smallint, 1),
                       timeout_sec = COALESCE((p_definition->>'timeout_sec')::integer, 180),
                       next_run_at = NULLIF(p_definition->>'next_run_at','')::timestamptz,
                       skill_revision_snapshot = COALESCE(p_definition->'skill_revision_snapshot','{"version":1,"skills":[]}'::jsonb),
                       execution_policy = p_definition->'execution_policy',
                       plan_snapshot = p_definition->'plan_snapshot',
                       data_scope = COALESCE(p_definition->'data_scope', '{"kind":"task_prompt"}'::JSONB),
                       consecutive_failures = 0, revision = revision + 1,
                       updated_at = NOW()
                 WHERE id = v_task.id
                 RETURNING * INTO v_task;
                v_result := jsonb_build_object('outcome','updated','task_id',v_task.id,'new_revision',v_task.revision);
            END IF;
            v_new_revision := v_task.revision;
        END IF;
    END IF;

    INSERT INTO public.scheduled_task_change_receipts(
        org_id, change_set_id, idempotency_key, task_id, operation,
        base_revision, new_revision, result
    ) VALUES (
        p_org_id, p_change_set_id, p_idempotency_key, p_task_id, p_operation,
        p_base_revision, v_new_revision, v_result
    );
    RETURN v_result || jsonb_build_object('task', CASE WHEN p_operation = 'delete' THEN NULL ELSE to_jsonb(v_task) END);
END;
$$;


ALTER FUNCTION public.commit_scheduled_task_changeset(p_change_set_id uuid, p_org_id uuid, p_user_id uuid, p_task_id uuid, p_operation text, p_base_revision bigint, p_definition jsonb, p_idempotency_key text) OWNER TO everydayai;

--
-- Name: complete_conversation_delivery(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.complete_conversation_delivery(p_delivery_id uuid, p_lease_token uuid, p_delivered_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_delivery conversation_deliveries%ROWTYPE;
BEGIN
    IF p_delivered_items IS NULL
       OR jsonb_typeof(p_delivered_items) <> 'array' THEN
        RAISE EXCEPTION 'DELIVERY_COMPLETE_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_delivery
      FROM conversation_deliveries
     WHERE id = p_delivery_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_delivery.status = 'delivered' THEN
        RETURN jsonb_build_object('outcome', 'already_delivered');
    END IF;
    IF v_delivery.status <> 'delivering'
       OR v_delivery.lease_token IS DISTINCT FROM p_lease_token
       OR v_delivery.lease_expires_at <= NOW() THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    UPDATE conversation_deliveries
       SET status = 'delivered',
           delivered_items = p_delivered_items,
           delivered_at = NOW(),
           lease_token = NULL,
           lease_expires_at = NULL,
           last_error = NULL,
           updated_at = NOW()
     WHERE id = p_delivery_id;
    RETURN jsonb_build_object('outcome', 'delivered');
END;
$$;


ALTER FUNCTION public.complete_conversation_delivery(p_delivery_id uuid, p_lease_token uuid, p_delivered_items jsonb) OWNER TO everydayai;

--
-- Name: complete_ecom_plan_local_draft(uuid, uuid, integer, jsonb, text, jsonb, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.complete_ecom_plan_local_draft(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_expected_draft jsonb, p_validator_version text, p_output jsonb, p_status text, p_items jsonb DEFAULT NULL::jsonb, p_reviews jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; r public.ecom_image_plans%ROWTYPE;
 fingerprint TEXT; prior JSONB; saved JSONB; credits INTEGER:=0;
BEGIN
 p=public.lock_ecom_format_plan(p_plan_id);
 SELECT * INTO r FROM public.ecom_image_plans WHERE id=COALESCE(p.root_plan_id,p.id);
 IF p_stage IS NULL OR p_stage NOT BETWEEN 1 AND 3 OR p_output IS NULL
  OR p_validator_version IS DISTINCT FROM 'ecom-format.v1'
  OR jsonb_typeof(p_expected_draft) IS DISTINCT FROM 'object'
  OR p_status IS NULL OR NOT ((p_stage<3 AND p_status IN ('planning','needs_input','insufficient'))
    OR (p_stage=3 AND p_status IN ('ready','needs_input')))
  OR (p_status='ready' AND (jsonb_typeof(p_items) IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_items) IS DISTINCT FROM p.image_count OR p_items IS DISTINCT FROM p_output->'images'))
  OR (p_stage<3 AND (p_items IS NOT NULL OR p_reviews IS NOT NULL)) THEN
  RAISE EXCEPTION 'ECOM_PLAN_DRAFT_INVALID' USING ERRCODE='22023'; END IF;
 fingerprint=md5(jsonb_build_object('draft',p_expected_draft,'validator',p_validator_version,
  'output',p_output,'status',p_status,'items',p_items,'reviews',p_reviews)::text);
 prior=p.stage_drafts->p_stage::text->'local_completion';
 IF prior IS NOT NULL THEN
  IF prior->>'fingerprint' IS DISTINCT FROM fingerprint OR p.stage_outputs->p_stage::text IS DISTINCT FROM p_output THEN
   RAISE EXCEPTION 'ECOM_PLAN_DRAFT_CONFLICT' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('outcome','replay');
 END IF;
 IF p.status IS DISTINCT FROM 'planning' OR p.current_stage IS DISTINCT FROM p_stage
  OR p.lease_token IS DISTINCT FROM p_lease_token OR p_lease_token IS NULL
  OR p.lease_expires_at IS NULL OR p.lease_expires_at<=NOW() THEN
  RAISE EXCEPTION 'ECOM_PLAN_LEASE_LOST' USING ERRCODE='55000'; END IF;
 IF p.stage_drafts->p_stage::text IS DISTINCT FROM p_expected_draft THEN
  RAISE EXCEPTION 'ECOM_PLAN_DRAFT_CONFLICT' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(COALESCE(r.recovery_state->'attempts','{}')) a
  WHERE a.value->>'plan_id'=p.id::text AND a.value->>'outcome' IN ('started','uncertain')) THEN
  RAISE EXCEPTION 'ECOM_PLAN_EXECUTION_UNCERTAIN' USING ERRCODE='55000'; END IF;
 IF p_status='ready' AND p.model_settings->'delivery_policy'='{"version":1,"retry_cost":"platform"}'::jsonb THEN
  SELECT COALESCE(SUM((value->'usage'->>'user_credits')::integer),0) INTO credits
   FROM jsonb_array_elements(p.stage_attempts) WHERE value->>'status'='completed'
   AND (value->>'stage')::integer<p_stage;
 END IF;
 saved=public.save_ecom_image_plan_stage(p.id,p_lease_token,p_stage,p_output,NULL,p_status,p_items,p_reviews,credits);
 -- Local audit is separate from provider receipts and bears zero new model usage.
 UPDATE public.ecom_image_plans SET stage_drafts=jsonb_set(stage_drafts,ARRAY[p_stage::text,'local_completion'],
  jsonb_build_object('fingerprint',fingerprint,'validator_version',p_validator_version,
   'draft_fingerprint',md5(p_expected_draft::text),'output_fingerprint',md5(p_output::text),
   'delivered_stage_credits',credits,'provider_calls',0,'completed_at',NOW())) WHERE id=p.id;
 RETURN saved||jsonb_build_object('outcome','saved');
END $$;


ALTER FUNCTION public.complete_ecom_plan_local_draft(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_expected_draft jsonb, p_validator_version text, p_output jsonb, p_status text, p_items jsonb, p_reviews jsonb) OWNER TO everydayai_owner;

--
-- Name: complete_scheduled_task_delivery(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.complete_scheduled_task_delivery(p_delivery_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_delivery scheduled_task_deliveries%ROWTYPE;
    v_push_status TEXT;
BEGIN
    SELECT * INTO v_delivery FROM scheduled_task_deliveries
     WHERE id = p_delivery_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'SCHEDULED_TASK_DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_delivery.status = 'delivered' THEN
        RETURN jsonb_build_object('outcome', 'already_delivered');
    END IF;
    IF v_delivery.status <> 'delivering'
       OR v_delivery.lease_token IS DISTINCT FROM p_lease_token
       OR v_delivery.lease_expires_at <= NOW() THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    UPDATE scheduled_task_deliveries
       SET status = 'delivered', delivered_at = NOW(),
           lease_token = NULL, lease_expires_at = NULL, last_error = NULL,
           updated_at = NOW()
     WHERE id = p_delivery_id;
    v_push_status := refresh_scheduled_task_run_push_status(v_delivery.run_id);
    RETURN jsonb_build_object('outcome', 'delivered', 'push_status', v_push_status);
END;
$$;


ALTER FUNCTION public.complete_scheduled_task_delivery(p_delivery_id uuid, p_lease_token uuid) OWNER TO everydayai;

--
-- Name: complete_scheduled_task_success(uuid, uuid, text, timestamp with time zone, text, jsonb, integer, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.complete_scheduled_task_success(p_task_id uuid, p_run_id uuid, p_next_status text, p_next_run_at timestamp with time zone, p_last_summary text, p_last_result jsonb, p_credits_used integer, p_tokens_used integer, p_duration_ms integer, p_deliveries jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task scheduled_tasks%ROWTYPE;
    v_run scheduled_task_runs%ROWTYPE;
    v_delivery JSONB;
    v_push_status TEXT;
BEGIN
    IF p_next_status NOT IN ('active', 'paused', 'error')
       OR p_last_result IS NULL OR jsonb_typeof(p_last_result) <> 'object'
       OR p_deliveries IS NULL OR jsonb_typeof(p_deliveries) <> 'array'
       OR p_credits_used < 0 OR p_tokens_used < 0 OR p_duration_ms < 0 THEN
        RAISE EXCEPTION 'SCHEDULED_TASK_SUCCESS_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    -- All lifecycle operations lock task before run, including recovery.
    SELECT * INTO v_task FROM scheduled_tasks WHERE id=p_task_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome','task_missing');
    END IF;
    SELECT * INTO v_run FROM scheduled_task_runs
      WHERE id=p_run_id AND task_id=p_task_id AND org_id=v_task.org_id FOR UPDATE;
    IF NOT FOUND OR v_run.status <> 'running'
       OR (v_task.run_token IS NOT NULL AND v_task.run_token <> p_run_id) THEN
        RETURN jsonb_build_object('outcome','run_not_running');
    END IF;
    IF NOT v_task.schedule_enabled THEN
        p_next_status := CASE WHEN v_task.run_previous_status='error' THEN 'error' ELSE 'paused' END;
        p_next_run_at := NULL;
    ELSIF v_task.schedule_type='once' THEN
        p_next_status := 'paused';
        p_next_run_at := NULL;
    ELSE
        p_next_status := 'active';
    END IF;

    FOR v_delivery IN SELECT value FROM jsonb_array_elements(p_deliveries) LOOP
        IF jsonb_typeof(v_delivery) <> 'object'
           OR COALESCE(v_delivery->>'delivery_key', '') = ''
           OR v_delivery->>'delivery_kind' <> 'result'
           OR jsonb_typeof(v_delivery->'target_context') <> 'object'
           OR jsonb_typeof(v_delivery->'payload') <> 'object'
           OR v_delivery->'target_context'->>'type' NOT IN ('wecom_user', 'wecom_group', 'web')
           OR (v_delivery->'target_context'->>'type' <> 'web' AND COALESCE(v_delivery->'target_context'->>'chatid', '') = '')
           OR (v_delivery->'target_context'->>'type' = 'web' AND
               (COALESCE(v_delivery->'target_context'->>'user_id','') = '' OR
                COALESCE(v_delivery->'target_context'->>'conversation_id','') = '')) THEN
            RAISE EXCEPTION 'SCHEDULED_TASK_DELIVERY_INVALID'
                USING ERRCODE = '22023';
        END IF;

        INSERT INTO scheduled_task_deliveries(
            run_id, task_id, org_id, delivery_key, delivery_kind,
            target_context, payload
        ) VALUES (
            p_run_id, p_task_id, v_task.org_id,
            v_delivery->>'delivery_key', 'result',
            v_delivery->'target_context', v_delivery->'payload'
        ) ON CONFLICT (run_id, delivery_key) DO NOTHING;
    END LOOP;

    UPDATE scheduled_tasks
       SET retry_config_revision = NULL, status = CASE WHEN v_task.status = 'running' THEN p_next_status ELSE v_task.status END,
           next_run_at = CASE
               WHEN v_task.status = 'running' THEN p_next_run_at
               ELSE v_task.next_run_at
           END,
           last_run_at = NOW(),
           last_summary = p_last_summary,
           last_result = (p_last_result - 'observations' - 'text' - 'notification_decision') ||
               CASE WHEN p_last_result ? 'notification_decision'
                    THEN jsonb_build_object('notification_decision', (p_last_result->'notification_decision') - 'state')
                    ELSE '{}'::jsonb END,
           notification_state = COALESCE(p_last_result->'notification_decision'->'state', notification_state),
           run_count = v_task.run_count + 1,
           consecutive_failures = 0,
           updated_at = NOW()
     WHERE id = p_task_id;

    UPDATE scheduled_task_runs
       SET status = 'success',
           result_text = p_last_result->>'text',
           observations = COALESCE(p_last_result->'observations','[]'::jsonb),
           notification_decision = (p_last_result->'notification_decision') - 'state',
           result_summary = p_last_summary,
           result_files = COALESCE(p_last_result->'files', '[]'::JSONB),
           credits_used = p_credits_used,
           tokens_used = p_tokens_used,
           duration_ms = p_duration_ms,
           finished_at = NOW()
     WHERE id = p_run_id;

    v_push_status := refresh_scheduled_task_run_push_status(p_run_id);
    RETURN jsonb_build_object(
        'outcome', 'completed',
        'push_status', v_push_status, 'next_run_at', p_next_run_at, 'schedule_status', p_next_status
    );
END;
$$;


ALTER FUNCTION public.complete_scheduled_task_success(p_task_id uuid, p_run_id uuid, p_next_status text, p_next_run_at timestamp with time zone, p_last_summary text, p_last_result jsonb, p_credits_used integer, p_tokens_used integer, p_duration_ms integer, p_deliveries jsonb) OWNER TO everydayai;

--
-- Name: complete_tool_invocation(uuid, uuid, text, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.complete_tool_invocation(p_task_id uuid, p_turn_id uuid, p_tool_call_id text, p_execution_token uuid, p_status text, p_result jsonb, p_error_message text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_updated_count BIGINT;
BEGIN
    IF p_task_id IS NULL OR p_turn_id IS NULL OR p_execution_token IS NULL
       OR NULLIF(BTRIM(p_tool_call_id), '') IS NULL
       OR p_status NOT IN ('succeeded', 'uncertain')
       OR p_result IS NULL OR jsonb_typeof(p_result) <> 'object' THEN
        RAISE EXCEPTION 'ACTOR_TOOL_INVOCATION_COMPLETE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_TOOL_INVOCATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    UPDATE tool_invocations
       SET status = p_status,
           result = p_result,
           error_message = LEFT(COALESCE(p_error_message, ''), 2000),
           execution_token = p_execution_token,
           completed_at = NOW(),
           updated_at = NOW()
     WHERE task_id = p_task_id
       AND turn_id = p_turn_id
       AND tool_call_id = BTRIM(p_tool_call_id)
       AND status = 'running';
    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        RETURN jsonb_build_object('outcome', 'already_completed');
    END IF;
    RETURN jsonb_build_object('outcome', p_status);
END;
$$;


ALTER FUNCTION public.complete_tool_invocation(p_task_id uuid, p_turn_id uuid, p_tool_call_id text, p_execution_token uuid, p_status text, p_result jsonb, p_error_message text) OWNER TO everydayai;

--
-- Name: confirm_scheduled_task_draft(uuid, uuid, uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.confirm_scheduled_task_draft(p_draft_id uuid, p_org_id uuid, p_user_id uuid, p_config_hash text, p_task_id uuid, p_next_run_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_draft scheduled_task_drafts%ROWTYPE;
    v_definition JSONB;
    v_source scheduled_tasks%ROWTYPE;
    v_source_status TEXT;
BEGIN
    SELECT * INTO v_draft FROM scheduled_task_drafts
      WHERE id = p_draft_id AND org_id = p_org_id AND user_id = p_user_id
      FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'missing');
    END IF;
    IF v_draft.status = 'confirmed' THEN
        RETURN jsonb_build_object(
            'outcome', 'confirmed',
            'task_id', COALESCE(v_draft.confirmed_task_id, v_draft.source_task_id)
        );
    END IF;
    IF v_draft.status <> 'ready' OR v_draft.config_hash <> p_config_hash
       OR v_draft.preflight_config_hash <> p_config_hash OR v_draft.expires_at <= NOW() THEN
        RETURN jsonb_build_object('outcome', 'not_ready');
    END IF;

    v_definition := v_draft.definition;
    IF v_draft.source_task_id IS NULL THEN
        INSERT INTO scheduled_tasks(
            id, org_id, user_id, name, prompt, cron_expr, schedule_type, weekdays,
            day_of_month, run_at, timezone, push_target, template_file, status,
            max_credits, retry_count, timeout_sec, next_run_at, run_count,
            consecutive_failures, execution_policy, plan_snapshot, skill_revision_snapshot
        ) VALUES (
            p_task_id, p_org_id, p_user_id, v_definition->>'name', v_definition->>'prompt',
            NULLIF(v_definition->>'cron_expr',''), v_definition->>'schedule_type',
            CASE WHEN jsonb_typeof(v_definition->'weekdays') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(v_definition->'weekdays')::smallint) END,
            NULLIF(v_definition->>'day_of_month','')::smallint,
            NULLIF(v_definition->>'run_at','')::timestamptz, COALESCE(v_definition->>'timezone','Asia/Shanghai'),
            v_definition->'push_target', v_definition->'template_file', 'active',
            COALESCE((v_definition->>'max_credits')::integer, 10),
            COALESCE((v_definition->>'retry_count')::smallint, 1),
            COALESCE((v_definition->>'timeout_sec')::integer, 180), p_next_run_at,
            0, 0, v_draft.execution_policy, v_draft.plan,
            COALESCE(v_definition->'skill_revision_snapshot','{"version":1,"skills":[]}'::jsonb)
        );
        UPDATE scheduled_task_drafts
           SET status = 'confirmed', confirmed_task_id = p_task_id, updated_at = NOW()
         WHERE id = p_draft_id;
        RETURN jsonb_build_object('outcome', 'created', 'task_id', p_task_id);
    END IF;

    SELECT * INTO v_source FROM scheduled_tasks
      WHERE id = v_draft.source_task_id AND org_id = p_org_id
      FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'source_missing');
    END IF;
    IF v_source.status = 'running' THEN
        RETURN jsonb_build_object('outcome', 'source_running');
    END IF;

    v_source_status := CASE
        WHEN v_source.status = 'active' THEN 'active'
        ELSE 'paused'
    END;
    UPDATE scheduled_tasks
       SET name = v_definition->>'name',
           prompt = v_definition->>'prompt',
           cron_expr = NULLIF(v_definition->>'cron_expr',''),
           schedule_type = v_definition->>'schedule_type',
           weekdays = CASE WHEN jsonb_typeof(v_definition->'weekdays') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(v_definition->'weekdays')::smallint) END,
           day_of_month = NULLIF(v_definition->>'day_of_month','')::smallint,
           run_at = NULLIF(v_definition->>'run_at','')::timestamptz,
           timezone = COALESCE(v_definition->>'timezone','Asia/Shanghai'),
           push_target = v_definition->'push_target',
           template_file = v_definition->'template_file',
           max_credits = COALESCE((v_definition->>'max_credits')::integer, 10),
           retry_count = COALESCE((v_definition->>'retry_count')::smallint, 1),
           timeout_sec = COALESCE((v_definition->>'timeout_sec')::integer, 180),
           status = v_source_status,
           next_run_at = CASE WHEN v_source_status = 'active' THEN p_next_run_at ELSE NULL END,
           consecutive_failures = 0,
           execution_policy = v_draft.execution_policy,
           plan_snapshot = v_draft.plan,
           skill_revision_snapshot = COALESCE(v_definition->'skill_revision_snapshot','{"version":1,"skills":[]}'::jsonb),
           updated_at = NOW()
     WHERE id = v_source.id;
    UPDATE scheduled_task_drafts
       SET status = 'confirmed', confirmed_task_id = v_source.id, updated_at = NOW()
     WHERE id = p_draft_id;
    RETURN jsonb_build_object('outcome', 'updated', 'task_id', v_source.id);
END;
$$;


ALTER FUNCTION public.confirm_scheduled_task_draft(p_draft_id uuid, p_org_id uuid, p_user_id uuid, p_config_hash text, p_task_id uuid, p_next_run_at timestamp with time zone) OWNER TO everydayai;

--
-- Name: consume_active_conversation_attachments(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.consume_active_conversation_attachments(p_conversation_id uuid, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_parts JSONB;
BEGIN
    PERFORM 1
      FROM conversation_attachment_refs
     WHERE conversation_id = p_conversation_id
       AND org_id = p_org_id
       AND status = 'ready'
       AND reference_state = 'active'
     FOR UPDATE;
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'type', 'file',
        'url', a.url,
        'workspace_path', a.workspace_path,
        'name', a.original_name,
        'mime_type', a.mime_type,
        'size', a.size,
        'asset_id', a.id
    ) ORDER BY a.created_at), '[]'::JSONB)
      INTO v_parts
      FROM conversation_attachment_refs a
     WHERE a.conversation_id = p_conversation_id
       AND a.org_id = p_org_id
       AND a.status = 'ready'
       AND a.reference_state = 'active';

    UPDATE conversation_attachment_refs
       SET reference_state = 'referenced'
     WHERE conversation_id = p_conversation_id
       AND org_id = p_org_id
       AND status = 'ready'
       AND reference_state = 'active';
    RETURN v_parts;
END;
$$;


ALTER FUNCTION public.consume_active_conversation_attachments(p_conversation_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: create_actor_cancel_control_command(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.create_actor_cancel_control_command() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.status = 'cancelled'
       AND OLD.status IS DISTINCT FROM NEW.status
       AND NEW.type = 'chat'
       AND (NEW.delivery_context @> '{"actor": true}'::JSONB) THEN
        INSERT INTO conversation_control_events(
            conversation_id, task_id, turn_id, event_type, dedupe_key, payload,
            status, applied_at
        ) VALUES (
            NEW.conversation_id, NEW.id, NEW.turn_id, 'cancel',
            'cancel:' || NEW.id::TEXT,
            jsonb_build_object(
                'reason', COALESCE(NEW.terminal_reason, 'user_cancelled')
            ),
            'applied', NOW()
        )
        ON CONFLICT (task_id, dedupe_key) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.create_actor_cancel_control_command() OWNER TO everydayai;

--
-- Name: create_actor_terminal_delivery(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.create_actor_terminal_delivery() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_channel TEXT;
BEGIN
    IF NEW.status NOT IN ('completed', 'failed')
       OR OLD.status IS NOT DISTINCT FROM NEW.status
       OR NOT (NEW.delivery_context @> '{"actor": true}'::JSONB) THEN
        RETURN NEW;
    END IF;

    v_channel := NEW.delivery_context->>'channel';
    IF v_channel <> 'wecom' THEN
        RETURN NEW;
    END IF;

    INSERT INTO conversation_deliveries(
        task_id, channel, delivery_kind, target_context
    ) VALUES (
        NEW.id, v_channel, 'assistant_terminal', NEW.delivery_context
    )
    ON CONFLICT (task_id, channel, delivery_kind) DO NOTHING;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.create_actor_terminal_delivery() OWNER TO everydayai;

--
-- Name: create_change_set(uuid, uuid, text, text, text, text, jsonb, jsonb, jsonb, jsonb, text, jsonb, jsonb, jsonb, jsonb, text, timestamp with time zone, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.create_change_set(p_id uuid, p_org_id uuid, p_resource_type text, p_resource_id text, p_operation text, p_base_revision text, p_base_snapshot jsonb, p_proposed_snapshot jsonb, p_patch jsonb, p_diff jsonb, p_risk_level text, p_policy_snapshot jsonb, p_plan_snapshot jsonb, p_tool_policy_snapshot jsonb, p_check_summary jsonb, p_idempotency_key text, p_expires_at timestamp with time zone, p_actor_id text, p_actor_type text, p_audit_subject jsonb, p_recovery_of_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_existing public.change_sets%ROWTYPE;
    v_created public.change_sets%ROWTYPE;
BEGIN
    SELECT * INTO v_existing
      FROM public.change_sets
     WHERE org_id = p_org_id AND idempotency_key = p_idempotency_key
     FOR UPDATE;
    IF FOUND THEN
        IF v_existing.resource_type <> p_resource_type
           OR v_existing.resource_id <> p_resource_id
           OR v_existing.operation <> p_operation
           OR v_existing.base_revision <> p_base_revision
           OR v_existing.base_snapshot IS DISTINCT FROM COALESCE(p_base_snapshot, '{}'::JSONB)
           OR v_existing.proposed_snapshot IS DISTINCT FROM COALESCE(p_proposed_snapshot, '{}'::JSONB) THEN
            RETURN jsonb_build_object('outcome', 'idempotency_conflict', 'change_set', to_jsonb(v_existing));
        END IF;
        RETURN jsonb_build_object('outcome', 'existing', 'change_set', to_jsonb(v_existing));
    END IF;

    INSERT INTO public.change_sets(
        id, org_id, resource_type, resource_id, operation, base_revision,
        base_snapshot, proposed_snapshot, patch, diff, risk_level, policy_snapshot,
        plan_snapshot, tool_policy_snapshot, check_summary, idempotency_key,
        expires_at, created_by, created_by_type, audit_subject, recovery_of_id
    ) VALUES (
        p_id, p_org_id, p_resource_type, p_resource_id, p_operation, p_base_revision,
        COALESCE(p_base_snapshot, '{}'::JSONB), COALESCE(p_proposed_snapshot, '{}'::JSONB),
        COALESCE(p_patch, '[]'::JSONB), COALESCE(p_diff, '{}'::JSONB),
        COALESCE(p_risk_level, 'medium'), COALESCE(p_policy_snapshot, '{}'::JSONB),
        p_plan_snapshot, p_tool_policy_snapshot, p_check_summary, p_idempotency_key,
        COALESCE(p_expires_at, NOW() + INTERVAL '24 hours'), p_actor_id, p_actor_type,
        COALESCE(p_audit_subject, '{}'::JSONB), p_recovery_of_id
    ) ON CONFLICT (org_id, idempotency_key) DO NOTHING
      RETURNING * INTO v_created;

    -- 并发创建时，唯一键冲突不会向调用方泄漏为 500；重新锁定赢家并按
    -- 同一候选内容比较，保证“重复请求回放、不同请求拒绝”的幂等语义。
    IF NOT FOUND THEN
        SELECT * INTO v_existing
          FROM public.change_sets
         WHERE org_id = p_org_id AND idempotency_key = p_idempotency_key
         FOR UPDATE;
        IF v_existing.resource_type <> p_resource_type
           OR v_existing.resource_id <> p_resource_id
           OR v_existing.operation <> p_operation
           OR v_existing.base_revision <> p_base_revision
           OR v_existing.base_snapshot IS DISTINCT FROM COALESCE(p_base_snapshot, '{}'::JSONB)
           OR v_existing.proposed_snapshot IS DISTINCT FROM COALESCE(p_proposed_snapshot, '{}'::JSONB) THEN
            RETURN jsonb_build_object('outcome', 'idempotency_conflict', 'change_set', to_jsonb(v_existing));
        END IF;
        RETURN jsonb_build_object('outcome', 'existing', 'change_set', to_jsonb(v_existing));
    END IF;

    INSERT INTO public.change_events(
        change_set_id, org_id, sequence, event_type, to_status,
        actor_id, actor_type, payload
    ) VALUES (
        v_created.id, v_created.org_id, 1, 'created', v_created.status,
        p_actor_id, p_actor_type,
        jsonb_build_object('contract_version', 'changeset.v1')
    );
    RETURN jsonb_build_object('outcome', 'created', 'change_set', to_jsonb(v_created));
END;
$$;


ALTER FUNCTION public.create_change_set(p_id uuid, p_org_id uuid, p_resource_type text, p_resource_id text, p_operation text, p_base_revision text, p_base_snapshot jsonb, p_proposed_snapshot jsonb, p_patch jsonb, p_diff jsonb, p_risk_level text, p_policy_snapshot jsonb, p_plan_snapshot jsonb, p_tool_policy_snapshot jsonb, p_check_summary jsonb, p_idempotency_key text, p_expires_at timestamp with time zone, p_actor_id text, p_actor_type text, p_audit_subject jsonb, p_recovery_of_id uuid) OWNER TO everydayai;

--
-- Name: create_detail_project(uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.create_detail_project(p_request_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor UUID:=NULLIF(current_setting('app.actor_user_id',true),'')::uuid;
 org UUID:=NULLIF(current_setting('app.org_id',true),'')::uuid; d public.detail_projects%ROWTYPE;
BEGIN
 IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',true) IS DISTINCT FROM 'runtime' OR actor IS NULL OR p_request_id IS NULL THEN
  RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF org IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_members WHERE user_id=actor AND org_id=org AND status='active') THEN
  RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 INSERT INTO public.detail_projects(id,user_id,org_id,platform) VALUES(p_request_id,actor,org,'taobao') ON CONFLICT(id) DO NOTHING;
 SELECT * INTO d FROM public.detail_projects WHERE id=p_request_id AND user_id=actor AND org_id IS NOT DISTINCT FROM org;
 IF NOT FOUND THEN RAISE EXCEPTION 'DETAIL_PROJECT_DENIED' USING ERRCODE='42501'; END IF;
 RETURN d.id;
END $$;


ALTER FUNCTION public.create_detail_project(p_request_id uuid) OWNER TO everydayai;

--
-- Name: create_governed_invitation(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.create_governed_invitation(p_org_id uuid, p_phone text, p_role text, p_invite_token text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    v_authority TEXT;
    v_invitation public.org_invitations%ROWTYPE;
BEGIN
    v_authority := public._assert_governance_authority(
        p_org_id, ARRAY['owner', 'admin'], FALSE
    );
    IF p_phone !~ '^1[3-9][0-9]{9}$'
       OR p_role NOT IN ('admin', 'member')
       OR COALESCE(BTRIM(p_invite_token), '') = ''
       OR LENGTH(p_invite_token) > 100
       OR p_expires_at <= NOW() THEN
        RAISE EXCEPTION 'GOVERNANCE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        p_org_id::TEXT || '::invite::' || p_phone, 0
    ));
    IF EXISTS (
        SELECT 1 FROM public.users account
        JOIN public.org_members member ON member.user_id = account.id
         WHERE account.phone = p_phone AND member.org_id = p_org_id
    ) OR EXISTS (
        SELECT 1 FROM public.org_invitations
         WHERE org_id = p_org_id
           AND phone = p_phone
           AND status = 'pending'
    ) THEN
        RAISE EXCEPTION 'GOVERNANCE_INVITATION_CONFLICT'
            USING ERRCODE = '23505';
    END IF;
    INSERT INTO public.org_invitations(
        org_id, phone, role, invite_token, invited_by, expires_at
    ) VALUES (
        p_org_id, p_phone, p_role, p_invite_token,
        public.tenant_actor_user_id(), p_expires_at
    ) RETURNING * INTO v_invitation;
    PERFORM public._record_governance_audit(
        p_org_id, v_authority, 'invitation.create', 'invitation',
        v_invitation.id::TEXT, jsonb_build_object('role', p_role)
    );
    RETURN to_jsonb(v_invitation);
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'GOVERNANCE_INVITATION_CONFLICT'
            USING ERRCODE = '23505';
END;
$_$;


ALTER FUNCTION public.create_governed_invitation(p_org_id uuid, p_phone text, p_role text, p_invite_token text, p_expires_at timestamp with time zone) OWNER TO everydayai_owner;

--
-- Name: create_governed_organization(text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.create_governed_organization(p_name text, p_owner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_authority TEXT;
    v_org public.organizations%ROWTYPE;
BEGIN
    v_authority := public._assert_governance_authority(
        NULL, ARRAY[]::TEXT[], TRUE
    );
    IF COALESCE(BTRIM(p_name), '') = ''
       OR LENGTH(BTRIM(p_name)) > 100
       OR NOT EXISTS (
           SELECT 1 FROM public.users
            WHERE id = p_owner_id AND status::TEXT = 'active'
       ) THEN
        RAISE EXCEPTION 'GOVERNANCE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        'organization-name::' || LOWER(BTRIM(p_name)), 0
    ));
    IF EXISTS (
        SELECT 1 FROM public.organizations WHERE name = BTRIM(p_name)
    ) THEN
        RAISE EXCEPTION 'GOVERNANCE_ORG_NAME_CONFLICT'
            USING ERRCODE = '23505';
    END IF;
    INSERT INTO public.organizations(name, owner_id)
    VALUES (BTRIM(p_name), p_owner_id)
    RETURNING * INTO v_org;
    INSERT INTO public.org_members(org_id, user_id, role, status)
    VALUES (v_org.id, p_owner_id, 'owner', 'active');
    PERFORM public._record_governance_audit(
        v_org.id, v_authority, 'organization.create',
        'organization', v_org.id::TEXT,
        jsonb_build_object('owner_id', p_owner_id)
    );
    RETURN to_jsonb(v_org)
        - 'encrypt_key'
        - 'wecom_secret_encrypted';
END;
$$;


ALTER FUNCTION public.create_governed_organization(p_name text, p_owner_id uuid) OWNER TO everydayai_owner;

--
-- Name: create_web_user_wecom_delivery(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.create_web_user_wecom_delivery() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_target_context JSONB;
BEGIN
    IF NOT (
        NEW.delivery_context @> '{"actor":true,"channel":"web"}'::JSONB
    ) THEN
        RETURN NEW;
    END IF;

    SELECT t.delivery_context
               - 'stream_task_id' - 'stream_req_id'
               - 'stream_id' - 'stream_started_at'
      INTO v_target_context
      FROM conversations c
      JOIN conversation_channel_bindings b
        ON b.conversation_id = c.id
       AND b.org_id = c.org_id
       AND b.channel = 'wecom'
      JOIN tasks t
        ON t.conversation_id = c.id
       AND t.org_id IS NOT DISTINCT FROM c.org_id
     WHERE c.id = NEW.conversation_id
       AND c.source = 'wecom'
       AND t.delivery_context @> '{"actor":true,"channel":"wecom"}'::JSONB
       AND t.delivery_context->>'corp_id' = b.corp_id
       AND t.delivery_context->>'chatid' = b.external_chat_id
       AND t.delivery_context->>'chattype' = b.chat_type
       AND t.delivery_context->>'transport' IN ('smart_robot', 'app')
     ORDER BY t.created_at DESC, t.id DESC
     LIMIT 1;

    IF v_target_context IS NULL THEN
        RETURN NEW;
    END IF;

    INSERT INTO conversation_deliveries(
        task_id, channel, delivery_kind, target_context
    ) VALUES (
        NEW.id, 'wecom', 'web_user_message', v_target_context
    )
    ON CONFLICT (task_id, channel, delivery_kind) DO NOTHING;
    RETURN NEW;
END;
$$;


