--
-- Name: deduct_credits_atomic(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.deduct_credits_atomic(p_user_id uuid, p_amount integer, p_reason text, p_change_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_new_balance INTEGER;
BEGIN
    -- 原子扣除
    UPDATE users
    SET credits = credits - p_amount,
        updated_at = NOW()
    WHERE id = p_user_id
      AND credits >= p_amount
    RETURNING credits INTO v_new_balance;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient credits');
    END IF;

    -- 记录历史
    INSERT INTO credits_history (user_id, change_type, change_amount, balance_after, description)
    VALUES (p_user_id, p_change_type::credits_change_type, -p_amount, v_new_balance, p_reason);

    RETURN jsonb_build_object('success', true, 'new_balance', v_new_balance);
END;
$$;


