--
-- Name: FUNCTION enqueue_wecom_generation_turn(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.enqueue_wecom_generation_turn(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb) IS '按稳定 ID 原子创建企微输入/输出消息并幂等进入 Conversation Actor 队列';


--
-- Name: enqueue_wecom_generation_turn(jsonb, uuid, uuid, uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.enqueue_wecom_generation_turn(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task_org_id UUID;
BEGIN
    BEGIN
        v_task_org_id := NULLIF(p_task_data->>'org_id', '')::UUID;
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'WECOM_ACTOR_ENQUEUE_ID_INVALID'
            USING ERRCODE = '22023';
    END;
    IF v_task_org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'WECOM_ACTOR_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    RETURN enqueue_wecom_generation_turn(
        p_task_data,
        p_input_message_id,
        p_output_message_id,
        p_turn_id,
        p_input_content,
        p_delivery_context
    );
END;
$$;


ALTER FUNCTION public.enqueue_wecom_generation_turn(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb, p_org_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION enqueue_wecom_generation_turn(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.enqueue_wecom_generation_turn(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb, p_org_id uuid) IS '租户范围校验后调用企微 Actor 原子入队核心';


--
-- Name: enqueue_wecom_generation_turn_v2(jsonb, uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.enqueue_wecom_generation_turn_v2(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_input messages%ROWTYPE;
    v_conversation_id UUID;
    v_org_id UUID;
    v_user_id UUID;
    v_task_id UUID;
    v_content JSONB;
    v_result JSONB;
BEGIN
    BEGIN
        v_conversation_id := (p_task_data->>'conversation_id')::UUID;
        v_org_id := NULLIF(p_task_data->>'org_id', '')::UUID;
        v_user_id := (p_task_data->>'user_id')::UUID;
        v_task_id := (p_task_data->>'id')::UUID;
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'WECOM_ACTOR_ENQUEUE_ID_INVALID'
            USING ERRCODE = '22023';
    END;
    IF jsonb_typeof(p_input_content) IS DISTINCT FROM 'array'
       OR p_input_message_id IS NULL OR p_output_message_id IS NULL
       OR p_turn_id IS NULL OR v_task_id IS NULL
       OR jsonb_typeof(p_delivery_context) IS DISTINCT FROM 'object'
       OR NOT (
           p_delivery_context @> '{"actor":true,"channel":"wecom"}'::JSONB
       )
       OR COALESCE(p_delivery_context->>'chatid', '') = ''
       OR COALESCE(p_delivery_context->>'transport', '')
          NOT IN ('smart_robot', 'app') THEN
        RAISE EXCEPTION 'WECOM_ACTOR_ENQUEUE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_conversation FROM conversations
     WHERE id = v_conversation_id FOR UPDATE;
    IF NOT FOUND OR v_conversation.org_id IS DISTINCT FROM v_org_id
       OR v_conversation.source IS DISTINCT FROM 'wecom'
       OR (
           v_conversation.scope_type = 'user'
           AND v_conversation.user_id IS DISTINCT FROM v_user_id
       )
       OR (
           v_conversation.scope_type = 'channel'
           AND NOT EXISTS (
               SELECT 1 FROM conversation_channel_bindings b
                WHERE b.conversation_id = v_conversation_id
                  AND b.org_id = v_org_id
                  AND b.corp_id = p_delivery_context->>'corp_id'
                  AND b.external_chat_id = p_delivery_context->>'chatid'
                  AND b.chat_type = 'group'
           )
       ) THEN
        RAISE EXCEPTION 'WECOM_ACTOR_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_input FROM messages
     WHERE id = p_input_message_id FOR UPDATE;
    IF v_input.id IS NULL THEN
        v_content := p_input_content
            || current_attachment_parts(v_conversation_id, v_org_id);
        INSERT INTO messages(
            id, conversation_id, org_id, role, content, status, turn_id,
            sender_user_id, sender_channel_identity
        ) VALUES (
            p_input_message_id, v_conversation_id, v_org_id, 'user',
            v_content, 'completed', p_turn_id, v_user_id,
            NULLIF(p_delivery_context->>'wecom_userid', '')
        ) RETURNING * INTO v_input;
        INSERT INTO messages(
            id, conversation_id, org_id, role, content, status, turn_id,
            reply_to_message_id
        ) VALUES (
            p_output_message_id, v_conversation_id, v_org_id, 'assistant',
            '[{"type":"text","text":""}]', 'generating', p_turn_id,
            p_input_message_id
        ) ON CONFLICT (id) DO NOTHING;
        SELECT enqueue_wecom_task_record(
            p_task_data, p_input_message_id, p_turn_id, 'serial',
            p_delivery_context
        ) INTO v_result;
        PERFORM bind_task_attachments(
            v_task_id, p_turn_id, p_input_message_id,
            v_conversation_id, v_org_id
        );
        IF COALESCE((v_result->>'already_enqueued')::BOOLEAN, FALSE) = FALSE THEN
            PERFORM increment_message_count(v_conversation_id, v_org_id);
        END IF;
    ELSE
        v_content := v_input.content;
        IF v_input.conversation_id IS DISTINCT FROM v_conversation_id
           OR v_input.org_id IS DISTINCT FROM v_org_id
           OR v_input.role::TEXT <> 'user'
           OR v_input.turn_id IS DISTINCT FROM p_turn_id
           OR (
               SELECT COALESCE(
                   jsonb_agg(value ORDER BY ordinality), '[]'::JSONB
               )
                 FROM jsonb_array_elements(v_content)
                      WITH ORDINALITY AS item(value, ordinality)
                WHERE ordinality <= jsonb_array_length(p_input_content)
           ) IS DISTINCT FROM p_input_content THEN
            RAISE EXCEPTION 'WECOM_ACTOR_MESSAGE_CONFLICT'
                USING ERRCODE = '23505';
        END IF;
        SELECT enqueue_wecom_task_record(
            p_task_data, p_input_message_id, p_turn_id, 'serial',
            p_delivery_context
        ) INTO v_result;
    END IF;
    RETURN v_result || jsonb_build_object(
        'input_message_id', p_input_message_id,
        'output_message_id', p_output_message_id,
        'attachment_count', jsonb_array_length(v_content)
            - jsonb_array_length(p_input_content)
    );
END;
$$;


ALTER FUNCTION public.enqueue_wecom_generation_turn_v2(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb) OWNER TO everydayai;

--
-- Name: enqueue_wecom_generation_turn_v2(jsonb, uuid, uuid, uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
