CREATE FUNCTION public.enqueue_wecom_generation_turn_v2(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NULLIF(p_task_data->>'org_id', '')::UUID IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'WECOM_ACTOR_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    RETURN enqueue_wecom_generation_turn_v2(
        p_task_data, p_input_message_id, p_output_message_id, p_turn_id,
        p_input_content, p_delivery_context
    );
END;
$$;


ALTER FUNCTION public.enqueue_wecom_generation_turn_v2(p_task_data jsonb, p_input_message_id uuid, p_output_message_id uuid, p_turn_id uuid, p_input_content jsonb, p_delivery_context jsonb, p_org_id uuid) OWNER TO everydayai;

--
-- Name: enqueue_wecom_task_record(jsonb, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.enqueue_wecom_task_record(p_task_data jsonb, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text, p_delivery_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_task_id UUID := (p_task_data->>'id')::UUID;
    v_output_id UUID := (p_task_data->>'assistant_message_id')::UUID;
    v_user_id UUID := (p_task_data->>'user_id')::UUID;
    v_org_id UUID := NULLIF(p_task_data->>'org_id', '')::UUID;
    v_conversation_id UUID := (p_task_data->>'conversation_id')::UUID;
    v_inserted_count BIGINT;
BEGIN
    INSERT INTO tasks(
        id, external_task_id, client_task_id, user_id, org_id, conversation_id,
        type, status, model_id, placeholder_message_id, assistant_message_id,
        request_params, placeholder_created_at, input_message_id, turn_id,
        execution_mode, delivery_context
    ) VALUES (
        v_task_id, p_task_data->>'external_task_id',
        p_task_data->>'client_task_id', v_user_id, v_org_id, v_conversation_id,
        'chat', 'pending', p_task_data->>'model_id',
        NULLIF(p_task_data->>'placeholder_message_id', '')::UUID,
        v_output_id, COALESCE(p_task_data->'request_params', '{}'::JSONB),
        NULLIF(p_task_data->>'placeholder_created_at', '')::TIMESTAMPTZ,
        p_input_message_id, p_turn_id, p_execution_mode, p_delivery_context
    )
    ON CONFLICT (id) DO NOTHING;
    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

    SELECT * INTO v_task FROM tasks WHERE id = v_task_id FOR UPDATE;
    IF v_task.id IS NULL OR v_task.type <> 'chat'
       OR v_task.conversation_id IS DISTINCT FROM v_conversation_id
       OR v_task.user_id IS DISTINCT FROM v_user_id
       OR v_task.org_id IS DISTINCT FROM v_org_id
       OR v_task.input_message_id IS DISTINCT FROM p_input_message_id
       OR v_task.turn_id IS DISTINCT FROM p_turn_id
       OR v_task.assistant_message_id IS DISTINCT FROM v_output_id
       OR v_task.execution_mode IS DISTINCT FROM p_execution_mode THEN
        RAISE EXCEPTION 'ACTOR_ENQUEUE_CONFLICT' USING ERRCODE = '23505';
    END IF;
    UPDATE messages SET turn_id = p_turn_id
     WHERE id = p_input_message_id;
    UPDATE messages SET turn_id = p_turn_id,
           reply_to_message_id = p_input_message_id
     WHERE id = v_output_id;
    RETURN jsonb_build_object(
        'task_id', v_task.id,
        'status', v_task.status,
        'queue_sequence', v_task.queue_sequence,
        'execution_mode', v_task.execution_mode,
        'already_enqueued', v_inserted_count = 0
    );
END;
$$;


ALTER FUNCTION public.enqueue_wecom_task_record(p_task_data jsonb, p_input_message_id uuid, p_turn_id uuid, p_execution_mode text, p_delivery_context jsonb) OWNER TO everydayai;

--
-- Name: enrich_change_set_proposal(uuid, uuid, text, jsonb, jsonb, jsonb, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.enrich_change_set_proposal(p_change_set_id uuid, p_org_id uuid, p_expected_status text, p_proposed_snapshot jsonb, p_patch jsonb, p_diff jsonb, p_risk_level text, p_policy_snapshot jsonb, p_plan_snapshot jsonb, p_tool_policy_snapshot jsonb, p_check_summary jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row public.change_sets%ROWTYPE;
BEGIN
    UPDATE public.change_sets
       SET proposed_snapshot = p_proposed_snapshot, patch = p_patch, diff = p_diff,
           risk_level = p_risk_level, policy_snapshot = p_policy_snapshot,
           plan_snapshot = p_plan_snapshot, tool_policy_snapshot = p_tool_policy_snapshot,
           check_summary = p_check_summary, updated_at = NOW()
     WHERE id = p_change_set_id AND org_id = p_org_id AND status = p_expected_status
     RETURNING * INTO v_row;
    IF NOT FOUND THEN
        SELECT * INTO v_row FROM public.change_sets
         WHERE id = p_change_set_id AND org_id = p_org_id;
        RETURN jsonb_build_object('outcome', 'state_conflict', 'change_set', to_jsonb(v_row));
    END IF;
    RETURN jsonb_build_object('outcome', 'enriched', 'change_set', to_jsonb(v_row));
END;
$$;


