--
-- Name: FUNCTION erp_distinct_shops(p_org_id uuid, p_platform character varying); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.erp_distinct_shops(p_org_id uuid, p_platform character varying) IS '店铺列表去重查询（local_shop_list 工具专用）';


--
-- Name: erp_distribution_query(uuid, text, text, text, text, text, numeric[], text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_distribution_query(p_org_id uuid, p_table text DEFAULT 'erp_document_items'::text, p_doc_type text DEFAULT NULL::text, p_start text DEFAULT NULL::text, p_end text DEFAULT NULL::text, p_field text DEFAULT 'amount'::text, p_buckets numeric[] DEFAULT '{0,50,100,200,500,1000,5000}'::numeric[], p_time_col text DEFAULT 'doc_created_at'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_case_lines  TEXT[] := '{}';
    v_label       TEXT;
    v_lo          NUMERIC;
    v_hi          NUMERIC;
    v_safe_field  TEXT;
    v_safe_table  TEXT;
    v_safe_tcol   TEXT;
    v_where       TEXT := '';
    v_sql         TEXT;
    v_result      JSONB;
BEGIN
    -- ── 安全校验：表名白名单 ──
    IF p_table NOT IN (
        'erp_document_items', 'erp_document_items_archive',
        'erp_product_daily_stats', 'erp_stock_status'
    ) THEN
        RAISE EXCEPTION 'table not allowed: %', p_table;
    END IF;

    -- ── 安全校验：字段名白名单 ──
    v_safe_field := CASE
        WHEN p_field IN (
            'amount', 'quantity', 'cost', 'gross_profit',
            'order_amount', 'order_qty', 'order_count', 'order_cost',
            'purchase_amount', 'purchase_qty', 'purchase_count',
            'aftersale_amount', 'aftersale_qty', 'aftersale_count',
            'total_stock', 'available_stock', 'sellable_num',
            'purchase_price', 'selling_price'
        ) THEN p_field
        ELSE NULL
    END;
    IF v_safe_field IS NULL THEN
        RAISE EXCEPTION 'field not allowed: %', p_field;
    END IF;

    -- ── 安全校验：时间列白名单 ──
    v_safe_tcol := CASE
        WHEN p_time_col IN (
            'doc_created_at', 'pay_time', 'consign_time',
            'stat_date', 'stock_modified_time'
        ) THEN p_time_col
        ELSE 'doc_created_at'
    END;
    v_safe_table := p_table;

    -- ── 构建 CASE WHEN 分桶表达式 ──
    FOR i IN 1 .. array_length(p_buckets, 1) LOOP
        v_lo := p_buckets[i];
        IF i < array_length(p_buckets, 1) THEN
            v_hi := p_buckets[i + 1];
            v_label := v_lo::TEXT || '~' || v_hi::TEXT;
            v_case_lines := v_case_lines || format(
                'WHEN %I >= %s AND %I < %s THEN %L',
                v_safe_field, v_lo, v_safe_field, v_hi, v_label
            );
        ELSE
            -- 最后一个桶：>= 最后边界
            v_label := v_lo::TEXT || '+';
            v_case_lines := v_case_lines || format(
                'WHEN %I >= %s THEN %L',
                v_safe_field, v_lo, v_label
            );
        END IF;
    END LOOP;

    -- ── WHERE 条件 ──
    v_where := format('WHERE org_id = %L', p_org_id);

    IF p_doc_type IS NOT NULL THEN
        v_where := v_where || format(' AND doc_type = %L', p_doc_type);
    END IF;

    IF p_start IS NOT NULL THEN
        v_where := v_where || format(' AND %I >= %L', v_safe_tcol, p_start);
    END IF;
    IF p_end IS NOT NULL THEN
        v_where := v_where || format(' AND %I < %L', v_safe_tcol, p_end);
    END IF;

    -- 排除 NULL 和负值
    v_where := v_where || format(' AND %I IS NOT NULL AND %I >= 0', v_safe_field, v_safe_field);

    -- ── 拼装最终 SQL ──
    v_sql := format(
        'SELECT jsonb_agg(row_to_json(t) ORDER BY t.sort_key) FROM ('
        '  SELECT'
        '    CASE %s ELSE ''other'' END AS bucket,'
        '    COUNT(*) AS count,'
        '    ROUND(SUM(%I)::NUMERIC, 2) AS bucket_total,'
        '    MIN(%I) AS sort_key'
        '  FROM %I %s'
        '  GROUP BY bucket'
        ') t',
        array_to_string(v_case_lines, ' '),
        v_safe_field,
        v_safe_field,
        v_safe_table,
        v_where
    );

    EXECUTE v_sql INTO v_result;
    RETURN COALESCE(v_result, '[]'::JSONB);
END;
$$;


ALTER FUNCTION public.erp_distribution_query(p_org_id uuid, p_table text, p_doc_type text, p_start text, p_end text, p_field text, p_buckets numeric[], p_time_col text) OWNER TO everydayai;

--
-- Name: FUNCTION erp_distribution_query(p_org_id uuid, p_table text, p_doc_type text, p_start text, p_end text, p_field text, p_buckets numeric[], p_time_col text); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.erp_distribution_query(p_org_id uuid, p_table text, p_doc_type text, p_start text, p_end text, p_field text, p_buckets numeric[], p_time_col text) IS '分布分析 RPC — 按数值字段动态分桶，返回各区间计数和总量';


--
-- Name: erp_global_stats_query(character varying, timestamp with time zone, timestamp with time zone, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_shop character varying DEFAULT NULL::character varying, p_platform character varying DEFAULT NULL::character varying, p_supplier character varying DEFAULT NULL::character varying, p_warehouse character varying DEFAULT NULL::character varying, p_group_by character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
    base_q TEXT;
    group_col TEXT;
    name_col TEXT;
    need_archive BOOLEAN;
BEGIN
    -- 输入校验
    IF p_start > p_end THEN
        RETURN jsonb_build_object('error', 'p_start must <= p_end');
    END IF;

    -- 90天前数据可能已归档
    need_archive := (p_start < NOW() - INTERVAL '90 days');

    -- 基础查询（只取聚合需要的列）
    base_q := format(
        'SELECT doc_id, quantity, amount, outer_id, item_name,
                shop_name, platform, supplier_name, warehouse_name,
                doc_status, order_status
         FROM erp_document_items
         WHERE doc_type = %L AND doc_created_at >= %L AND doc_created_at < %L',
        p_doc_type, p_start, p_end
    );

    -- 归档表 UNION（仅查归档区间，避免与热表重叠）
    IF need_archive THEN
        base_q := base_q || format(
            ' UNION ALL
             SELECT doc_id, quantity, amount, outer_id, item_name,
                    shop_name, platform, supplier_name, warehouse_name,
                    doc_status, order_status
             FROM erp_document_items_archive
             WHERE doc_type = %L AND doc_created_at >= %L AND doc_created_at < %L',
            p_doc_type, p_start, LEAST(p_end, NOW() - INTERVAL '90 days')
        );
    END IF;

    -- 可选筛选条件
    base_q := 'SELECT * FROM (' || base_q || ') AS raw WHERE 1=1';
    IF p_shop IS NOT NULL THEN
        base_q := base_q || format(' AND shop_name ILIKE %L', '%%' || p_shop || '%%');
    END IF;
    IF p_platform IS NOT NULL THEN
        base_q := base_q || format(' AND platform = %L', p_platform);
    END IF;
    IF p_supplier IS NOT NULL THEN
        base_q := base_q || format(' AND supplier_name ILIKE %L', '%%' || p_supplier || '%%');
    END IF;
    IF p_warehouse IS NOT NULL THEN
        base_q := base_q || format(' AND warehouse_name ILIKE %L', '%%' || p_warehouse || '%%');
    END IF;

    IF p_group_by IS NULL THEN
        -- 总计模式
        EXECUTE format(
            'SELECT jsonb_build_object(
                ''doc_count'', COUNT(DISTINCT doc_id),
                ''total_qty'', COALESCE(SUM(quantity), 0),
                ''total_amount'', COALESCE(SUM(amount), 0)
            ) FROM (%s) sub', base_q
        ) INTO result;
    ELSE
        -- 分组模式
        group_col := CASE p_group_by
            WHEN 'product' THEN 'outer_id'
            WHEN 'shop' THEN 'shop_name'
            WHEN 'platform' THEN 'platform'
            WHEN 'supplier' THEN 'supplier_name'
            WHEN 'warehouse' THEN 'warehouse_name'
            WHEN 'status' THEN 'COALESCE(doc_status, order_status)'
            ELSE 'doc_type'
        END;
        name_col := CASE p_group_by
            WHEN 'product' THEN ', MAX(item_name) as item_name'
            ELSE ''
        END;

        -- status 分组特殊处理（表达式不能用 %I）
        IF p_group_by = 'status' THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT COALESCE(doc_status, order_status, ''未知'') as group_key,
                           COUNT(DISTINCT doc_id) as doc_count,
                           COALESCE(SUM(quantity), 0) as total_qty,
                           COALESCE(SUM(amount), 0) as total_amount
                    FROM (%s) sub
                    GROUP BY COALESCE(doc_status, order_status, ''未知'')
                    ORDER BY COUNT(DISTINCT doc_id) DESC
                    LIMIT %s
                 ) t',
                base_q, p_limit
            ) INTO result;
        ELSE
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT %I as group_key %s,
                           COUNT(DISTINCT doc_id) as doc_count,
                           COALESCE(SUM(quantity), 0) as total_qty,
                           COALESCE(SUM(amount), 0) as total_amount
                    FROM (%s) sub
                    WHERE %I IS NOT NULL
                    GROUP BY %I
                    ORDER BY COALESCE(SUM(amount), 0) DESC
                    LIMIT %s
                 ) t',
                group_col, name_col, base_q, group_col, group_col, p_limit
            ) INTO result;
        END IF;
    END IF;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer) OWNER TO everydayai;

--
-- Name: erp_global_stats_query(character varying, timestamp with time zone, timestamp with time zone, character varying, character varying, character varying, character varying, character varying, integer, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_shop character varying DEFAULT NULL::character varying, p_platform character varying DEFAULT NULL::character varying, p_supplier character varying DEFAULT NULL::character varying, p_warehouse character varying DEFAULT NULL::character varying, p_group_by character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 20, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
    base_q TEXT;
    group_col TEXT;
    name_col TEXT;
    need_archive BOOLEAN;
    org_filter TEXT;
BEGIN
    IF p_start > p_end THEN
        RETURN jsonb_build_object('error', 'p_start must <= p_end');
    END IF;

    need_archive := (p_start < NOW() - INTERVAL '90 days');

    -- org_id 过滤条件
    IF p_org_id IS NOT NULL THEN
        org_filter := format(' AND org_id = %L', p_org_id);
    ELSE
        org_filter := ' AND org_id IS NULL';
    END IF;

    base_q := format(
        'SELECT doc_id, quantity, amount, outer_id, item_name,
                shop_name, platform, supplier_name, warehouse_name,
                doc_status, order_status
         FROM erp_document_items
         WHERE doc_type = %L AND doc_created_at >= %L AND doc_created_at < %L',
        p_doc_type, p_start, p_end
    ) || org_filter;

    IF need_archive THEN
        base_q := base_q || format(
            ' UNION ALL
             SELECT doc_id, quantity, amount, outer_id, item_name,
                    shop_name, platform, supplier_name, warehouse_name,
                    doc_status, order_status
             FROM erp_document_items_archive
             WHERE doc_type = %L AND doc_created_at >= %L AND doc_created_at < %L',
            p_doc_type, p_start, LEAST(p_end, NOW() - INTERVAL '90 days')
        ) || org_filter;
    END IF;

    base_q := 'SELECT * FROM (' || base_q || ') AS raw WHERE 1=1';
    IF p_shop IS NOT NULL THEN
        base_q := base_q || format(' AND shop_name ILIKE %L', '%%' || p_shop || '%%');
    END IF;
    IF p_platform IS NOT NULL THEN
        base_q := base_q || format(' AND platform = %L', p_platform);
    END IF;
    IF p_supplier IS NOT NULL THEN
        base_q := base_q || format(' AND supplier_name ILIKE %L', '%%' || p_supplier || '%%');
    END IF;
    IF p_warehouse IS NOT NULL THEN
        base_q := base_q || format(' AND warehouse_name ILIKE %L', '%%' || p_warehouse || '%%');
    END IF;

    IF p_group_by IS NULL THEN
        EXECUTE format(
            'SELECT jsonb_build_object(
                ''doc_count'', COUNT(DISTINCT doc_id),
                ''total_qty'', COALESCE(SUM(quantity), 0),
                ''total_amount'', COALESCE(SUM(amount), 0)
            ) FROM (%s) sub', base_q
        ) INTO result;
    ELSE
        group_col := CASE p_group_by
            WHEN 'product' THEN 'outer_id'
            WHEN 'shop' THEN 'shop_name'
            WHEN 'platform' THEN 'platform'
            WHEN 'supplier' THEN 'supplier_name'
            WHEN 'warehouse' THEN 'warehouse_name'
            WHEN 'status' THEN 'COALESCE(doc_status, order_status)'
            ELSE 'doc_type'
        END;
        name_col := CASE p_group_by
            WHEN 'product' THEN ', MAX(item_name) as item_name'
            ELSE ''
        END;

        IF p_group_by = 'status' THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT COALESCE(doc_status, order_status, ''未知'') as group_key,
                           COUNT(DISTINCT doc_id) as doc_count,
                           COALESCE(SUM(quantity), 0) as total_qty,
                           COALESCE(SUM(amount), 0) as total_amount
                    FROM (%s) sub
                    GROUP BY COALESCE(doc_status, order_status, ''未知'')
                    ORDER BY COUNT(DISTINCT doc_id) DESC
                    LIMIT %s
                 ) t',
                base_q, p_limit
            ) INTO result;
        ELSE
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT %I as group_key %s,
                           COUNT(DISTINCT doc_id) as doc_count,
                           COALESCE(SUM(quantity), 0) as total_qty,
                           COALESCE(SUM(amount), 0) as total_amount
                    FROM (%s) sub
                    WHERE %I IS NOT NULL
                    GROUP BY %I
                    ORDER BY COALESCE(SUM(amount), 0) DESC
                    LIMIT %s
                 ) t',
                group_col, name_col, base_q, group_col, group_col, p_limit
            ) INTO result;
        END IF;
    END IF;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer, p_org_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer, p_org_id uuid) IS 'ERP全局统计RPC（多租户），p_org_id 必传';


--
-- Name: erp_global_stats_query(character varying, timestamp with time zone, timestamp with time zone, character varying, character varying, character varying, character varying, character varying, character varying, integer, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying DEFAULT 'doc_created_at'::character varying, p_shop character varying DEFAULT NULL::character varying, p_platform character varying DEFAULT NULL::character varying, p_supplier character varying DEFAULT NULL::character varying, p_warehouse character varying DEFAULT NULL::character varying, p_group_by character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 20, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
    base_q TEXT;
    group_col TEXT;
    name_col TEXT;
    need_archive BOOLEAN;
    org_filter TEXT;
    time_col TEXT;
BEGIN
    IF p_start > p_end THEN
        RETURN jsonb_build_object('error', 'p_start must <= p_end');
    END IF;

    -- 白名单校验时间字段（防 SQL 注入）
    IF p_time_col IN ('doc_created_at', 'pay_time', 'consign_time') THEN
        time_col := p_time_col;
    ELSE
        time_col := 'doc_created_at';
    END IF;

    need_archive := (p_start < NOW() - INTERVAL '90 days');

    -- org_id 过滤条件
    IF p_org_id IS NOT NULL THEN
        org_filter := format(' AND org_id = %L', p_org_id);
    ELSE
        org_filter := ' AND org_id IS NULL';
    END IF;

    base_q := format(
        'SELECT doc_id, quantity, amount, outer_id, item_name,
                shop_name, platform, supplier_name, warehouse_name,
                doc_status, order_status
         FROM erp_document_items
         WHERE doc_type = %L AND %I >= %L AND %I < %L',
        p_doc_type, time_col, p_start, time_col, p_end
    ) || org_filter;

    IF need_archive THEN
        base_q := base_q || format(
            ' UNION ALL
             SELECT doc_id, quantity, amount, outer_id, item_name,
                    shop_name, platform, supplier_name, warehouse_name,
                    doc_status, order_status
             FROM erp_document_items_archive
             WHERE doc_type = %L AND %I >= %L AND %I < %L',
            p_doc_type, time_col, p_start, time_col, LEAST(p_end, NOW() - INTERVAL '90 days')
        ) || org_filter;
    END IF;

    base_q := 'SELECT * FROM (' || base_q || ') AS raw WHERE 1=1';
    IF p_shop IS NOT NULL THEN
        base_q := base_q || format(' AND shop_name ILIKE %L', '%%' || p_shop || '%%');
    END IF;
    IF p_platform IS NOT NULL THEN
        base_q := base_q || format(' AND platform = %L', p_platform);
    END IF;
    IF p_supplier IS NOT NULL THEN
        base_q := base_q || format(' AND supplier_name ILIKE %L', '%%' || p_supplier || '%%');
    END IF;
    IF p_warehouse IS NOT NULL THEN
        base_q := base_q || format(' AND warehouse_name ILIKE %L', '%%' || p_warehouse || '%%');
    END IF;

    IF p_group_by IS NULL THEN
        EXECUTE format(
            'SELECT jsonb_build_object(
                ''doc_count'', COUNT(DISTINCT doc_id),
                ''total_qty'', COALESCE(SUM(quantity), 0),
                ''total_amount'', COALESCE(SUM(amount), 0)
            ) FROM (%s) sub', base_q
        ) INTO result;
    ELSIF p_group_by = 'shop' THEN
        -- 店铺分组：按 shop_name + platform 联合分组，避免跨平台同名合并
        EXECUTE format(
            'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
             FROM (
                SELECT shop_name as group_key, platform,
                       COUNT(DISTINCT doc_id) as doc_count,
                       COALESCE(SUM(quantity), 0) as total_qty,
                       COALESCE(SUM(amount), 0) as total_amount
                FROM (%s) sub
                WHERE shop_name IS NOT NULL
                GROUP BY shop_name, platform
                ORDER BY COALESCE(SUM(amount), 0) DESC
                LIMIT %s
             ) t',
            base_q, p_limit
        ) INTO result;
    ELSIF p_group_by = 'status' THEN
        EXECUTE format(
            'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
             FROM (
                SELECT COALESCE(doc_status, order_status, ''未知'') as group_key,
                       COUNT(DISTINCT doc_id) as doc_count,
                       COALESCE(SUM(quantity), 0) as total_qty,
                       COALESCE(SUM(amount), 0) as total_amount
                FROM (%s) sub
                GROUP BY COALESCE(doc_status, order_status, ''未知'')
                ORDER BY COUNT(DISTINCT doc_id) DESC
                LIMIT %s
             ) t',
            base_q, p_limit
        ) INTO result;
    ELSE
        group_col := CASE p_group_by
            WHEN 'product' THEN 'outer_id'
            WHEN 'platform' THEN 'platform'
            WHEN 'supplier' THEN 'supplier_name'
            WHEN 'warehouse' THEN 'warehouse_name'
            ELSE 'doc_type'
        END;
        name_col := CASE p_group_by
            WHEN 'product' THEN ', MAX(item_name) as item_name'
            ELSE ''
        END;

        EXECUTE format(
            'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
             FROM (
                SELECT %I as group_key %s,
                       COUNT(DISTINCT doc_id) as doc_count,
                       COALESCE(SUM(quantity), 0) as total_qty,
                       COALESCE(SUM(amount), 0) as total_amount
                FROM (%s) sub
                WHERE %I IS NOT NULL
                GROUP BY %I
                ORDER BY COALESCE(SUM(amount), 0) DESC
                LIMIT %s
             ) t',
            group_col, name_col, base_q, group_col, group_col, p_limit
        ) INTO result;
    END IF;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


