--
-- Name: FUNCTION erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer, p_org_id uuid) IS 'ERP全局统计RPC（多租户），group_by=shop 按 shop_name+platform 联合分组';


--
-- Name: erp_global_stats_query(character varying, timestamp with time zone, timestamp with time zone, character varying, character varying, character varying, character varying, character varying, character varying, integer, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying DEFAULT 'doc_created_at'::character varying, p_shop character varying DEFAULT NULL::character varying, p_platform character varying DEFAULT NULL::character varying, p_supplier character varying DEFAULT NULL::character varying, p_warehouse character varying DEFAULT NULL::character varying, p_group_by character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 20, p_org_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
    base_q TEXT;
    group_col TEXT;
    name_col TEXT;
    need_archive BOOLEAN;
    org_filter TEXT;
    time_col TEXT;
    i INT;
    f JSONB;
    field_name TEXT;
    op TEXT;
    val JSONB;
    val_text TEXT;
BEGIN
    IF p_start > p_end THEN
        RETURN jsonb_build_object('error', 'p_start must <= p_end');
    END IF;

    IF p_time_col IN ('doc_created_at', 'pay_time', 'consign_time',
                      'apply_date', 'delivery_date', 'finished_at') THEN
        time_col := p_time_col;
    ELSE
        time_col := 'doc_created_at';
    END IF;

    need_archive := (p_start < NOW() - INTERVAL '90 days');

    IF p_org_id IS NOT NULL THEN
        org_filter := format(' AND org_id = %L', p_org_id);
    ELSE
        org_filter := ' AND org_id IS NULL';
    END IF;

    base_q := format(
        'SELECT * FROM erp_document_items
         WHERE doc_type = %L AND %I >= %L AND %I < %L',
        p_doc_type, time_col, p_start, time_col, p_end
    ) || org_filter;

    IF need_archive THEN
        base_q := base_q || format(
            ' UNION ALL
             SELECT * FROM erp_document_items_archive
             WHERE doc_type = %L AND %I >= %L AND %I < %L',
            p_doc_type, time_col, p_start, time_col, LEAST(p_end, NOW() - INTERVAL '90 days')
        ) || org_filter;
    END IF;

    base_q := 'SELECT * FROM (' || base_q || ') AS raw WHERE 1=1';

    IF p_shop IS NOT NULL THEN
        base_q := base_q || format(' AND shop_name ILIKE %L', '%%' || p_shop || '%%');
    END IF;
    IF p_platform IS NOT NULL THEN
        base_q := base_q || format(' AND platform = %L', p_platform);
    END IF;
    IF p_supplier IS NOT NULL THEN
        base_q := base_q || format(' AND supplier_name ILIKE %L', '%%' || p_supplier || '%%');
    END IF;
    IF p_warehouse IS NOT NULL THEN
        base_q := base_q || format(' AND warehouse_name ILIKE %L', '%%' || p_warehouse || '%%');
    END IF;

    -- Filter DSL 解析（与 104 完全一致）
    IF p_filters IS NOT NULL AND jsonb_typeof(p_filters) = 'array' THEN
        FOR i IN 0..jsonb_array_length(p_filters) - 1 LOOP
            f := p_filters->i;
            field_name := f->>'field';
            op := f->>'op';
            val := f->'value';
            val_text := val#>>'{}';

            CASE op
                WHEN 'eq' THEN
                    base_q := base_q || format(' AND %I = %L', field_name, val_text);
                WHEN 'ne' THEN
                    base_q := base_q || format(' AND %I != %L', field_name, val_text);
                WHEN 'gt' THEN
                    base_q := base_q || format(' AND %I > %L', field_name, val_text);
                WHEN 'gte' THEN
                    base_q := base_q || format(' AND %I >= %L', field_name, val_text);
                WHEN 'lt' THEN
                    base_q := base_q || format(' AND %I < %L', field_name, val_text);
                WHEN 'lte' THEN
                    base_q := base_q || format(' AND %I <= %L', field_name, val_text);
                WHEN 'like' THEN
                    base_q := base_q || format(' AND %I ILIKE %L', field_name, val_text);
                WHEN 'not_like' THEN
                    base_q := base_q || format(' AND %I NOT ILIKE %L', field_name, val_text);
                WHEN 'in' THEN
                    IF jsonb_typeof(val) = 'array' AND jsonb_array_length(val) > 0 THEN
                        base_q := base_q || format(
                            ' AND %I IN (SELECT jsonb_array_elements_text(%L::jsonb))',
                            field_name, val::text
                        );
                    END IF;
                WHEN 'not_in' THEN
                    IF jsonb_typeof(val) = 'array' AND jsonb_array_length(val) > 0 THEN
                        base_q := base_q || format(
                            ' AND %I NOT IN (SELECT jsonb_array_elements_text(%L::jsonb))',
                            field_name, val::text
                        );
                    END IF;
                WHEN 'is_null' THEN
                    IF val_text = 'true' OR val_text = '1' THEN
                        base_q := base_q || format(' AND %I IS NULL', field_name);
                    ELSE
                        base_q := base_q || format(' AND %I IS NOT NULL', field_name);
                    END IF;
                WHEN 'between' THEN
                    IF jsonb_typeof(val) = 'array' AND jsonb_array_length(val) = 2 THEN
                        base_q := base_q || format(' AND %I BETWEEN %L AND %L',
                            field_name, val->>0, val->>1);
                    END IF;
                ELSE
                    NULL;
            END CASE;
        END LOOP;
    END IF;

    -- ── 聚合逻辑（106 扩展：新增 avg/min/max/distinct_buyer/cost/profit）──

    IF p_group_by IS NULL THEN
        EXECUTE format(
            'SELECT jsonb_build_object(
                ''doc_count'', COUNT(DISTINCT doc_id),
                ''total_qty'', COALESCE(SUM(quantity), 0),
                ''total_amount'', COALESCE(SUM(amount), 0),
                ''avg_amount'', ROUND(COALESCE(AVG(amount), 0)::numeric, 2),
                ''min_amount'', COALESCE(MIN(amount), 0),
                ''max_amount'', COALESCE(MAX(amount), 0),
                ''distinct_buyer'', COUNT(DISTINCT CASE WHEN buyer_nick IS NOT NULL AND buyer_nick != '''' THEN buyer_nick END),
                ''total_cost'', COALESCE(SUM(cost), 0),
                ''total_profit'', COALESCE(SUM(gross_profit), 0)
            ) FROM (%s) sub', base_q
        ) INTO result;
    ELSE
        -- 106: 每个分组分支新增扩展聚合列
        IF p_group_by = 'status' THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT COALESCE(doc_status, order_status, ''未知'') as group_key,
                           COUNT(DISTINCT doc_id) as doc_count,
                           COALESCE(SUM(quantity), 0) as total_qty,
                           COALESCE(SUM(amount), 0) as total_amount,
                           ROUND(COALESCE(AVG(amount), 0)::numeric, 2) as avg_amount,
                           COALESCE(MIN(amount), 0) as min_amount,
                           COALESCE(MAX(amount), 0) as max_amount,
                           COUNT(DISTINCT CASE WHEN buyer_nick IS NOT NULL AND buyer_nick != '''' THEN buyer_nick END) as distinct_buyer,
                           COALESCE(SUM(cost), 0) as total_cost,
                           COALESCE(SUM(gross_profit), 0) as total_profit
                    FROM (%s) sub
                    GROUP BY COALESCE(doc_status, order_status, ''未知'')
                    ORDER BY COALESCE(SUM(amount), 0) DESC
                    LIMIT %s
                 ) t',
                base_q, p_limit
            ) INTO result;

        ELSIF p_group_by = 'product' THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT sub.outer_id as group_key,
                           COALESCE(MAX(sub.item_name), (SELECT ep.title FROM erp_products ep WHERE ep.outer_id = sub.outer_id AND ep.org_id' || COALESCE(' = ' || quote_literal(p_org_id), ' IS NULL') || ' LIMIT 1)) as item_name,
                           COUNT(DISTINCT sub.doc_id) as doc_count,
                           COALESCE(SUM(sub.quantity), 0) as total_qty,
                           COALESCE(SUM(sub.amount), 0) as total_amount,
                           ROUND(COALESCE(AVG(sub.amount), 0)::numeric, 2) as avg_amount,
                           COALESCE(MIN(sub.amount), 0) as min_amount,
                           COALESCE(MAX(sub.amount), 0) as max_amount,
                           COUNT(DISTINCT CASE WHEN sub.buyer_nick IS NOT NULL AND sub.buyer_nick != '''' THEN sub.buyer_nick END) as distinct_buyer,
                           COALESCE(SUM(sub.cost), 0) as total_cost,
                           COALESCE(SUM(sub.gross_profit), 0) as total_profit
                    FROM (%s) sub
                    WHERE sub.outer_id IS NOT NULL
                    GROUP BY sub.outer_id
                    ORDER BY COALESCE(SUM(sub.amount), 0) DESC
                    LIMIT %s
                 ) t',
                base_q, p_limit
            ) INTO result;

        ELSIF p_group_by = 'shop' THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT COALESCE(dim.name, sub.shop_name) as group_key,
                           COUNT(DISTINCT sub.doc_id) as doc_count,
                           COALESCE(SUM(sub.quantity), 0) as total_qty,
                           COALESCE(SUM(sub.amount), 0) as total_amount,
                           ROUND(COALESCE(AVG(sub.amount), 0)::numeric, 2) as avg_amount,
                           COALESCE(MIN(sub.amount), 0) as min_amount,
                           COALESCE(MAX(sub.amount), 0) as max_amount,
                           COUNT(DISTINCT CASE WHEN sub.buyer_nick IS NOT NULL AND sub.buyer_nick != '''' THEN sub.buyer_nick END) as distinct_buyer,
                           COALESCE(SUM(sub.cost), 0) as total_cost,
                           COALESCE(SUM(sub.gross_profit), 0) as total_profit
                    FROM (%s) sub
                    LEFT JOIN erp_shops dim ON sub.shop_user_id = dim.user_id
                        AND sub.org_id = dim.org_id
                    WHERE sub.shop_user_id IS NOT NULL OR sub.shop_name IS NOT NULL
                    GROUP BY COALESCE(dim.name, sub.shop_name)
                    ORDER BY COALESCE(SUM(sub.amount), 0) DESC
                    LIMIT %s
                 ) t',
                base_q, p_limit
            ) INTO result;

        ELSIF p_group_by = 'supplier' THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT COALESCE(dim.name, sub.supplier_name) as group_key,
                           COUNT(DISTINCT sub.doc_id) as doc_count,
                           COALESCE(SUM(sub.quantity), 0) as total_qty,
                           COALESCE(SUM(sub.amount), 0) as total_amount,
                           ROUND(COALESCE(AVG(sub.amount), 0)::numeric, 2) as avg_amount,
                           COALESCE(MIN(sub.amount), 0) as min_amount,
                           COALESCE(MAX(sub.amount), 0) as max_amount,
                           COUNT(DISTINCT CASE WHEN sub.buyer_nick IS NOT NULL AND sub.buyer_nick != '''' THEN sub.buyer_nick END) as distinct_buyer,
                           COALESCE(SUM(sub.cost), 0) as total_cost,
                           COALESCE(SUM(sub.gross_profit), 0) as total_profit
                    FROM (%s) sub
                    LEFT JOIN erp_suppliers dim ON sub.supplier_code = dim.code
                        AND sub.org_id = dim.org_id
                    WHERE sub.supplier_code IS NOT NULL OR sub.supplier_name IS NOT NULL
                    GROUP BY COALESCE(dim.name, sub.supplier_name)
                    ORDER BY COALESCE(SUM(sub.amount), 0) DESC
                    LIMIT %s
                 ) t',
                base_q, p_limit
            ) INTO result;

        ELSIF p_group_by = 'warehouse' THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT COALESCE(dim.name, sub.warehouse_name) as group_key,
                           COUNT(DISTINCT sub.doc_id) as doc_count,
                           COALESCE(SUM(sub.quantity), 0) as total_qty,
                           COALESCE(SUM(sub.amount), 0) as total_amount,
                           ROUND(COALESCE(AVG(sub.amount), 0)::numeric, 2) as avg_amount,
                           COALESCE(MIN(sub.amount), 0) as min_amount,
                           COALESCE(MAX(sub.amount), 0) as max_amount,
                           COUNT(DISTINCT CASE WHEN sub.buyer_nick IS NOT NULL AND sub.buyer_nick != '''' THEN sub.buyer_nick END) as distinct_buyer,
                           COALESCE(SUM(sub.cost), 0) as total_cost,
                           COALESCE(SUM(sub.gross_profit), 0) as total_profit
                    FROM (%s) sub
                    LEFT JOIN erp_warehouses dim ON sub.warehouse_id = dim.warehouse_id
                        AND sub.org_id = dim.org_id
                    WHERE sub.warehouse_id IS NOT NULL OR sub.warehouse_name IS NOT NULL
                    GROUP BY COALESCE(dim.name, sub.warehouse_name)
                    ORDER BY COALESCE(SUM(sub.amount), 0) DESC
                    LIMIT %s
                 ) t',
                base_q, p_limit
            ) INTO result;

        ELSE
            -- platform / doc_type 等：直接用字段值分组
            group_col := CASE p_group_by
                WHEN 'platform' THEN 'platform'
                ELSE 'doc_type'
            END;
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb)
                 FROM (
                    SELECT %I as group_key,
                           COUNT(DISTINCT doc_id) as doc_count,
                           COALESCE(SUM(quantity), 0) as total_qty,
                           COALESCE(SUM(amount), 0) as total_amount,
                           ROUND(COALESCE(AVG(amount), 0)::numeric, 2) as avg_amount,
                           COALESCE(MIN(amount), 0) as min_amount,
                           COALESCE(MAX(amount), 0) as max_amount,
                           COUNT(DISTINCT CASE WHEN buyer_nick IS NOT NULL AND buyer_nick != '''' THEN buyer_nick END) as distinct_buyer,
                           COALESCE(SUM(cost), 0) as total_cost,
                           COALESCE(SUM(gross_profit), 0) as total_profit
                    FROM (%s) sub
                    WHERE %I IS NOT NULL
                    GROUP BY %I
                    ORDER BY COALESCE(SUM(amount), 0) DESC
                    LIMIT %s
                 ) t',
                group_col, base_q, group_col, group_col, p_limit
            ) INTO result;
        END IF;
    END IF;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer, p_org_id uuid, p_filters jsonb) OWNER TO everydayai;

--
-- Name: FUNCTION erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer, p_org_id uuid, p_filters jsonb); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.erp_global_stats_query(p_doc_type character varying, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying, p_shop character varying, p_platform character varying, p_supplier character varying, p_warehouse character varying, p_group_by character varying, p_limit integer, p_org_id uuid, p_filters jsonb) IS 'ERP全局统计RPC — 106: 新增 AVG/MIN/MAX + distinct_buyer + cost/profit';


--
-- Name: erp_order_stats_grouped(uuid, timestamp with time zone, timestamp with time zone, character varying, jsonb, character varying); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_order_stats_grouped(p_org_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying DEFAULT 'pay_time'::character varying, p_filters jsonb DEFAULT NULL::jsonb, p_group_by character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    base_q TEXT;
    result JSONB;
    time_col TEXT;
    need_archive BOOLEAN;
    group_col TEXT;
    i INT;
    f JSONB;
    field_name TEXT;
    op TEXT;
    val JSONB;
    val_text TEXT;
BEGIN
    IF p_start > p_end THEN
        RETURN '[]'::jsonb;
    END IF;

    IF p_time_col IN ('doc_created_at', 'pay_time', 'consign_time') THEN
        time_col := p_time_col;
    ELSE
        time_col := 'pay_time';
    END IF;

    need_archive := (p_start < NOW() - INTERVAL '90 days');

    base_q := format(
        'SELECT doc_id, quantity, amount, outer_id, item_name, '
        'shop_name, shop_user_id, platform, supplier_name, supplier_code, '
        'warehouse_name, warehouse_id, '
        'doc_status, order_status, order_type, order_no, '
        'sku_outer_id, express_no, buyer_nick, status_name, '
        'cost, pay_amount, gross_profit, refund_money, '
        'post_fee, discount_fee, aftersale_type, refund_status, '
        'is_cancel, is_refund, is_exception, is_halt, is_urgent, '
        'is_scalping, unified_status, is_presell, '
        'online_status, handler_status, org_id '
        'FROM erp_document_items '
        'WHERE doc_type = ''order'' '
        'AND org_id = %L '
        'AND %I >= %L AND %I < %L',
        p_org_id, time_col, p_start, time_col, p_end
    );

    IF need_archive THEN
        base_q := base_q || format(
            ' UNION ALL '
            'SELECT doc_id, quantity, amount, outer_id, item_name, '
            'shop_name, shop_user_id, platform, supplier_name, supplier_code, '
            'warehouse_name, warehouse_id, '
            'doc_status, order_status, order_type, order_no, '
            'sku_outer_id, express_no, buyer_nick, status_name, '
            'cost, pay_amount, gross_profit, refund_money, '
            'post_fee, discount_fee, aftersale_type, refund_status, '
            'is_cancel, is_refund, is_exception, is_halt, is_urgent, '
            'is_scalping, unified_status, is_presell, '
            'online_status, handler_status, org_id '
            'FROM erp_document_items_archive '
            'WHERE doc_type = ''order'' '
            'AND org_id = %L '
            'AND %I >= %L AND %I < %L',
            p_org_id, time_col, p_start, time_col, LEAST(p_end, NOW() - INTERVAL '90 days')
        );
    END IF;

    base_q := 'SELECT * FROM (' || base_q || ') AS raw WHERE 1=1';

    -- ── Filter DSL 解析 ─────────────────────────────────────
    -- WHITELIST_SYNC: 必须与 base_q SELECT 列保持一致（减 doc_id/org_id）
    -- Python 端对照常量: erp_unified_schema.RPC_ORDER_STATS_FILTER_FIELDS
    IF p_filters IS NOT NULL AND jsonb_typeof(p_filters) = 'array' THEN
        FOR i IN 0..jsonb_array_length(p_filters) - 1 LOOP
            f := p_filters->i;
            field_name := f->>'field';
            op := f->>'op';
            val := f->'value';
            val_text := val#>>'{}';

            IF field_name NOT IN (
                -- 维度字段（101 新增 ★）
                'platform', 'shop_name', 'supplier_name', 'warehouse_name', 'item_name',
                -- 关联 ID（100 已有）
                'supplier_code', 'shop_user_id', 'warehouse_id',
                -- 文本字段
                'order_status', 'doc_status', 'status_name',
                'outer_id', 'sku_outer_id', 'order_no', 'express_no',
                'buyer_nick', 'order_type',
                'aftersale_type', 'refund_status',
                -- 数值字段
                'amount', 'quantity', 'cost', 'pay_amount',
                'gross_profit', 'refund_money', 'post_fee', 'discount_fee',
                -- 标记字段
                'is_cancel', 'is_refund', 'is_exception', 'is_halt', 'is_urgent',
                'is_scalping', 'unified_status', 'is_presell',
                'online_status', 'handler_status'
            ) THEN
                CONTINUE;
            END IF;

            CASE op
                WHEN 'eq' THEN
                    base_q := base_q || format(' AND %I = %L', field_name, val_text);
                WHEN 'ne' THEN
                    base_q := base_q || format(' AND %I != %L', field_name, val_text);
                WHEN 'gt' THEN
                    base_q := base_q || format(' AND %I > %L', field_name, val_text);
                WHEN 'gte' THEN
                    base_q := base_q || format(' AND %I >= %L', field_name, val_text);
                WHEN 'lt' THEN
                    base_q := base_q || format(' AND %I < %L', field_name, val_text);
                WHEN 'lte' THEN
                    base_q := base_q || format(' AND %I <= %L', field_name, val_text);
                WHEN 'like' THEN
                    base_q := base_q || format(' AND %I ILIKE %L', field_name, val_text);
                WHEN 'not_like' THEN
                    base_q := base_q || format(' AND %I NOT ILIKE %L', field_name, val_text);
                WHEN 'in' THEN
                    IF jsonb_typeof(val) = 'array' AND jsonb_array_length(val) > 0 THEN
                        base_q := base_q || format(
                            ' AND %I IN (SELECT jsonb_array_elements_text(%L::jsonb))',
                            field_name, val::text
                        );
                    END IF;
                WHEN 'not_in' THEN
                    IF jsonb_typeof(val) = 'array' AND jsonb_array_length(val) > 0 THEN
                        base_q := base_q || format(
                            ' AND %I NOT IN (SELECT jsonb_array_elements_text(%L::jsonb))',
                            field_name, val::text
                        );
                    END IF;
                WHEN 'is_null' THEN
                    IF val_text = 'true' OR val_text = '1' THEN
                        base_q := base_q || format(' AND %I IS NULL', field_name);
                    ELSE
                        base_q := base_q || format(' AND %I IS NOT NULL', field_name);
                    END IF;
                WHEN 'between' THEN
                    IF jsonb_typeof(val) = 'array' AND jsonb_array_length(val) = 2 THEN
                        base_q := base_q || format(
                            ' AND %I BETWEEN %L AND %L',
                            field_name, val->>0, val->>1
                        );
                    END IF;
                ELSE
                    NULL;
            END CASE;
        END LOOP;
    END IF;

    -- 聚合
    IF p_group_by IS NULL THEN
        EXECUTE format(
            'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) '
            'FROM ('
            '  SELECT order_type, order_status, is_scalping, '
            '         COUNT(DISTINCT doc_id) AS doc_count, '
            '         COALESCE(SUM(quantity), 0) AS total_qty, '
            '         COALESCE(SUM(amount), 0) AS total_amount '
            '  FROM (%s) sub '
            '  GROUP BY order_type, order_status, is_scalping'
            ') t',
            base_q
        ) INTO result;
    ELSE
        IF p_group_by = 'status' THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) '
                'FROM ('
                '  SELECT COALESCE(doc_status, order_status, ''未知'') AS group_key, '
                '         order_type, order_status, is_scalping, '
                '         COUNT(DISTINCT doc_id) AS doc_count, '
                '         COALESCE(SUM(quantity), 0) AS total_qty, '
                '         COALESCE(SUM(amount), 0) AS total_amount '
                '  FROM (%s) sub '
                '  GROUP BY COALESCE(doc_status, order_status, ''未知''), '
                '           order_type, order_status, is_scalping '
                '  ORDER BY COUNT(DISTINCT doc_id) DESC'
                ') t',
                base_q
            ) INTO result;

        ELSIF p_group_by = 'product' THEN
            -- 100: item_name 兜底 erp_products.title
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) '
                'FROM ('
                '  SELECT sub.outer_id AS group_key, '
                '         COALESCE(MAX(sub.item_name), (SELECT ep.title FROM erp_products ep WHERE ep.outer_id = sub.outer_id AND ep.org_id = %L LIMIT 1)) AS item_name, '
                '         order_type, order_status, is_scalping, '
                '         COUNT(DISTINCT sub.doc_id) AS doc_count, '
                '         COALESCE(SUM(sub.quantity), 0) AS total_qty, '
                '         COALESCE(SUM(sub.amount), 0) AS total_amount '
                '  FROM (%s) sub '
                '  WHERE sub.outer_id IS NOT NULL '
                '  GROUP BY sub.outer_id, order_type, order_status, is_scalping '
                '  ORDER BY COALESCE(SUM(sub.amount), 0) DESC'
                ') t',
                p_org_id, base_q
            ) INTO result;

        ELSIF p_group_by = 'shop' THEN
            -- 100: shop_user_id + LEFT JOIN erp_shops
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) '
                'FROM ('
                '  SELECT COALESCE(dim.name, sub.shop_name) AS group_key, '
                '         order_type, order_status, is_scalping, '
                '         COUNT(DISTINCT sub.doc_id) AS doc_count, '
                '         COALESCE(SUM(sub.quantity), 0) AS total_qty, '
                '         COALESCE(SUM(sub.amount), 0) AS total_amount '
                '  FROM (%s) sub '
                '  LEFT JOIN erp_shops dim ON sub.shop_user_id = dim.user_id AND sub.org_id = dim.org_id '
                '  WHERE sub.shop_user_id IS NOT NULL OR sub.shop_name IS NOT NULL '
                '  GROUP BY COALESCE(dim.name, sub.shop_name), order_type, order_status, is_scalping '
                '  ORDER BY COALESCE(SUM(sub.amount), 0) DESC'
                ') t',
                base_q
            ) INTO result;

        ELSIF p_group_by = 'supplier' THEN
            -- 100: supplier_code + LEFT JOIN erp_suppliers
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) '
                'FROM ('
                '  SELECT COALESCE(dim.name, sub.supplier_name) AS group_key, '
                '         order_type, order_status, is_scalping, '
                '         COUNT(DISTINCT sub.doc_id) AS doc_count, '
                '         COALESCE(SUM(sub.quantity), 0) AS total_qty, '
                '         COALESCE(SUM(sub.amount), 0) AS total_amount '
                '  FROM (%s) sub '
                '  LEFT JOIN erp_suppliers dim ON sub.supplier_code = dim.code AND sub.org_id = dim.org_id '
                '  WHERE sub.supplier_code IS NOT NULL OR sub.supplier_name IS NOT NULL '
                '  GROUP BY COALESCE(dim.name, sub.supplier_name), order_type, order_status, is_scalping '
                '  ORDER BY COALESCE(SUM(sub.amount), 0) DESC'
                ') t',
                base_q
            ) INTO result;

        ELSIF p_group_by = 'warehouse' THEN
            -- 100: warehouse_id + LEFT JOIN erp_warehouses
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) '
                'FROM ('
                '  SELECT COALESCE(dim.name, sub.warehouse_name) AS group_key, '
                '         order_type, order_status, is_scalping, '
                '         COUNT(DISTINCT sub.doc_id) AS doc_count, '
                '         COALESCE(SUM(sub.quantity), 0) AS total_qty, '
                '         COALESCE(SUM(sub.amount), 0) AS total_amount '
                '  FROM (%s) sub '
                '  LEFT JOIN erp_warehouses dim ON sub.warehouse_id = dim.warehouse_id AND sub.org_id = dim.org_id '
                '  WHERE sub.warehouse_id IS NOT NULL OR sub.warehouse_name IS NOT NULL '
                '  GROUP BY COALESCE(dim.name, sub.warehouse_name), order_type, order_status, is_scalping '
                '  ORDER BY COALESCE(SUM(sub.amount), 0) DESC'
                ') t',
                base_q
            ) INTO result;

        ELSE
            -- platform 等：直接用字段值分组
            group_col := CASE p_group_by
                WHEN 'platform' THEN 'platform'
                ELSE p_group_by
            END;
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) '
                'FROM ('
                '  SELECT %I AS group_key, '
                '         order_type, order_status, is_scalping, '
                '         COUNT(DISTINCT doc_id) AS doc_count, '
                '         COALESCE(SUM(quantity), 0) AS total_qty, '
                '         COALESCE(SUM(amount), 0) AS total_amount '
                '  FROM (%s) sub '
                '  WHERE %I IS NOT NULL '
                '  GROUP BY %I, order_type, order_status, is_scalping '
                '  ORDER BY COALESCE(SUM(amount), 0) DESC'
                ') t',
                group_col, base_q, group_col, group_col
            ) INTO result;
        END IF;
    END IF;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.erp_order_stats_grouped(p_org_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying, p_filters jsonb, p_group_by character varying) OWNER TO everydayai;

--
-- Name: FUNCTION erp_order_stats_grouped(p_org_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying, p_filters jsonb, p_group_by character varying); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.erp_order_stats_grouped(p_org_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_time_col character varying, p_filters jsonb, p_group_by character varying) IS '订单分类统计RPC — 104: 新增 not_in 操作符';


--
-- Name: erp_repurchase_rate_query(uuid, timestamp with time zone, timestamp with time zone, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_repurchase_rate_query(p_org_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_group_by text DEFAULT NULL::text, p_platform text DEFAULT NULL::text, p_shop_name text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_group_col    TEXT;
    v_grp_select   TEXT := '';
    v_grp_inner    TEXT := '';
    v_grp_outer    TEXT := '';
    v_where        TEXT := '';
    v_from         TEXT;
    v_sql          TEXT;
    v_result       JSONB;
    v_need_archive BOOLEAN;
BEGIN
    -- 分组列
    IF p_group_by IS NOT NULL THEN
        v_group_col := CASE p_group_by
            WHEN 'platform'  THEN 'platform'
            WHEN 'shop_name' THEN 'shop_name'
            ELSE NULL
        END;
        IF v_group_col IS NOT NULL THEN
            v_grp_select := v_group_col || ' AS group_key, ';
            v_grp_inner  := ', ' || v_group_col;
            v_grp_outer  := 'GROUP BY ' || v_group_col;
        END IF;
    END IF;

    -- 额外过滤
    IF p_platform IS NOT NULL THEN
        v_where := v_where || format(' AND platform = %L', p_platform);
    END IF;
    IF p_shop_name IS NOT NULL THEN
        v_where := v_where || format(' AND shop_name ILIKE %L', '%' || p_shop_name || '%');
    END IF;

    -- 是否需要归档表（起始时间 > 90 天前）
    v_need_archive := p_start < (CURRENT_TIMESTAMP - INTERVAL '90 days');

    -- FROM 子句（主表 + 可选归档表）
    IF v_need_archive THEN
        v_from := format(
            '(SELECT buyer_nick, doc_id %s FROM erp_document_items'
            '   WHERE doc_type = ''order'' AND org_id = %L'
            '     AND doc_created_at >= %L AND doc_created_at < %L'
            '     AND buyer_nick IS NOT NULL AND buyer_nick != '''''
            '     %s'
            ' UNION ALL'
            ' SELECT buyer_nick, doc_id %s FROM erp_document_items_archive'
            '   WHERE doc_type = ''order'' AND org_id = %L'
            '     AND doc_created_at >= %L AND doc_created_at < %L'
            '     AND buyer_nick IS NOT NULL AND buyer_nick != '''''
            '     %s'
            ') combined',
            v_grp_inner, p_org_id, p_start, p_end, v_where,
            v_grp_inner, p_org_id, p_start, p_end, v_where
        );
    ELSE
        v_from := format(
            'erp_document_items'
            ' WHERE doc_type = ''order'' AND org_id = %L'
            '   AND doc_created_at >= %L AND doc_created_at < %L'
            '   AND buyer_nick IS NOT NULL AND buyer_nick != '''''
            '   %s',
            p_org_id, p_start, p_end, v_where
        );
        -- 非归档：需要把 WHERE 从 FROM 里提出来给子查询
        -- 重新组织：用子查询统一写法
        v_from := format(
            '(SELECT buyer_nick, doc_id %s FROM erp_document_items'
            '   WHERE doc_type = ''order'' AND org_id = %L'
            '     AND doc_created_at >= %L AND doc_created_at < %L'
            '     AND buyer_nick IS NOT NULL AND buyer_nick != '''''
            '     %s'
            ') combined',
            v_grp_inner, p_org_id, p_start, p_end, v_where
        );
    END IF;

    v_sql := format(
        'SELECT jsonb_agg(row_to_json(t)) FROM ('
        '  SELECT'
        '    %s'
        '    ROUND('
        '      COUNT(DISTINCT CASE WHEN cnt >= 2 THEN buyer_nick END)::numeric /'
        '      NULLIF(COUNT(DISTINCT buyer_nick), 0) * 100, 2'
        '    ) AS metric_value,'
        '    COUNT(DISTINCT buyer_nick) AS total_buyers,'
        '    COUNT(DISTINCT CASE WHEN cnt >= 2 THEN buyer_nick END) AS repeat_buyers'
        '  FROM ('
        '    SELECT buyer_nick %s, COUNT(DISTINCT doc_id) AS cnt'
        '    FROM %s'
        '    GROUP BY buyer_nick %s'
        '  ) sub'
        '  %s'
        '  ORDER BY metric_value DESC NULLS LAST'
        '  LIMIT %s'
        ') t',
        v_grp_select,
        v_grp_inner,
        v_from,
        v_grp_inner,
        v_grp_outer,
        p_limit
    );

    EXECUTE v_sql INTO v_result;
    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.erp_repurchase_rate_query(p_org_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_group_by text, p_platform text, p_shop_name text, p_limit integer) OWNER TO everydayai;

--
-- Name: erp_ship_time_query(uuid, timestamp with time zone, timestamp with time zone, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_ship_time_query(p_org_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_group_by text DEFAULT NULL::text, p_platform text DEFAULT NULL::text, p_shop_name text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_group_col  TEXT;
    v_grp_select TEXT := '';
    v_grp_clause TEXT := '';
    v_where      TEXT := '';
    v_from       TEXT;
    v_sql        TEXT;
    v_result     JSONB;
    v_need_archive BOOLEAN;
BEGIN
    -- 分组列
    IF p_group_by IS NOT NULL THEN
        v_group_col := CASE p_group_by
            WHEN 'platform'  THEN 'platform'
            WHEN 'shop_name' THEN 'shop_name'
            ELSE NULL
        END;
        IF v_group_col IS NOT NULL THEN
            v_grp_select := v_group_col || ' AS group_key, ';
            v_grp_clause := 'GROUP BY ' || v_group_col;
        END IF;
    END IF;

    -- 额外过滤
    IF p_platform IS NOT NULL THEN
        v_where := v_where || format(' AND platform = %L', p_platform);
    END IF;
    IF p_shop_name IS NOT NULL THEN
        v_where := v_where || format(' AND shop_name ILIKE %L', '%' || p_shop_name || '%');
    END IF;

    -- 归档表判断
    v_need_archive := p_start < (CURRENT_TIMESTAMP - INTERVAL '90 days');

    -- 基础 WHERE 条件（主表或 UNION ALL）
    IF v_need_archive THEN
        v_from := format(
            '(SELECT pay_time, consign_time %s FROM erp_document_items'
            '   WHERE doc_type = ''order'' AND org_id = %L'
            '     AND doc_created_at >= %L AND doc_created_at < %L'
            '     AND pay_time IS NOT NULL AND consign_time IS NOT NULL'
            '     AND consign_time > pay_time'
            '     %s'
            ' UNION ALL'
            ' SELECT pay_time, consign_time %s FROM erp_document_items_archive'
            '   WHERE doc_type = ''order'' AND org_id = %L'
            '     AND doc_created_at >= %L AND doc_created_at < %L'
            '     AND pay_time IS NOT NULL AND consign_time IS NOT NULL'
            '     AND consign_time > pay_time'
            '     %s'
            ') combined',
            CASE WHEN v_group_col IS NOT NULL THEN ', ' || v_group_col ELSE '' END,
            p_org_id, p_start, p_end, v_where,
            CASE WHEN v_group_col IS NOT NULL THEN ', ' || v_group_col ELSE '' END,
            p_org_id, p_start, p_end, v_where
        );
    ELSE
        v_from := format(
            '(SELECT pay_time, consign_time %s FROM erp_document_items'
            '   WHERE doc_type = ''order'' AND org_id = %L'
            '     AND doc_created_at >= %L AND doc_created_at < %L'
            '     AND pay_time IS NOT NULL AND consign_time IS NOT NULL'
            '     AND consign_time > pay_time'
            '     %s'
            ') combined',
            CASE WHEN v_group_col IS NOT NULL THEN ', ' || v_group_col ELSE '' END,
            p_org_id, p_start, p_end, v_where
        );
    END IF;

    v_sql := format(
        'SELECT jsonb_agg(row_to_json(t)) FROM ('
        '  SELECT'
        '    %s'
        '    ROUND(AVG(EXTRACT(EPOCH FROM (consign_time - pay_time)) / 3600)::numeric, 1)'
        '      AS avg_ship_hours,'
        '    ROUND('
        '      COUNT(CASE WHEN consign_time - pay_time < INTERVAL ''24 hours'' THEN 1 END)::numeric /'
        '      NULLIF(COUNT(*), 0) * 100, 2'
        '    ) AS same_day_rate,'
        '    COUNT(*) AS total_shipped'
        '  FROM %s'
        '  %s'
        '  ORDER BY avg_ship_hours ASC NULLS LAST'
        '  LIMIT %s'
        ') t',
        v_grp_select,
        v_from,
        v_grp_clause,
        p_limit
    );

    EXECUTE v_sql INTO v_result;
    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.erp_ship_time_query(p_org_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_group_by text, p_platform text, p_shop_name text, p_limit integer) OWNER TO everydayai;

--
-- Name: erp_trend_query(uuid, date, date, text, text[], text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_trend_query(p_org_id uuid, p_start date, p_end date, p_granularity text DEFAULT 'day'::text, p_metrics text[] DEFAULT '{order_count,order_amount}'::text[], p_group_by text DEFAULT NULL::text, p_outer_id text DEFAULT NULL::text, p_platform text DEFAULT NULL::text, p_shop_name text DEFAULT NULL::text, p_limit integer DEFAULT 366) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_date_expr   TEXT;
    v_select_cols TEXT;
    v_where_extra TEXT := '';
    v_group_extra TEXT := '';
    v_group_sel   TEXT := '';
    v_result      JSONB;
    v_metric      TEXT;
    v_parts       TEXT[] := '{}';
    -- 白名单：允许的指标列（防止 SQL 注入）
    v_allowed     TEXT[] := ARRAY[
        'order_count', 'order_qty', 'order_amount', 'order_cost',
        'order_shipped_count', 'order_finished_count',
        'order_refund_count', 'order_cancelled_count',
        'aftersale_count', 'aftersale_refund_count',
        'aftersale_return_count', 'aftersale_exchange_count',
        'aftersale_reissue_count', 'aftersale_reject_count',
        'aftersale_repair_count', 'aftersale_other_count',
        'aftersale_qty', 'aftersale_amount',
        'purchase_count', 'purchase_qty',
        'purchase_received_qty', 'purchase_amount',
        'receipt_count', 'receipt_qty',
        'shelf_count', 'shelf_qty',
        'purchase_return_count', 'purchase_return_qty', 'purchase_return_amount'
    ];
BEGIN
    -- 参数校验
    IF p_start > p_end THEN
        RETURN jsonb_build_object('error', 'p_start must <= p_end');
    END IF;

    -- 时间分桶表达式
    v_date_expr := CASE p_granularity
        WHEN 'day'   THEN 'stat_date'
        WHEN 'week'  THEN 'date_trunc(''week'', stat_date)::date'
        WHEN 'month' THEN 'date_trunc(''month'', stat_date)::date'
        ELSE 'stat_date'  -- 未知粒度降级为 day
    END;

    -- 动态构建 SELECT 列（只返回用户要的 metrics，白名单校验）
    FOREACH v_metric IN ARRAY p_metrics LOOP
        IF v_metric = ANY(v_allowed) THEN
            v_parts := array_append(v_parts,
                format('COALESCE(SUM(%I), 0) AS %I', v_metric, v_metric));
        END IF;
    END LOOP;

    -- 至少保留一个指标
    IF array_length(v_parts, 1) IS NULL OR array_length(v_parts, 1) = 0 THEN
        v_parts := ARRAY['COALESCE(SUM(order_count), 0) AS order_count',
                         'COALESCE(SUM(order_amount), 0) AS order_amount'];
    END IF;

    v_select_cols := array_to_string(v_parts, ', ');

    -- 可选 WHERE 条件
    IF p_outer_id IS NOT NULL THEN
        v_where_extra := v_where_extra || format(' AND outer_id = %L', p_outer_id);
    END IF;
    IF p_platform IS NOT NULL THEN
        v_where_extra := v_where_extra || format(' AND platform = %L', p_platform);
    END IF;
    IF p_shop_name IS NOT NULL THEN
        v_where_extra := v_where_extra || format(' AND shop_name ILIKE %L', '%%' || p_shop_name || '%%');
    END IF;

    -- 可选 GROUP BY 维度（除了时间分桶外的额外分组）
    IF p_group_by IS NOT NULL THEN
        IF p_group_by IN ('outer_id', 'platform', 'shop_name') THEN
            v_group_extra := format(', %I', p_group_by);
            v_group_sel := format(', %I AS group_key', p_group_by);
        ELSIF p_group_by = 'sku_outer_id' THEN
            v_group_extra := ', sku_outer_id';
            v_group_sel := ', sku_outer_id AS group_key';
        END IF;
    END IF;

    -- 执行查询
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) '
        'FROM ('
        '  SELECT %s AS period %s, %s'
        '  FROM erp_product_daily_stats'
        '  WHERE org_id = $1'
        '    AND stat_date >= $2 AND stat_date < $3'
        '    %s'
        '  GROUP BY %s %s'
        '  ORDER BY %s %s'
        '  LIMIT $4'
        ') t',
        v_date_expr,         -- period
        v_group_sel,         -- , group_key（如果有分组）
        v_select_cols,       -- SUM(order_count) AS order_count, ...
        v_where_extra,       -- AND outer_id = ... AND platform = ...
        v_date_expr,         -- GROUP BY period
        v_group_extra,       -- , outer_id（如果有分组）
        v_date_expr,         -- ORDER BY period
        v_group_extra        -- , outer_id（如果有分组）
    ) INTO v_result USING p_org_id, p_start, p_end, p_limit;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$_$;


