--
-- Name: FUNCTION erp_trend_query(p_org_id uuid, p_start date, p_end date, p_granularity text, p_metrics text[], p_group_by text, p_outer_id text, p_platform text, p_shop_name text, p_limit integer); Type: COMMENT; Schema: public; Owner: everydayai
