--
-- Name: erp_try_acquire_sync_lock(integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_try_acquire_sync_lock(p_lock_ttl_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_acquired BOOLEAN;
BEGIN
    -- 原子 CAS：仅当无人持锁或锁已超时时才更新
    UPDATE erp_sync_state
    SET status = 'running', last_run_at = NOW()
    WHERE sync_type = 'purchase'  -- 用 purchase 行作为全局锁标记
      AND (
          status != 'running'
          OR last_run_at < NOW() - (p_lock_ttl_seconds || ' seconds')::INTERVAL
      );

    GET DIAGNOSTICS v_acquired = ROW_COUNT;
    RETURN v_acquired > 0;
END;
$$;


ALTER FUNCTION public.erp_try_acquire_sync_lock(p_lock_ttl_seconds integer) OWNER TO everydayai;

--
-- Name: erp_try_acquire_sync_lock(integer, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.erp_try_acquire_sync_lock(p_lock_ttl_seconds integer DEFAULT 300, p_org_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_acquired INTEGER;
BEGIN
    UPDATE erp_sync_state
    SET status = 'running', last_run_at = NOW()
    WHERE sync_type = 'purchase'
      AND ((p_org_id IS NULL AND org_id IS NULL) OR org_id = p_org_id)
      AND (
          status != 'running'
          OR last_run_at < NOW() - (p_lock_ttl_seconds || ' seconds')::INTERVAL
      );

    GET DIAGNOSTICS v_acquired = ROW_COUNT;
    RETURN v_acquired > 0;
END;
$$;


ALTER FUNCTION public.erp_try_acquire_sync_lock(p_lock_ttl_seconds integer, p_org_id uuid) OWNER TO everydayai;

