--
-- Name: export_legacy_configuration_snapshot(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.export_legacy_configuration_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF session_user <> 'everydayai_config_import_reader'
       OR current_setting(
           'app.legacy_config_export', TRUE
       ) IS DISTINCT FROM 'read' THEN
        RAISE EXCEPTION 'CONFIG_EXPORT_AUTHORITY_DENIED'
            USING ERRCODE = '42501';
    END IF;
    RETURN jsonb_build_object(
        'organizations',
        (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', organization.id,
                'wecom_corp_id', organization.wecom_corp_id,
                'encrypt_key', organization.encrypt_key
            ) ORDER BY organization.id), '[]'::JSONB)
              FROM public.organizations organization
        ),
        'org_configs',
        (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'org_id', config.org_id,
                'config_key', config.config_key,
                'config_value_encrypted', config.config_value_encrypted
            ) ORDER BY config.org_id, config.config_key), '[]'::JSONB)
              FROM public.org_configs config
        ),
        'external_credentials',
        (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'org_id', credential.org_id,
                'source', credential.source,
                'status', credential.status,
                'kuaimai_company_id', credential.kuaimai_company_id,
                'censeid_cookie', credential.censeid_cookie,
                'cookie_full', credential.cookie_full
            ) ORDER BY credential.org_id, credential.source), '[]'::JSONB)
              FROM public.kuaimai_external_credentials credential
        )
    );
END;
$$;


ALTER FUNCTION public.export_legacy_configuration_snapshot() OWNER TO everydayai_owner;

--
-- Name: fail_chat_image_before_dispatch(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.fail_chat_image_before_dispatch(p_task_id uuid, p_error text, p_expected_phase text, p_claim_token uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_task public.tasks%ROWTYPE; v_state JSONB;
BEGIN
    PERFORM public.assert_chat_image_worker(p_org_id);
    SELECT * INTO v_task FROM public.tasks WHERE id=p_task_id AND type='image'
        AND org_id IS NOT DISTINCT FROM p_org_id FOR UPDATE;
    IF NOT FOUND OR NOT (v_task.request_params ? '_media_request_v1') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE='42501';
    END IF;
    v_state:=v_task.request_params->'_media_lifecycle_v1';
    IF p_expected_phase IS NULL OR p_expected_phase NOT IN ('queued','submitting')
       OR v_state->>'phase' IS DISTINCT FROM p_expected_phase
       OR v_state ? 'dispatch_started_at'
       OR (p_expected_phase='submitting' AND v_state->>'claim_token' IS DISTINCT FROM p_claim_token::TEXT) THEN
        RETURN jsonb_build_object('outcome','state_changed');
    END IF;
    UPDATE public.tasks SET result=jsonb_build_object('status','failed','error',LEFT(p_error,2000)),
        request_params=jsonb_set(request_params,'{_media_lifecycle_v1}',v_state ||
            jsonb_build_object('phase','settling','provider_finished_at',NOW())),version=COALESCE(version,0)+1
        WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','settling');
END;
$$;


ALTER FUNCTION public.fail_chat_image_before_dispatch(p_task_id uuid, p_error text, p_expected_phase text, p_claim_token uuid, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: fail_conversation_delivery(uuid, uuid, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.fail_conversation_delivery(p_delivery_id uuid, p_lease_token uuid, p_error text, p_delivered_items jsonb, p_max_attempts integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_delivery conversation_deliveries%ROWTYPE;
    v_dead BOOLEAN;
    v_delay_seconds INTEGER;
BEGIN
    IF p_max_attempts < 1
       OR p_error IS NULL
       OR p_delivered_items IS NULL
       OR jsonb_typeof(p_delivered_items) <> 'array' THEN
        RAISE EXCEPTION 'DELIVERY_FAIL_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_delivery
      FROM conversation_deliveries
     WHERE id = p_delivery_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_delivery.status <> 'delivering'
       OR v_delivery.lease_token IS DISTINCT FROM p_lease_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    v_dead := v_delivery.attempt_count >= p_max_attempts;
    v_delay_seconds := LEAST(
        900,
        5 * CAST(POWER(2, GREATEST(v_delivery.attempt_count - 1, 0)) AS INTEGER)
    );
    UPDATE conversation_deliveries
       SET status = CASE WHEN v_dead THEN 'dead' ELSE 'pending' END,
           delivered_items = p_delivered_items,
           next_attempt_at = CASE
               WHEN v_dead THEN next_attempt_at
               ELSE NOW() + make_interval(secs => v_delay_seconds)
           END,
           lease_token = NULL,
           lease_expires_at = NULL,
           last_error = LEFT(p_error, 2000),
           updated_at = NOW()
     WHERE id = p_delivery_id;
    RETURN jsonb_build_object(
        'outcome', CASE WHEN v_dead THEN 'dead' ELSE 'retry_scheduled' END,
        'retry_seconds', CASE WHEN v_dead THEN NULL ELSE v_delay_seconds END
    );
END;
$$;


ALTER FUNCTION public.fail_conversation_delivery(p_delivery_id uuid, p_lease_token uuid, p_error text, p_delivered_items jsonb, p_max_attempts integer) OWNER TO everydayai;

--
-- Name: fail_ecom_plan(uuid, uuid, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.fail_ecom_plan(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_status text, p_error jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE root_id UUID; saved JSONB;
BEGIN
    SELECT COALESCE(root_plan_id,id) INTO root_id FROM public.ecom_image_plans WHERE id=p_plan_id;
    PERFORM 1 FROM public.ecom_image_plans WHERE id=root_id FOR UPDATE;
    saved=public.save_ecom_image_plan_stage(p_plan_id,p_lease_token,p_stage,NULL,
        jsonb_build_object('stage',p_stage,'status',p_status,'error',p_error),p_status);
    UPDATE public.ecom_image_plans SET recovery_state=jsonb_set(recovery_state,'{last_error}',p_error)
        WHERE id=p_plan_id;
    RETURN saved;
END $$;


ALTER FUNCTION public.fail_ecom_plan(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_status text, p_error jsonb) OWNER TO everydayai_owner;

--
-- Name: fail_generation_turn(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.fail_generation_turn(p_task_id uuid, p_execution_token uuid, p_error_code text, p_error_message text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_task tasks%ROWTYPE;
    v_conversation_id UUID;
    v_snapshot JSONB := '[]'::JSONB;
    v_blocks_text TEXT;
    v_remaining_text TEXT;
BEGIN
    IF p_execution_token IS NULL
       OR NULLIF(BTRIM(p_error_code), '') IS NULL
       OR NULLIF(BTRIM(p_error_message), '') IS NULL THEN
        RAISE EXCEPTION 'ACTOR_FAIL_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT conversation_id INTO v_conversation_id FROM tasks WHERE id = p_task_id;
    IF v_conversation_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_conversation FROM conversations
     WHERE id = v_conversation_id FOR UPDATE;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;

    IF v_task.id IS NULL OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB)
       OR v_task.conversation_id IS DISTINCT FROM v_conversation.id
       OR v_task.org_id IS DISTINCT FROM v_conversation.org_id THEN
        RAISE EXCEPTION 'ACTOR_FAIL_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.status = 'failed'
       AND v_task.execution_token IS NOT DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'already_failed', 'task_id', p_task_id);
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    -- Materialize fenced progress atomically with the failure, as with pause/cancel.
    -- The prefix rule matches services.task_utils.merge_blocks_with_text.
    IF jsonb_typeof(v_task.accumulated_blocks) = 'array'
       AND jsonb_array_length(v_task.accumulated_blocks) > 0 THEN
        v_snapshot := v_task.accumulated_blocks;
    END IF;
    SELECT COALESCE(string_agg(item.value->>'text', '' ORDER BY item.ordinality), '')
      INTO v_blocks_text
      FROM jsonb_array_elements(v_snapshot) WITH ORDINALITY AS item(value, ordinality)
     WHERE item.value->>'type' = 'text';
    IF v_task.accumulated_content IS NOT NULL
       AND LEFT(v_task.accumulated_content, LENGTH(v_blocks_text)) = v_blocks_text THEN
        v_remaining_text := SUBSTRING(v_task.accumulated_content FROM LENGTH(v_blocks_text) + 1);
        IF BTRIM(v_remaining_text) <> '' THEN
            v_snapshot := v_snapshot || jsonb_build_array(
                jsonb_build_object('type', 'text', 'text', v_remaining_text)
            );
        END IF;
    END IF;
    -- A failed task cannot keep a running tool spinner in its saved message.
    SELECT COALESCE(jsonb_agg(
        CASE WHEN item.value->>'type' = 'tool_step' AND item.value->>'status' = 'running'
             THEN item.value || jsonb_build_object('status', 'error')
             ELSE item.value END ORDER BY item.ordinality
    ), '[]'::JSONB) INTO v_snapshot
      FROM jsonb_array_elements(v_snapshot) WITH ORDINALITY AS item(value, ordinality);
    v_snapshot := v_snapshot || jsonb_build_array(jsonb_build_object(
        'type', 'text', 'text',
        CASE WHEN jsonb_array_length(v_snapshot) > 0 THEN E'\n\n' ELSE '' END || p_error_message
    ));

    UPDATE tasks
       SET status = 'failed',
           fail_code = LEFT(p_error_code, 50),
           error_message = p_error_message,
           completed_at = NOW(),
           lease_expires_at = NULL,
           terminal_reason = 'execution_failed'
     WHERE id = p_task_id;
    UPDATE messages
       SET content = v_snapshot,
           status = 'failed',
           is_error = TRUE
     WHERE id = v_task.assistant_message_id;
    UPDATE conversations
       SET active_serial_task_id = NULL,
           actor_updated_at = NOW()
     WHERE id = v_conversation.id
       AND active_serial_task_id = p_task_id;

    RETURN jsonb_build_object('outcome', 'failed', 'task_id', p_task_id);
END;
$$;


