--
-- Name: fail_scheduled_task_delivery(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.fail_scheduled_task_delivery(p_delivery_id uuid, p_lease_token uuid, p_error text, p_max_attempts integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_delivery scheduled_task_deliveries%ROWTYPE;
    v_dead BOOLEAN;
    v_delay_seconds INTEGER;
    v_push_status TEXT;
BEGIN
    IF p_max_attempts < 1 OR COALESCE(p_error, '') = '' THEN
        RAISE EXCEPTION 'SCHEDULED_TASK_DELIVERY_FAIL_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_delivery FROM scheduled_task_deliveries
     WHERE id = p_delivery_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'SCHEDULED_TASK_DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_delivery.status <> 'delivering'
       OR v_delivery.lease_token IS DISTINCT FROM p_lease_token
       OR v_delivery.lease_expires_at <= NOW() THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    v_dead := v_delivery.attempt_count >= p_max_attempts;
    v_delay_seconds := LEAST(
        900,
        5 * CAST(POWER(2, GREATEST(v_delivery.attempt_count - 1, 0)) AS INTEGER)
    );
    UPDATE scheduled_task_deliveries
       SET status = CASE WHEN v_dead THEN 'dead' ELSE 'pending' END,
           next_attempt_at = CASE
               WHEN v_dead THEN next_attempt_at
               ELSE NOW() + make_interval(secs => v_delay_seconds)
           END,
           lease_token = NULL,
           lease_expires_at = NULL,
           last_error = LEFT(p_error, 2000),
           updated_at = NOW()
     WHERE id = p_delivery_id;
    v_push_status := refresh_scheduled_task_run_push_status(v_delivery.run_id);
    RETURN jsonb_build_object(
        'outcome', CASE WHEN v_dead THEN 'dead' ELSE 'retry_scheduled' END,
        'retry_seconds', CASE WHEN v_dead THEN NULL ELSE v_delay_seconds END,
        'push_status', v_push_status
    );
END;
$$;


ALTER FUNCTION public.fail_scheduled_task_delivery(p_delivery_id uuid, p_lease_token uuid, p_error text, p_max_attempts integer) OWNER TO everydayai;

--
-- Name: feedback_chat_image(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.feedback_chat_image(p_task_id uuid, p_rating text, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',TRUE) IS DISTINCT FROM 'runtime'
       OR NULLIF(current_setting('app.org_id',TRUE),'')::UUID IS DISTINCT FROM p_org_id
       OR COALESCE(p_rating,'') NOT IN ('helpful','not_helpful') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_FEEDBACK_DENIED' USING ERRCODE='42501';
    END IF;
    UPDATE public.tasks SET request_params=jsonb_set(request_params,'{_media_feedback_v1}',
        jsonb_build_object('rating',p_rating,'recorded_at',NOW()))
      WHERE id=p_task_id AND user_id=NULLIF(current_setting('app.actor_user_id',TRUE),'')::UUID
        AND org_id IS NOT DISTINCT FROM p_org_id AND type='image'
        AND request_params->'_media_lifecycle_v1'->>'phase'='published'
        AND COALESCE(request_params->'_media_request_v1'->'origin'->>'destination','chat')<>'skill_trial';
    IF NOT FOUND THEN RAISE EXCEPTION 'CHAT_IMAGE_FEEDBACK_DENIED' USING ERRCODE='42501'; END IF;
    RETURN jsonb_build_object('rating',p_rating);
END;
$$;


ALTER FUNCTION public.feedback_chat_image(p_task_id uuid, p_rating text, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: finish_detail_delivery_retry(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.finish_detail_delivery_retry(p_plan_id uuid, p_key text, p_token uuid, p_status text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; j JSONB; delay INTEGER;
BEGIN
 p=public.lock_detail_delivery_plan(p_plan_id); j=p.delivery_recovery->p_key;
 IF p_status IS NULL OR p_status NOT IN ('submitted','waiting','blocked') OR p_reason IS NULL OR length(p_reason)>128 THEN
  RAISE EXCEPTION 'DETAIL_RETRY_INVALID' USING ERRCODE='22023'; END IF;
 IF j->>'status' IS DISTINCT FROM 'running' OR j->>'claim_token' IS DISTINCT FROM p_token::text
  OR (j->>'lease_expires_at')::timestamptz<=NOW() THEN RETURN FALSE; END IF;
 delay=LEAST(300,5*(2^LEAST(COALESCE((j->>'attempts')::int,0),6))::int);
 j=(j-'claim_token'-'lease_expires_at')||jsonb_build_object('status',p_status,'reason',p_reason,
  'next_retry_at',NOW()+make_interval(secs=>delay));
 UPDATE public.ecom_image_plans SET delivery_recovery=jsonb_set(delivery_recovery,ARRAY[p_key],j) WHERE id=p.id;
 RETURN TRUE;
END $$;


ALTER FUNCTION public.finish_detail_delivery_retry(p_plan_id uuid, p_key text, p_token uuid, p_status text, p_reason text) OWNER TO everydayai_owner;

--
-- Name: finish_ecom_plan_attempt(uuid, uuid, integer, uuid, jsonb, text, jsonb, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.finish_ecom_plan_attempt(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_attempt_id uuid, p_usage jsonb, p_outcome text, p_output jsonb DEFAULT NULL::jsonb, p_status text DEFAULT 'planning'::text, p_items jsonb DEFAULT NULL::jsonb, p_reviews jsonb DEFAULT NULL::jsonb, p_credits integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; r public.ecom_image_plans%ROWTYPE;
        root_id UUID; a JSONB; final JSONB; fingerprint TEXT; saved JSONB;
BEGIN
    SELECT COALESCE(root_plan_id,id) INTO root_id FROM public.ecom_image_plans WHERE id=p_plan_id;
    SELECT * INTO r FROM public.ecom_image_plans WHERE id=root_id FOR UPDATE;
    SELECT * INTO p FROM public.ecom_image_plans WHERE id=p_plan_id FOR UPDATE;
    IF SESSION_USER <> 'everydayai' OR current_setting('app.access_kind',TRUE) <> 'runtime'
       OR p.id IS NULL OR r.id IS NULL OR r.user_id IS DISTINCT FROM p.user_id OR r.org_id IS DISTINCT FROM p.org_id
       OR r.conversation_id IS DISTINCT FROM p.conversation_id
       OR p.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',TRUE),'')::uuid
       OR p.org_id IS DISTINCT FROM NULLIF(current_setting('app.org_id',TRUE),'')::uuid
       OR p_outcome IS NULL OR p_outcome NOT IN ('completed','validation_failed','rejected','uncertain') THEN
        RAISE EXCEPTION 'ECOM_PLAN_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
    a=r.recovery_state->'attempts'->p_attempt_id::text;
    IF a IS NULL OR a->>'plan_id' IS DISTINCT FROM p.id::text OR (a->>'stage')::integer IS DISTINCT FROM p_stage THEN
        RAISE EXCEPTION 'ECOM_PLAN_ATTEMPT_CONFLICT' USING ERRCODE='22023';
    END IF;
    IF p.source_kind='detail_project'
       AND p.model_settings->'delivery_policy'='{"version":1,"retry_cost":"platform"}'::jsonb THEN
        IF p_outcome='completed' AND p_status='ready' AND p_output IS NOT NULL THEN
            -- Charge each valid stage once, only when the complete prompt set is delivered.
            SELECT p_credits+COALESCE(SUM((value->'usage'->>'user_credits')::integer),0)
              INTO p_credits FROM jsonb_array_elements(p.stage_attempts)
             WHERE value->>'status'='completed' AND (value->>'stage')::integer<p_stage;
            p_usage=COALESCE(p_usage,'{}')||jsonb_build_object('billing_party','user','delivered_stage_credits',p_credits);
        ELSE
            p_usage=COALESCE(p_usage,'{}')||jsonb_build_object('billing_party',
                CASE WHEN p_outcome='completed' AND p_output IS NOT NULL AND p_status='planning'
                  THEN 'pending_delivery' ELSE 'platform' END,
                'platform_credits_estimate',CASE WHEN p_outcome='validation_failed' THEN p_credits ELSE 0 END);
            p_credits=0;
        END IF;
    END IF;
    fingerprint=md5(jsonb_build_object('usage',p_usage,'outcome',p_outcome,'output',p_output,
        'status',p_status,'items',p_items,'reviews',p_reviews,'credits',p_credits)::text);
    IF a->>'outcome'<>'started' THEN
        IF a->>'fingerprint' IS DISTINCT FROM fingerprint THEN
            RAISE EXCEPTION 'ECOM_PLAN_ATTEMPT_CONFLICT' USING ERRCODE='22023';
        END IF;
        RETURN jsonb_build_object('outcome','replay','attempt_id',p_attempt_id);
    END IF;
    saved=public.save_ecom_image_plan_stage(p_plan_id,p_lease_token,p_stage,p_output,
        jsonb_build_object('attempt_id',p_attempt_id,'stage',p_stage,'status',p_outcome,'usage',p_usage),
        p_status,p_items,p_reviews,p_credits);
    final=a || jsonb_build_object('outcome',p_outcome,'fingerprint',fingerprint,'usage',p_usage,
        'user_credits',p_credits,'completed_at',NOW());
    UPDATE public.ecom_image_plans SET recovery_state=jsonb_set(recovery_state,
        ARRAY['attempts',p_attempt_id::text],final),updated_at=NOW() WHERE id=root_id;
    RETURN saved || jsonb_build_object('outcome','saved','attempt_id',p_attempt_id);
END $$;


ALTER FUNCTION public.finish_ecom_plan_attempt(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_attempt_id uuid, p_usage jsonb, p_outcome text, p_output jsonb, p_status text, p_items jsonb, p_reviews jsonb, p_credits integer) OWNER TO everydayai_owner;

--
-- Name: finish_ecom_plan_draft_attempt(uuid, uuid, integer, uuid, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.finish_ecom_plan_draft_attempt(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_attempt_id uuid, p_usage jsonb, p_draft jsonb, p_credits integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE result JSONB; usage JSONB;
BEGIN
    IF p_draft IS NULL OR jsonb_typeof(p_draft) <> 'object' THEN
        RAISE EXCEPTION 'ECOM_PLAN_DRAFT_INVALID' USING ERRCODE='22023';
    END IF;
    -- Included in the existing settlement fingerprint: an idempotent replay
    -- cannot replace a settled draft with a different one at the same charge.
    usage=COALESCE(p_usage,'{}'::jsonb) || jsonb_build_object('draft_fingerprint',md5(p_draft::text));
    result=public.finish_ecom_plan_attempt(p_plan_id,p_lease_token,p_stage,p_attempt_id,
        usage,'validation_failed',NULL,'planning',NULL,NULL,p_credits);
    IF result->>'outcome'='saved' THEN
        UPDATE public.ecom_image_plans SET stage_drafts=jsonb_set(stage_drafts,ARRAY[p_stage::text],p_draft),
            updated_at=NOW() WHERE id=p_plan_id;
    END IF;
    RETURN result;
END $$;


ALTER FUNCTION public.finish_ecom_plan_draft_attempt(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_attempt_id uuid, p_usage jsonb, p_draft jsonb, p_credits integer) OWNER TO everydayai_owner;

--
-- Name: finish_scheduled_task_failure(uuid, uuid, uuid, jsonb, text, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.finish_scheduled_task_failure(p_task_id uuid, p_org_id uuid, p_run_id uuid, p_update jsonb, p_error text, p_tokens integer, p_duration integer, p_stale_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_task scheduled_tasks%ROWTYPE; v_status TEXT; v_next TIMESTAMPTZ;
BEGIN
    SELECT * INTO v_task FROM scheduled_tasks WHERE id=p_task_id AND org_id=p_org_id FOR UPDATE;
    IF NOT FOUND OR v_task.status <> 'running' OR v_task.run_token IS DISTINCT FROM p_run_id
       OR (p_stale_before IS NOT NULL AND v_task.claimed_at >= p_stale_before) THEN
        RETURN jsonb_build_object('outcome','claim_lost');
    END IF;
    IF p_stale_before IS NULL AND NOT EXISTS (
        SELECT 1 FROM scheduled_task_runs WHERE id=p_run_id AND task_id=p_task_id AND status='running'
    ) THEN
        RETURN jsonb_build_object('outcome','run_not_running');
    END IF;
    v_status := p_update->>'status';
    IF v_status NOT IN ('active','paused','error') OR v_status IS NULL THEN
        RAISE EXCEPTION 'SCHEDULED_TASK_FAILURE_STATUS_INVALID';
    END IF;
    v_next := NULLIF(p_update->>'next_run_at','')::timestamptz;
    IF NOT v_task.schedule_enabled THEN
        v_status := CASE WHEN v_task.run_previous_status='error' THEN 'error' ELSE 'paused' END;
    END IF;
    IF v_status <> 'active' THEN v_next:=NULL; END IF;
    UPDATE scheduled_task_runs SET status='failed',error_message=LEFT(p_error,500),tokens_used=p_tokens,
        duration_ms=p_duration,finished_at=NOW()
      WHERE id=p_run_id AND task_id=p_task_id AND org_id=p_org_id AND status='running';
    UPDATE scheduled_tasks SET status=v_status,next_run_at=v_next,
        retry_config_revision=CASE WHEN v_status='active' AND
            (COALESCE((p_update->>'retry_scheduled')::boolean,FALSE) OR p_stale_before IS NOT NULL)
            THEN v_task.run_config_revision ELSE NULL END,
        consecutive_failures=COALESCE((p_update->>'consecutive_failures')::integer,consecutive_failures),updated_at=NOW()
      WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','finished','status',v_status,'next_run_at',v_next);
END $$;


ALTER FUNCTION public.finish_scheduled_task_failure(p_task_id uuid, p_org_id uuid, p_run_id uuid, p_update jsonb, p_error text, p_tokens integer, p_duration integer, p_stale_before timestamp with time zone) OWNER TO everydayai;

