CREATE TABLE public.conversations (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid,
    title character varying(200) DEFAULT '新对话'::character varying,
    model_id character varying(100),
    message_count integer DEFAULT 0,
    credits_consumed integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    last_message_preview text,
    context_summary text,
    summary_message_count integer DEFAULT 0,
    org_id uuid,
    source character varying(20) DEFAULT 'web'::character varying,
    image_style_directive text,
    chat_settings jsonb DEFAULT '{}'::jsonb,
    context_revision bigint DEFAULT 0 NOT NULL,
    last_closed_message_id uuid,
    summary_revision bigint DEFAULT 0 NOT NULL,
    summary_through_message_id uuid,
    active_serial_task_id uuid,
    actor_updated_at timestamp with time zone DEFAULT now() NOT NULL,
    scope_type text DEFAULT 'user'::text NOT NULL,
    scope_id text,
    CONSTRAINT conversations_context_revision_check CHECK ((context_revision >= 0)),
    CONSTRAINT conversations_scope_owner_check CHECK ((((scope_type = 'user'::text) AND (user_id IS NOT NULL)) OR ((scope_type = 'channel'::text) AND (user_id IS NULL)))),
    CONSTRAINT conversations_scope_type_check CHECK ((scope_type = ANY (ARRAY['user'::text, 'channel'::text]))),
    CONSTRAINT conversations_summary_revision_check CHECK ((summary_revision >= 0))
);


