CREATE TABLE public.tasks (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    conversation_id uuid,
    type character varying(20) NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    credits_locked integer DEFAULT 0,
    credits_used integer DEFAULT 0,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    external_task_id character varying(100),
    request_params jsonb,
    result jsonb,
    fail_code character varying(50),
    placeholder_message_id character varying(100),
    last_polled_at timestamp with time zone,
    client_context jsonb,
    kie_url_expires_at timestamp with time zone,
    version integer DEFAULT 1,
    oss_retry_count integer DEFAULT 0,
    placeholder_created_at timestamp with time zone,
    accumulated_content text,
    model_id character varying(100),
    total_credits integer DEFAULT 0,
    assistant_message_id uuid,
    credit_transaction_id uuid,
    client_task_id character varying(100),
    image_index integer,
    batch_id text,
    result_data jsonb,
    org_id uuid,
    accumulated_blocks jsonb DEFAULT '[]'::jsonb,
    input_message_id uuid,
    turn_id uuid,
    base_context_revision bigint,
    context_through_message_id uuid,
    execution_mode text DEFAULT 'serial'::text NOT NULL,
    queue_sequence bigint NOT NULL,
    execution_token uuid,
    lease_expires_at timestamp with time zone,
    execution_attempt integer DEFAULT 0 NOT NULL,
    delivery_context jsonb DEFAULT '{}'::jsonb NOT NULL,
    terminal_reason text,
    CONSTRAINT tasks_base_context_revision_check CHECK (((base_context_revision IS NULL) OR (base_context_revision >= 0))),
    CONSTRAINT tasks_conversation_source_check CHECK (((conversation_id IS NOT NULL) OR ((((type)::text = 'image'::text) AND ((((request_params -> '_media_request_v1'::text) -> 'origin'::text) ->> 'destination'::text) = 'detail_project'::text)) IS TRUE))),
    CONSTRAINT tasks_delivery_context_object_check CHECK ((jsonb_typeof(delivery_context) = 'object'::text)),
    CONSTRAINT tasks_execution_attempt_check CHECK ((execution_attempt >= 0)),
    CONSTRAINT tasks_execution_mode_check CHECK ((execution_mode = ANY (ARRAY['serial'::text, 'branch'::text]))),
    CONSTRAINT tasks_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'paused'::character varying, 'completed'::character varying, 'failed'::character varying, 'cancelled'::character varying])::text[]))),
    CONSTRAINT tasks_type_check CHECK (((type)::text = ANY ((ARRAY['chat'::character varying, 'image'::character varying, 'video'::character varying])::text[])))
);


