--
-- Name: list_actor_organizations(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.list_actor_organizations() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public._assert_governance_self_scope();
    v_result JSONB;
BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'org_id', organization.id,
        'name', organization.name,
        'logo_url', organization.logo_url,
        'role', member.role,
        'features', organization.features
    ) ORDER BY member.joined_at), '[]'::JSONB)
      INTO v_result
      FROM public.org_members member
      JOIN public.organizations organization
        ON organization.id = member.org_id
     WHERE member.user_id = v_actor
       AND member.status = 'active'
       AND organization.status = 'active';
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.list_actor_organizations() OWNER TO everydayai_owner;

--
-- Name: list_actor_pending_invitations(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.list_actor_pending_invitations() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public._assert_governance_self_scope();
    v_result JSONB;
BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'invite_token', invitation.invite_token,
        'org_name', organization.name,
        'role', invitation.role,
        'expires_at', invitation.expires_at
    ) ORDER BY invitation.created_at), '[]'::JSONB)
      INTO v_result
      FROM public.users account
      JOIN public.org_invitations invitation
        ON invitation.phone = account.phone
       AND invitation.status = 'pending'
       AND invitation.expires_at > NOW()
      JOIN public.organizations organization
        ON organization.id = invitation.org_id
     WHERE account.id = v_actor;
    RETURN v_result;
END;
$$;


