--
-- Name: list_user_configuration_status(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.list_user_configuration_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public._assert_user_configuration_actor();
BEGIN
    RETURN public._list_configuration_status('user', NULL, v_actor);
END;
$$;


ALTER FUNCTION public.list_user_configuration_status() OWNER TO everydayai_owner;

--
-- Name: load_generation_checkpoint(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.load_generation_checkpoint(p_task_id uuid, p_execution_token uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_checkpoint conversation_turn_checkpoints%ROWTYPE;
BEGIN
    IF p_task_id IS NULL OR p_execution_token IS NULL THEN
        RAISE EXCEPTION 'ACTOR_CHECKPOINT_LOAD_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_CHECKPOINT_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    SELECT * INTO v_checkpoint FROM conversation_turn_checkpoints
     WHERE task_id = p_task_id AND status IN ('ready', 'paused');
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'empty');
    END IF;
    RETURN jsonb_build_object(
        'outcome', 'loaded', 'version', v_checkpoint.version,
        'safe_point', v_checkpoint.safe_point, 'state', v_checkpoint.state
    );
END;
$$;


ALTER FUNCTION public.load_generation_checkpoint(p_task_id uuid, p_execution_token uuid) OWNER TO everydayai;

--
-- Name: ecom_image_plans; Type: TABLE; Schema: public; Owner: everydayai_owner
--

CREATE TABLE public.ecom_image_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    org_id uuid,
    conversation_id uuid,
    parent_task_id uuid,
    input_message_id uuid,
    base_context_revision bigint,
    invocation_key text NOT NULL,
    plan_revision integer DEFAULT 1 NOT NULL,
    supersedes_plan_id uuid,
    input_digest text NOT NULL,
    status text NOT NULL,
    current_stage smallint NOT NULL,
    image_count smallint NOT NULL,
    input_snapshot jsonb NOT NULL,
    prompt_versions jsonb NOT NULL,
    model_settings jsonb NOT NULL,
    stage_outputs jsonb DEFAULT '{}'::jsonb NOT NULL,
    stage_attempts jsonb DEFAULT '[]'::jsonb NOT NULL,
    items jsonb DEFAULT '[]'::jsonb NOT NULL,
    review_records jsonb DEFAULT '[]'::jsonb NOT NULL,
    target_size jsonb NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    root_plan_id uuid,
    recovery_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    stage_drafts jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_kind text DEFAULT 'chat'::text NOT NULL,
    project_id uuid,
    generation_run_id uuid,
    delivery_recovery jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT ecom_image_plans_current_stage_check CHECK (((current_stage >= 1) AND (current_stage <= 3))),
    CONSTRAINT ecom_image_plans_delivery_recovery_check CHECK ((jsonb_typeof(delivery_recovery) = 'object'::text)),
    CONSTRAINT ecom_image_plans_image_count_check CHECK (((image_count >= 1) AND (image_count <= 15))),
    CONSTRAINT ecom_image_plans_input_digest_check CHECK ((input_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ecom_image_plans_plan_revision_check CHECK ((plan_revision > 0)),
    CONSTRAINT ecom_image_plans_source_kind_check CHECK ((source_kind = ANY (ARRAY['chat'::text, 'detail_project'::text]))),
    CONSTRAINT ecom_image_plans_stage_drafts_check CHECK ((jsonb_typeof(stage_drafts) = 'object'::text)),
    CONSTRAINT ecom_image_plans_status_check CHECK ((status = ANY (ARRAY['planning'::text, 'needs_input'::text, 'insufficient'::text, 'ready'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT ecom_plan_source_check CHECK ((((source_kind = 'chat'::text) AND (conversation_id IS NOT NULL) AND (parent_task_id IS NOT NULL) AND (input_message_id IS NOT NULL) AND (base_context_revision IS NOT NULL) AND (project_id IS NULL)) OR ((source_kind = 'detail_project'::text) AND (project_id IS NOT NULL) AND (generation_run_id IS NOT NULL) AND (conversation_id IS NULL) AND (parent_task_id IS NULL) AND (input_message_id IS NULL) AND (base_context_revision IS NULL))))
);

ALTER TABLE ONLY public.ecom_image_plans FORCE ROW LEVEL SECURITY;


ALTER TABLE public.ecom_image_plans OWNER TO everydayai_owner;

--
-- Name: lock_detail_delivery_plan(uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.lock_detail_delivery_plan(p_plan_id uuid) RETURNS public.ecom_image_plans
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; d public.detail_projects%ROWTYPE; project UUID;
BEGIN
 IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',true) IS DISTINCT FROM 'runtime' THEN
  RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT project_id INTO project FROM public.ecom_image_plans WHERE id=p_plan_id;
 SELECT * INTO d FROM public.detail_projects WHERE id=project FOR UPDATE;
 SELECT * INTO p FROM public.ecom_image_plans WHERE id=p_plan_id FOR UPDATE;
 IF d.id IS NULL OR p.id IS NULL OR p.source_kind IS DISTINCT FROM 'detail_project'
  OR d.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',true),'')::uuid
  OR d.org_id IS DISTINCT FROM NULLIF(current_setting('app.org_id',true),'')::uuid
  OR p.user_id IS DISTINCT FROM d.user_id OR p.org_id IS DISTINCT FROM d.org_id
  OR d.status='archived' OR d.run_state->>'run_id' IS DISTINCT FROM p.generation_run_id::text
  OR d.run_state->>'delivery_stopped'='true'
  OR p.model_settings->'delivery_policy' IS DISTINCT FROM '{"version":1,"retry_cost":"platform"}'::jsonb THEN
  RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN p;
END $$;


ALTER FUNCTION public.lock_detail_delivery_plan(p_plan_id uuid) OWNER TO everydayai_owner;

--
-- Name: lock_ecom_format_plan(uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.lock_ecom_format_plan(p_plan_id uuid) RETURNS public.ecom_image_plans
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; d public.detail_projects%ROWTYPE; project UUID; root UUID;
BEGIN
 IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',true) IS DISTINCT FROM 'runtime' THEN
  RAISE EXCEPTION 'ECOM_PLAN_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT project_id,COALESCE(root_plan_id,id) INTO project,root FROM public.ecom_image_plans WHERE id=p_plan_id;
 SELECT * INTO d FROM public.detail_projects WHERE id=project FOR UPDATE;
 PERFORM 1 FROM public.ecom_image_plans WHERE id=root FOR UPDATE;
 SELECT * INTO p FROM public.ecom_image_plans WHERE id=p_plan_id FOR UPDATE;
 IF p.id IS NULL OR d.id IS NULL OR p.source_kind IS DISTINCT FROM 'detail_project'
  OR p.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',true),'')::uuid
  OR p.org_id IS DISTINCT FROM NULLIF(current_setting('app.org_id',true),'')::uuid
  OR d.user_id IS DISTINCT FROM p.user_id OR d.org_id IS DISTINCT FROM p.org_id
  OR d.status='archived' OR d.run_state->>'run_id' IS DISTINCT FROM p.generation_run_id::text
  OR d.run_state->>'delivery_stopped'='true' THEN
  RAISE EXCEPTION 'ECOM_PLAN_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN p;
END $$;


ALTER FUNCTION public.lock_ecom_format_plan(p_plan_id uuid) OWNER TO everydayai_owner;

--
-- Name: maintain_tool_audit_partitions(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.maintain_tool_audit_partitions() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_month DATE;
    partition_name TEXT;
    old_month DATE;
    old_partition TEXT;
BEGIN
    -- 创建未来 2 个月的分区（幂等，已存在则跳过）
    FOR i IN 1..2 LOOP
        target_month := DATE_TRUNC('month', NOW()) + (i || ' months')::INTERVAL;
        partition_name := 'tool_audit_log_' || TO_CHAR(target_month, 'YYYY_MM');
        BEGIN
            EXECUTE format(
                'CREATE TABLE IF NOT EXISTS %I PARTITION OF tool_audit_log
                 FOR VALUES FROM (%L) TO (%L)',
                partition_name, target_month, target_month + INTERVAL '1 month'
            );
            RAISE NOTICE 'Created partition: %', partition_name;
        EXCEPTION WHEN duplicate_table THEN
            NULL; -- 已存在，跳过
        END;
    END LOOP;

    -- 删除 90 天前的月分区
    old_month := DATE_TRUNC('month', NOW() - INTERVAL '90 days');
    old_partition := 'tool_audit_log_' || TO_CHAR(old_month, 'YYYY_MM');
    EXECUTE format('DROP TABLE IF EXISTS %I', old_partition);
    RAISE NOTICE 'Dropped old partition (if existed): %', old_partition;
END;
$$;


ALTER FUNCTION public.maintain_tool_audit_partitions() OWNER TO everydayai;

--
-- Name: mark_chat_image_dispatch(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.mark_chat_image_dispatch(p_task_id uuid, p_claim_token uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_task public.tasks%ROWTYPE; v_lifecycle JSONB;
BEGIN
    PERFORM public.assert_chat_image_worker(p_org_id);
    SELECT * INTO v_task FROM public.tasks WHERE id=p_task_id AND type='image'
        AND org_id IS NOT DISTINCT FROM p_org_id FOR UPDATE;
    v_lifecycle:=v_task.request_params->'_media_lifecycle_v1';
    IF NOT FOUND OR v_task.status <> 'running' OR v_lifecycle->>'phase' <> 'submitting'
       OR v_lifecycle->>'claim_token' IS DISTINCT FROM p_claim_token::TEXT
       OR (v_lifecycle->>'lease_expires_at')::TIMESTAMPTZ <= NOW()
       OR v_lifecycle ? 'dispatch_started_at' THEN
        RETURN jsonb_build_object('outcome','not_owned');
    END IF;
    UPDATE public.tasks SET request_params=jsonb_set(request_params,'{_media_lifecycle_v1}',
        v_lifecycle || jsonb_build_object('dispatch_started_at',NOW())) WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','dispatch');
END;
$$;


ALTER FUNCTION public.mark_chat_image_dispatch(p_task_id uuid, p_claim_token uuid, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: mark_chat_image_uncertain(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.mark_chat_image_uncertain(p_task_id uuid, p_claim_token uuid, p_timeout_seconds integer, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_task public.tasks%ROWTYPE; v_lifecycle JSONB;
BEGIN
    PERFORM public.assert_chat_image_worker(p_org_id);
    IF p_timeout_seconds IS NULL OR p_timeout_seconds NOT BETWEEN 60 AND 86400 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_DEADLINE_INVALID' USING ERRCODE='22023';
    END IF;
    SELECT * INTO v_task FROM public.tasks WHERE id=p_task_id AND type='image'
        AND org_id IS NOT DISTINCT FROM p_org_id FOR UPDATE;
    v_lifecycle:=v_task.request_params->'_media_lifecycle_v1';
    IF NOT FOUND OR NOT (v_task.request_params ? '_media_request_v1') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE='42501';
    END IF;
    IF v_lifecycle->>'phase'='uncertain' THEN RETURN jsonb_build_object('outcome','uncertain'); END IF;
    IF COALESCE(v_lifecycle->>'phase','') NOT IN ('submitting','accepted')
       OR (v_lifecycle->>'phase'='submitting' AND v_lifecycle->>'claim_token' IS DISTINCT FROM p_claim_token::TEXT) THEN
        RETURN jsonb_build_object('outcome','not_owned');
    END IF;
    UPDATE public.tasks SET request_params=jsonb_set(request_params,'{_media_lifecycle_v1}',
        v_lifecycle || jsonb_build_object('phase','uncertain','uncertain_at',NOW(),
            'uncertain_deadline',NOW()+make_interval(secs=>p_timeout_seconds))) WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','uncertain');
END;
$$;


ALTER FUNCTION public.mark_chat_image_uncertain(p_task_id uuid, p_claim_token uuid, p_timeout_seconds integer, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: mark_stale_tool_invocation_uncertain(uuid, uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.mark_stale_tool_invocation_uncertain(p_task_id uuid, p_turn_id uuid, p_tool_call_id text, p_execution_token uuid, p_stale_after_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_invocation tool_invocations%ROWTYPE;
    v_updated_count BIGINT;
    v_threshold INTEGER := GREATEST(COALESCE(p_stale_after_seconds, 900), 1);
BEGIN
    IF p_task_id IS NULL OR p_turn_id IS NULL OR p_execution_token IS NULL
       OR NULLIF(BTRIM(p_tool_call_id), '') IS NULL THEN
        RAISE EXCEPTION 'ACTOR_TOOL_INVOCATION_STALE_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_TOOL_INVOCATION_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    SELECT * INTO v_invocation FROM tool_invocations
     WHERE task_id = p_task_id AND turn_id = p_turn_id
       AND tool_call_id = BTRIM(p_tool_call_id) FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'missing');
    END IF;
    IF v_invocation.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', v_invocation.status);
    END IF;
    IF v_invocation.updated_at >= NOW() - make_interval(secs => v_threshold) THEN
        RETURN jsonb_build_object('outcome', 'fresh');
    END IF;
    UPDATE tool_invocations SET status = 'uncertain',
        error_message = LEFT('外部工具调用超过恢复阈值，结果未知；禁止自动重试。', 2000),
        completed_at = NOW(), updated_at = NOW()
     WHERE id = v_invocation.id AND status = 'running';
    GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    IF v_updated_count = 0 THEN
        RETURN jsonb_build_object('outcome', 'already_completed');
    END IF;
    RETURN jsonb_build_object(
        'outcome', 'uncertain',
        'error_message', '外部工具调用超过恢复阈值，结果未知；禁止自动重试。'
    );
END;
$$;


ALTER FUNCTION public.mark_stale_tool_invocation_uncertain(p_task_id uuid, p_turn_id uuid, p_tool_call_id text, p_execution_token uuid, p_stale_after_seconds integer) OWNER TO everydayai;

--
-- Name: materialize_actor_cancel_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.materialize_actor_cancel_snapshot(p_task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_message messages%ROWTYPE;
    v_blocks JSONB;
    v_message_blocks JSONB;
    v_content JSONB;
    v_block_text TEXT := '';
    v_remaining TEXT := '';
    v_now TIMESTAMPTZ := NOW();
BEGIN
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF v_task.id IS NULL OR v_task.assistant_message_id IS NULL THEN
        RETURN jsonb_build_object('saved', FALSE, 'reason', 'message_missing');
    END IF;
    SELECT * INTO v_message FROM messages
     WHERE id = v_task.assistant_message_id FOR UPDATE;
    IF v_message.id IS NULL THEN
        RETURN jsonb_build_object('saved', FALSE, 'reason', 'message_missing');
    END IF;
    IF v_message.status::TEXT = 'completed' THEN
        RETURN jsonb_build_object('saved', FALSE, 'reason', 'already_completed');
    END IF;

    v_blocks := CASE
        WHEN jsonb_typeof(COALESCE(v_task.accumulated_blocks, '[]'::JSONB)) = 'array'
            THEN COALESCE(v_task.accumulated_blocks, '[]'::JSONB)
        ELSE '[]'::JSONB
    END;
    IF jsonb_array_length(v_blocks) = 0
       AND COALESCE(v_task.accumulated_content, '') = '' THEN
        v_message_blocks := public.actor_message_text_to_blocks(v_message.content);
        IF jsonb_typeof(v_message_blocks) = 'array' THEN
            v_blocks := v_message_blocks;
        END IF;
    END IF;

    SELECT COALESCE(
        string_agg(COALESCE(item.value->>'text', ''), '' ORDER BY item.ordinality), ''
    ) INTO v_block_text
      FROM jsonb_array_elements(v_blocks) WITH ORDINALITY AS item(value, ordinality)
     WHERE jsonb_typeof(item.value) = 'object' AND item.value->>'type' = 'text';

    IF COALESCE(v_task.accumulated_content, '') <> ''
       AND LEFT(v_task.accumulated_content, LENGTH(v_block_text)) = v_block_text THEN
        v_remaining := SUBSTRING(v_task.accumulated_content FROM LENGTH(v_block_text) + 1);
        IF BTRIM(v_remaining) <> '' THEN
            v_blocks := v_blocks || jsonb_build_array(
                jsonb_build_object('type', 'text', 'text', v_remaining)
            );
        END IF;
    ELSIF jsonb_array_length(v_blocks) = 0
          AND BTRIM(COALESCE(v_task.accumulated_content, '')) <> '' THEN
        v_blocks := jsonb_build_array(
            jsonb_build_object('type', 'text', 'text', v_task.accumulated_content)
        );
    END IF;

    SELECT COALESCE(jsonb_agg(
        CASE
            WHEN item.value->>'type' = 'tool_step'
             AND item.value->>'status' = 'running'
            THEN item.value || jsonb_build_object('status', 'cancelled', 'cancelled_at', v_now)
            ELSE item.value
        END ORDER BY item.ordinality
    ), '[]'::JSONB) INTO v_content
      FROM jsonb_array_elements(v_blocks) WITH ORDINALITY AS item(value, ordinality);

    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_content) AS item(value)
         WHERE item.value->>'type' = 'interrupt_marker'
    ) THEN
        v_content := v_content || jsonb_build_array(
            jsonb_build_object(
                'type', 'interrupt_marker', 'interrupted_at', v_now,
                'reason', 'user_cancel'
            )
        );
    END IF;

    -- messages.content 的生产契约是 TEXT，保存 JSONB 的文本表示。
    UPDATE messages SET content = v_content::TEXT, status = 'interrupted', is_error = FALSE
     WHERE id = v_message.id AND status::TEXT <> 'completed';
    RETURN jsonb_build_object(
        'saved', TRUE, 'message_id', v_message.id, 'content', v_content
    );
END;
$$;


ALTER FUNCTION public.materialize_actor_cancel_snapshot(p_task_id uuid) OWNER TO everydayai;

--
-- Name: materialize_actor_pause_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.materialize_actor_pause_snapshot(p_task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_snapshot JSONB;
    v_content JSONB;
BEGIN
    v_snapshot := public.materialize_actor_cancel_snapshot(p_task_id);
    IF COALESCE((v_snapshot->>'saved')::BOOLEAN, FALSE) IS NOT TRUE THEN
        RETURN v_snapshot;
    END IF;

    SELECT COALESCE(jsonb_agg(
        CASE
            WHEN item.value->>'type' = 'interrupt_marker'
            THEN item.value || jsonb_build_object('reason', 'user_pause')
            ELSE item.value
        END ORDER BY item.ordinality
    ), '[]'::JSONB) INTO v_content
      FROM jsonb_array_elements(COALESCE(v_snapshot->'content', '[]'::JSONB))
           WITH ORDINALITY AS item(value, ordinality);
    UPDATE messages SET content = v_content::TEXT
     WHERE id = (v_snapshot->>'message_id')::UUID;
    RETURN v_snapshot || jsonb_build_object('content', v_content);
END;
$$;


ALTER FUNCTION public.materialize_actor_pause_snapshot(p_task_id uuid) OWNER TO everydayai;

