--
-- Name: mcp_record_connector_audit(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.mcp_record_connector_audit(p_org_id uuid, p_authority text, p_action text, p_target_kind text, p_target_key text, p_metadata jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_authority TEXT;
    v_audit_id UUID := gen_random_uuid();
BEGIN
    v_authority := public._assert_mcp_application_actor(p_org_id, TRUE);
    IF p_authority IS DISTINCT FROM v_authority
       OR p_action NOT IN (
           'mcp_connector.set_enabled',
           'mcp_connector.set_credential',
           'mcp_connector.delete_credential'
       )
       OR p_target_kind IS DISTINCT FROM 'mcp_connector'
       OR p_target_key IS DISTINCT FROM 'test-readonly'
       OR p_metadata IS NULL
       OR jsonb_typeof(p_metadata) <> 'object' THEN
        RAISE EXCEPTION 'MCP_CONNECTOR_AUDIT_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.governance_audit_log(
        id, org_id, actor_id, authority, action, target_kind,
        target_key, request_id, metadata
    ) VALUES (
        v_audit_id, p_org_id, public.mcp_application_actor_user_id(), v_authority,
        p_action, p_target_kind, p_target_key,
        NULLIF(current_setting('app.request_id', TRUE), ''), p_metadata
    );
    RETURN v_audit_id;
END;
$$;


ALTER FUNCTION public.mcp_record_connector_audit(p_org_id uuid, p_authority text, p_action text, p_target_kind text, p_target_key text, p_metadata jsonb) OWNER TO everydayai_owner;

--
-- Name: merge_wecom_duplicate_users(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.merge_wecom_duplicate_users(p_keep_uid uuid, p_drop_uids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_moved_credits INT := 0;
  v_moved_convs INT := 0;
  v_moved_imgs INT := 0;
  v_moved_tasks INT := 0;
  v_moved_credits_hist INT := 0;
  v_moved_mappings INT := 0;
BEGIN
  -- 安全校验
  IF p_keep_uid = ANY(p_drop_uids) THEN
    RAISE EXCEPTION 'keep_uid 不能在 drop_uids 中';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_keep_uid) THEN
    RAISE EXCEPTION 'keep_uid 不存在: %', p_keep_uid;
  END IF;

  -- 累加 drop 的积分到 keep（先查后改，避免漏积分）
  SELECT COALESCE(SUM(credits), 0) INTO v_moved_credits
  FROM users WHERE id = ANY(p_drop_uids);

  UPDATE users SET credits = credits + v_moved_credits, updated_at = NOW()
  WHERE id = p_keep_uid;

  -- 迁移所有 FK 引用到 keep_uid
  UPDATE conversations SET user_id = p_keep_uid WHERE user_id = ANY(p_drop_uids);
  GET DIAGNOSTICS v_moved_convs = ROW_COUNT;

  UPDATE image_generations SET user_id = p_keep_uid WHERE user_id = ANY(p_drop_uids);
  GET DIAGNOSTICS v_moved_imgs = ROW_COUNT;

  UPDATE tasks SET user_id = p_keep_uid WHERE user_id = ANY(p_drop_uids);
  GET DIAGNOSTICS v_moved_tasks = ROW_COUNT;

  UPDATE credits_history SET user_id = p_keep_uid WHERE user_id = ANY(p_drop_uids);
  GET DIAGNOSTICS v_moved_credits_hist = ROW_COUNT;

  -- mapping 迁移：用 UPDATE ... ON CONFLICT DO NOTHING 兼容 keep 已有 mapping 的场景
  -- （UPDATE 不支持 ON CONFLICT，需用 DELETE 冲突项策略）
  -- 先删 drop 中与 keep 已有 mapping 重复的项
  DELETE FROM wecom_user_mappings
  WHERE user_id = ANY(p_drop_uids)
    AND EXISTS (
      SELECT 1 FROM wecom_user_mappings keep_m
      WHERE keep_m.user_id = p_keep_uid
        AND keep_m.wecom_userid = wecom_user_mappings.wecom_userid
        AND keep_m.corp_id = wecom_user_mappings.corp_id
        AND keep_m.org_id IS NOT DISTINCT FROM wecom_user_mappings.org_id
    );
  -- 剩下的迁移到 keep
  UPDATE wecom_user_mappings SET user_id = p_keep_uid WHERE user_id = ANY(p_drop_uids);
  GET DIAGNOSTICS v_moved_mappings = ROW_COUNT;

  -- org_members 类似：去重后迁移
  DELETE FROM org_members
  WHERE user_id = ANY(p_drop_uids)
    AND EXISTS (
      SELECT 1 FROM org_members km
      WHERE km.user_id = p_keep_uid AND km.org_id = org_members.org_id
    );
  UPDATE org_members SET user_id = p_keep_uid WHERE user_id = ANY(p_drop_uids);

  -- messages 通过 conversation_id 关联，不需要直接迁移
  -- credit_transactions / admin_action_logs 等其他 FK 表
  UPDATE credit_transactions SET user_id = p_keep_uid WHERE user_id = ANY(p_drop_uids);
  UPDATE admin_action_logs   SET target_user_id = p_keep_uid WHERE target_user_id = ANY(p_drop_uids);

  -- 删除 drop 用户（此时已无 FK 引用）
  DELETE FROM users WHERE id = ANY(p_drop_uids);

  RETURN jsonb_build_object(
    'keep_uid', p_keep_uid,
    'dropped', cardinality(p_drop_uids),
    'merged_credits', v_moved_credits,
    'merged_conversations', v_moved_convs,
    'merged_image_generations', v_moved_imgs,
    'merged_tasks', v_moved_tasks,
    'merged_credits_history', v_moved_credits_hist,
    'merged_mappings', v_moved_mappings
  );
END;
$$;


ALTER FUNCTION public.merge_wecom_duplicate_users(p_keep_uid uuid, p_drop_uids uuid[]) OWNER TO everydayai;

--
-- Name: FUNCTION merge_wecom_duplicate_users(p_keep_uid uuid, p_drop_uids uuid[]); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.merge_wecom_duplicate_users(p_keep_uid uuid, p_drop_uids uuid[]) IS '合并重复 wecom 用户：drop_uids 的所有 FK 引用迁到 keep_uid，累加积分';


--
-- Name: partial_refund_credits(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.partial_refund_credits(p_user_id uuid, p_refund_amount integer, p_description text DEFAULT ''::text, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_new_balance INTEGER;
BEGIN
    IF p_refund_amount <= 0 THEN
        RETURN jsonb_build_object('refunded', false, 'reason', 'zero_or_negative');
    END IF;

    UPDATE users
    SET credits = credits + p_refund_amount,
        updated_at = NOW()
    WHERE id = p_user_id
    RETURNING credits INTO v_new_balance;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('refunded', false, 'reason', 'user_not_found');
    END IF;

    INSERT INTO credits_history (user_id, change_type, change_amount, balance_after, description, org_id)
    VALUES (p_user_id, 'partial_refund'::credits_change_type, p_refund_amount, v_new_balance, p_description, p_org_id);

    RETURN jsonb_build_object('refunded', true, 'new_balance', v_new_balance, 'amount', p_refund_amount);
END;
$$;


ALTER FUNCTION public.partial_refund_credits(p_user_id uuid, p_refund_amount integer, p_description text, p_org_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION partial_refund_credits(p_user_id uuid, p_refund_amount integer, p_description text, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.partial_refund_credits(p_user_id uuid, p_refund_amount integer, p_description text, p_org_id uuid) IS '按量计费差额退回（定时任务等场景，含多租户 org_id）';


--
-- Name: pause_generation_turn_owned(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.pause_generation_turn_owned(p_task_id uuid, p_execution_token uuid, p_reason text DEFAULT 'user_paused'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_conversation conversations%ROWTYPE;
    v_snapshot JSONB;
    v_checkpoint conversation_turn_checkpoints%ROWTYPE;
    v_output_context_revision BIGINT;
    v_closed_revision BIGINT;
BEGIN
    IF p_task_id IS NULL OR p_execution_token IS NULL THEN
        RAISE EXCEPTION 'ACTOR_PAUSE_OWNER_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_PAUSE_OWNER_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_conversation FROM conversations
     WHERE id = v_task.conversation_id FOR UPDATE;
    IF NOT FOUND OR v_conversation.org_id IS DISTINCT FROM v_task.org_id THEN
        RAISE EXCEPTION 'ACTOR_PAUSE_OWNER_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_task.status = 'paused' THEN
        RETURN jsonb_build_object('outcome', 'already_paused', 'task_id', p_task_id);
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    SELECT * INTO v_checkpoint FROM conversation_turn_checkpoints
     WHERE task_id = p_task_id AND status = 'ready' FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ACTOR_PAUSE_CHECKPOINT_MISSING' USING ERRCODE = '55000';
    END IF;

    v_snapshot := public.materialize_actor_pause_snapshot(p_task_id);
    SELECT context_revision INTO v_output_context_revision FROM messages
     WHERE id = v_task.assistant_message_id FOR UPDATE;
    IF v_output_context_revision IS NULL THEN
        v_closed_revision := v_conversation.context_revision + 1;
        UPDATE messages SET context_revision = v_closed_revision, message_kind = 'conversation'
         WHERE id = v_task.input_message_id
           AND conversation_id = v_task.conversation_id AND context_revision IS NULL;
        UPDATE messages SET context_revision = v_closed_revision, message_kind = 'conversation'
         WHERE id = v_task.assistant_message_id
           AND conversation_id = v_task.conversation_id AND context_revision IS NULL;
        UPDATE conversations SET context_revision = v_closed_revision,
            last_closed_message_id = v_task.assistant_message_id, actor_updated_at = NOW()
         WHERE id = v_conversation.id;
    ELSE
        v_closed_revision := v_output_context_revision;
    END IF;

    UPDATE conversation_turn_checkpoints SET status = 'paused', updated_at = NOW()
     WHERE task_id = p_task_id AND version = v_checkpoint.version;
    UPDATE conversation_control_events SET status = 'applied',
        applied_execution_token = p_execution_token, applied_at = NOW()
     WHERE task_id = p_task_id AND dedupe_key = 'pause:' || p_task_id::TEXT
       AND status = 'pending';
    UPDATE tasks SET status = 'paused',
        error_message = COALESCE(NULLIF(BTRIM(p_reason), ''), '用户暂停了任务'),
        execution_token = NULL, lease_expires_at = NULL, terminal_reason = 'user_paused'
     WHERE id = p_task_id;
    UPDATE conversations SET active_serial_task_id = NULL, actor_updated_at = NOW()
     WHERE id = v_task.conversation_id AND active_serial_task_id = p_task_id;
    RETURN jsonb_build_object(
        'outcome', 'paused', 'task_id', p_task_id,
        'checkpoint_version', v_checkpoint.version,
        'closed_revision', v_closed_revision,
        'snapshot_saved', COALESCE((v_snapshot->>'saved')::BOOLEAN, FALSE)
    );
END;
$$;


ALTER FUNCTION public.pause_generation_turn_owned(p_task_id uuid, p_execution_token uuid, p_reason text) OWNER TO everydayai;

--
-- Name: persist_ecom_plan_format_state(uuid, uuid, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.persist_ecom_plan_format_state(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_expected_draft jsonb, p_draft jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE;
BEGIN
 p=public.lock_ecom_format_plan(p_plan_id);
 IF p_stage NOT BETWEEN 1 AND 3 OR p_stage IS NULL OR jsonb_typeof(p_draft) IS DISTINCT FROM 'object'
  OR p_draft->>'format_version' IS DISTINCT FROM 'ecom-format.v1' THEN
  RAISE EXCEPTION 'ECOM_PLAN_DRAFT_INVALID' USING ERRCODE='22023'; END IF;
 IF p.status IS DISTINCT FROM 'planning' OR p.current_stage IS DISTINCT FROM p_stage
  OR p.lease_token IS DISTINCT FROM p_lease_token OR p_lease_token IS NULL
  OR p.lease_expires_at IS NULL OR p.lease_expires_at<=NOW() THEN
  RAISE EXCEPTION 'ECOM_PLAN_LEASE_LOST' USING ERRCODE='55000'; END IF;
 IF p.stage_drafts->p_stage::text IS DISTINCT FROM p_expected_draft THEN
  RAISE EXCEPTION 'ECOM_PLAN_DRAFT_CONFLICT' USING ERRCODE='22023'; END IF;
 UPDATE public.ecom_image_plans SET stage_drafts=jsonb_set(stage_drafts,ARRAY[p_stage::text],p_draft),
  updated_at=NOW() WHERE id=p.id;
 RETURN jsonb_build_object('outcome','saved','draft_fingerprint',md5(p_draft::text));
END $$;


ALTER FUNCTION public.persist_ecom_plan_format_state(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_expected_draft jsonb, p_draft jsonb) OWNER TO everydayai_owner;

--
-- Name: publish_chat_image_result(uuid, jsonb, text, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.publish_chat_image_result(p_task_id uuid, p_content jsonb, p_status text, p_error text DEFAULT ''::text, p_platform_pays boolean DEFAULT false, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_task public.tasks%ROWTYPE; v_lifecycle JSONB; v_snapshot JSONB;
    v_tx public.credit_transactions%ROWTYPE; v_revision BIGINT; v_conv UUID;
    v_message public.messages%ROWTYPE; v_cost INTEGER:=0; v_balance INTEGER;
    v_trial_id UUID; v_trial RECORD; v_project_id UUID;
BEGIN
    PERFORM public.assert_chat_image_worker(p_org_id);
    IF p_platform_pays IS NULL OR p_status IS NULL OR p_status NOT IN ('completed','failed','cancelled')
       OR p_content IS NULL OR jsonb_typeof(p_content)<>'array' OR jsonb_array_length(p_content)<>1 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_PUBLICATION_INVALID' USING ERRCODE='22023';
    END IF;
    SELECT conversation_id,(request_params->'_media_request_v1'->'origin'->>'trial_id')::UUID,
 (request_params->'_media_request_v1'->'origin'->>'project_id')::UUID INTO v_conv,v_trial_id,v_project_id
        FROM public.tasks WHERE id=p_task_id AND type='image'
        AND org_id IS NOT DISTINCT FROM p_org_id AND request_params ? '_media_request_v1';
    IF NOT FOUND THEN RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE='42501'; END IF;
    -- Same ordering as Actor publication: conversation before output/task rows.
    IF v_project_id IS NOT NULL THEN
        PERFORM 1 FROM public.detail_projects WHERE id=v_project_id AND org_id IS NOT DISTINCT FROM p_org_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'DETAIL_PROJECT_DENIED' USING ERRCODE='42501'; END IF;
    ELSIF v_trial_id IS NULL THEN
        SELECT context_revision INTO v_revision FROM public.conversations WHERE id=v_conv FOR UPDATE;
    ELSE
        SELECT * INTO v_trial FROM public.skill_draft_trial_runs WHERE id=v_trial_id AND org_id=p_org_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'CHAT_IMAGE_TRIAL_DENIED' USING ERRCODE='42501'; END IF;
    END IF;
    SELECT * INTO v_task FROM public.tasks WHERE id=p_task_id FOR UPDATE;
    v_snapshot:=v_task.request_params->'_media_request_v1';
    v_lifecycle:=v_task.request_params->'_media_lifecycle_v1';
    IF v_project_id IS NOT NULL THEN
        IF v_snapshot->'origin'->>'destination' IS DISTINCT FROM 'detail_project' OR NOT EXISTS(
            SELECT 1 FROM public.detail_projects d WHERE d.id=v_project_id AND d.user_id=v_task.user_id
            AND d.org_id IS NOT DISTINCT FROM p_org_id AND d.run_state->>'run_id'=v_snapshot->'origin'->>'generation_run_id') THEN
            RAISE EXCEPTION 'DETAIL_PROJECT_DENIED' USING ERRCODE='42501';
        END IF;
    ELSIF v_trial_id IS NULL THEN
        SELECT * INTO v_message FROM public.messages WHERE id=v_task.assistant_message_id FOR UPDATE;
        IF FOUND AND v_lifecycle->>'phase'='published'
           AND v_message.generation_params->>'task_id' IS DISTINCT FROM p_task_id::TEXT THEN
            RETURN jsonb_build_object('outcome','superseded','message_id',v_message.id);
        END IF;
        IF NOT FOUND OR v_message.conversation_id IS DISTINCT FROM v_conv
       OR v_message.generation_params->>'task_id' IS DISTINCT FROM p_task_id::TEXT
       OR v_message.generation_params->>'origin' IS DISTINCT FROM 'chat_image' THEN
            RAISE EXCEPTION 'CHAT_IMAGE_TARGET_DENIED' USING ERRCODE='42501';
        END IF;
    ELSIF v_snapshot->'origin'->>'destination' IS DISTINCT FROM 'skill_trial'
        OR v_trial.actor_user_id IS DISTINCT FROM v_task.user_id
        OR v_trial.result->>'image_task_id' IS DISTINCT FROM p_task_id::TEXT THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TRIAL_DENIED' USING ERRCODE='42501';
    END IF;
    IF v_lifecycle->>'phase'='published' THEN
        RETURN jsonb_build_object('outcome','replay','message_id',v_message.id,'revision',v_message.context_revision);
    END IF;
    IF p_platform_pays THEN
        IF v_lifecycle->>'phase' IS DISTINCT FROM 'uncertain' OR p_status<>'failed'
           OR (v_lifecycle->>'uncertain_deadline')::TIMESTAMPTZ IS NULL
           OR (v_lifecycle->>'uncertain_deadline')::TIMESTAMPTZ > NOW() THEN
            RAISE EXCEPTION 'CHAT_IMAGE_UNCERTAIN_NOT_DUE' USING ERRCODE='55000';
        END IF;
    ELSIF v_lifecycle->>'phase' IS DISTINCT FROM 'settling' THEN
        RAISE EXCEPTION 'CHAT_IMAGE_NOT_SETTLING' USING ERRCODE='55000';
    END IF;
    -- Prelock user before ledger, compatible with submission and legacy refunds.
    PERFORM 1 FROM public.users WHERE id=v_task.user_id FOR UPDATE;
    IF v_task.credit_transaction_id IS NOT NULL THEN
        SELECT * INTO v_tx FROM public.credit_transactions WHERE id=v_task.credit_transaction_id FOR UPDATE;
        IF NOT FOUND OR v_tx.task_id IS DISTINCT FROM p_task_id OR v_tx.user_id IS DISTINCT FROM v_task.user_id
           OR v_tx.org_id IS DISTINCT FROM p_org_id THEN
            RAISE EXCEPTION 'CHAT_IMAGE_LEDGER_DENIED' USING ERRCODE='42501';
        END IF;
        IF p_status='completed' THEN
            IF v_tx.status NOT IN ('pending','confirmed') THEN
                RAISE EXCEPTION 'CHAT_IMAGE_LEDGER_ALREADY_REFUNDED' USING ERRCODE='55000';
            END IF;
            UPDATE public.credit_transactions SET status='confirmed',confirmed_at=NOW()
                WHERE id=v_tx.id AND status='pending';
            v_cost:=v_tx.amount;
        ELSE
            IF v_tx.status NOT IN ('pending','refunded') THEN
                RAISE EXCEPTION 'CHAT_IMAGE_LEDGER_NOT_REFUNDABLE' USING ERRCODE='55000';
            END IF;
            PERFORM public.atomic_refund_credits(v_tx.id);
            IF NOT EXISTS(SELECT 1 FROM public.credit_transactions WHERE id=v_tx.id AND status='refunded') THEN
                RAISE EXCEPTION 'CHAT_IMAGE_REFUND_NOT_CONFIRMED' USING ERRCODE='55000';
            END IF;
        END IF;
    ELSIF p_status='completed' OR p_platform_pays OR v_task.result->>'status'='success' THEN
        RAISE EXCEPTION 'CHAT_IMAGE_LEDGER_MISSING' USING ERRCODE='55000';
    END IF;
    IF v_project_id IS NOT NULL THEN
        UPDATE public.detail_projects SET updated_at=NOW() WHERE id=v_project_id;
    ELSIF v_trial_id IS NOT NULL THEN
        UPDATE public.skill_draft_trial_runs SET status=CASE WHEN p_status='completed' THEN 'completed' ELSE 'failed' END,
            completed_at=NOW(),result=result || jsonb_build_object('status',p_status,
                'images',CASE WHEN p_status='completed' THEN p_content ELSE '[]'::JSONB END,
                'error',p_error,'credits_charged',v_cost,'submission_state','published') WHERE id=v_trial_id;
    ELSE
        v_revision:=COALESCE(v_revision,0)+1;
        UPDATE public.messages SET content=p_content::TEXT,status=CASE WHEN p_status='completed' THEN 'completed' ELSE 'failed' END,
        credits_cost=v_cost,context_revision=v_revision,
        generation_params=generation_params || jsonb_build_object('type','image','model',v_snapshot->>'model',
            'source_task_id',v_snapshot->>'source_task_id','num_images',1)
        WHERE id=v_message.id;
        UPDATE public.conversations SET context_revision=v_revision WHERE id=v_conv;
    END IF;
    -- Deliberately do not modify input message, closed parent Turn or sidebar preview.
    UPDATE public.tasks SET status=p_status,completed_at=NOW(),credits_used=v_cost,error_message=LEFT(p_error,2000),
        result_data=p_content->0,request_params=jsonb_set(request_params,'{_media_lifecycle_v1}',
            v_lifecycle || jsonb_build_object('phase','published','delivery_pending',TRUE,'published_at',NOW()))
        || CASE WHEN p_platform_pays OR (p_status='failed' AND v_task.result->>'status'='success') THEN jsonb_build_object('_media_platform_cost_v1',jsonb_build_object(
            'reason',CASE WHEN p_platform_pays THEN 'submission_uncertain_expired' ELSE 'image_output_contract_failure' END,
            'refunded_user_credits',COALESCE(v_tx.amount,0),
            'estimated_provider_credits',(v_snapshot->>'estimated_provider_credits')::INTEGER,
            'evidence',CASE WHEN p_platform_pays THEN 'unconfirmed' ELSE 'provider_success_unbilled' END,
            'recorded_at',NOW(),'model',v_snapshot->>'model',
            'resolution',v_snapshot->>'resolution')) ELSE '{}'::JSONB END,
        version=COALESCE(version,0)+1 WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','published','message_id',v_message.id,'revision',v_revision);
END;
$$;


ALTER FUNCTION public.publish_chat_image_result(p_task_id uuid, p_content jsonb, p_status text, p_error text, p_platform_pays boolean, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: publish_conversation_subtask_completion(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.publish_conversation_subtask_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_link conversation_subtask_links%ROWTYPE;
    v_parent tasks%ROWTYPE;
    v_status TEXT;
    v_event_status TEXT;
BEGIN
    IF OLD.status IS NOT DISTINCT FROM NEW.status
       OR NEW.status NOT IN ('completed', 'failed', 'cancelled') THEN
        RETURN NEW;
    END IF;

    SELECT * INTO v_link
      FROM conversation_subtask_links
     WHERE child_task_id = NEW.id
     FOR UPDATE;
    IF NOT FOUND OR v_link.status <> 'pending' THEN
        RETURN NEW;
    END IF;

    v_status := CASE NEW.status
        WHEN 'completed' THEN 'completed'
        WHEN 'failed' THEN 'failed'
        ELSE 'cancelled'
    END;
    SELECT * INTO v_parent FROM tasks WHERE id = v_link.parent_task_id FOR UPDATE;
    v_event_status := CASE
        WHEN v_parent.status = 'running' THEN 'pending'
        ELSE 'ignored'
    END;

    UPDATE conversation_subtask_links
       SET status = v_status,
           result = COALESCE(NEW.result, '{}'::JSONB),
           error_message = LEFT(COALESCE(NEW.error_message, ''), 2000),
           completed_at = NOW()
     WHERE id = v_link.id;

    INSERT INTO conversation_control_events(
        conversation_id, task_id, turn_id, event_type, dedupe_key, payload,
        status, applied_at
    ) VALUES (
        v_link.parent_conversation_id, v_link.parent_task_id,
        v_parent.turn_id, 'subtask_completed',
        'subtask:' || NEW.id::TEXT,
        jsonb_build_object(
            'child_task_id', NEW.id,
            'parent_command_id', v_link.parent_command_id,
            'status', v_status,
            'result', COALESCE(NEW.result, '{}'::JSONB),
            'error_message', COALESCE(NEW.error_message, '')
        ),
        v_event_status,
        CASE WHEN v_event_status = 'ignored' THEN NOW() ELSE NULL END
    ) ON CONFLICT (task_id, dedupe_key) DO NOTHING;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.publish_conversation_subtask_completion() OWNER TO everydayai;

--
-- Name: reach_active_member(uuid, boolean); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.reach_active_member(p_org uuid, p_admin boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT p_org=NULLIF(current_setting('app.org_id',TRUE),'')::uuid AND NULLIF(current_setting('app.actor_user_id',TRUE),'')::uuid IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.org_members m
        JOIN public.organizations o ON o.id=m.org_id JOIN public.users u ON u.id=m.user_id
        WHERE m.org_id=p_org AND m.user_id=NULLIF(current_setting('app.actor_user_id',TRUE),'')::uuid
        AND m.status='active' AND o.status='active' AND u.status='active'
        AND (NOT p_admin OR m.role IN ('owner','admin')))
$$;


ALTER FUNCTION public.reach_active_member(p_org uuid, p_admin boolean) OWNER TO everydayai_owner;

--
-- Name: reach_budget_visible(text, boolean); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.reach_budget_visible(p_key text, p_admin boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM reach_connections c WHERE c.status='active'
 AND public.reach_active_member(c.org_id,p_admin)
 AND encode(sha256(convert_to(c.platform||':'||c.account_id,'UTF8')),'hex')=p_key)
$$;


