--
-- Name: read_conversation_control_commands(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.read_conversation_control_commands(p_task_id uuid, p_execution_token uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
BEGIN
    IF p_task_id IS NULL
       OR p_execution_token IS NULL
       OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION 'ACTOR_CONTROL_READ_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat' THEN
        RAISE EXCEPTION 'ACTOR_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN '[]'::JSONB;
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RAISE EXCEPTION 'ACTOR_CONTROL_READ_OWNERSHIP_LOST'
            USING ERRCODE = '42501';
    END IF;

    RETURN COALESCE(
        (
            SELECT jsonb_agg(to_jsonb(pending_events)
                             ORDER BY pending_events.event_sequence,
                                      pending_events.id)
              FROM (
                  SELECT id, conversation_id, task_id, turn_id,
                         event_type, payload, event_sequence
                    FROM conversation_control_events
                   WHERE task_id = p_task_id
                     AND status = 'pending'
                   ORDER BY event_sequence, id
                   LIMIT p_limit
              ) AS pending_events
        ),
        '[]'::JSONB
    );
END;
$$;


ALTER FUNCTION public.read_conversation_control_commands(p_task_id uuid, p_execution_token uuid, p_limit integer) OWNER TO everydayai;

--
-- Name: FUNCTION read_conversation_control_commands(p_task_id uuid, p_execution_token uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.read_conversation_control_commands(p_task_id uuid, p_execution_token uuid, p_limit integer) IS '仅当前 running task 的 fencing owner 可读取待处理控制事件';


--
-- Name: read_conversation_delivery_state(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.read_conversation_delivery_state(p_task_id uuid, p_user_id uuid, p_last_seq bigint DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_session conversation_delivery_sessions%ROWTYPE;
BEGIN
    IF p_task_id IS NULL OR p_user_id IS NULL OR p_last_seq < 0 THEN
        RAISE EXCEPTION 'DELIVERY_STATE_READ_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks
     WHERE id = p_task_id AND user_id = p_user_id;
    IF NOT FOUND OR v_task.type <> 'chat' THEN
        RETURN jsonb_build_object('outcome', 'not_found');
    END IF;
    SELECT * INTO v_session FROM conversation_delivery_sessions
     WHERE task_id = p_task_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'outcome', 'empty', 'task_status', v_task.status,
            'snapshot_content', COALESCE(v_task.accumulated_content, ''),
            'snapshot_blocks', COALESCE(v_task.accumulated_blocks, '[]'::JSONB)
        );
    END IF;
    RETURN jsonb_build_object(
        'outcome', 'found',
        'task_status', v_task.status,
        'session_id', v_session.id,
        'stream_id', v_session.stream_id,
        'execution_attempt', v_session.execution_attempt,
        'delivery_status', v_session.status,
        'next_seq', v_session.next_seq,
        'snapshot_seq', v_session.snapshot_seq,
        'snapshot_content', v_session.snapshot_content,
        'snapshot_blocks', v_session.snapshot_blocks,
        'events', COALESCE((
            SELECT jsonb_agg(to_jsonb(event_row) ORDER BY event_row.delivery_seq)
              FROM (
                  SELECT delivery_seq, event_type, payload
                   FROM conversation_delivery_events
                   WHERE session_id = v_session.id
                     AND delivery_seq > GREATEST(p_last_seq, v_session.snapshot_seq)
                   ORDER BY delivery_seq
                   LIMIT 500
              ) event_row
        ), '[]'::JSONB)
    );
END;
$$;


ALTER FUNCTION public.read_conversation_delivery_state(p_task_id uuid, p_user_id uuid, p_last_seq bigint) OWNER TO everydayai;

--
-- Name: record_change_check(uuid, uuid, uuid, text, text, text, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.record_change_check(p_check_id uuid, p_change_set_id uuid, p_org_id uuid, p_check_type text, p_check_key text, p_status text, p_input jsonb, p_result jsonb, p_actor_id text, p_actor_type text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_check public.change_checks%ROWTYPE;
    v_set public.change_sets%ROWTYPE;
    v_sequence BIGINT;
BEGIN
    SELECT * INTO v_set
      FROM public.change_sets
     WHERE id = p_change_set_id AND org_id = p_org_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'missing');
    END IF;

    INSERT INTO public.change_checks(
        id, change_set_id, org_id, check_type, check_key, input, result,
        status, actor_id, actor_type, finished_at
    ) VALUES (
        p_check_id, p_change_set_id, p_org_id, p_check_type, p_check_key,
        COALESCE(p_input, '{}'::JSONB), COALESCE(p_result, '{}'::JSONB),
        p_status, p_actor_id, p_actor_type,
        CASE WHEN p_status IN ('passed', 'failed', 'skipped') THEN NOW() ELSE NULL END
    ) RETURNING * INTO v_check;

    SELECT COALESCE(MAX(sequence), 0) + 1 INTO v_sequence
      FROM public.change_events WHERE change_set_id = p_change_set_id;
    INSERT INTO public.change_events(
        change_set_id, org_id, sequence, event_type, actor_id, actor_type, payload
    ) VALUES (
        p_change_set_id, p_org_id, v_sequence, 'check.' || p_check_type,
        p_actor_id, p_actor_type,
        jsonb_build_object('check_id', v_check.id, 'check_key', p_check_key, 'status', p_status, 'result', COALESCE(p_result, '{}'::JSONB))
    );
    RETURN jsonb_build_object('outcome', 'recorded', 'check', to_jsonb(v_check));
END;
$$;


ALTER FUNCTION public.record_change_check(p_check_id uuid, p_change_set_id uuid, p_org_id uuid, p_check_type text, p_check_key text, p_status text, p_input jsonb, p_result jsonb, p_actor_id text, p_actor_type text) OWNER TO everydayai;

--
-- Name: record_chat_image_provider_result(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.record_chat_image_provider_result(p_task_id uuid, p_result jsonb, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_task public.tasks%ROWTYPE; v_lifecycle JSONB;
BEGIN
    PERFORM public.assert_chat_image_worker(p_org_id);
    IF p_result IS NULL OR jsonb_typeof(p_result)<>'object'
       OR COALESCE(p_result->>'status','') NOT IN ('success','failed') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_RESULT_INVALID' USING ERRCODE='22023';
    END IF;
    SELECT * INTO v_task FROM public.tasks WHERE id=p_task_id AND type='image'
        AND org_id IS NOT DISTINCT FROM p_org_id FOR UPDATE;
    IF NOT FOUND OR NOT (v_task.request_params ? '_media_request_v1') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE='42501';
    END IF;
    v_lifecycle:=v_task.request_params->'_media_lifecycle_v1';
    IF v_lifecycle->>'phase' IN ('settling','published') THEN
        RETURN jsonb_build_object('outcome','replay');
    END IF;
    IF COALESCE(v_lifecycle->>'phase','') NOT IN ('queued','submitting','accepted','uncertain') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_STATE_INVALID' USING ERRCODE='55000';
    END IF;
    -- Only a definite supplier result can override uncertainty. An error before
    -- dispatch is also definite; callers never feed a network timeout here.
    UPDATE public.tasks SET result=p_result,
        request_params=jsonb_set(request_params,'{_media_lifecycle_v1}',v_lifecycle ||
            jsonb_build_object('phase','settling','provider_finished_at',NOW())),
        version=COALESCE(version,0)+1 WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','settling');
END;
$$;


ALTER FUNCTION public.record_chat_image_provider_result(p_task_id uuid, p_result jsonb, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: record_org_mcp_connector_health(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.record_org_mcp_connector_health(p_org_id uuid, p_connector_id text, p_health_status text, p_error_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public._assert_configuration_runtime_actor(TRUE);
    v_state public.organization_mcp_connectors%ROWTYPE;
BEGIN
    IF p_org_id IS DISTINCT FROM public.tenant_org_id()
       OR p_connector_id IS DISTINCT FROM 'test-readonly'
       OR p_health_status IS NULL
       OR p_health_status NOT IN ('ready', 'error')
       OR (p_error_code IS NOT NULL AND p_error_code NOT IN (
           'MCP_AUTH_FAILED', 'MCP_CREDENTIAL_UNAVAILABLE', 'MCP_HEALTH_FAILED',
           'MCP_REMOTE_ERROR', 'MCP_PROTOCOL_ERROR', 'MCP_RESULT_INVALID',
           'MCP_SCHEMA_NOT_REVIEWED', 'MCP_TIMEOUT', 'MCP_TOOL_ERROR',
           'MCP_UNAVAILABLE', 'MCP_CANCELLED'
       )) THEN
        RAISE EXCEPTION 'MCP_HEALTH_FACT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.organization_mcp_connectors(
        org_id, connector_id, enabled, health_status,
        last_checked_at, last_error_code, updated_by, updated_at
    ) VALUES (
        p_org_id, p_connector_id, FALSE, p_health_status,
        NOW(), p_error_code, v_actor, NOW()
    )
    ON CONFLICT (org_id, connector_id) DO UPDATE SET
        health_status = EXCLUDED.health_status,
        last_checked_at = NOW(),
        last_error_code = EXCLUDED.last_error_code,
        updated_by = EXCLUDED.updated_by,
        updated_at = NOW()
    RETURNING * INTO v_state;
    RETURN jsonb_build_object(
        'org_id', p_org_id, 'connector_id', p_connector_id,
        'enabled', v_state.enabled,
        'state', CASE
            WHEN NOT v_state.enabled THEN 'disabled'
            WHEN v_state.health_status = 'ready' THEN 'ready'
            ELSE 'error'
        END,
        'health_status', v_state.health_status,
        'last_checked_at', v_state.last_checked_at,
        'last_error_code', v_state.last_error_code,
        'updated_at', v_state.updated_at
    );
END;
$$;


ALTER FUNCTION public.record_org_mcp_connector_health(p_org_id uuid, p_connector_id text, p_health_status text, p_error_code text) OWNER TO everydayai_owner;

--
-- Name: record_user_activity(uuid, text, uuid, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.record_user_activity(p_user_id uuid, p_event_type text, p_org_id uuid DEFAULT NULL::uuid, p_source text DEFAULT 'web'::text, p_resource_type text DEFAULT NULL::text, p_resource_id text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now(), p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO user_activity_events (
    user_id, org_id, event_type, source, resource_type,
    resource_id, occurred_at, metadata
  ) VALUES (
    p_user_id, p_org_id, p_event_type, p_source, p_resource_type,
    p_resource_id, COALESCE(p_occurred_at, NOW()), COALESCE(p_metadata, '{}'::jsonb)
  );

  UPDATE users
  SET last_active_at = (
    SELECT MAX(v)
    FROM (VALUES (users.last_active_at), (COALESCE(p_occurred_at, NOW()))) AS t(v)
    WHERE v IS NOT NULL
  )
  WHERE id = p_user_id;
END;
$$;


ALTER FUNCTION public.record_user_activity(p_user_id uuid, p_event_type text, p_org_id uuid, p_source text, p_resource_type text, p_resource_id text, p_occurred_at timestamp with time zone, p_metadata jsonb) OWNER TO everydayai;

--
-- Name: refresh_scheduled_task_run_push_status(uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.refresh_scheduled_task_run_push_status(p_run_id uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_total INTEGER;
    v_pending INTEGER;
    v_delivered INTEGER;
    v_dead INTEGER;
    v_status TEXT;
BEGIN
    SELECT
        COUNT(*),
        COUNT(*) FILTER (WHERE status IN ('pending', 'delivering')),
        COUNT(*) FILTER (WHERE status = 'delivered'),
        COUNT(*) FILTER (WHERE status = 'dead')
      INTO v_total, v_pending, v_delivered, v_dead
      FROM scheduled_task_deliveries
     WHERE run_id = p_run_id
       AND delivery_kind = 'result';

    v_status := CASE
        WHEN v_total = 0 THEN 'skipped'
        WHEN v_pending > 0 AND v_delivered = 0 THEN 'queued'
        WHEN v_pending > 0 THEN 'retrying'
        WHEN v_dead = 0 THEN 'pushed'
        WHEN v_delivered = 0 THEN 'push_failed'
        ELSE 'partial'
    END;

    UPDATE scheduled_task_runs
       SET push_status = v_status
     WHERE id = p_run_id;
    RETURN v_status;
END;
$$;


ALTER FUNCTION public.refresh_scheduled_task_run_push_status(p_run_id uuid) OWNER TO everydayai;

--
-- Name: register_conversation_subtask(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.register_conversation_subtask(p_parent_task_id uuid, p_parent_execution_token uuid, p_parent_command_id text, p_child_task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_parent tasks%ROWTYPE;
    v_child tasks%ROWTYPE;
    v_link conversation_subtask_links%ROWTYPE;
    v_inserted_count BIGINT;
BEGIN
    IF p_parent_task_id IS NULL OR p_parent_execution_token IS NULL
       OR p_child_task_id IS NULL
       OR NULLIF(BTRIM(p_parent_command_id), '') IS NULL THEN
        RAISE EXCEPTION 'ACTOR_SUBTASK_REGISTER_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_parent FROM tasks WHERE id = p_parent_task_id FOR UPDATE;
    SELECT * INTO v_child FROM tasks WHERE id = p_child_task_id FOR UPDATE;
    IF NOT FOUND OR v_parent.id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_SUBTASK_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_parent.type <> 'chat'
       OR v_parent.status <> 'running'
       OR v_parent.execution_token IS DISTINCT FROM p_parent_execution_token
       OR NOT (v_parent.delivery_context @> '{"actor": true}'::JSONB)
       OR v_child.id IS NULL
       OR v_child.type <> 'chat'
       OR v_child.status NOT IN ('pending', 'running')
       OR NOT (v_child.delivery_context @> '{"actor": true}'::JSONB)
       OR v_child.user_id IS DISTINCT FROM v_parent.user_id
       OR v_child.org_id IS DISTINCT FROM v_parent.org_id THEN
        RAISE EXCEPTION 'ACTOR_SUBTASK_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    INSERT INTO conversation_subtask_links(
        parent_task_id, parent_conversation_id, child_task_id, parent_command_id
    ) VALUES (
        p_parent_task_id, v_parent.conversation_id, p_child_task_id,
        BTRIM(p_parent_command_id)
    )
    ON CONFLICT (parent_task_id, parent_command_id) DO NOTHING;
    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

    SELECT * INTO v_link
      FROM conversation_subtask_links
     WHERE parent_task_id = p_parent_task_id
       AND parent_command_id = BTRIM(p_parent_command_id);
    IF v_link.child_task_id IS DISTINCT FROM p_child_task_id THEN
        RAISE EXCEPTION 'ACTOR_SUBTASK_COMMAND_REUSE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    RETURN jsonb_build_object(
        'outcome', 'registered',
        'link_id', v_link.id,
        'already_registered', v_inserted_count = 0
    );
END;
$$;


ALTER FUNCTION public.register_conversation_subtask(p_parent_task_id uuid, p_parent_execution_token uuid, p_parent_command_id text, p_child_task_id uuid) OWNER TO everydayai;

--
-- Name: register_user_asset(uuid, text, text, text, text, text, text, text, text, text, text, text, bigint, text, jsonb, text, uuid, text, text, text, uuid, uuid, uuid, uuid, uuid, integer, text, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.register_user_asset(p_org_id uuid, p_storage_scope text, p_storage_owner_key text, p_storage_provider text, p_storage_key text, p_media_type text, p_original_url text, p_thumbnail_url text, p_download_url text, p_workspace_path text, p_name text, p_mime_type text, p_size bigint, p_content_sha256 text, p_asset_metadata jsonb, p_ref_key text, p_actor_user_id uuid, p_source_type text, p_source_kind text, p_ref_kind text, p_conversation_id uuid, p_source_message_id uuid, p_source_task_id uuid, p_source_generation_id uuid, p_source_attachment_id uuid, p_content_index integer, p_model_id text, p_prompt text, p_ref_metadata jsonb, p_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_asset_result JSONB;
    v_ref_result JSONB;
    v_asset_id UUID;
BEGIN
    IF p_storage_scope IS NULL
       OR p_storage_scope NOT IN ('user', 'channel')
       OR p_storage_provider IS NULL
       OR p_storage_provider NOT IN ('workspace', 'oss')
       OR p_media_type IS NULL
       OR p_media_type NOT IN ('image', 'video', 'file')
       OR p_source_type IS NULL
       OR p_source_type NOT IN ('upload', 'generated')
       OR p_source_kind IS NULL
       OR p_source_kind NOT IN (
           'web_upload', 'wecom_upload', 'image_task', 'video_task',
           'media_tool', 'ecom_image'
       )
       OR p_ref_kind IS NULL
       OR p_ref_kind NOT IN (
           'upload', 'task', 'message', 'image_generation', 'attachment'
       )
       OR p_storage_owner_key IS NULL
       OR (
           p_storage_scope = 'user'
           AND p_storage_owner_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       )
       OR (
           p_storage_scope = 'channel'
           AND p_storage_owner_key !~ '^channels/wecom/[0-9a-f]{24}$'
       )
       OR p_actor_user_id IS NULL
       OR COALESCE(BTRIM(p_storage_key), '') = ''
       OR COALESCE(BTRIM(p_original_url), '') = ''
       OR COALESCE(BTRIM(p_download_url), '') = ''
       OR COALESCE(BTRIM(p_name), '') = ''
       OR COALESCE(BTRIM(p_ref_key), '') = ''
       OR (p_size IS NOT NULL AND p_size < 0)
       OR (
           p_content_sha256 IS NOT NULL
           AND p_content_sha256 !~ '^[0-9a-f]{64}$'
       )
       OR (p_content_index IS NOT NULL AND p_content_index < 0)
    THEN
        RAISE EXCEPTION 'USER_ASSET_INVALID_INPUT';
    END IF;

    v_asset_result := _resolve_user_asset(
        p_org_id, p_storage_scope, p_storage_owner_key, p_storage_provider,
        p_storage_key, p_media_type, p_original_url, p_thumbnail_url,
        p_download_url, p_workspace_path, p_name, p_mime_type, p_size,
        p_content_sha256, p_asset_metadata, p_created_at
    );
    v_asset_id := (v_asset_result->'asset'->>'id')::UUID;
    v_ref_result := _bind_user_asset_ref(
        v_asset_id, p_ref_key, p_actor_user_id, p_org_id, p_source_type,
        p_source_kind, p_ref_kind, p_conversation_id, p_source_message_id,
        p_source_task_id, p_source_generation_id, p_source_attachment_id,
        p_content_index, p_model_id, p_prompt, p_ref_metadata, p_created_at
    );

    RETURN jsonb_build_object(
        'asset', v_asset_result->'asset',
        'ref', v_ref_result->'ref',
        'asset_created', (v_asset_result->>'created')::BOOLEAN,
        'ref_created', (v_ref_result->>'created')::BOOLEAN
    );
END
$_$;


ALTER FUNCTION public.register_user_asset(p_org_id uuid, p_storage_scope text, p_storage_owner_key text, p_storage_provider text, p_storage_key text, p_media_type text, p_original_url text, p_thumbnail_url text, p_download_url text, p_workspace_path text, p_name text, p_mime_type text, p_size bigint, p_content_sha256 text, p_asset_metadata jsonb, p_ref_key text, p_actor_user_id uuid, p_source_type text, p_source_kind text, p_ref_kind text, p_conversation_id uuid, p_source_message_id uuid, p_source_task_id uuid, p_source_generation_id uuid, p_source_attachment_id uuid, p_content_index integer, p_model_id text, p_prompt text, p_ref_metadata jsonb, p_created_at timestamp with time zone) OWNER TO everydayai;

--
-- Name: remove_governed_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.remove_governed_member(p_org_id uuid, p_target_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_authority TEXT;
    v_target_role TEXT;
BEGIN
    v_authority := public._assert_governance_authority(
        p_org_id, ARRAY['owner', 'admin'], FALSE
    );
    IF p_target_user_id = public.tenant_actor_user_id() THEN
        RAISE EXCEPTION 'GOVERNANCE_SELF_MUTATION_DENIED'
            USING ERRCODE = '42501';
    END IF;
    SELECT role INTO v_target_role FROM public.org_members
     WHERE org_id = p_org_id AND user_id = p_target_user_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'GOVERNANCE_MEMBER_MISSING'
            USING ERRCODE = 'P0002';
    END IF;
    IF v_target_role = 'owner'
       OR (v_authority = 'admin' AND v_target_role = 'admin') THEN
        RAISE EXCEPTION 'GOVERNANCE_AUTHORITY_DENIED'
            USING ERRCODE = '42501';
    END IF;
    DELETE FROM public.org_members
     WHERE org_id = p_org_id AND user_id = p_target_user_id;
    PERFORM public._record_governance_audit(
        p_org_id, v_authority, 'member.remove', 'member',
        p_target_user_id::TEXT,
        jsonb_build_object('previous_role', v_target_role)
    );
    RETURN TRUE;
END;
$$;


ALTER FUNCTION public.remove_governed_member(p_org_id uuid, p_target_user_id uuid) OWNER TO everydayai_owner;

--
-- Name: renew_conversation_delivery(uuid, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.renew_conversation_delivery(p_delivery_id uuid, p_lease_token uuid, p_lease_seconds integer DEFAULT 60, p_delivered_items jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_delivery conversation_deliveries%ROWTYPE;
BEGIN
    IF p_lease_seconds NOT BETWEEN 15 AND 300
       OR (
           p_delivered_items IS NOT NULL
           AND jsonb_typeof(p_delivered_items) <> 'array'
       ) THEN
        RAISE EXCEPTION 'DELIVERY_RENEW_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_delivery
      FROM conversation_deliveries
     WHERE id = p_delivery_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_delivery.status <> 'delivering'
       OR v_delivery.lease_token IS DISTINCT FROM p_lease_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    IF v_delivery.lease_expires_at <= NOW() THEN
        RETURN jsonb_build_object('outcome', 'lease_expired');
    END IF;

    UPDATE conversation_deliveries
       SET lease_expires_at = NOW() + make_interval(secs => p_lease_seconds),
           delivered_items = COALESCE(p_delivered_items, delivered_items),
           updated_at = NOW()
     WHERE id = p_delivery_id;
    RETURN jsonb_build_object('outcome', 'renewed');
END;
$$;


ALTER FUNCTION public.renew_conversation_delivery(p_delivery_id uuid, p_lease_token uuid, p_lease_seconds integer, p_delivered_items jsonb) OWNER TO everydayai;

--
-- Name: renew_detail_page_plan(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.renew_detail_page_plan(p_plan_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',true) IS DISTINCT FROM 'runtime'
  OR p_lease_token IS NULL THEN RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 UPDATE public.ecom_image_plans p SET lease_expires_at=NOW()+interval '600 seconds'
  WHERE p.id=p_plan_id AND p.source_kind='detail_project' AND p.status='planning'
  AND p.lease_token=p_lease_token AND p.lease_expires_at>NOW()
  AND p.user_id=NULLIF(current_setting('app.actor_user_id',true),'')::uuid
  AND p.org_id IS NOT DISTINCT FROM NULLIF(current_setting('app.org_id',true),'')::uuid
  AND EXISTS(SELECT 1 FROM public.detail_projects d WHERE d.id=p.project_id AND d.user_id=p.user_id
   AND d.org_id IS NOT DISTINCT FROM p.org_id AND d.run_state->>'run_id'=p.generation_run_id::text
   AND d.status IN ('analyzing','plan_ready','generating'));
 RETURN FOUND;
END $$;


ALTER FUNCTION public.renew_detail_page_plan(p_plan_id uuid, p_lease_token uuid) OWNER TO everydayai_owner;

--
-- Name: renew_generation_lease(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.renew_generation_lease(p_task_id uuid, p_execution_token uuid, p_lease_seconds integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
BEGIN
    IF p_execution_token IS NULL OR p_lease_seconds NOT BETWEEN 15 AND 300 THEN
        RAISE EXCEPTION 'ACTOR_RENEW_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ACTOR_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;

    UPDATE tasks
       SET lease_expires_at = NOW() + make_interval(secs => p_lease_seconds)
     WHERE id = p_task_id
     RETURNING * INTO v_task;
    RETURN jsonb_build_object(
        'outcome', 'renewed',
        'lease_expires_at', v_task.lease_expires_at
    );
END;
$$;


ALTER FUNCTION public.renew_generation_lease(p_task_id uuid, p_execution_token uuid, p_lease_seconds integer) OWNER TO everydayai;

--
-- Name: FUNCTION renew_generation_lease(p_task_id uuid, p_execution_token uuid, p_lease_seconds integer); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.renew_generation_lease(p_task_id uuid, p_execution_token uuid, p_lease_seconds integer) IS '仅当前 fencing token 可续约 running Chat task';


--
-- Name: replace_skill_draft_candidate(uuid, uuid, uuid, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.replace_skill_draft_candidate(p_change_set_id uuid, p_org_id uuid, p_actor_id uuid, p_expected_revision bigint, p_proposed_snapshot jsonb, p_content_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_row public.change_sets%ROWTYPE; v_sequence BIGINT;
BEGIN
    IF p_actor_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id', true), '')::uuid
       OR p_org_id IS DISTINCT FROM public.skill_catalog_org_id()
       OR p_content_sha256 !~ '^[a-f0-9]{64}$'
       OR p_proposed_snapshot->>'content_sha256' IS DISTINCT FROM p_content_sha256 THEN
        RAISE EXCEPTION 'SKILL_CANDIDATE_REPLACE_DENIED' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_row FROM public.change_sets
     WHERE id = p_change_set_id AND org_id = p_org_id FOR UPDATE;
    IF NOT FOUND OR v_row.resource_type <> 'skill_draft' OR v_row.status <> 'awaiting_approval'
       OR v_row.expires_at <= now()
       OR v_row.created_by <> p_actor_id::text OR v_row.revision <> p_expected_revision
       OR NOT EXISTS (SELECT 1 FROM public.org_members m JOIN public.organizations o ON o.id=m.org_id
           JOIN public.users u ON u.id=m.user_id WHERE m.org_id=p_org_id AND m.user_id=p_actor_id
             AND m.status='active' AND m.role IN ('owner','admin') AND o.status='active' AND u.status='active') THEN
        RETURN jsonb_build_object('outcome', 'conflict');
    END IF;
    UPDATE public.change_sets SET proposed_snapshot=p_proposed_snapshot,
        audit_subject=audit_subject || jsonb_build_object('candidate_sha256', p_content_sha256),
        revision=revision+1, updated_at=now(), updated_by=p_actor_id::text, updated_by_type='user'
     WHERE id=p_change_set_id RETURNING * INTO v_row;
    SELECT COALESCE(MAX(sequence),0)+1 INTO v_sequence FROM public.change_events WHERE change_set_id=p_change_set_id;
    INSERT INTO public.change_events(change_set_id,org_id,sequence,event_type,from_status,to_status,
        actor_id,actor_type,payload) VALUES (p_change_set_id,p_org_id,v_sequence,'candidate_revised',
        'awaiting_approval','awaiting_approval',p_actor_id::text,'user',
        jsonb_build_object('content_sha256',p_content_sha256,'revision',v_row.revision));
    RETURN jsonb_build_object('outcome','replaced','change_set',to_jsonb(v_row));
END $_$;


ALTER FUNCTION public.replace_skill_draft_candidate(p_change_set_id uuid, p_org_id uuid, p_actor_id uuid, p_expected_revision bigint, p_proposed_snapshot jsonb, p_content_sha256 text) OWNER TO everydayai;

--
-- Name: replay_chat_image_snapshot(uuid, uuid, jsonb, uuid, boolean); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.replay_chat_image_snapshot(p_source_task_id uuid, p_request_id uuid, p_snapshot jsonb, p_org_id uuid DEFAULT NULL::uuid, p_allow_new boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor UUID:=NULLIF(current_setting('app.actor_user_id',TRUE),'')::UUID;
    v_source public.tasks%ROWTYPE; v_existing public.tasks%ROWTYPE; v_parent public.tasks%ROWTYPE;
    v_task UUID:=gen_random_uuid(); v_message UUID:=gen_random_uuid(); v_budget JSONB;
    v_target public.messages%ROWTYPE; v_retry_revision BIGINT;
    v_cost INTEGER:=(p_snapshot->>'estimated_credits')::INTEGER; v_max_cost INTEGER; v_max_count INTEGER;
BEGIN
    IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',TRUE) IS DISTINCT FROM 'runtime'
       OR v_actor IS NULL OR p_request_id IS NULL OR NULLIF(current_setting('app.org_id',TRUE),'')::UUID IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'CHAT_IMAGE_REPLAY_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
    SELECT * INTO v_source FROM public.tasks WHERE id=p_source_task_id AND type='image' AND user_id=v_actor
        AND org_id IS NOT DISTINCT FROM p_org_id;
    IF NOT FOUND OR NOT(v_source.request_params ? '_media_request_v1')
       OR v_source.request_params->'_media_request_v1'->'origin'->>'destination'='skill_trial'
       OR v_source.status NOT IN ('completed','failed','cancelled')
       OR v_source.request_params->'_media_lifecycle_v1'->>'phase' IS DISTINCT FROM 'published' THEN
        RAISE EXCEPTION 'CHAT_IMAGE_REPLAY_SOURCE_DENIED' USING ERRCODE='42501';
    END IF;
    IF v_source.request_params->'_media_request_v1'->'origin'->>'destination'='detail_project' THEN
        IF p_snapshot->'origin'->>'retry_of_task_id' IS DISTINCT FROM p_source_task_id::text
        OR p_snapshot->'origin'->>'retry_request_id' IS DISTINCT FROM p_request_id::text THEN
            RAISE EXCEPTION 'DETAIL_REPLAY_DENIED' USING ERRCODE='42501'; END IF;
        SELECT * INTO v_existing FROM public.tasks WHERE user_id=v_actor AND org_id IS NOT DISTINCT FROM p_org_id
            AND request_params->'_media_request_v1'->'origin'->>'retry_of_task_id'=p_source_task_id::text
            AND request_params->'_media_request_v1'->'origin'->>'retry_request_id'=p_request_id::text;
        IF FOUND THEN RETURN jsonb_build_object('outcome','replay','task_id',v_existing.id,'message_id',NULL,
            'submission_state',v_existing.request_params->'_media_lifecycle_v1'->>'phase'); END IF;
        IF p_allow_new IS DISTINCT FROM TRUE THEN RETURN jsonb_build_object('outcome','new_required'); END IF;
        RETURN public.accept_detail_page_image(
            (p_snapshot->'origin'->>'project_id')::uuid,
            (p_snapshot->'origin'->'plan_source'->>'plan_id')::uuid,
            (p_snapshot->'origin'->'plan_source'->>'item_id')::uuid,p_snapshot,p_org_id);
    END IF;
    -- Match publication lock order: conversation, parent task, output message.
    PERFORM 1 FROM public.conversations WHERE id=v_source.conversation_id FOR UPDATE;
    SELECT * INTO v_parent FROM public.tasks WHERE id=(v_source.request_params->'_media_request_v1'->'origin'->>'parent_task_id')::UUID FOR UPDATE;
    IF NOT FOUND OR v_parent.user_id IS DISTINCT FROM v_actor OR v_parent.org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'CHAT_IMAGE_REPLAY_PARENT_DENIED' USING ERRCODE='42501';
    END IF;
    IF p_snapshot->>'schema_version' IS DISTINCT FROM '1' OR p_snapshot->>'num_images' IS DISTINCT FROM '1'
       OR p_snapshot->'origin' ? 'tool_call_id' OR p_snapshot->'origin' ? 'destination'
       OR p_snapshot->'origin'->>'org_id' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->'origin'->>'org_id'
       OR p_snapshot->'origin'->>'context_scope' IS DISTINCT FROM 'user'
       OR p_snapshot->'origin'->>'input_message_id' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->'origin'->>'input_message_id'
       OR p_snapshot->'origin'->>'base_context_revision' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->'origin'->>'base_context_revision'
       OR p_snapshot->'origin'->>'retry_of_task_id' IS DISTINCT FROM p_source_task_id::TEXT
       OR p_snapshot->'origin'->>'retry_request_id' IS DISTINCT FROM p_request_id::TEXT
       OR p_snapshot->'origin'->>'parent_task_id' IS DISTINCT FROM v_parent.id::TEXT
       OR p_snapshot->'origin'->>'actor_user_id' IS DISTINCT FROM v_actor::TEXT
       OR p_snapshot->'origin'->>'workspace_owner_id' IS DISTINCT FROM v_actor::TEXT
       OR p_snapshot->'origin'->>'conversation_id' IS DISTINCT FROM v_source.conversation_id::TEXT
       OR p_snapshot->>'prompt' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->>'prompt'
       OR p_snapshot->'references' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->'references'
       OR p_snapshot->>'model' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->>'model'
       OR p_snapshot->>'mode' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->>'mode'
       OR p_snapshot->>'aspect_ratio' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->>'aspect_ratio'
       OR p_snapshot->>'resolution' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->>'resolution'
       OR p_snapshot->>'output_format' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->>'output_format'
       OR p_snapshot->>'background' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->>'background'
       OR p_snapshot->'size_requirement' IS DISTINCT FROM v_source.request_params->'_media_request_v1'->'size_requirement' THEN
        RAISE EXCEPTION 'CHAT_IMAGE_REPLAY_INPUT_CHANGED' USING ERRCODE='22023';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=v_actor AND status='active')
       OR NOT EXISTS(SELECT 1 FROM public.conversations WHERE id=v_source.conversation_id AND user_id=v_actor AND org_id IS NOT DISTINCT FROM p_org_id AND scope_type='user')
       OR (p_org_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_members m JOIN public.organizations o ON o.id=m.org_id
            WHERE m.user_id=v_actor AND m.org_id=p_org_id AND m.status='active' AND o.status='active')) THEN
        RAISE EXCEPTION 'CHAT_IMAGE_REPLAY_IDENTITY_DENIED' USING ERRCODE='42501';
    END IF;
    SELECT * INTO v_existing FROM public.tasks WHERE type='image'
        AND request_params->'_media_request_v1'->'origin'->>'retry_of_task_id'=p_source_task_id::TEXT
        AND request_params->'_media_request_v1'->'origin'->>'retry_request_id'=p_request_id::TEXT;
    IF FOUND THEN RETURN jsonb_build_object('outcome','replay','task_id',v_existing.id,'message_id',v_existing.assistant_message_id,
        'submission_state',v_existing.request_params->'_media_lifecycle_v1'->>'phase'); END IF;
    SELECT * INTO v_target FROM public.messages WHERE id=v_source.assistant_message_id FOR UPDATE;
    IF NOT FOUND OR v_target.conversation_id IS DISTINCT FROM v_source.conversation_id
       OR v_target.org_id IS DISTINCT FROM p_org_id
       OR v_target.generation_params->>'origin' IS DISTINCT FROM 'chat_image' THEN
        RAISE EXCEPTION 'CHAT_IMAGE_RETRY_TARGET_DENIED' USING ERRCODE='42501';
    END IF;
    IF v_source.status IN ('failed','cancelled') AND v_target.generation_params->>'task_id' IS DISTINCT FROM p_source_task_id::TEXT THEN
        -- A second click/request ID must recover the existing attempt, not pay again.
        SELECT * INTO v_existing FROM public.tasks WHERE id=(v_target.generation_params->>'task_id')::UUID
            AND user_id=v_actor AND org_id IS NOT DISTINCT FROM p_org_id
            AND request_params->'_media_request_v1'->'origin'->>'retry_of_task_id'=p_source_task_id::TEXT;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'CHAT_IMAGE_RETRY_SUPERSEDED' USING ERRCODE='55000';
        END IF;
        RETURN jsonb_build_object('outcome','replay','task_id',v_existing.id,'message_id',v_existing.assistant_message_id,
            'submission_state',v_existing.request_params->'_media_lifecycle_v1'->>'phase');
    END IF;
    IF p_allow_new IS DISTINCT FROM TRUE THEN RETURN jsonb_build_object('outcome','new_required'); END IF;
    v_max_count:=(p_snapshot->'budget'->>'max_requests')::INTEGER;
    v_max_cost:=(p_snapshot->'budget'->>'max_credits')::INTEGER;
    IF v_cost IS NULL OR v_cost NOT BETWEEN 1 AND 300 OR v_max_count IS NULL OR v_max_count NOT BETWEEN 1 AND 15
       OR v_max_cost IS NULL OR v_max_cost NOT BETWEEN 1 AND 300 OR pg_column_size(p_snapshot)>128000 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_REPLAY_BUDGET_INVALID' USING ERRCODE='22023';
    END IF;
    v_budget:=COALESCE(v_parent.request_params->'_media_retry_budget_v1','{}'::JSONB);
    v_max_count:=LEAST(v_max_count,COALESCE((v_budget->>'max_requests')::INTEGER,v_max_count));
    v_max_cost:=LEAST(v_max_cost,COALESCE((v_budget->>'max_credits')::INTEGER,v_max_cost));
    v_max_cost:=LEAST(v_max_cost,COALESCE((v_parent.request_params->'_media_budget_v1'->>'max_credits')::INTEGER,v_max_cost));
    IF COALESCE((v_budget->>'reserved_credits')::INTEGER,0)
       + COALESCE((v_parent.request_params->'_media_budget_v1'->>'reserved_credits')::INTEGER,0)+v_cost>v_max_cost THEN
        RAISE EXCEPTION 'CHAT_IMAGE_REPLAY_BUDGET_EXCEEDED' USING ERRCODE='54000';
    END IF;
    IF v_source.status IN ('failed','cancelled') THEN
        v_message:=v_source.assistant_message_id;
        UPDATE public.conversations SET context_revision=COALESCE(context_revision,0)+1
            WHERE id=v_source.conversation_id RETURNING context_revision INTO v_retry_revision;
        UPDATE public.messages SET content='[{"type":"image","url":null}]',status='pending',credits_cost=0,context_revision=v_retry_revision,
            generation_params=generation_params || jsonb_build_object('task_id',v_task,
                'source_task_id',p_source_task_id,'submission_state','queued')
            WHERE id=v_message;
    ELSE
    INSERT INTO public.messages(id,conversation_id,org_id,role,content,status,generation_params)
        VALUES(v_message,v_source.conversation_id,p_org_id,'assistant','[{"type":"image","url":null}]','pending',
            jsonb_build_object('origin','chat_image','task_id',v_task,'type','image','num_images',1,'model',p_snapshot->>'model',
                'mode',p_snapshot->>'mode','aspect_ratio',p_snapshot->>'aspect_ratio','resolution',p_snapshot->>'resolution','source_task_id',p_source_task_id,
                'size_requirement',p_snapshot->'size_requirement'));
    END IF;
    INSERT INTO public.tasks(id,user_id,org_id,conversation_id,type,status,model_id,assistant_message_id,placeholder_message_id,batch_id,image_index,request_params)
        VALUES(v_task,v_actor,p_org_id,v_source.conversation_id,'image','pending',p_snapshot->>'model',v_message,v_message::TEXT,v_task::TEXT,0,
            jsonb_build_object('_media_request_v1',p_snapshot,'_media_lifecycle_v1',jsonb_build_object('phase','queued','accepted_at',NOW())));
    UPDATE public.tasks SET request_params=jsonb_set(COALESCE(request_params,'{}'::JSONB),'{_media_retry_budget_v1}',
        jsonb_build_object('requests',COALESCE((v_budget->>'requests')::INTEGER,0)+1,
            'reserved_credits',COALESCE((v_budget->>'reserved_credits')::INTEGER,0)+v_cost,
            'max_requests',v_max_count,'max_credits',v_max_cost)) WHERE id=v_parent.id;
    RETURN jsonb_build_object('outcome','accepted','task_id',v_task,'message_id',v_message,'submission_state','queued','context_revision',v_retry_revision);
END;
$$;


ALTER FUNCTION public.replay_chat_image_snapshot(p_source_task_id uuid, p_request_id uuid, p_snapshot jsonb, p_org_id uuid, p_allow_new boolean) OWNER TO everydayai_owner;

--
-- Name: reserve_ecom_plan_attempt(uuid, uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.reserve_ecom_plan_attempt(p_plan_id uuid, p_lease_token uuid, p_attempt_id uuid, p_stage integer, p_wall_seconds integer DEFAULT 600) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; r public.ecom_image_plans%ROWTYPE; t public.tasks%ROWTYPE;
        root_id UUID; state JSONB; attempts JSONB; n INTEGER; reset_window BOOLEAN;
BEGIN
    SELECT COALESCE(root_plan_id,id) INTO root_id FROM public.ecom_image_plans WHERE id=p_plan_id;
    SELECT * INTO r FROM public.ecom_image_plans WHERE id=root_id FOR UPDATE;
    SELECT * INTO p FROM public.ecom_image_plans WHERE id=p_plan_id FOR UPDATE;
    SELECT * INTO t FROM public.tasks WHERE id=p.parent_task_id;
    IF SESSION_USER <> 'everydayai' OR current_setting('app.access_kind',TRUE) <> 'runtime'
       OR p.id IS NULL OR r.id IS NULL OR r.user_id IS DISTINCT FROM p.user_id OR r.org_id IS DISTINCT FROM p.org_id
       OR r.conversation_id IS DISTINCT FROM p.conversation_id
       OR p.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',TRUE),'')::uuid
       OR p.org_id IS DISTINCT FROM NULLIF(current_setting('app.org_id',TRUE),'')::uuid
       OR (p.source_kind='chat' AND (t.id IS NULL OR t.status <> 'running')) OR p_lease_token IS NULL OR p.lease_token IS DISTINCT FROM p_lease_token
       OR p.lease_expires_at IS NULL OR p.lease_expires_at < NOW() OR p.status <> 'planning' OR p.current_stage IS DISTINCT FROM p_stage
       OR p_stage IS NULL OR p_attempt_id IS NULL OR p_wall_seconds IS NULL OR p_wall_seconds NOT BETWEEN 1 AND (CASE WHEN p.source_kind='detail_project' THEN 1800 ELSE 600 END) THEN
        RAISE EXCEPTION 'ECOM_PLAN_LEASE_LOST' USING ERRCODE='55000';
    END IF;
    state=r.recovery_state;
    reset_window=COALESCE((t.request_params->'_ecom_workflow'->>'reset_window')::boolean,false)
        AND t.request_params->'_ecom_workflow'->>'window_task_id'=t.id::text
        AND state->>'window_task_id' IS DISTINCT FROM t.id::text;
    IF state->>'window_task_id' IS NULL AND jsonb_array_length(r.stage_attempts)>0 AND NOT reset_window THEN
        RAISE EXCEPTION 'ECOM_PLAN_EXECUTION_UNCERTAIN' USING ERRCODE='55000';
    END IF;
    IF state->>'window_task_id' IS NULL OR reset_window THEN
        state=jsonb_build_object('version',1,'window_task_id',COALESCE(t.id,p.generation_run_id),'deadline',NOW()+make_interval(secs=>p_wall_seconds),
            'counts','{}'::jsonb,'attempts','{}'::jsonb);
    END IF;
    -- Only an unstarted page window may begin its clock on actual reservation.
    IF p.source_kind='detail_project' AND state->>'pending_start'='true'
       AND state->>'deadline' IS NULL AND COALESCE(state->'attempts','{}')='{}'::jsonb THEN
        state=(state-'pending_start')||jsonb_build_object('deadline',NOW()+make_interval(secs=>p_wall_seconds));
    END IF;
    attempts=COALESCE(state->'attempts','{}'::jsonb);
    IF attempts ? p_attempt_id::text THEN
        RETURN jsonb_build_object('outcome','replay','attempt',attempts->p_attempt_id::text);
    END IF;
    IF EXISTS(SELECT 1 FROM jsonb_each(attempts) x WHERE x.value->>'outcome' IN ('started','uncertain')) THEN
        RAISE EXCEPTION 'ECOM_PLAN_EXECUTION_UNCERTAIN' USING ERRCODE='55000';
    END IF;
    IF (state->>'deadline')::timestamptz <= NOW() THEN
        RAISE EXCEPTION 'ECOM_PLAN_PARENT_BUDGET_EXHAUSTED' USING ERRCODE='55000';
    END IF;
    n=COALESCE((state->'counts'->>p_stage::text)::integer,0);
    IF n>=3 THEN RAISE EXCEPTION 'ECOM_PLAN_RETRY_EXHAUSTED' USING ERRCODE='55000'; END IF;
    state=jsonb_set(state,ARRAY['counts',p_stage::text],to_jsonb(n+1));
    state=jsonb_set(state,ARRAY['attempts',p_attempt_id::text],jsonb_build_object(
        'stage',p_stage,'plan_id',p.id,'outcome','started','started_at',NOW(),'ordinal',n+1));
    UPDATE public.ecom_image_plans SET recovery_state=state,updated_at=NOW() WHERE id=root_id;
    RETURN jsonb_build_object('outcome','execute','attempt_id',p_attempt_id,'ordinal',n+1,
        'remaining_attempts',2-n,'deadline',state->>'deadline');
END $$;


ALTER FUNCTION public.reserve_ecom_plan_attempt(p_plan_id uuid, p_lease_token uuid, p_attempt_id uuid, p_stage integer, p_wall_seconds integer) OWNER TO everydayai_owner;

--
-- Name: resolve_platform_admin_user_assets_download(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.resolve_platform_admin_user_assets_download(p_actor_user_id uuid, p_asset_ids jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_items JSONB;
    v_resolved_count INTEGER;
    v_asset_ids UUID[] := ARRAY[]::UUID[];
    v_element JSONB;
    v_asset_id UUID;
BEGIN
    IF p_actor_user_id IS NULL
       OR p_asset_ids IS NULL
       OR jsonb_typeof(p_asset_ids) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'ADMIN_ASSET_DOWNLOAD_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    IF jsonb_array_length(p_asset_ids) NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION 'ADMIN_ASSET_DOWNLOAD_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    FOR v_element IN SELECT value FROM jsonb_array_elements(p_asset_ids)
    LOOP
        BEGIN
            v_asset_id := (v_element #>> '{}')::UUID;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'ADMIN_ASSET_DOWNLOAD_ARGUMENT_INVALID'
                USING ERRCODE = '22023';
        END;
        IF v_asset_id = ANY(v_asset_ids) THEN
            RAISE EXCEPTION 'ADMIN_ASSET_DOWNLOAD_ARGUMENT_INVALID'
                USING ERRCODE = '22023';
        END IF;
        v_asset_ids := array_append(v_asset_ids, v_asset_id);
    END LOOP;

    SELECT count(*)::INTEGER,
           COALESCE(jsonb_agg(
               jsonb_build_object(
                   'id', resolved.id,
                   'download_url', resolved.download_url,
                   'name', resolved.name
               ) ORDER BY resolved.ordinality
           ), '[]'::JSONB)
      INTO v_resolved_count, v_items
      FROM (
          SELECT requested.ordinality, asset.id, asset.download_url, asset.name
            FROM unnest(v_asset_ids) WITH ORDINALITY
                 AS requested(asset_id, ordinality)
            JOIN public.user_assets AS asset
              ON asset.id = requested.asset_id
             AND asset.status = 'ready'
           WHERE EXISTS (
               SELECT 1
                 FROM public.user_asset_refs AS asset_ref
                WHERE asset_ref.asset_id = asset.id
                  AND asset_ref.actor_user_id = p_actor_user_id
           )
      ) AS resolved;

    IF v_resolved_count <> cardinality(v_asset_ids) THEN
        RAISE EXCEPTION 'ADMIN_ASSET_DOWNLOAD_SCOPE_INVALID'
            USING ERRCODE = '42501';
    END IF;
    RETURN v_items;
END;
$$;


ALTER FUNCTION public.resolve_platform_admin_user_assets_download(p_actor_user_id uuid, p_asset_ids jsonb) OWNER TO everydayai;

--
-- Name: FUNCTION resolve_platform_admin_user_assets_download(p_actor_user_id uuid, p_asset_ids jsonb); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.resolve_platform_admin_user_assets_download(p_actor_user_id uuid, p_asset_ids jsonb) IS '旧 Web 管理后台按用户资产归属解析下载地址；不依赖 Runtime 会话';


--
-- Name: resolve_wecom_conversation(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.resolve_wecom_conversation(p_user_id uuid, p_corp_id text, p_external_chat_id text, p_chat_type text, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_binding conversation_channel_bindings%ROWTYPE;
    v_conversation_id UUID;
    v_owner_user_id UUID;
    v_scope_type TEXT;
BEGIN
    IF p_org_id IS NULL
       OR p_user_id IS NULL
       OR COALESCE(BTRIM(p_corp_id), '') = ''
       OR COALESCE(BTRIM(p_external_chat_id), '') = ''
       OR p_chat_type NOT IN ('single', 'group') THEN
        RAISE EXCEPTION 'WECOM_CONVERSATION_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM users WHERE id = p_user_id
    ) THEN
        RAISE EXCEPTION 'WECOM_CONVERSATION_USER_MISSING'
            USING ERRCODE = '23503';
    END IF;

    SELECT * INTO v_binding
      FROM conversation_channel_bindings
     WHERE org_id = p_org_id
       AND channel = 'wecom'
       AND corp_id = BTRIM(p_corp_id)
       AND external_chat_id = BTRIM(p_external_chat_id)
     FOR UPDATE;

    IF FOUND THEN
        IF v_binding.chat_type IS DISTINCT FROM p_chat_type
           OR (
               p_chat_type = 'single'
               AND v_binding.owner_user_id IS DISTINCT FROM p_user_id
           ) THEN
            RAISE EXCEPTION 'WECOM_CONVERSATION_BINDING_CONFLICT'
                USING ERRCODE = '23505';
        END IF;
        UPDATE conversation_channel_bindings
           SET last_seen_at = NOW()
         WHERE id = v_binding.id;
        RETURN jsonb_build_object(
            'conversation_id', v_binding.conversation_id,
            'scope_type', CASE p_chat_type
                WHEN 'group' THEN 'channel' ELSE 'user' END,
            'already_exists', TRUE
        );
    END IF;

    IF p_chat_type = 'single' THEN
        v_conversation_id := claim_legacy_wecom_conversation(
            p_user_id, p_corp_id, p_external_chat_id, p_org_id
        );
        IF v_conversation_id IS NOT NULL THEN
            RETURN jsonb_build_object(
                'conversation_id', v_conversation_id,
                'scope_type', 'user',
                'already_exists', TRUE
            );
        END IF;
    END IF;

    v_owner_user_id := CASE WHEN p_chat_type = 'single'
        THEN p_user_id ELSE NULL END;
    v_scope_type := CASE WHEN p_chat_type = 'group'
        THEN 'channel' ELSE 'user' END;

    INSERT INTO conversations(
        user_id, org_id, title, source, message_count, credits_consumed,
        scope_type, scope_id
    ) VALUES (
        v_owner_user_id, p_org_id,
        CASE WHEN p_chat_type = 'group' THEN '企微群聊' ELSE '企微对话' END,
        'wecom', 0, 0, v_scope_type, BTRIM(p_external_chat_id)
    )
    RETURNING id INTO v_conversation_id;

    BEGIN
        INSERT INTO conversation_channel_bindings(
            org_id, conversation_id, channel, corp_id,
            external_chat_id, chat_type, owner_user_id
        ) VALUES (
            p_org_id, v_conversation_id, 'wecom', BTRIM(p_corp_id),
            BTRIM(p_external_chat_id), p_chat_type, v_owner_user_id
        );
    EXCEPTION WHEN unique_violation THEN
        DELETE FROM conversations WHERE id = v_conversation_id;
        SELECT * INTO v_binding
          FROM conversation_channel_bindings
         WHERE org_id = p_org_id
           AND channel = 'wecom'
           AND corp_id = BTRIM(p_corp_id)
           AND external_chat_id = BTRIM(p_external_chat_id);
        IF NOT FOUND THEN
            RAISE;
        END IF;
        v_conversation_id := v_binding.conversation_id;
        v_scope_type := CASE v_binding.chat_type
            WHEN 'group' THEN 'channel' ELSE 'user' END;
    END;

    RETURN jsonb_build_object(
        'conversation_id', v_conversation_id,
        'scope_type', v_scope_type,
        'already_exists', FALSE
    );
END;
$$;


ALTER FUNCTION public.resolve_wecom_conversation(p_user_id uuid, p_corp_id text, p_external_chat_id text, p_chat_type text, p_org_id uuid) OWNER TO everydayai;

--
-- Name: resume_detail_delivery_acceptance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.resume_detail_delivery_acceptance(p_plan_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; j JSONB;
BEGIN
 p=public.lock_detail_delivery_plan(p_plan_id); j=p.delivery_recovery->'acceptance';
 IF p_token IS NULL OR p.status<>'ready' OR j->>'status' IS DISTINCT FROM 'running'
  OR j->>'claim_token' IS DISTINCT FROM p_token::text OR (j->>'lease_expires_at')::timestamptz IS NULL
  OR (j->>'lease_expires_at')::timestamptz<=NOW()
  OR (p.recovery_state->>'resume_request_id' IS DISTINCT FROM j->>'request_id'
   AND p.recovery_state->'acceptance_error'->>'attempt_id' IS DISTINCT FROM j->>'source') THEN
  RAISE EXCEPTION 'DETAIL_PLAN_NOT_RETRYABLE' USING ERRCODE='55000'; END IF;
 RETURN public.resume_detail_page_plan(p.project_id,p.id,(j->>'request_id')::uuid);
END $$;


ALTER FUNCTION public.resume_detail_delivery_acceptance(p_plan_id uuid, p_token uuid) OWNER TO everydayai_owner;

--
-- Name: resume_detail_delivery_plan(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.resume_detail_delivery_plan(p_plan_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; j JSONB; state JSONB;
BEGIN
 p=public.lock_detail_delivery_plan(p_plan_id); j=p.delivery_recovery->'plan';
 IF p_token IS NULL OR j->>'status' IS DISTINCT FROM 'running'
  OR j->>'claim_token' IS DISTINCT FROM p_token::text OR (j->>'lease_expires_at')::timestamptz IS NULL
  OR (j->>'lease_expires_at')::timestamptz<=NOW() THEN
  RAISE EXCEPTION 'DETAIL_PLAN_NOT_RETRYABLE' USING ERRCODE='55000'; END IF;
 IF p.status='planning' AND p.recovery_state->>'window_task_id'=j->>'request_id' THEN
  RETURN jsonb_build_object('status','resumed'); END IF;
 IF p.status<>'failed' OR p.lease_expires_at>NOW() THEN
  RAISE EXCEPTION 'DETAIL_PLAN_NOT_RETRYABLE' USING ERRCODE='55000'; END IF;
 -- Keep uncertain provider usage uncertain. This new delivery window is explicitly platform-backed.
 state=jsonb_build_object('version',1,'window_task_id',j->>'request_id',
  'pending_start',true,
  'counts','{}'::jsonb,'attempts','{}'::jsonb,'resume_request_id',j->>'request_id',
  'previous_windows',COALESCE(p.recovery_state->'previous_windows','[]')||jsonb_build_array(
   (p.recovery_state-'previous_windows')||jsonb_build_object('retry_cost','platform')));
 UPDATE public.ecom_image_plans SET status='planning',lease_token=NULL,lease_expires_at=NULL,recovery_state=state,
  updated_at=NOW() WHERE id=p.id;
 UPDATE public.detail_projects SET status='analyzing',updated_at=NOW() WHERE id=p.project_id;
 RETURN jsonb_build_object('status','resumed');
END $$;


ALTER FUNCTION public.resume_detail_delivery_plan(p_plan_id uuid, p_token uuid) OWNER TO everydayai_owner;

--
-- Name: resume_detail_page_plan(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.resume_detail_page_plan(p_project_id uuid, p_plan_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; d public.detail_projects%ROWTYPE; state JSONB;
BEGIN
 IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',true) IS DISTINCT FROM 'runtime' OR p_request_id IS NULL THEN RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO d FROM public.detail_projects WHERE id=p_project_id AND user_id=NULLIF(current_setting('app.actor_user_id',true),'')::uuid
  AND org_id IS NOT DISTINCT FROM NULLIF(current_setting('app.org_id',true),'')::uuid FOR UPDATE;
 SELECT * INTO p FROM public.ecom_image_plans WHERE id=p_plan_id AND project_id=p_project_id FOR UPDATE;
 IF d.id IS NULL OR p.id IS NULL OR p.source_kind<>'detail_project' OR p.user_id<>d.user_id
  OR p.org_id IS DISTINCT FROM d.org_id OR d.status='archived' OR d.run_state->>'run_id' IS DISTINCT FROM p.generation_run_id::text THEN
  RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF p.recovery_state->>'resume_request_id'=p_request_id::text THEN RETURN to_jsonb(p); END IF;
 IF p.status='ready' THEN
  UPDATE public.ecom_image_plans SET recovery_state=(recovery_state-'acceptance_error')||jsonb_build_object('resume_request_id',p_request_id),updated_at=NOW() WHERE id=p.id;
 ELSIF p.status='failed' AND (p.lease_expires_at IS NULL OR p.lease_expires_at<=NOW()) THEN
  IF EXISTS(SELECT 1 FROM jsonb_each(COALESCE(p.recovery_state->'attempts','{}')) a
   WHERE a.value->>'outcome'='started' OR (a.value->>'outcome'='uncertain' AND NOT public.detail_attempt_is_closed_timeout(a.value))) THEN
   RAISE EXCEPTION 'ECOM_PLAN_EXECUTION_UNCERTAIN' USING ERRCODE='55000'; END IF;
  state=jsonb_build_object('version',1,'window_task_id',p_request_id,
   'pending_start',true,
   'counts','{}'::jsonb,'attempts','{}'::jsonb,'resume_request_id',p_request_id,
   'previous_windows',COALESCE(p.recovery_state->'previous_windows','[]')||jsonb_build_array(p.recovery_state-'previous_windows'));
  UPDATE public.ecom_image_plans SET status='planning',lease_token=NULL,lease_expires_at=NULL,recovery_state=state,updated_at=NOW() WHERE id=p.id;
 ELSE RAISE EXCEPTION 'DETAIL_PLAN_NOT_RETRYABLE' USING ERRCODE='55000'; END IF;
 UPDATE public.detail_projects SET status='analyzing',updated_at=NOW() WHERE id=d.id;
 RETURN jsonb_build_object('status','resumed');
END $$;


ALTER FUNCTION public.resume_detail_page_plan(p_project_id uuid, p_plan_id uuid, p_request_id uuid) OWNER TO everydayai_owner;

--
-- Name: resume_paused_generation_turn(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.resume_paused_generation_turn(p_task_id uuid, p_user_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_conversation conversations%ROWTYPE;
    v_checkpoint conversation_turn_checkpoints%ROWTYPE;
BEGIN
    IF p_task_id IS NULL OR p_user_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_RESUME_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    SELECT * INTO v_conversation FROM conversations WHERE id = v_task.conversation_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB)
       OR v_task.user_id IS DISTINCT FROM p_user_id
       OR v_task.org_id IS DISTINCT FROM p_org_id
       OR v_conversation.user_id IS DISTINCT FROM p_user_id
       OR v_conversation.org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'ACTOR_RESUME_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.status IN ('pending', 'running') THEN
        RETURN jsonb_build_object(
            'outcome', 'already_enqueued', 'task_id', p_task_id,
            'conversation_id', v_task.conversation_id,
            'external_task_id', v_task.external_task_id,
            'client_task_id', v_task.client_task_id
        );
    END IF;
    IF v_task.status <> 'paused' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    SELECT * INTO v_checkpoint FROM conversation_turn_checkpoints
     WHERE task_id = p_task_id AND status = 'paused' FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ACTOR_RESUME_CHECKPOINT_MISSING' USING ERRCODE = '55000';
    END IF;

    UPDATE tasks SET status = 'pending', error_message = NULL,
        terminal_reason = 'resume_requested', completed_at = NULL,
        execution_token = NULL, lease_expires_at = NULL
     WHERE id = p_task_id;
    UPDATE conversation_turn_checkpoints SET status = 'ready', updated_at = NOW()
     WHERE task_id = p_task_id;
    INSERT INTO conversation_control_events(
        conversation_id, task_id, turn_id, event_type, dedupe_key, payload,
        status, applied_at
    ) VALUES (
        v_task.conversation_id, p_task_id, v_task.turn_id, 'resume',
        'resume:' || p_task_id::TEXT || ':' || v_checkpoint.version,
        jsonb_build_object('user_id', p_user_id), 'applied', NOW()
    ) ON CONFLICT (task_id, dedupe_key) DO NOTHING;
    RETURN jsonb_build_object(
        'outcome', 'enqueued', 'task_id', p_task_id,
        'checkpoint_version', v_checkpoint.version,
        'conversation_id', v_task.conversation_id,
        'assistant_message_id', v_task.assistant_message_id,
        'external_task_id', v_task.external_task_id,
        'client_task_id', v_task.client_task_id
    );
END;
$$;


ALTER FUNCTION public.resume_paused_generation_turn(p_task_id uuid, p_user_id uuid, p_org_id uuid) OWNER TO everydayai;

--
-- Name: save_conversation_delivery_snapshot(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.save_conversation_delivery_snapshot(p_task_id uuid, p_execution_token uuid, p_content text, p_blocks jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_session conversation_delivery_sessions%ROWTYPE;
BEGIN
    IF p_task_id IS NULL OR p_execution_token IS NULL
       OR p_content IS NULL OR p_blocks IS NULL
       OR jsonb_typeof(p_blocks) <> 'array' THEN
        RAISE EXCEPTION 'DELIVERY_SNAPSHOT_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat' THEN
        RAISE EXCEPTION 'DELIVERY_SNAPSHOT_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    SELECT * INTO v_session FROM conversation_delivery_sessions
     WHERE task_id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_session.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    UPDATE conversation_delivery_sessions
       SET snapshot_seq = next_seq,
           snapshot_content = p_content,
           snapshot_blocks = p_blocks,
           updated_at = NOW()
     WHERE id = v_session.id;
    RETURN jsonb_build_object(
        'outcome', 'saved', 'stream_id', v_session.stream_id,
        'execution_attempt', v_session.execution_attempt,
        'snapshot_seq', v_session.next_seq
    );
END;
$$;


ALTER FUNCTION public.save_conversation_delivery_snapshot(p_task_id uuid, p_execution_token uuid, p_content text, p_blocks jsonb) OWNER TO everydayai;

--
-- Name: save_ecom_image_plan_stage(uuid, uuid, integer, jsonb, jsonb, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.save_ecom_image_plan_stage(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_output jsonb, p_attempt jsonb, p_status text, p_items jsonb DEFAULT NULL::jsonb, p_reviews jsonb DEFAULT NULL::jsonb, p_credits integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE p public.ecom_image_plans%ROWTYPE; balance INTEGER;
BEGIN
    IF SESSION_USER <> 'everydayai' OR current_setting('app.access_kind', TRUE) NOT IN ('runtime','runtime_admin') THEN
        RAISE EXCEPTION 'ECOM_PLAN_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
    IF p_stage NOT BETWEEN 1 AND 3 OR p_status NOT IN ('planning','needs_input','insufficient','ready','failed','cancelled') THEN
        RAISE EXCEPTION 'ECOM_PLAN_STAGE_OR_STATUS_INVALID' USING ERRCODE='22023';
    END IF;
    SELECT * INTO p FROM public.ecom_image_plans WHERE id=p_plan_id FOR UPDATE;
    IF NOT FOUND OR p.lease_token IS DISTINCT FROM p_lease_token OR p.lease_expires_at IS NULL OR p.lease_expires_at < NOW()
       OR p.current_stage IS DISTINCT FROM p_stage OR p.status <> 'planning'
       OR p.user_id IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id',TRUE),'')::uuid THEN
        RAISE EXCEPTION 'ECOM_PLAN_LEASE_LOST' USING ERRCODE='55000';
    END IF;
    IF p_attempt IS NOT NULL AND p_output IS NULL THEN
        IF p_credits < 0 OR p_credits > 100000 THEN
            RAISE EXCEPTION 'ECOM_PLAN_CREDITS_INVALID' USING ERRCODE='22023';
        END IF;
        IF p_credits > 0 THEN
            UPDATE public.users SET credits=credits-p_credits,updated_at=NOW()
                WHERE id=p.user_id AND credits >= p_credits RETURNING credits INTO balance;
            IF NOT FOUND THEN RAISE EXCEPTION 'ECOM_PLAN_INSUFFICIENT_CREDITS' USING ERRCODE='P0001'; END IF;
            INSERT INTO public.credits_history(user_id,change_type,change_amount,balance_after,description,org_id)
                VALUES(p.user_id,'conversation_cost'::public.credits_change_type,-p_credits,balance,
                    COALESCE(p.model_settings->>'model','ecommerce')||' planning stage '||p_stage,p.org_id);
        END IF;
        UPDATE public.ecom_image_plans SET stage_attempts=stage_attempts || jsonb_build_array(p_attempt),
            status=CASE WHEN p_status IN ('failed','cancelled') THEN p_status ELSE status END,
            lease_token=CASE WHEN p_status IN ('failed','cancelled') THEN NULL ELSE lease_token END,
            lease_expires_at=CASE WHEN p_status IN ('failed','cancelled') THEN NULL ELSE lease_expires_at END,
            updated_at=NOW(),row_version=row_version+1 WHERE id=p_plan_id;
        RETURN jsonb_build_object('row_version',p.row_version+1);
    END IF;
    IF p_output IS NOT NULL THEN
        IF p_credits < 0 OR p_credits > 100000 THEN
            RAISE EXCEPTION 'ECOM_PLAN_CREDITS_INVALID' USING ERRCODE='22023';
        END IF;
        IF p_credits > 0 THEN
            UPDATE public.users SET credits=credits-p_credits,updated_at=NOW()
                WHERE id=p.user_id AND credits >= p_credits RETURNING credits INTO balance;
            IF NOT FOUND THEN RAISE EXCEPTION 'ECOM_PLAN_INSUFFICIENT_CREDITS' USING ERRCODE='P0001'; END IF;
            INSERT INTO public.credits_history(user_id,change_type,change_amount,balance_after,description,org_id)
                VALUES(p.user_id,'conversation_cost'::public.credits_change_type,-p_credits,balance,
                    COALESCE(p.model_settings->>'model','ecommerce')||' planning stage '||p_stage,p.org_id);
        END IF;
        UPDATE public.ecom_image_plans SET
            stage_outputs=stage_outputs || jsonb_build_object(p_stage::text,p_output),
            stage_attempts=CASE WHEN p_attempt IS NULL THEN stage_attempts
                ELSE stage_attempts || jsonb_build_array(p_attempt) END,
            current_stage=CASE WHEN p_status='planning' THEN LEAST(3,p_stage+1) ELSE p_stage END,
            status=p_status,
            items=COALESCE(p_items,items), review_records=COALESCE(p_reviews,review_records),
            lease_token=CASE WHEN p_status='planning' THEN p_lease_token ELSE NULL END,
            lease_expires_at=CASE WHEN p_status='planning' THEN NOW()+INTERVAL '600 seconds' ELSE NULL END,
            updated_at=NOW(),row_version=row_version+1 WHERE id=p_plan_id;
    ELSE
        UPDATE public.ecom_image_plans SET status=p_status,lease_token=NULL,lease_expires_at=NULL,
            updated_at=NOW(),row_version=row_version+1 WHERE id=p_plan_id;
    END IF;
    RETURN jsonb_build_object('row_version',p.row_version+1);
END $$;


ALTER FUNCTION public.save_ecom_image_plan_stage(p_plan_id uuid, p_lease_token uuid, p_stage integer, p_output jsonb, p_attempt jsonb, p_status text, p_items jsonb, p_reviews jsonb, p_credits integer) OWNER TO everydayai_owner;

--
-- Name: save_generation_checkpoint(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.save_generation_checkpoint(p_task_id uuid, p_execution_token uuid, p_safe_point text, p_state jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
    v_version BIGINT;
BEGIN
    IF p_task_id IS NULL OR p_execution_token IS NULL
       OR NULLIF(BTRIM(p_safe_point), '') IS NULL
       OR p_state IS NULL OR jsonb_typeof(p_state) <> 'object' THEN
        RAISE EXCEPTION 'ACTOR_CHECKPOINT_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF NOT FOUND OR v_task.type <> 'chat'
       OR NOT (v_task.delivery_context @> '{"actor": true}'::JSONB) THEN
        RAISE EXCEPTION 'ACTOR_CHECKPOINT_SCOPE_MISMATCH' USING ERRCODE = '42501';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object('outcome', 'terminal', 'status', v_task.status);
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    IF v_task.lease_expires_at IS NULL OR v_task.lease_expires_at <= NOW() THEN
        RETURN jsonb_build_object('outcome', 'lease_expired');
    END IF;

    INSERT INTO conversation_turn_checkpoints(
        task_id, conversation_id, turn_id, version, safe_point, state, status
    ) VALUES (
        p_task_id, v_task.conversation_id, v_task.turn_id,
        1, BTRIM(p_safe_point), p_state, 'ready'
    ) ON CONFLICT (task_id) DO UPDATE SET
        conversation_id = EXCLUDED.conversation_id,
        turn_id = EXCLUDED.turn_id,
        version = conversation_turn_checkpoints.version + 1,
        safe_point = EXCLUDED.safe_point,
        state = EXCLUDED.state,
        status = 'ready', updated_at = NOW();

    SELECT version INTO v_version FROM conversation_turn_checkpoints
     WHERE task_id = p_task_id;
    RETURN jsonb_build_object('outcome', 'saved', 'task_id', p_task_id, 'version', v_version);
END;
$$;


ALTER FUNCTION public.save_generation_checkpoint(p_task_id uuid, p_execution_token uuid, p_safe_point text, p_state jsonb) OWNER TO everydayai;

--
-- Name: save_scheduled_web_delivery(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.save_scheduled_web_delivery(p_delivery_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE d scheduled_task_deliveries%ROWTYPE; c conversations%ROWTYPE; inserted UUID;
BEGIN
 SELECT * INTO d FROM scheduled_task_deliveries WHERE id=p_delivery_id FOR UPDATE;
 IF NOT FOUND OR d.status <> 'delivering' OR d.lease_token IS DISTINCT FROM p_lease_token
    OR d.lease_expires_at <= NOW() THEN
  RETURN jsonb_build_object('outcome','ownership_lost');
 END IF;
 IF d.target_context->>'type' <> 'web' THEN
  RAISE EXCEPTION 'SCHEDULED_WEB_TARGET_INVALID';
 END IF;
 -- Recheck ownership at delivery time. No fallback into another conversation.
 SELECT * INTO c FROM conversations
 WHERE id=(d.target_context->>'conversation_id')::uuid AND org_id=d.org_id
 AND user_id=(d.target_context->>'user_id')::uuid FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('outcome','conversation_unavailable'); END IF;
 IF NOT EXISTS (SELECT 1 FROM org_members WHERE org_id=d.org_id AND user_id=c.user_id AND status='active') THEN
  RETURN jsonb_build_object('outcome','membership_unavailable');
 END IF;
 INSERT INTO messages(id,conversation_id,org_id,role,content,status)
 VALUES(d.id,c.id,d.org_id,'assistant',d.payload->'content','completed')
 ON CONFLICT(id) DO NOTHING RETURNING id INTO inserted;
 IF inserted IS NULL AND NOT EXISTS (SELECT 1 FROM messages WHERE id=d.id AND conversation_id=c.id AND org_id=d.org_id) THEN
  RAISE EXCEPTION 'SCHEDULED_WEB_MESSAGE_CONFLICT';
 END IF;
 IF inserted IS NOT NULL THEN
  UPDATE conversations SET last_message_preview=LEFT(d.payload->>'text',100),
   message_count=COALESCE(message_count,0)+1, updated_at=NOW() WHERE id=c.id;
 END IF;
 UPDATE scheduled_task_runs SET result_message_id=d.id WHERE id=d.run_id AND org_id=d.org_id;
 RETURN jsonb_build_object('outcome',CASE WHEN inserted IS NULL THEN 'existing' ELSE 'saved' END,
                          'message_id',d.id,'conversation_id',c.id);
END $$;


ALTER FUNCTION public.save_scheduled_web_delivery(p_delivery_id uuid, p_lease_token uuid) OWNER TO everydayai;

--
-- Name: scan_chat_image_work(uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.scan_chat_image_work(p_org_id uuid DEFAULT NULL::uuid, p_after_created timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_rows JSONB;
BEGIN
    PERFORM public.assert_chat_image_worker(p_org_id);
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION 'CHAT_IMAGE_SCAN_LIMIT_INVALID' USING ERRCODE='22023';
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.created_at,t.id),'[]'::JSONB) INTO v_rows FROM (
        SELECT * FROM public.tasks WHERE type='image' AND org_id IS NOT DISTINCT FROM p_org_id
        AND request_params ? '_media_request_v1'
        AND (request_params->'_media_lifecycle_v1'->>'phase' IN ('queued','submitting','accepted','uncertain','settling')
            OR request_params->'_media_lifecycle_v1'->>'delivery_pending'='true')
        AND (p_after_created IS NULL OR (created_at,id)>(p_after_created,p_after_id))
        ORDER BY created_at,id LIMIT p_limit
    ) t;
    RETURN v_rows;
END;
$$;


ALTER FUNCTION public.scan_chat_image_work(p_org_id uuid, p_after_created timestamp with time zone, p_after_id uuid, p_limit integer) OWNER TO everydayai_owner;

--
-- Name: scan_detail_page_work(uuid, integer); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.scan_detail_page_work(p_org_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE rows JSONB;
BEGIN
 PERFORM public.assert_chat_image_worker(p_org_id);
 IF p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'DETAIL_SCAN_INVALID'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]') INTO rows FROM(
 SELECT ranked.* FROM (
  SELECT d.*,row_number() OVER(PARTITION BY user_id ORDER BY updated_at,id) AS owner_turn
  FROM public.detail_projects d WHERE org_id IS NOT DISTINCT FROM p_org_id AND status IN ('analyzing','plan_ready','generating')
 ) ranked ORDER BY owner_turn,updated_at,id LIMIT p_limit) d;
 RETURN rows;
END $$;


ALTER FUNCTION public.scan_detail_page_work(p_org_id uuid, p_limit integer) OWNER TO everydayai_owner;

