--
-- Name: search_governed_user_by_phone(text); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.search_governed_user_by_phone(p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    v_result JSONB;
BEGIN
    PERFORM public._assert_governance_authority(
        NULL, ARRAY[]::TEXT[], TRUE
    );
    IF p_phone !~ '^1[3-9][0-9]{9}$' THEN
        RAISE EXCEPTION 'GOVERNANCE_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT jsonb_build_object(
        'found', TRUE,
        'user', jsonb_build_object(
            'id', id,
            'nickname', nickname,
            'phone', LEFT(phone, 3) || '****' || RIGHT(phone, 4),
            'status', status
        )
    ) INTO v_result
      FROM public.users
     WHERE phone = p_phone;
    RETURN COALESCE(v_result, jsonb_build_object(
        'found', FALSE, 'user', NULL
    ));
END;
$_$;


ALTER FUNCTION public.search_governed_user_by_phone(p_phone text) OWNER TO everydayai_owner;

--
-- Name: set_org_configuration(uuid, text, text, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.set_org_configuration(p_org_id uuid, p_definition_version text, p_config_key text, p_value_json jsonb, p_secret_envelope jsonb, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_authority TEXT;
    v_actor UUID := public.tenant_actor_user_id();
    v_result JSONB;
BEGIN
    v_authority := public._assert_governance_authority(
        p_org_id, ARRAY['owner', 'admin'], FALSE
    );
    v_result := public._write_configuration_entry(
        'organization', p_org_id, NULL, p_definition_version, p_config_key,
        p_value_json, p_secret_envelope, p_expected_version, v_actor
    );
    PERFORM public._record_governance_audit(
        p_org_id, v_authority, 'organization_config.set', 'configuration',
        p_config_key, jsonb_build_object(
            'scope', 'organization', 'version', v_result->'version'
        )
    );
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.set_org_configuration(p_org_id uuid, p_definition_version text, p_config_key text, p_value_json jsonb, p_secret_envelope jsonb, p_expected_version bigint) OWNER TO everydayai_owner;

--
-- Name: set_org_mcp_connector_enabled(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.set_org_mcp_connector_enabled(p_org_id uuid, p_connector_id text, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_actor UUID := public.tenant_actor_user_id();
    v_authority TEXT;
    v_state public.organization_mcp_connectors%ROWTYPE;
BEGIN
    v_authority := public._assert_governance_authority(
        p_org_id, ARRAY['owner', 'admin'], FALSE
    );
    IF p_connector_id IS DISTINCT FROM 'test-readonly' OR p_enabled IS NULL THEN
        RAISE EXCEPTION 'MCP_CONNECTOR_NOT_ALLOWLISTED'
            USING ERRCODE = '22023';
    END IF;
    IF p_enabled AND NOT EXISTS (
        SELECT 1
          FROM public.configuration_entries entry
          JOIN public.secret_records secret ON secret.id = entry.secret_id
         WHERE entry.scope_kind = 'organization'
           AND entry.org_id = p_org_id
           AND entry.config_key = 'mcp.test_readonly.bearer_token'
           AND entry.status = 'active'
           AND secret.scope_kind = 'organization'
           AND secret.org_id = p_org_id
           AND secret.secret_name = 'mcp.test_readonly_bearer_token'
           AND secret.status = 'active'
    ) THEN
        RAISE EXCEPTION 'MCP_CREDENTIAL_REQUIRED'
            USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.organization_mcp_connectors(
        org_id, connector_id, enabled, health_status,
        last_error_code, updated_by, updated_at
    ) VALUES (
        p_org_id, p_connector_id, p_enabled,
        CASE WHEN p_enabled THEN 'configured' ELSE 'unknown' END,
        NULL, v_actor, NOW()
    )
    ON CONFLICT (org_id, connector_id) DO UPDATE SET
        enabled = EXCLUDED.enabled,
        health_status = CASE WHEN EXCLUDED.enabled
            THEN 'configured' ELSE organization_mcp_connectors.health_status END,
        last_error_code = CASE WHEN EXCLUDED.enabled
            THEN NULL ELSE organization_mcp_connectors.last_error_code END,
        updated_by = EXCLUDED.updated_by,
        updated_at = NOW()
    RETURNING * INTO v_state;
    PERFORM public._record_governance_audit(
        p_org_id, v_authority, 'mcp_connector.set_enabled',
        'mcp_connector', p_connector_id,
        jsonb_build_object('enabled', v_state.enabled)
    );
    RETURN jsonb_build_object(
        'org_id', p_org_id, 'connector_id', p_connector_id,
        'enabled', v_state.enabled,
        'state', CASE WHEN v_state.enabled THEN 'configured' ELSE 'disabled' END,
        'health_status', v_state.health_status,
        'last_checked_at', v_state.last_checked_at,
        'last_error_code', v_state.last_error_code,
        'updated_at', v_state.updated_at
    );
END;
$$;


ALTER FUNCTION public.set_org_mcp_connector_enabled(p_org_id uuid, p_connector_id text, p_enabled boolean) OWNER TO everydayai_owner;

