CREATE FUNCTION public.set_user_configuration(p_user_id uuid, p_definition_version text, p_config_key text, p_value_json jsonb, p_secret_envelope jsonb, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
