--
-- Name: skill_authoring_guard(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.skill_authoring_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE d public.skill_drafts%ROWTYPE;
BEGIN
    IF TG_TABLE_NAME = 'skill_change_audits' THEN
        IF TG_OP <> 'INSERT' OR pg_trigger_depth() < 2 THEN
            RAISE EXCEPTION 'SKILL_AUDIT_IMMUTABLE' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_TABLE_NAME IN ('skill_revisions', 'skill_assignments') THEN
        SELECT * INTO d FROM public.skill_drafts WHERE package_id = NEW.package_id FOR UPDATE;
        IF FOUND AND d.deleted_at IS NOT NULL THEN
            RAISE EXCEPTION 'SKILL_PACKAGE_DELETED' USING ERRCODE = '23514';
        END IF;
        IF TG_TABLE_NAME = 'skill_assignments' THEN RETURN NEW; END IF;
    END IF;
    IF TG_TABLE_NAME = 'skill_revisions' THEN
        IF TG_OP = 'UPDATE' AND NEW.status <> OLD.status AND NOT coalesce((
            (OLD.status = 'published' AND NEW.status IN ('deprecated', 'disabled', 'retired'))
            OR (OLD.status = 'deprecated' AND NEW.status IN ('disabled', 'retired'))
            OR (OLD.status = 'disabled' AND NEW.status IN ('published', 'deprecated')
                AND ((current_setting('app.skill_action', true) = 'enable'
                    AND NEW.status = public.skill_disabled_restore_state(OLD.package_id,
                        (SELECT version FROM public.skill_drafts
                            WHERE package_id = OLD.package_id AND status = 'disabled'), OLD.id))
                OR (current_setting('app.skill_action', true) = 'deprecate' AND NEW.status = 'deprecated'
                    AND public.skill_disabled_restore_state(OLD.package_id,
                        (SELECT version FROM public.skill_drafts
                            WHERE package_id = OLD.package_id AND status = 'disabled'), OLD.id)
                        IN ('published', 'deprecated'))))
        ), false) THEN
            RAISE EXCEPTION 'SKILL_TRANSITION_INVALID' USING ERRCODE = '23514';
        END IF;
        IF TG_OP = 'INSERT' THEN
            SELECT * INTO d FROM public.skill_drafts WHERE package_id = NEW.package_id FOR UPDATE;
            IF FOUND AND (d.status <> 'in_review' OR d.approved_by IS NULL
                OR d.revision <> NEW.revision OR d.approved_sha256 <> NEW.content_sha256) THEN
                RAISE EXCEPTION 'SKILL_APPROVAL_REQUIRED' USING ERRCODE = '23514';
            END IF;
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'SKILL_DRAFT_DELETE_FORBIDDEN' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'draft' OR NEW.version <> 1 OR NEW.approved_by IS NOT NULL
            OR NEW.deleted_at IS NOT NULL OR NEW.deleted_by IS NOT NULL THEN
            RAISE EXCEPTION 'SKILL_TRANSITION_INVALID' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.deleted_at IS NOT NULL THEN
        RAISE EXCEPTION 'SKILL_PACKAGE_DELETED' USING ERRCODE = '23514';
    END IF;
    IF (NEW.deleted_at, NEW.deleted_by) IS DISTINCT FROM (OLD.deleted_at, OLD.deleted_by) THEN
        IF NOT coalesce((current_setting('app.skill_action', true) = 'delete'
            AND OLD.status = 'deprecated' AND NEW.status = 'deprecated'
            AND NEW.deleted_at = now()
            AND NEW.deleted_by = NULLIF(current_setting('app.actor_user_id', true), '')::uuid
            AND (to_jsonb(NEW) - ARRAY['deleted_at','deleted_by','version','updated_at']) =
                (to_jsonb(OLD) - ARRAY['deleted_at','deleted_by','version','updated_at'])), false) THEN
            RAISE EXCEPTION 'SKILL_TRANSITION_INVALID' USING ERRCODE = '23514';
        END IF;
        PERFORM set_config('lock_timeout', '2s', true);
        LOCK TABLE public.tasks, public.conversation_turn_checkpoints IN SHARE MODE;
        IF public.skill_deletion_blockers(OLD.package_id,
            (SELECT skill_key FROM public.skill_packages WHERE id = OLD.package_id))
            <> '{"blocking_tasks":0,"uncertain_tasks":0}'::jsonb THEN
            RAISE EXCEPTION 'SKILL_DELETE_IN_USE' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.package_id <> OLD.package_id OR NEW.version <> OLD.version + 1
        OR NOT coalesce(((OLD.status = 'draft' AND NEW.status IN ('draft', 'in_review', 'deprecated', 'disabled'))
            OR (OLD.status = 'in_review' AND NEW.status IN ('draft', 'in_review', 'published', 'deprecated', 'disabled'))
            OR (OLD.status = 'published' AND NEW.status IN ('draft', 'deprecated', 'disabled'))
            OR (OLD.status = 'deprecated' AND NEW.status = 'deprecated' AND NEW.deleted_at IS NOT NULL)
            OR (OLD.status = 'disabled' AND current_setting('app.skill_action', true) = 'enable'
                AND NEW.status = public.skill_disabled_restore_state(OLD.package_id, OLD.version))
            OR (OLD.status = 'disabled' AND NEW.status = 'deprecated'
                AND current_setting('app.skill_action', true) = 'deprecate'
                AND public.skill_disabled_restore_state(OLD.package_id, OLD.version)
                    IN ('draft', 'in_review', 'published', 'deprecated'))), false) THEN
        RAISE EXCEPTION 'SKILL_TRANSITION_INVALID' USING ERRCODE = '23514';
    END IF;
    IF (NEW.content, NEW.revision) IS DISTINCT FROM (OLD.content, OLD.revision)
        AND NOT (NEW.status = 'draft' AND OLD.status IN ('draft', 'published')) THEN
        RAISE EXCEPTION 'SKILL_REVIEW_CONTENT_FROZEN' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'draft' AND NEW.approved_by IS NOT NULL THEN
        RAISE EXCEPTION 'SKILL_APPROVAL_INVALID' USING ERRCODE = '23514';
    END IF;
    IF NEW.approved_by IS NOT NULL AND (NEW.approved_by, NEW.approved_sha256, NEW.approved_at)
        IS DISTINCT FROM (OLD.approved_by, OLD.approved_sha256, OLD.approved_at) THEN
        IF OLD.status <> 'in_review' OR NEW.status <> 'in_review' OR OLD.approved_by IS NOT NULL
            OR NEW.approved_by IS DISTINCT FROM NULLIF(current_setting('app.actor_user_id', true), '')::uuid THEN
            RAISE EXCEPTION 'SKILL_APPROVAL_INVALID' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.status = 'published' AND (OLD.approved_by IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.skill_revisions r WHERE r.package_id = NEW.package_id
            AND r.revision = NEW.revision AND r.content_sha256 = OLD.approved_sha256
            AND r.status = 'published'
    )) THEN
        RAISE EXCEPTION 'SKILL_APPROVAL_REQUIRED' USING ERRCODE = '23514';
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
END $$;


ALTER FUNCTION public.skill_authoring_guard() OWNER TO everydayai;

--
-- Name: skill_binding_conversation_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.skill_binding_conversation_access(target uuid, organization uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT organization IS NOT DISTINCT FROM public.skill_catalog_org_id()
      AND EXISTS (SELECT 1 FROM public.users u
          WHERE u.id = NULLIF(current_setting('app.actor_user_id', true), '')::UUID
            AND u.status = 'active')
      AND EXISTS (
        SELECT 1 FROM public.conversations c
        WHERE c.id = target AND c.org_id IS NOT DISTINCT FROM organization
          AND c.scope_type = 'user' AND c.scope_id = c.user_id::TEXT
          AND (
              (organization IS NULL AND c.user_id = NULLIF(current_setting('app.actor_user_id', true), '')::UUID)
              OR (organization IS NOT NULL AND (
                  c.user_id = NULLIF(current_setting('app.actor_user_id', true), '')::UUID
                  OR EXISTS (
                      SELECT 1 FROM public.org_members actor_membership
                      WHERE actor_membership.org_id = organization
                        AND actor_membership.user_id = NULLIF(current_setting('app.actor_user_id', true), '')::UUID
                        AND actor_membership.status = 'active'
                        AND actor_membership.role IN ('owner', 'admin')
                  )
              ))
          )
          AND (organization IS NULL OR EXISTS (
              SELECT 1 FROM public.organizations o JOIN public.org_members m ON m.org_id = o.id
              WHERE o.id = organization AND o.status = 'active' AND m.user_id = c.user_id
                AND m.status = 'active'
          ))
    )
$$;


ALTER FUNCTION public.skill_binding_conversation_access(target uuid, organization uuid) OWNER TO everydayai;

--
-- Name: skill_binding_guard(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.skill_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor UUID := NULLIF(current_setting('app.actor_user_id', true), '')::UUID;
BEGIN
    IF TG_OP='UPDATE' THEN
        RAISE EXCEPTION 'SKILL_BINDING_IMMUTABLE' USING ERRCODE='23514';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('skill-binding:' || NEW.conversation_id::TEXT, 0));
    IF NOT EXISTS (
        SELECT 1 FROM public.skill_packages p JOIN public.skill_revisions r ON r.package_id=p.id
        LEFT JOIN LATERAL (SELECT * FROM public.skill_assignments
            WHERE package_id=p.id AND (org_id=NEW.org_id OR org_id IS NULL)
            ORDER BY org_id NULLS LAST LIMIT 1) a ON true
        WHERE p.id=NEW.package_id AND p.skill_key=NEW.skill_key AND r.id=NEW.revision_id AND r.status='published'
            AND ((p.scope_kind='personal' AND p.owner_user_id=actor)
                OR (p.scope_kind='org' AND p.org_id=NEW.org_id AND a.enabled AND a.revision_id=r.id)
                OR (p.scope_kind='platform' AND a.enabled AND a.revision_id=r.id))
    ) THEN
        RAISE EXCEPTION 'SKILL_BINDING_REVISION_UNAVAILABLE' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.conversation_skill_bindings
            WHERE conversation_id=NEW.conversation_id AND skill_key=NEW.skill_key)
        AND (SELECT count(*) FROM public.conversation_skill_bindings WHERE conversation_id=NEW.conversation_id) >= 4 THEN
        RAISE EXCEPTION 'SKILL_BINDING_LIMIT' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.skill_binding_guard() OWNER TO everydayai;

--
-- Name: skill_catalog_guard(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.skill_catalog_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    package public.skill_packages%ROWTYPE;
    expected_path TEXT;
BEGIN
    IF TG_TABLE_NAME IN ('skill_packages', 'skill_activation_audits') AND TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'SKILL_RECORD_IMMUTABLE' USING ERRCODE = '23514';
    END IF;
    IF TG_TABLE_NAME = 'skill_revisions' AND TG_OP <> 'INSERT' THEN
        IF TG_OP = 'DELETE' THEN
            RAISE EXCEPTION 'SKILL_REVISION_IMMUTABLE' USING ERRCODE = '23514';
        END IF;
        IF (to_jsonb(NEW) - 'status') IS DISTINCT FROM (to_jsonb(OLD) - 'status')
           OR (OLD.status = 'retired' AND NEW.status <> 'retired') THEN
            RAISE EXCEPTION 'SKILL_REVISION_IMMUTABLE' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_TABLE_NAME IN ('skill_revisions', 'skill_assignments', 'skill_activation_audits') THEN
        SELECT * INTO package FROM public.skill_packages WHERE id = NEW.package_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'SKILL_PACKAGE_UNAVAILABLE' USING ERRCODE = '23514';
        END IF;
        IF TG_TABLE_NAME = 'skill_revisions' THEN
            expected_path := CASE package.scope_kind
                WHEN 'platform' THEN 'platform'
                WHEN 'personal' THEN 'personal/' || package.owner_user_id::TEXT
                ELSE 'org/' || package.org_id::TEXT
                END || '/' || package.skill_key || '/' || NEW.revision || '/SKILL.md';
            IF NEW.nas_path <> expected_path THEN
                RAISE EXCEPTION 'SKILL_PATH_IDENTITY_MISMATCH' USING ERRCODE = '23514';
            END IF;
        ELSE
            IF package.scope_kind = 'personal' THEN
                RAISE EXCEPTION 'SKILL_PERSONAL_ASSIGNMENT_FORBIDDEN' USING ERRCODE = '23514';
            END IF;
            IF package.org_id IS NOT NULL AND package.org_id <> NEW.org_id THEN
                RAISE EXCEPTION 'SKILL_ORG_MISMATCH' USING ERRCODE = '23514';
            END IF;
            IF TG_TABLE_NAME = 'skill_assignments' THEN
                IF TG_OP = 'UPDATE' AND (NEW.org_id, NEW.package_id) IS DISTINCT FROM (OLD.org_id, OLD.package_id) THEN
                    RAISE EXCEPTION 'SKILL_ASSIGNMENT_IDENTITY_IMMUTABLE' USING ERRCODE = '23514';
                END IF;
                IF NEW.enabled AND NOT EXISTS (
                    SELECT 1 FROM public.skill_revisions
                    WHERE id = NEW.revision_id AND package_id = NEW.package_id AND status = 'published'
                ) THEN
                    RAISE EXCEPTION 'SKILL_REVISION_UNAVAILABLE' USING ERRCODE = '23514';
                END IF;
                NEW.updated_at := now();
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.skill_catalog_guard() OWNER TO everydayai;

