--
-- Name: skill_record_change(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.skill_record_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE old_data JSONB; new_data JSONB; pid UUID; owner_org UUID;
BEGIN
    new_data := to_jsonb(NEW);
    old_data := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
    IF TG_TABLE_NAME = 'skill_assignments' AND TG_OP = 'UPDATE'
       AND (new_data - 'updated_at') = (old_data - 'updated_at') THEN RETURN NEW; END IF;
    IF TG_TABLE_NAME = 'skill_revisions' AND TG_OP = 'UPDATE'
       AND new_data->>'status' = old_data->>'status' THEN RETURN NEW; END IF;
    pid := (CASE WHEN TG_TABLE_NAME = 'skill_packages' THEN new_data->>'id' ELSE new_data->>'package_id' END)::uuid;
    SELECT org_id INTO owner_org FROM public.skill_packages WHERE id = pid;
    IF TG_TABLE_NAME = 'skill_assignments' THEN owner_org := (new_data->>'org_id')::uuid; END IF;
    INSERT INTO public.skill_change_audits(package_id, org_id, actor_user_id, request_id,
        entity, action, from_state, to_state, draft_version, revision, from_revision_id, to_revision_id)
    VALUES (pid, owner_org, NULLIF(current_setting('app.actor_user_id', true), '')::uuid,
        coalesce(current_setting('app.request_id', true), ''), TG_TABLE_NAME,
        coalesce(NULLIF(current_setting('app.skill_action', true), ''), lower(TG_OP)),
        coalesce(old_data->>'status', old_data->>'enabled'),
        CASE WHEN new_data->>'deleted_at' IS NOT NULL THEN 'deleted'
            ELSE coalesce(new_data->>'status', new_data->>'enabled') END,
        (new_data->>'version')::bigint, new_data->>'revision',
        (old_data->>'revision_id')::uuid,
        (CASE WHEN TG_TABLE_NAME = 'skill_revisions' THEN new_data->>'id'
            ELSE new_data->>'revision_id' END)::uuid);
    RETURN NEW;
END $$;


ALTER FUNCTION public.skill_record_change() OWNER TO everydayai;

--
-- Name: social_analytics_due(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_analytics_due() RETURNS TABLE(org_id uuid, owner_id uuid, schedule_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 WITH revoked AS (UPDATE social_analytics_schedules s SET enabled=false,error='CREATOR_ACCESS_REVOKED'
 WHERE current_setting('app.access_kind',true)='worker' AND s.enabled AND NOT EXISTS
 (SELECT 1 FROM org_members m JOIN users u ON u.id=m.user_id JOIN organizations o ON o.id=m.org_id
 WHERE m.org_id=s.org_id AND m.user_id=s.owner_id AND m.status='active' AND u.status='active' AND o.status='active'))
 SELECT s.org_id,s.owner_id,s.id FROM social_analytics_schedules s
 WHERE current_setting('app.access_kind',true)='worker' AND s.enabled AND s.next_at<=now()
 AND EXISTS(SELECT 1 FROM org_members m JOIN users u ON u.id=m.user_id JOIN organizations o ON o.id=m.org_id
 WHERE m.org_id=s.org_id AND m.user_id=s.owner_id AND m.status='active' AND u.status='active' AND o.status='active')
 ORDER BY s.next_at LIMIT 10
$$;


ALTER FUNCTION public.social_analytics_due() OWNER TO everydayai_owner;

--
-- Name: social_analytics_event(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_analytics_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF NEW.status IN ('completed','partial','failed','needs_input','paused_auth','paused_platform') AND NEW.status IS DISTINCT FROM OLD.status THEN
 IF TG_TABLE_NAME='social_production_runs' THEN
   IF NEW.kind NOT IN ('postmortem','comment_insights','strategy') THEN RETURN NEW; END IF;
 ELSE
   IF NEW.plan->>'purpose' IS DISTINCT FROM 'metrics' THEN RETURN NEW; END IF;
 END IF;
 INSERT INTO social_analytics_events(org_id,owner_id,object_id,state) VALUES(NEW.org_id,NEW.owner_id,NEW.id,NEW.status) ON CONFLICT DO NOTHING;
 END IF; RETURN NEW; END $$;


ALTER FUNCTION public.social_analytics_event() OWNER TO everydayai_owner;

--
-- Name: social_analytics_notifications(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_analytics_notifications() RETURNS TABLE(org_id uuid, owner_id uuid, object_id uuid, state text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 UPDATE social_analytics_events e SET notified_at=now() WHERE e.id IN
 (SELECT n.id FROM social_analytics_events n WHERE current_setting('app.access_kind',true)='worker' AND n.notified_at IS NULL
 AND EXISTS(SELECT 1 FROM org_members m JOIN users u ON u.id=m.user_id JOIN organizations o ON o.id=m.org_id
 WHERE m.org_id=n.org_id AND m.user_id=n.owner_id AND m.status='active' AND u.status='active' AND o.status='active')
 ORDER BY n.created_at FOR UPDATE SKIP LOCKED LIMIT 20) RETURNING e.org_id,e.owner_id,e.object_id,e.state
$$;


ALTER FUNCTION public.social_analytics_notifications() OWNER TO everydayai_owner;

--
-- Name: social_metric_binding(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_metric_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM social_publish_intents i JOIN reach_connections c ON c.id=i.connection_id AND c.org_id=i.org_id
 WHERE i.id=NEW.intent_id AND i.org_id=NEW.org_id AND i.state='verified' AND i.connection_id=NEW.connection_id
 AND c.account_id=NEW.account_id AND c.platform=NEW.platform AND i.verification->>'remote_id'=NEW.remote_id) THEN
 RAISE EXCEPTION 'metric publication identity mismatch'; END IF;
 IF NEW.content_type NOT IN ('image','video','text') OR (NEW.published_at IS NOT NULL AND NEW.published_at>NEW.observed_at) THEN
 RAISE EXCEPTION 'invalid metric scope or publication time'; END IF;
 RETURN NEW; END $$;


