--
-- Name: social_ops_due(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_ops_due() RETURNS TABLE(org_id uuid, owner_id uuid, job_id uuid, run_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 WITH revoked_jobs AS (
 UPDATE social_research_jobs j SET status='paused_auth',last_error='CREATOR_ACCESS_REVOKED'
 WHERE current_setting('app.access_kind',true)='worker' AND j.status IN ('queued','running','waiting_budget')
 AND NOT EXISTS(SELECT 1 FROM org_members m JOIN organizations o ON o.id=m.org_id JOIN users u ON u.id=m.user_id
 WHERE m.org_id=j.org_id AND m.user_id=j.owner_id AND m.status='active' AND o.status='active' AND u.status='active')
 ), revoked_runs AS (
 UPDATE social_production_runs r SET status='needs_input',error='CREATOR_ACCESS_REVOKED'
 WHERE current_setting('app.access_kind',true)='worker' AND r.status IN ('queued','running')
 AND NOT EXISTS(SELECT 1 FROM org_members m JOIN organizations o ON o.id=m.org_id JOIN users u ON u.id=m.user_id
 WHERE m.org_id=r.org_id AND m.user_id=r.owner_id AND m.status='active' AND o.status='active' AND u.status='active')
 )
 SELECT q.org_id,q.owner_id,q.job_id,q.run_id FROM (SELECT j.org_id,j.owner_id,j.id AS job_id,NULL::uuid AS run_id FROM social_research_jobs j
 WHERE current_setting('app.access_kind',true)='worker' AND
 (j.plan->>'purpose' IS DISTINCT FROM 'metrics' OR current_setting('app.social_analytics_enabled',true)='true') AND
 ((j.status IN ('queued','running','waiting_budget') AND j.next_eligible_at<=now()) OR
 (j.status IN ('completed','partial','failed') AND j.next_occurrence_at<=now()))
 ORDER BY j.next_eligible_at,j.created_at LIMIT 10) q
 UNION ALL
 SELECT p.org_id,p.owner_id,p.job_id,p.run_id FROM (SELECT r.org_id,r.owner_id,r.job_id,r.id AS run_id FROM social_production_runs r
 WHERE current_setting('app.access_kind',true)='worker' AND
 (r.kind NOT IN ('postmortem','comment_insights','strategy') OR current_setting('app.social_analytics_enabled',true)='true') AND (r.status='queued' OR
 (r.status='running' AND r.lease_expires_at<now())) ORDER BY r.created_at LIMIT 10) p
$$;


ALTER FUNCTION public.social_ops_due() OWNER TO everydayai_owner;

--
-- Name: social_publish_due(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_publish_due() RETURNS TABLE(org_id uuid, owner_id uuid, intent_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF current_setting('app.access_kind',true) IS DISTINCT FROM 'worker' THEN RETURN; END IF;
 UPDATE social_publish_intents i SET state='expired',grant_hash=NULL,lease_token=NULL,error='AUTHORIZATION_EXPIRED',updated_at=now()
 WHERE scheduled_at IS NOT NULL AND state IN ('scheduled','preparing','waiting_budget','paused') AND authorized_until<now();
 UPDATE social_publish_intents SET state='uncertain',error='DISPATCH_INTERRUPTED',updated_at=now()
 WHERE scheduled_at IS NOT NULL AND state='dispatching' AND lease_expires_at<now();
 UPDATE social_publish_intents i SET state='paused',grant_hash=NULL,lease_token=NULL,error='CREATOR_ACCESS_REVOKED',updated_at=now()
 WHERE scheduled_at IS NOT NULL AND state IN ('scheduled','preparing','waiting_budget') AND NOT EXISTS
 (SELECT 1 FROM org_members m JOIN organizations o ON o.id=m.org_id JOIN users u ON u.id=m.user_id
 WHERE m.org_id=i.org_id AND m.user_id=i.owner_id AND m.status='active' AND o.status='active' AND u.status='active');
 RETURN QUERY SELECT i.org_id,i.owner_id,i.id FROM social_publish_intents i
 WHERE i.scheduled_at<=now() AND i.authorized_until>=now() AND i.grant_hash IS NOT NULL
 AND ((i.state IN ('scheduled','waiting_budget') AND i.next_attempt_at<=now()) OR (i.state='preparing' AND i.lease_expires_at<now()))
 ORDER BY i.scheduled_at LIMIT 10;
END $$;


ALTER FUNCTION public.social_publish_due() OWNER TO everydayai_owner;

--
-- Name: social_publish_event(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_publish_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF TG_OP='INSERT' OR NEW.state IS DISTINCT FROM OLD.state OR NEW.approval_hash IS DISTINCT FROM OLD.approval_hash THEN
 INSERT INTO social_publish_events(org_id,intent_id,state,reason,actor_id,snapshot)
 VALUES(NEW.org_id,NEW.id,NEW.state,NEW.error,NULLIF(current_setting('app.actor_user_id',true),'')::uuid,
 jsonb_build_object('approval_hash',NEW.approval_hash,'revision',NEW.revision,'connection_id',NEW.connection_id,
 'credential_version',NEW.credential_version,'visibility',NEW.visibility,'scheduled_at',NEW.scheduled_at,
 'schedule_timezone',NEW.schedule_timezone,'authorized_until',NEW.authorized_until,'approved_by',NEW.approved_by,
 'data',NEW.payload->'data'));
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.social_publish_event() OWNER TO everydayai_owner;

--
-- Name: social_publish_notifications(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_publish_notifications() RETURNS TABLE(org_id uuid, owner_id uuid, intent_id uuid, state text, reason text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 WITH picked AS (SELECT e.id FROM social_publish_events e WHERE current_setting('app.access_kind',true)='worker' AND NOT e.notified
 AND EXISTS(SELECT 1 FROM social_publish_intents i WHERE i.id=e.intent_id AND i.scheduled_at IS NOT NULL)
 AND e.state IN ('scheduled','waiting_budget','paused','submitted','verified','uncertain','failed','cancelled','expired','invalidated')
 ORDER BY e.id LIMIT 20 FOR UPDATE SKIP LOCKED), claimed AS (UPDATE social_publish_events e SET notified=true FROM picked p WHERE e.id=p.id RETURNING e.*)
 SELECT e.org_id,i.owner_id,e.intent_id,e.state,e.reason FROM claimed e JOIN social_publish_intents i ON i.id=e.intent_id AND i.org_id=e.org_id
$$;


ALTER FUNCTION public.social_publish_notifications() OWNER TO everydayai_owner;

--
-- Name: social_revoke_changed_connection(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_revoke_changed_connection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF NEW.credential_version<>OLD.credential_version OR NEW.status<>OLD.status THEN
 UPDATE social_publish_intents SET state='paused',grant_hash=NULL,lease_token=NULL,error='CONNECTION_CHANGED',updated_at=now()
 WHERE connection_id=NEW.id AND org_id=NEW.org_id AND scheduled_at IS NOT NULL AND state IN ('awaiting_confirmation','scheduled','waiting_budget','paused','preparing');
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.social_revoke_changed_connection() OWNER TO everydayai_owner;

--
-- Name: social_revoke_changed_content(); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.social_revoke_changed_content() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF NEW.current_revision<>OLD.current_revision THEN
 UPDATE social_publish_intents SET state='invalidated',grant_hash=NULL,lease_token=NULL,error='CONTENT_CHANGED',updated_at=now()
 WHERE content_id=NEW.id AND org_id=NEW.org_id AND scheduled_at IS NOT NULL AND state IN ('awaiting_confirmation','scheduled','waiting_budget','paused','preparing');
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.social_revoke_changed_content() OWNER TO everydayai_owner;

--
-- Name: stage_wecom_attachment(uuid, uuid, text, uuid, text, jsonb, text, text, text, text, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.stage_wecom_attachment(p_conversation_id uuid, p_source_message_id uuid, p_source_provider_id text, p_sender_user_id uuid, p_sender_channel_identity text, p_content jsonb, p_original_name text, p_url text, p_workspace_path text, p_storage_scope text, p_mime_type text, p_size bigint, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_attachment conversation_attachment_refs%ROWTYPE;
BEGIN
    IF p_org_id IS NULL
       OR p_conversation_id IS NULL
       OR p_source_message_id IS NULL
       OR p_sender_user_id IS NULL
       OR COALESCE(BTRIM(p_source_provider_id), '') = ''
       OR COALESCE(BTRIM(p_original_name), '') = ''
       OR COALESCE(BTRIM(p_url), '') = ''
       OR COALESCE(BTRIM(p_workspace_path), '') = ''
       OR p_storage_scope NOT IN ('user', 'channel')
       OR COALESCE(BTRIM(p_mime_type), '') = ''
       OR p_size < 0
       OR jsonb_typeof(p_content) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'WECOM_ATTACHMENT_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_attachment
      FROM conversation_attachment_refs
     WHERE org_id = p_org_id
       AND channel = 'wecom'
       AND source_provider_id = BTRIM(p_source_provider_id)
     FOR UPDATE;
    IF FOUND THEN
        RETURN jsonb_build_object(
            'attachment_id', v_attachment.id,
            'message_id', v_attachment.source_message_id,
            'already_staged', TRUE
        );
    END IF;

    SELECT * INTO v_conversation
      FROM conversations
     WHERE id = p_conversation_id
     FOR UPDATE;
    IF NOT FOUND OR v_conversation.org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'WECOM_ATTACHMENT_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF (v_conversation.scope_type = 'channel') IS DISTINCT FROM
       (p_storage_scope = 'channel') THEN
        RAISE EXCEPTION 'WECOM_ATTACHMENT_STORAGE_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    INSERT INTO messages(
        id, conversation_id, org_id, role, content, status,
        sender_user_id, sender_channel_identity
    ) VALUES (
        p_source_message_id, p_conversation_id, p_org_id, 'user',
        p_content, 'completed', p_sender_user_id,
        NULLIF(BTRIM(p_sender_channel_identity), '')
    );

    INSERT INTO conversation_attachment_refs(
        org_id, conversation_id, source_message_id, source_provider_id,
        channel, sender_user_id, original_name, url, workspace_path,
        storage_scope, mime_type, size, status, reference_state, ready_at
    ) VALUES (
        p_org_id, p_conversation_id, p_source_message_id,
        BTRIM(p_source_provider_id), 'wecom', p_sender_user_id,
        BTRIM(p_original_name), BTRIM(p_url), BTRIM(p_workspace_path), p_storage_scope,
        BTRIM(p_mime_type), p_size, 'ready', 'active', NOW()
    )
    RETURNING * INTO v_attachment;

    PERFORM increment_message_count(p_conversation_id, p_org_id);
    RETURN jsonb_build_object(
        'attachment_id', v_attachment.id,
        'message_id', p_source_message_id,
        'already_staged', FALSE
    );
END;
$$;


ALTER FUNCTION public.stage_wecom_attachment(p_conversation_id uuid, p_source_message_id uuid, p_source_provider_id text, p_sender_user_id uuid, p_sender_channel_identity text, p_content jsonb, p_original_name text, p_url text, p_workspace_path text, p_storage_scope text, p_mime_type text, p_size bigint, p_org_id uuid) OWNER TO everydayai;

--
-- Name: stage_wecom_attachment_v2(uuid, uuid, text, uuid, text, jsonb, text, text, text, text, text, bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.stage_wecom_attachment_v2(p_conversation_id uuid, p_source_message_id uuid, p_source_provider_id text, p_sender_user_id uuid, p_sender_channel_identity text, p_content jsonb, p_original_name text, p_url text, p_workspace_path text, p_storage_scope text, p_mime_type text, p_size bigint, p_asset_identity jsonb, p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_conversation conversations%ROWTYPE;
    v_existing conversation_attachment_refs%ROWTYPE;
    v_attachment_id UUID := gen_random_uuid();
    v_set_id UUID;
    v_content JSONB;
    v_hash TEXT;
BEGIN
    v_hash := NULLIF(BTRIM(p_asset_identity->>'content_sha256'), '');
    IF p_org_id IS NULL OR p_conversation_id IS NULL
       OR p_source_message_id IS NULL OR p_sender_user_id IS NULL
       OR COALESCE(BTRIM(p_source_provider_id), '') = ''
       OR jsonb_typeof(p_content) IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_content) <> 1
       OR jsonb_typeof(p_asset_identity) IS DISTINCT FROM 'object'
       OR COALESCE(p_asset_identity->>'canonical_name', '') = ''
       OR COALESCE(p_asset_identity->>'detected_mime_type', '') = ''
       OR COALESCE(p_asset_identity->>'detection_source', '') = ''
       OR v_hash !~ '^[0-9a-f]{64}$'
       OR COALESCE(BTRIM(p_url), '') = ''
       OR COALESCE(BTRIM(p_workspace_path), '') = ''
       OR p_storage_scope NOT IN ('user', 'channel')
       OR p_size < 0 THEN
        RAISE EXCEPTION 'WECOM_ATTACHMENT_ARGUMENT_INVALID'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_existing
      FROM conversation_attachment_refs
     WHERE org_id = p_org_id AND channel = 'wecom'
       AND source_provider_id = BTRIM(p_source_provider_id)
     FOR UPDATE;
    IF FOUND THEN
        IF v_existing.conversation_id IS DISTINCT FROM p_conversation_id
           OR v_existing.sender_user_id IS DISTINCT FROM p_sender_user_id THEN
            RAISE EXCEPTION 'WECOM_ATTACHMENT_REPLAY_SCOPE_MISMATCH'
                USING ERRCODE = '42501';
        END IF;
        IF v_existing.content_sha256 IS NOT NULL
           AND v_existing.content_sha256 IS DISTINCT FROM v_hash THEN
            RAISE EXCEPTION 'WECOM_ATTACHMENT_CONTENT_CONFLICT'
                USING ERRCODE = '23505';
        END IF;
        UPDATE conversation_attachment_refs
           SET provider_name = COALESCE(
                   NULLIF(p_asset_identity->>'provider_name', ''),
                   provider_name
               ),
               canonical_name = p_asset_identity->>'canonical_name',
               detected_mime_type = p_asset_identity->>'detected_mime_type',
               detection_source = p_asset_identity->>'detection_source',
               content_sha256 = v_hash,
               original_name = p_asset_identity->>'canonical_name',
               mime_type = p_asset_identity->>'detected_mime_type'
         WHERE id = v_existing.id;
        v_content := jsonb_set(
            p_content, '{0,asset_id}',
            to_jsonb(v_existing.id::TEXT), TRUE
        );
        UPDATE messages
           SET content = v_content
         WHERE id = v_existing.source_message_id
           AND conversation_id = p_conversation_id
           AND org_id = p_org_id;
        RETURN jsonb_build_object(
            'attachment_id', v_existing.id,
            'message_id', v_existing.source_message_id,
            'attachment_set_id', v_existing.attachment_set_id,
            'already_staged', TRUE
        );
    END IF;

    SELECT * INTO v_conversation FROM conversations
     WHERE id = p_conversation_id FOR UPDATE;
    IF NOT FOUND OR v_conversation.org_id IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'WECOM_ATTACHMENT_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF (v_conversation.scope_type = 'channel') IS DISTINCT FROM
       (p_storage_scope = 'channel') THEN
        RAISE EXCEPTION 'WECOM_ATTACHMENT_STORAGE_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    SELECT attachment_set_id INTO v_set_id
      FROM conversation_attachment_refs a
     WHERE a.conversation_id = p_conversation_id
       AND a.org_id = p_org_id AND a.status = 'ready'
       AND a.reference_state = 'active'
     ORDER BY a.created_at DESC LIMIT 1;
    IF v_set_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM task_attachment_refs r
         WHERE r.attachment_set_id = v_set_id
    ) THEN
        UPDATE conversation_attachment_refs
           SET reference_state = 'replaced'
         WHERE conversation_id = p_conversation_id
           AND org_id = p_org_id
           AND attachment_set_id = v_set_id
           AND reference_state = 'active';
        v_set_id := NULL;
    END IF;
    v_set_id := COALESCE(v_set_id, gen_random_uuid());
    v_content := jsonb_set(
        p_content, '{0,asset_id}', to_jsonb(v_attachment_id::TEXT), TRUE
    );

    INSERT INTO messages(
        id, conversation_id, org_id, role, content, status,
        sender_user_id, sender_channel_identity
    ) VALUES (
        p_source_message_id, p_conversation_id, p_org_id, 'user',
        v_content, 'completed', p_sender_user_id,
        NULLIF(BTRIM(p_sender_channel_identity), '')
    );
    INSERT INTO conversation_attachment_refs(
        id, org_id, conversation_id, source_message_id, source_provider_id,
        channel, sender_user_id, original_name, url, workspace_path,
        storage_scope, mime_type, size, status, reference_state, ready_at,
        provider_name, canonical_name, detected_mime_type, detection_source,
        content_sha256, attachment_set_id
    ) VALUES (
        v_attachment_id, p_org_id, p_conversation_id, p_source_message_id,
        BTRIM(p_source_provider_id), 'wecom', p_sender_user_id,
        p_asset_identity->>'canonical_name', BTRIM(p_url),
        BTRIM(p_workspace_path), p_storage_scope,
        p_asset_identity->>'detected_mime_type', p_size, 'ready', 'active',
        NOW(), NULLIF(p_asset_identity->>'provider_name', ''),
        p_asset_identity->>'canonical_name',
        p_asset_identity->>'detected_mime_type',
        p_asset_identity->>'detection_source', v_hash, v_set_id
    );
    PERFORM increment_message_count(p_conversation_id, p_org_id);
    RETURN jsonb_build_object(
        'attachment_id', v_attachment_id,
        'message_id', p_source_message_id,
        'attachment_set_id', v_set_id,
        'already_staged', FALSE
    );
END;
$_$;


ALTER FUNCTION public.stage_wecom_attachment_v2(p_conversation_id uuid, p_source_message_id uuid, p_source_provider_id text, p_sender_user_id uuid, p_sender_channel_identity text, p_content jsonb, p_original_name text, p_url text, p_workspace_path text, p_storage_scope text, p_mime_type text, p_size bigint, p_asset_identity jsonb, p_org_id uuid) OWNER TO everydayai;

--
-- Name: start_detail_page_run(uuid, integer, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.start_detail_page_run(p_project_id uuid, p_version integer, p_request_id uuid, p_plans jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE d public.detail_projects%ROWTYPE; actor UUID:=NULLIF(current_setting('app.actor_user_id',true),'')::uuid;
 org UUID:=NULLIF(current_setting('app.org_id',true),'')::uuid; entry JSONB;
BEGIN
 IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',true)<>'runtime' OR actor IS NULL OR p_request_id IS NULL THEN
  RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO d FROM public.detail_projects WHERE id=p_project_id AND user_id=actor AND org_id IS NOT DISTINCT FROM org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DETAIL_PROJECT_DENIED' USING ERRCODE='42501'; END IF;
 IF d.run_state->>'request_id'=p_request_id::text THEN RETURN to_jsonb(d); END IF;
 IF d.status NOT IN ('draft','completed','failed') THEN RAISE EXCEPTION 'DETAIL_RUN_ACTIVE' USING ERRCODE='55000'; END IF;
 IF d.version<>p_version THEN RAISE EXCEPTION 'DETAIL_PROJECT_VERSION_CONFLICT' USING ERRCODE='55000'; END IF;
 -- Do not strand unresolved provider work when advancing the current run.
 IF EXISTS(SELECT 1 FROM public.ecom_image_plans p WHERE p.project_id=d.id
   AND p.generation_run_id::text=d.run_state->>'run_id' AND (p.status='planning'
    OR EXISTS(SELECT 1 FROM jsonb_each(COALESCE(p.recovery_state->'attempts','{}'::jsonb)) a
       WHERE a.value->>'outcome' IN ('started','uncertain') AND NOT public.detail_attempt_is_closed_timeout(a.value))))
  OR EXISTS(SELECT 1 FROM public.tasks t WHERE t.user_id=actor AND t.org_id IS NOT DISTINCT FROM org
    AND t.request_params->'_media_request_v1'->'origin'->>'project_id'=d.id::text
    AND t.request_params->'_media_request_v1'->'origin'->>'generation_run_id'=d.run_state->>'run_id'
    AND t.status NOT IN ('completed','failed','cancelled')) THEN
  RAISE EXCEPTION 'ECOM_PLAN_EXECUTION_UNCERTAIN' USING ERRCODE='55000'; END IF;
 IF jsonb_typeof(p_plans)<>'array' OR jsonb_array_length(p_plans)<>(CASE WHEN d.content_type='default' THEN 2 ELSE 1 END) THEN
  RAISE EXCEPTION 'DETAIL_PLAN_INVALID' USING ERRCODE='22023'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_plans) LOOP
  IF entry->>'project_id' IS DISTINCT FROM d.id::text OR entry->>'user_id' IS DISTINCT FROM actor::text
   OR entry->>'org_id' IS DISTINCT FROM org::text OR entry->>'generation_run_id' IS DISTINCT FROM p_request_id::text
   OR (entry->>'image_count')::int<>(CASE WHEN d.content_type='default' THEN 7 ELSE d.image_count END)
   OR entry->'model_settings'->>'model' IS DISTINCT FROM d.prompt_model THEN
   RAISE EXCEPTION 'DETAIL_PLAN_INVALID' USING ERRCODE='22023'; END IF;
  INSERT INTO public.ecom_image_plans(id,user_id,org_id,source_kind,project_id,generation_run_id,invocation_key,input_digest,
    status,current_stage,image_count,input_snapshot,prompt_versions,model_settings,target_size)
   VALUES((entry->>'id')::uuid,actor,org,'detail_project',d.id,p_request_id,entry->>'invocation_key',entry->>'input_digest',
    'planning',1,(entry->>'image_count')::int,entry->'input_snapshot',entry->'prompt_versions',entry->'model_settings',entry->'target_size');
 END LOOP;
 UPDATE public.detail_projects SET status='analyzing',version=version+1,updated_at=NOW(),
  run_state=jsonb_build_object('run_id',p_request_id,'request_id',p_request_id,'started_at',NOW()) WHERE id=d.id RETURNING * INTO d;
 RETURN to_jsonb(d);
END $$;


ALTER FUNCTION public.start_detail_page_run(p_project_id uuid, p_version integer, p_request_id uuid, p_plans jsonb) OWNER TO everydayai_owner;

--
-- Name: start_scheduled_task_run(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.start_scheduled_task_run(p_task_id uuid, p_org_id uuid, p_run_token uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_task scheduled_tasks%ROWTYPE; v_inserted UUID; v_definition JSONB;
BEGIN
    SELECT * INTO v_task FROM scheduled_tasks WHERE id=p_task_id AND org_id=p_org_id FOR UPDATE;
    IF NOT FOUND OR v_task.status <> 'running' OR v_task.run_token IS DISTINCT FROM p_run_token THEN
        RETURN jsonb_build_object('outcome','claim_lost');
    END IF;
    -- A repeated starter cannot revoke a run which crossed the start boundary
    -- before the user paused future scheduling.
    IF EXISTS (SELECT 1 FROM scheduled_task_runs WHERE id=p_run_token AND task_id=p_task_id AND org_id=p_org_id) THEN
        RETURN jsonb_build_object('outcome','already_started');
    END IF;
    IF NOT v_task.schedule_enabled AND (NOT v_task.run_manual OR v_task.revision <> v_task.run_claim_revision) THEN
        UPDATE scheduled_tasks SET status='paused',next_run_at=NULL,updated_at=NOW() WHERE id=p_task_id;
        RETURN jsonb_build_object('outcome','paused_before_start');
    END IF;
    SELECT definition_snapshot INTO STRICT v_definition FROM public.scheduled_task_config_revisions
    WHERE id=v_task.run_config_revision AND task_id=p_task_id AND org_id=p_org_id;
    INSERT INTO scheduled_task_runs(id,task_id,org_id,execution_id,plan_snapshot,status,started_at,
        config_revision,skill_revision_snapshot,definition_snapshot)
    VALUES(p_run_token,p_task_id,p_org_id,p_run_token,v_definition->'plan_snapshot','running',NOW(),
        v_task.run_config_revision,v_definition->'skill_revision_snapshot',v_definition)
    ON CONFLICT(id) DO NOTHING RETURNING id INTO v_inserted;
    RETURN jsonb_build_object('outcome',CASE WHEN v_inserted IS NULL THEN 'already_started' ELSE 'started' END,
                             'run_id',v_inserted,'config_revision',v_task.run_config_revision,'definition_snapshot',v_definition);
END $$;


ALTER FUNCTION public.start_scheduled_task_run(p_task_id uuid, p_org_id uuid, p_run_token uuid) OWNER TO everydayai;

--
-- Name: stop_detail_delivery_recovery(uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.stop_detail_delivery_recovery(p_project_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',true) IS DISTINCT FROM 'runtime' THEN
  RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 UPDATE public.detail_projects SET run_state=run_state||'{"delivery_stopped":true}'::jsonb,updated_at=NOW()
  WHERE id=p_project_id AND user_id=NULLIF(current_setting('app.actor_user_id',true),'')::uuid
  AND org_id IS NOT DISTINCT FROM NULLIF(current_setting('app.org_id',true),'')::uuid AND status<>'archived';
 IF NOT FOUND THEN RAISE EXCEPTION 'DETAIL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN TRUE;
END $$;


ALTER FUNCTION public.stop_detail_delivery_recovery(p_project_id uuid) OWNER TO everydayai_owner;

--
-- Name: stop_queued_chat_image(uuid, uuid); Type: FUNCTION; Schema: public; Owner: everydayai_owner
--

CREATE FUNCTION public.stop_queued_chat_image(p_task_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_task public.tasks%ROWTYPE;
BEGIN
    IF SESSION_USER<>'everydayai' OR current_setting('app.access_kind',TRUE) IS DISTINCT FROM 'runtime'
       OR NULLIF(current_setting('app.org_id',TRUE),'')::UUID IS DISTINCT FROM p_org_id THEN
        RAISE EXCEPTION 'CHAT_IMAGE_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
    SELECT * INTO v_task FROM public.tasks WHERE id=p_task_id AND user_id=NULLIF(current_setting('app.actor_user_id',TRUE),'')::UUID
        AND org_id IS NOT DISTINCT FROM p_org_id AND type='image' FOR UPDATE;
    IF NOT FOUND OR NOT (v_task.request_params ? '_media_request_v1') THEN
        RAISE EXCEPTION 'CHAT_IMAGE_TASK_DENIED' USING ERRCODE='42501';
    END IF;
    IF v_task.request_params->'_media_lifecycle_v1'->>'phase'<>'queued' THEN
        RETURN jsonb_build_object('outcome','already_submitted','message','任务已领取或提交，无法撤回；将继续核实与结算');
    END IF;
    UPDATE public.tasks SET result=jsonb_build_object('status','failed','error','排队任务已停止','cancelled',TRUE),
        request_params=jsonb_set(request_params,'{_media_lifecycle_v1,phase}','"settling"') WHERE id=p_task_id;
    RETURN jsonb_build_object('outcome','stopped');
END;
$$;


ALTER FUNCTION public.stop_queued_chat_image(p_task_id uuid, p_org_id uuid) OWNER TO everydayai_owner;

--
-- Name: sync_conversation_delivery_status(); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.sync_conversation_delivery_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    UPDATE conversation_delivery_sessions
       SET status = CASE NEW.status
           WHEN 'paused' THEN 'paused'
           WHEN 'completed' THEN 'committed'
           WHEN 'failed' THEN 'failed'
           WHEN 'cancelled' THEN 'cancelled'
           ELSE status
       END,
       updated_at = NOW()
     WHERE task_id = NEW.id
       AND NEW.status IN ('paused', 'completed', 'failed', 'cancelled');
    IF NEW.status IN ('completed', 'failed', 'cancelled') THEN
        DELETE FROM conversation_delivery_events
         WHERE task_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_conversation_delivery_status() OWNER TO everydayai;

