--
-- Name: transition_change_set(uuid, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.transition_change_set(p_change_set_id uuid, p_org_id uuid, p_expected_status text, p_next_status text, p_actor_id text, p_actor_type text, p_event_type text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_row public.change_sets%ROWTYPE;
    v_from_status TEXT;
    v_sequence BIGINT;
BEGIN
    SELECT * INTO v_row
      FROM public.change_sets
     WHERE id = p_change_set_id AND org_id = p_org_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('outcome', 'missing');
    END IF;

    IF v_row.status <> p_expected_status THEN
        RETURN jsonb_build_object('outcome', 'state_conflict', 'change_set', to_jsonb(v_row));
    END IF;

    -- 到期优先于后续人工操作；committing 由恢复器处理，避免业务提交中途被过期抢占。
    IF v_row.expires_at <= NOW()
       AND v_row.status NOT IN ('applied', 'cancelled', 'rejected', 'failed', 'expired', 'conflicted', 'committing')
       AND p_next_status <> 'expired' THEN
        v_from_status := v_row.status;
        UPDATE public.change_sets
           SET status = 'expired', updated_by = p_actor_id, updated_by_type = p_actor_type,
               revision = revision + 1, updated_at = NOW(),
               audit_subject = audit_subject || jsonb_build_object('last_actor_id', p_actor_id, 'last_actor_type', p_actor_type)
         WHERE id = v_row.id
         RETURNING * INTO v_row;
        SELECT COALESCE(MAX(sequence), 0) + 1 INTO v_sequence
          FROM public.change_events WHERE change_set_id = v_row.id;
        INSERT INTO public.change_events(
            change_set_id, org_id, sequence, event_type, from_status, to_status,
            actor_id, actor_type, payload
        ) VALUES (
            v_row.id, v_row.org_id, v_sequence, 'expired', v_from_status, 'expired',
            p_actor_id, p_actor_type, '{}'::JSONB
        );
        RETURN jsonb_build_object('outcome', 'expired', 'change_set', to_jsonb(v_row));
    END IF;

    IF NOT (
        (v_row.status = 'draft' AND p_next_status IN ('resolving', 'cancelled', 'expired')) OR
        (v_row.status = 'resolving' AND p_next_status IN ('proposed', 'failed', 'cancelled', 'expired')) OR
        (v_row.status = 'proposed' AND p_next_status IN ('validating', 'rejected', 'failed', 'cancelled', 'expired')) OR
        (v_row.status = 'validating' AND p_next_status IN ('preflighting', 'rejected', 'failed', 'cancelled', 'expired', 'conflicted')) OR
        (v_row.status = 'preflighting' AND p_next_status IN ('awaiting_approval', 'committing', 'rejected', 'failed', 'cancelled', 'expired', 'conflicted')) OR
        (v_row.status = 'awaiting_approval' AND p_next_status IN ('committing', 'rejected', 'failed', 'cancelled', 'expired', 'conflicted')) OR
        (v_row.status = 'committing' AND p_next_status IN ('applied', 'failed', 'conflicted'))
    ) THEN
        RETURN jsonb_build_object('outcome', 'invalid_transition', 'change_set', to_jsonb(v_row));
    END IF;

    -- Only checked, explicit task requests can skip an additional approval.
    IF v_row.status = 'preflighting' AND p_next_status = 'committing' AND NOT COALESCE((
        v_row.resource_type = 'scheduled_task'
        AND v_row.operation IN ('create','update','pause','resume')
        AND v_row.created_by = p_actor_id AND p_actor_type = 'user'
        AND p_event_type = 'request_accepted'
        AND v_row.policy_snapshot->'requires_approval' = 'false'::JSONB
        AND v_row.policy_snapshot->>'risk_level' IN ('low','medium')
        AND v_row.policy_snapshot#>>'{submission,version}' = 'scheduled_task.submit.v1'
        AND v_row.policy_snapshot#>>'{submission,mode}' = 'apply_if_allowed'
        AND v_row.policy_snapshot#>>'{submission,actor_id}' = p_actor_id
        AND NOT EXISTS (
            SELECT 1 FROM (VALUES ('authorization'),('validation'),('preflight')) AS required(kind)
             WHERE NOT EXISTS (
                SELECT 1 FROM public.change_checks c
                 WHERE c.change_set_id=v_row.id AND c.org_id=v_row.org_id
                   AND c.check_type=required.kind
                   AND (c.status='passed' OR (required.kind='preflight' AND c.status='skipped'))
                   AND COALESCE(c.result->'passed', 'true'::JSONB) = 'true'::JSONB
             )
        )
    ), FALSE) THEN
        RETURN jsonb_build_object('outcome','invalid_transition','change_set',to_jsonb(v_row));
    END IF;

    v_from_status := v_row.status;
    UPDATE public.change_sets
       SET status = p_next_status,
           updated_by = p_actor_id,
           updated_by_type = p_actor_type,
           committed_revision = CASE WHEN p_next_status = 'applied' THEN p_payload->>'new_revision' ELSE committed_revision END,
           error_code = CASE WHEN p_next_status = 'failed' THEN COALESCE(p_payload->>'error_type', 'changeset_failed') ELSE error_code END,
           error_message = CASE WHEN p_next_status = 'failed' THEN p_payload->>'error_message' ELSE error_message END,
           conflict = CASE WHEN p_next_status = 'conflicted' THEN p_payload ELSE conflict END,
           audit_subject = audit_subject || jsonb_build_object('last_actor_id', p_actor_id, 'last_actor_type', p_actor_type),
           revision = revision + 1,
           updated_at = NOW()
     WHERE id = v_row.id
     RETURNING * INTO v_row;
    SELECT COALESCE(MAX(sequence), 0) + 1 INTO v_sequence
      FROM public.change_events WHERE change_set_id = v_row.id;
    INSERT INTO public.change_events(
        change_set_id, org_id, sequence, event_type, from_status, to_status,
        actor_id, actor_type, payload
    ) VALUES (
        v_row.id, v_row.org_id, v_sequence, p_event_type, v_from_status, p_next_status,
        p_actor_id, p_actor_type, COALESCE(p_payload, '{}'::JSONB)
    );
    RETURN jsonb_build_object('outcome', 'transitioned', 'change_set', to_jsonb(v_row));
END;
$$;


ALTER FUNCTION public.transition_change_set(p_change_set_id uuid, p_org_id uuid, p_expected_status text, p_next_status text, p_actor_id text, p_actor_type text, p_event_type text, p_payload jsonb) OWNER TO everydayai;

--
-- Name: transition_chat_form_state(uuid, uuid, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.transition_chat_form_state(p_message_id uuid, p_conversation_id uuid, p_form_id text, p_expected_status text, p_next_status text, p_result_message text DEFAULT NULL::text, p_next_form jsonb DEFAULT NULL::jsonb, p_error_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_content JSONB;
    v_block JSONB;
    v_path TEXT[];
    v_current_status TEXT;
BEGIN
    IF p_expected_status NOT IN ('open', 'submitting')
       OR p_next_status NOT IN ('open', 'submitting', 'cancelled', 'submitted') THEN
        RAISE EXCEPTION 'CHAT_FORM_STATE_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT content::JSONB INTO v_content FROM messages
      WHERE id = p_message_id AND conversation_id = p_conversation_id AND role = 'assistant'
      FOR UPDATE;
    IF NOT FOUND OR jsonb_typeof(v_content) <> 'array' THEN
        RETURN jsonb_build_object('outcome', 'message_missing');
    END IF;

    WITH RECURSIVE form_nodes(path, block) AS (
        SELECT ARRAY[(item.ordinality - 1)::TEXT], item.value
          FROM jsonb_array_elements(v_content) WITH ORDINALITY AS item(value, ordinality)
        UNION ALL
        SELECT array_append(node.path, 'next_form'), node.block->'next_form'
          FROM form_nodes AS node
         WHERE jsonb_typeof(node.block->'next_form') = 'object'
    )
    SELECT path, block INTO v_path, v_block
      FROM form_nodes
     WHERE block->>'type' = 'form' AND block->>'form_id' = p_form_id
     LIMIT 1;

    IF v_path IS NULL THEN
        RETURN jsonb_build_object('outcome', 'form_missing');
    END IF;

    v_current_status := COALESCE(v_block->>'status', 'open');
    IF v_current_status <> p_expected_status THEN
        RETURN jsonb_build_object('outcome', 'state_conflict', 'status', v_current_status);
    END IF;

    v_block := v_block || jsonb_build_object('status', p_next_status);
    IF p_result_message IS NOT NULL THEN
        v_block := v_block || jsonb_build_object('result_message', p_result_message);
    END IF;
    IF p_next_form IS NOT NULL THEN
        v_block := v_block || jsonb_build_object('next_form', p_next_form);
    END IF;
    IF p_error_message IS NOT NULL THEN
        v_block := v_block || jsonb_build_object('error_message', p_error_message);
    ELSIF p_next_status <> 'open' THEN
        v_block := v_block - 'error_message';
    END IF;

    v_content := jsonb_set(v_content, v_path, v_block, FALSE);
    UPDATE messages SET content = v_content::TEXT WHERE id = p_message_id;
    RETURN jsonb_build_object('outcome', 'transitioned', 'status', p_next_status);
END;
$$;


ALTER FUNCTION public.transition_chat_form_state(p_message_id uuid, p_conversation_id uuid, p_form_id text, p_expected_status text, p_next_status text, p_result_message text, p_next_form jsonb, p_error_message text) OWNER TO everydayai;

--
-- Name: update_generation_progress(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.update_generation_progress(p_task_id uuid, p_execution_token uuid, p_accumulated_content text, p_accumulated_blocks jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_task tasks%ROWTYPE;
BEGIN
    IF p_task_id IS NULL
       OR p_execution_token IS NULL
       OR p_accumulated_content IS NULL
       OR p_accumulated_blocks IS NULL
       OR jsonb_typeof(p_accumulated_blocks) <> 'array' THEN
        RAISE EXCEPTION 'ACTOR_PROGRESS_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_task FROM tasks WHERE id = p_task_id FOR UPDATE;
    IF v_task.id IS NULL OR v_task.type <> 'chat' THEN
        RAISE EXCEPTION 'ACTOR_TASK_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
    IF v_task.status <> 'running' THEN
        RETURN jsonb_build_object(
            'outcome', 'terminal', 'status', v_task.status
        );
    END IF;
    IF v_task.execution_token IS DISTINCT FROM p_execution_token THEN
        RETURN jsonb_build_object('outcome', 'ownership_lost');
    END IF;
    IF v_task.lease_expires_at IS NULL OR v_task.lease_expires_at <= NOW() THEN
        RETURN jsonb_build_object('outcome', 'lease_expired');
    END IF;

    UPDATE tasks
       SET accumulated_content = p_accumulated_content,
           accumulated_blocks = p_accumulated_blocks
     WHERE id = p_task_id;

    RETURN jsonb_build_object('outcome', 'updated', 'task_id', p_task_id);
END;
$$;


ALTER FUNCTION public.update_generation_progress(p_task_id uuid, p_execution_token uuid, p_accumulated_content text, p_accumulated_blocks jsonb) OWNER TO everydayai;

