--
-- Name: update_wecom_conversation_setting(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.update_wecom_conversation_setting(p_conversation_id uuid, p_user_id uuid, p_setting_key text, p_setting_value text, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conversation conversations%ROWTYPE;
BEGIN
    IF p_conversation_id IS NULL
       OR p_user_id IS NULL
       OR p_setting_key NOT IN ('model', 'thinking_mode')
       OR COALESCE(p_setting_value, '') = ''
       OR (
           p_setting_key = 'thinking_mode'
           AND p_setting_value NOT IN ('deep', 'fast')
       ) THEN
        RAISE EXCEPTION 'WECOM_SETTING_ARGUMENT_INVALID' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_conversation
      FROM conversations
     WHERE id = p_conversation_id
       AND user_id = p_user_id
       AND org_id IS NOT DISTINCT FROM p_org_id
       AND source = 'wecom'
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'WECOM_SETTING_CONVERSATION_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    IF p_setting_key = 'model' THEN
        UPDATE conversations
           SET model_id = p_setting_value,
               updated_at = NOW()
         WHERE id = p_conversation_id
         RETURNING * INTO v_conversation;
    ELSE
        UPDATE conversations
           SET chat_settings = jsonb_set(
                   COALESCE(chat_settings, '{}'::JSONB),
                   '{thinking_mode}',
                   to_jsonb(p_setting_value),
                   TRUE
               ),
               updated_at = NOW()
         WHERE id = p_conversation_id
         RETURNING * INTO v_conversation;
    END IF;

    RETURN jsonb_build_object(
        'model_id', v_conversation.model_id,
        'chat_settings', COALESCE(v_conversation.chat_settings, '{}'::JSONB)
    );
END;
$$;


ALTER FUNCTION public.update_wecom_conversation_setting(p_conversation_id uuid, p_user_id uuid, p_setting_key text, p_setting_value text, p_org_id uuid) OWNER TO everydayai;

--
-- Name: FUNCTION update_wecom_conversation_setting(p_conversation_id uuid, p_user_id uuid, p_setting_key text, p_setting_value text, p_org_id uuid); Type: COMMENT; Schema: public; Owner: everydayai
--

COMMENT ON FUNCTION public.update_wecom_conversation_setting(p_conversation_id uuid, p_user_id uuid, p_setting_key text, p_setting_value text, p_org_id uuid) IS '按 user/org/source 校验并原子持久化企业微信对话模型或思考模式';


--
-- Name: wecom_get_or_create_user(text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: everydayai
--

CREATE FUNCTION public.wecom_get_or_create_user(p_wecom_userid text, p_corp_id text, p_org_id uuid, p_channel text, p_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID;
  v_existing UUID;
  v_lock_key BIGINT;
BEGIN
  -- advisory lock：同一 (wecom_userid, corp_id) 的并发请求串行化
  -- xact_lock = 事务结束自动释放，无泄漏风险
  v_lock_key := hashtextextended(p_wecom_userid || '::' || p_corp_id, 0);
  PERFORM pg_advisory_xact_lock(v_lock_key);

  -- 锁后 double-check：另一个并发请求可能已创建
  SELECT user_id INTO v_existing
  FROM wecom_user_mappings
  WHERE wecom_userid = p_wecom_userid
    AND corp_id = p_corp_id
    AND org_id IS NOT DISTINCT FROM p_org_id;

  IF v_existing IS NOT NULL THEN
    UPDATE users SET last_login_at = NOW() WHERE id = v_existing;
    RETURN jsonb_build_object(
      'user_id', v_existing,
      'is_new', false
    );
  END IF;

  -- 创建用户（单事务内：失败任一步全回滚）
  INSERT INTO users (
    nickname, login_methods, created_by, role, credits, status, last_login_at
  ) VALUES (
    p_display_name, '["wecom"]'::jsonb, 'wecom'::user_created_by,
    'user'::user_role, 100, 'active'::account_status, NOW()
  ) RETURNING id INTO v_user_id;

  -- 创建映射（依赖 wecom_mappings_uniq_idx 兜底）
  INSERT INTO wecom_user_mappings (
    wecom_userid, corp_id, user_id, channel, wecom_nickname, org_id
  ) VALUES (
    p_wecom_userid, p_corp_id, v_user_id, p_channel, p_display_name, p_org_id
  );

  -- 注册赠送积分
  INSERT INTO credits_history (
    user_id, change_amount, balance_after, change_type, description, org_id
  ) VALUES (
    v_user_id, 100, 100, 'register_gift'::credits_change_type,
    '企业微信用户注册赠送积分', p_org_id
  );

  RETURN jsonb_build_object(
    'user_id', v_user_id,
    'is_new', true
  );
END;
$$;


