-- Name: detail_projects; Type: TABLE; Schema: public; Owner: everydayai
--

CREATE TABLE public.detail_projects (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    org_id uuid,
    status text DEFAULT 'draft'::text NOT NULL,
    content_type text DEFAULT 'default'::text NOT NULL,
    platform text DEFAULT 'auto'::text NOT NULL,
    requirement text DEFAULT ''::text NOT NULL,
    language text DEFAULT 'zh-CN'::text NOT NULL,
    aspect_ratio text DEFAULT '1:1'::text NOT NULL,
    quality text DEFAULT '1k'::text NOT NULL,
    image_count smallint DEFAULT 14 NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    prompt_model text DEFAULT 'kimi-k3'::text NOT NULL,
    run_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    title text DEFAULT ''::text NOT NULL,
    CONSTRAINT detail_projects_content_type_check CHECK ((content_type = ANY (ARRAY['default'::text, 'main_image'::text, 'detail_page'::text]))),
    CONSTRAINT detail_projects_image_count_check CHECK ((((content_type = 'default'::text) AND (image_count = 14)) OR ((content_type = ANY (ARRAY['main_image'::text, 'detail_page'::text])) AND ((image_count >= 1) AND (image_count <= 15))))),
    CONSTRAINT detail_projects_language_check CHECK ((language = ANY (ARRAY['zh-CN'::text, 'none'::text]))),
    CONSTRAINT detail_projects_platform_check CHECK ((platform = ANY (ARRAY['auto'::text, 'taobao'::text, 'tmall'::text, 'jd'::text, 'pdd'::text]))),
    CONSTRAINT detail_projects_prompt_model_check CHECK ((prompt_model = ANY (ARRAY['kimi-k3'::text, 'gemini-3.8-flash'::text, 'gpt-6-luna'::text]))),
    CONSTRAINT detail_projects_quality_check CHECK ((quality = ANY (ARRAY['1k'::text, '2k'::text, '4k'::text]))),
    CONSTRAINT detail_projects_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'analyzing'::text, 'plan_ready'::text, 'generating'::text, 'completed'::text, 'failed'::text, 'archived'::text]))),
    CONSTRAINT detail_projects_title_check CHECK ((length(title) <= 120)),
    CONSTRAINT detail_projects_version_check CHECK ((version > 0))
);


