--
-- Name: mv_kit_stock; Type: MATERIALIZED VIEW; Schema: public; Owner: everydayai
--

CREATE MATERIALIZED VIEW public.mv_kit_stock AS
 WITH kit_components AS (
         SELECT p_1.org_id,
            p_1.outer_id AS kit_outer_id,
            (comp.value ->> 'skuOuterId'::text) AS kit_sku_outer_id,
            (comp.value ->> 'outerId'::text) AS sub_code,
            GREATEST(((comp.value ->> 'ratio'::text))::integer, 1) AS ratio
           FROM public.erp_products p_1,
            LATERAL jsonb_array_elements(p_1.suit_singles) comp(value)
          WHERE ((p_1.item_type = 1) AND (p_1.suit_singles IS NOT NULL) AND (p_1.active_status = 1) AND ((comp.value ->> 'skuOuterId'::text) IS NOT NULL) AND ((comp.value ->> 'skuOuterId'::text) <> ''::text))
        ), sub_stock AS (
         SELECT erp_stock_status.org_id,
            erp_stock_status.sku_outer_id AS sub_code,
            sum(erp_stock_status.sellable_num) AS total_sellable,
            sum(erp_stock_status.total_stock) AS total_stock,
            sum(erp_stock_status.purchase_num) AS total_onway
           FROM public.erp_stock_status
          WHERE ((erp_stock_status.sku_outer_id)::text <> ''::text)
          GROUP BY erp_stock_status.org_id, erp_stock_status.sku_outer_id
        ), kit_stock AS (
         SELECT kc.org_id,
            kc.kit_outer_id,
            kc.kit_sku_outer_id,
            (min(floor((COALESCE(ss.total_sellable, (0)::numeric) / (kc.ratio)::numeric))))::integer AS sellable_num,
            (min(floor((COALESCE(ss.total_stock, (0)::numeric) / (kc.ratio)::numeric))))::integer AS total_stock,
            (min(floor((COALESCE(ss.total_onway, (0)::numeric) / (kc.ratio)::numeric))))::integer AS purchase_num
           FROM (kit_components kc
             LEFT JOIN sub_stock ss ON ((((ss.sub_code)::text = kc.sub_code) AND (ss.org_id = kc.org_id))))
          GROUP BY kc.org_id, kc.kit_outer_id, kc.kit_sku_outer_id
        )
 SELECT ks.org_id,
    ks.kit_outer_id AS outer_id,
    ks.kit_sku_outer_id AS sku_outer_id,
    p.title AS item_name,
    ps.properties_name,
    ''::character varying AS warehouse_id,
    ks.sellable_num,
    ks.total_stock,
    0 AS lock_stock,
    ks.purchase_num,
        CASE
            WHEN (ks.sellable_num <= 0) THEN 3
            WHEN (ks.sellable_num < 10) THEN 2
            ELSE 1
        END AS stock_status
   FROM ((kit_stock ks
     LEFT JOIN public.erp_products p ON ((((p.outer_id)::text = (ks.kit_outer_id)::text) AND (p.org_id = ks.org_id))))
     LEFT JOIN public.erp_product_skus ps ON ((((ps.sku_outer_id)::text = ks.kit_sku_outer_id) AND (ps.org_id = ks.org_id))))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_kit_stock OWNER TO everydayai;

