    CONSTRAINT skill_chat_proposals_status_check CHECK ((status = ANY (ARRAY['awaiting_confirmation'::text, 'awaiting_review'::text, 'committed'::text, 'cancelled'::text, 'rejected'::text, 'expired'::text]))),
    CONSTRAINT skill_chat_proposals_target_contract CHECK ((((operation = 'create'::text) AND (target_package_id IS NULL) AND (target_revision IS NULL) AND (target_draft_version IS NULL)) OR ((operation = 'update'::text) AND (target_package_id IS NOT NULL) AND (target_revision IS NOT NULL) AND (target_draft_version IS NOT NULL) AND (target_scope = 'personal'::text)))),
    CONSTRAINT skill_chat_proposals_target_scope_check CHECK ((target_scope = ANY (ARRAY['personal'::text, 'org'::text, 'platform'::text]))),
    CONSTRAINT skill_chat_proposals_version_check CHECK ((version > 0))
);

