    CONSTRAINT skill_drafts_approved_sha256_check CHECK ((approved_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT skill_drafts_check CHECK ((((approved_by IS NULL) AND (approved_sha256 IS NULL) AND (approved_at IS NULL)) OR ((approved_by IS NOT NULL) AND (approved_sha256 IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT skill_drafts_content_check CHECK ((jsonb_typeof(content) = 'object'::text)),
    CONSTRAINT skill_drafts_revision_check CHECK ((revision ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$'::text)),
    CONSTRAINT skill_drafts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'in_review'::text, 'published'::text, 'deprecated'::text, 'disabled'::text]))),
    CONSTRAINT skill_drafts_version_check CHECK ((version > 0))
);

