--

CREATE TABLE public.user_assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid,
    storage_scope text NOT NULL,
    storage_owner_key text NOT NULL,
    storage_provider text NOT NULL,
    storage_key text NOT NULL,
    media_type text NOT NULL,
    status text DEFAULT 'ready'::text NOT NULL,
    original_url text NOT NULL,
    thumbnail_url text,
    download_url text NOT NULL,
    workspace_path text,
    name text NOT NULL,
    mime_type text,
    size bigint,
    content_sha256 text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_assets_check CHECK ((((storage_scope = 'user'::text) AND (storage_owner_key ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)) OR ((storage_scope = 'channel'::text) AND (storage_owner_key ~ '^channels/wecom/[0-9a-f]{24}$'::text)))),
    CONSTRAINT user_assets_content_sha256_check CHECK (((content_sha256 IS NULL) OR (content_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT user_assets_download_url_check CHECK ((btrim(download_url) <> ''::text)),
    CONSTRAINT user_assets_media_type_check CHECK ((media_type = ANY (ARRAY['image'::text, 'video'::text, 'file'::text]))),
    CONSTRAINT user_assets_name_check CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT user_assets_original_url_check CHECK ((btrim(original_url) <> ''::text)),
    CONSTRAINT user_assets_size_check CHECK (((size IS NULL) OR (size >= 0))),
    CONSTRAINT user_assets_status_check CHECK ((status = ANY (ARRAY['ready'::text, 'deleted'::text]))),
    CONSTRAINT user_assets_storage_key_check CHECK ((btrim(storage_key) <> ''::text)),
    CONSTRAINT user_assets_storage_provider_check CHECK ((storage_provider = ANY (ARRAY['workspace'::text, 'oss'::text]))),
    CONSTRAINT user_assets_storage_scope_check CHECK ((storage_scope = ANY (ARRAY['user'::text, 'channel'::text])))
);


