--
-- Name: ecom_image_plan_acceptances ecom_image_plan_acceptances_actor; Type: POLICY; Schema: public; Owner: everydayai_owner
--

CREATE POLICY ecom_image_plan_acceptances_actor ON public.ecom_image_plan_acceptances TO everydayai USING ((EXISTS ( SELECT 1
   FROM public.tasks t
  WHERE ((t.id = ecom_image_plan_acceptances.parent_task_id) AND (t.user_id = (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid) AND (NOT (t.org_id IS DISTINCT FROM (NULLIF(current_setting('app.org_id'::text, true), ''::text))::uuid)))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.tasks t
  WHERE ((t.id = ecom_image_plan_acceptances.parent_task_id) AND (t.user_id = (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid) AND (NOT (t.org_id IS DISTINCT FROM (NULLIF(current_setting('app.org_id'::text, true), ''::text))::uuid))))));


