CREATE POLICY ecom_image_plans_actor ON public.ecom_image_plans TO everydayai USING (((user_id = (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid) AND (NOT (org_id IS DISTINCT FROM (NULLIF(current_setting('app.org_id'::text, true), ''::text))::uuid)))) WITH CHECK (((user_id = (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid) AND (NOT (org_id IS DISTINCT FROM (NULLIF(current_setting('app.org_id'::text, true), ''::text))::uuid))));


