-- Name: skill_assignments skill_assignments_insert; Type: POLICY; Schema: public; Owner: everydayai
--

CREATE POLICY skill_assignments_insert ON public.skill_assignments FOR INSERT TO everydayai WITH CHECK ((((org_id = public.skill_catalog_org_id()) AND (current_setting('app.access_kind'::text, true) = 'runtime_admin'::text)) OR ((org_id IS NULL) AND public.skill_platform_assignment_write_allowed())));


--
-- Name: skill_assignments skill_assignments_read; Type: POLICY; Schema: public; Owner: everydayai
--

CREATE POLICY skill_assignments_read ON public.skill_assignments FOR SELECT TO everydayai USING (((org_id = public.skill_catalog_org_id()) OR ((org_id IS NULL) AND (EXISTS ( SELECT 1
   FROM public.skill_packages p
  WHERE ((p.id = skill_assignments.package_id) AND (p.scope_kind = 'platform'::text)))))));


--
-- Name: skill_assignments skill_assignments_update; Type: POLICY; Schema: public; Owner: everydayai
--

CREATE POLICY skill_assignments_update ON public.skill_assignments FOR UPDATE TO everydayai USING ((((org_id = public.skill_catalog_org_id()) AND (current_setting('app.access_kind'::text, true) = 'runtime_admin'::text)) OR ((org_id IS NULL) AND public.skill_platform_assignment_write_allowed()))) WITH CHECK ((((org_id = public.skill_catalog_org_id()) AND (current_setting('app.access_kind'::text, true) = 'runtime_admin'::text)) OR ((org_id IS NULL) AND public.skill_platform_assignment_write_allowed())));


