-- Name: skill_activation_audits skill_audits_insert; Type: POLICY; Schema: public; Owner: everydayai
--

CREATE POLICY skill_audits_insert ON public.skill_activation_audits FOR INSERT TO everydayai WITH CHECK (((org_id = public.skill_catalog_org_id()) AND (NOT (actor_user_id IS DISTINCT FROM (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid)) AND (current_setting('app.access_kind'::text, true) = 'runtime_admin'::text)));


--
-- Name: skill_activation_audits skill_audits_read; Type: POLICY; Schema: public; Owner: everydayai
--

CREATE POLICY skill_audits_read ON public.skill_activation_audits FOR SELECT TO everydayai USING ((org_id = public.skill_catalog_org_id()));


--
-- Name: skill_authoring_receipts skill_authoring_receipt_admin; Type: POLICY; Schema: public; Owner: everydayai
--

CREATE POLICY skill_authoring_receipt_admin ON public.skill_authoring_receipts TO everydayai USING (((current_setting('app.access_kind'::text, true) = 'runtime_admin'::text) AND (NOT (org_id IS DISTINCT FROM public.skill_catalog_org_id())) AND (NOT (actor_user_id IS DISTINCT FROM (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid)) AND (EXISTS ( SELECT 1
   FROM public.org_members m
  WHERE ((m.org_id = skill_authoring_receipts.org_id) AND (m.user_id = skill_authoring_receipts.actor_user_id) AND ((m.status)::text = 'active'::text) AND ((m.role)::text = ANY ((ARRAY['owner'::character varying, 'admin'::character varying])::text[]))))))) WITH CHECK (((current_setting('app.access_kind'::text, true) = 'runtime_admin'::text) AND (NOT (org_id IS DISTINCT FROM public.skill_catalog_org_id())) AND (NOT (actor_user_id IS DISTINCT FROM (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid)) AND (EXISTS ( SELECT 1
   FROM public.org_members m
  WHERE ((m.org_id = skill_authoring_receipts.org_id) AND (m.user_id = skill_authoring_receipts.actor_user_id) AND ((m.status)::text = 'active'::text) AND ((m.role)::text = ANY ((ARRAY['owner'::character varying, 'admin'::character varying])::text[])))))));


