--

CREATE POLICY skill_change_audits_insert ON public.skill_change_audits FOR INSERT TO everydayai WITH CHECK (((current_setting('app.access_kind'::text, true) = 'runtime_admin'::text) AND (NOT (actor_user_id IS DISTINCT FROM (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid)) AND (EXISTS ( SELECT 1
   FROM public.skill_packages p
  WHERE ((p.id = skill_change_audits.package_id) AND (((p.scope_kind = 'personal'::text) AND (p.owner_user_id = skill_change_audits.actor_user_id)) OR ((p.scope_kind = 'org'::text) AND (p.org_id = public.skill_catalog_org_id())) OR ((p.scope_kind = 'platform'::text) AND (current_setting('app.skill_action'::text, true) ~~ 'platform_%'::text))))))));


