   FROM public.skill_packages p
  WHERE ((p.id = skill_change_audits.package_id) AND (((p.scope_kind = 'personal'::text) AND (p.owner_user_id = (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid)) OR ((p.scope_kind = 'org'::text) AND (p.org_id = public.skill_catalog_org_id())) OR ((p.scope_kind = 'platform'::text) AND (current_setting('app.skill_action'::text, true) ~~ 'platform_%'::text))))))));


