--
-- Name: skill_chat_proposals skill_chat_proposals_platform_admin_read; Type: POLICY; Schema: public; Owner: everydayai
--

CREATE POLICY skill_chat_proposals_platform_admin_read ON public.skill_chat_proposals FOR SELECT TO everydayai USING (((current_setting('app.access_kind'::text, true) = 'runtime_admin'::text) AND (target_scope = 'platform'::text) AND ((status = 'awaiting_review'::text) OR ((status = ANY (ARRAY['committed'::text, 'rejected'::text])) AND (current_setting('app.skill_action'::text, true) = 'platform_chat_publish'::text))) AND (EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.id = (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid) AND (u.status = 'active'::public.account_status) AND (u.role = 'super_admin'::public.user_role))))));


--
-- Name: skill_chat_proposals skill_chat_proposals_platform_admin_update; Type: POLICY; Schema: public; Owner: everydayai
--

CREATE POLICY skill_chat_proposals_platform_admin_update ON public.skill_chat_proposals FOR UPDATE TO everydayai USING (((current_setting('app.access_kind'::text, true) = 'runtime_admin'::text) AND (target_scope = 'platform'::text) AND (status = 'awaiting_review'::text) AND (EXISTS ( SELECT 1
   FROM public.users u
  WHERE ((u.id = (NULLIF(current_setting('app.actor_user_id'::text, true), ''::text))::uuid) AND (u.status = 'active'::public.account_status) AND (u.role = 'super_admin'::public.user_role)))))) WITH CHECK (((current_setting('app.access_kind'::text, true) = 'runtime_admin'::text) AND (target_scope = 'platform'::text) AND (EXISTS ( SELECT 1
